def normalize_seed_list(seeds, *, default=(0,)):
    """Validate and de-duplicate a panel's seed list, preserving order.

    A duplicated seed would enqueue the SAME ``variant::seed`` cell twice
    (the second run silently overwriting the first record), and an explicitly
    empty/absent list would train the fallback seed 0 while the manifest
    planned no cells at all.  Both make the on-disk trace disagree with the
    work that actually ran, so the axes are normalised once, before
    probing/tracking.
    Accepts a scalar, an iterable of integers, or a comma/space separated
    string; booleans and non-integral floats are rejected rather than silently
    truncated to a different seed.
    """
    if seeds is None:
        seeds = list(default)
    elif isinstance(seeds, (bool, np.bool_)):
        raise ValueError(f'seed must be an integer, got boolean {seeds!r}')
    elif isinstance(seeds, numbers.Real):
        seeds = [seeds]
    elif isinstance(seeds, np.ndarray) and seeds.ndim == 0:
        seeds = [seeds.item()]
    elif isinstance(seeds, (str, bytes)):
        seeds = seeds.decode().split() if isinstance(seeds, bytes) else seeds.replace(',', ' ').split()
    out = []
    seen = set()
    for raw in seeds:
        if isinstance(raw, (bool, np.bool_)):
            raise ValueError(f'seed must be an integer, got boolean {raw!r}')
        # Use the shared scalar reader: it handles NumPy scalars and rejects
        # non-integral numeric objects (e.g. Decimal('1.5')) instead of
        # silently truncating them with int(), and enforces the RNG domain.
        try:
            s = _seed_value(raw)
        except ValueError as _se:
            raise ValueError(f'seed must be an integer in [0, {MAX_SEED}], got {raw!r}') from _se
        if s in seen:
            print(f'[seeds] WARNING: duplicate seed {s} removed from the panel plan (it would otherwise be trained twice under the same key)')
            continue
        seen.add(s)
        out.append(s)
    if not out:
        # The fallback is still a declared seed plan, not a raw int() cast:
        # default=(True,) or default=(1.5,) must not silently become seed 1.
        try:
            _fallback = list(default)
        except TypeError:
            _fallback = [default]
        for raw in _fallback:
            if isinstance(raw, (bool, np.bool_)):
                raise ValueError(f'default seed must be an integer, got boolean {raw!r}')
            try:
                s = _seed_value(raw)
            except ValueError as _se:
                raise ValueError(f'default seed must be an integer in [0, {MAX_SEED}], got {raw!r}') from _se
            if s not in seen:
                seen.add(s)
                out.append(s)
    return out


def normalize_variant_list(variants):
    """Validate and de-duplicate a panel's variant list, preserving order."""
    if variants is None:
        return []
    if isinstance(variants, str):
        variants = [variants]
    out = []
    seen = set()
    for raw in variants:
        v = str(raw)
        if v in seen:
            print(f'[variants] WARNING: duplicate variant {v!r} removed from the panel plan (it would otherwise be trained twice under the same key)')
            continue
        seen.add(v)
        out.append(v)
    return out


_LAST_SEED = None


def set_seed(seed):
    """Seed every RNG that can affect a run: Python ``random``, NumPy's
    legacy global RNG, PyTorch's CPU RNG and every CUDA device, plus the
    Python hash seed (best effort for child processes).  Returns the integer
    seed so callers can record exactly what was used.  torch's deterministic
    algorithm / cuDNN switches are pinned at the same time, so two runs with
    the same seed on the same machine follow the same kernels."""
    global _LAST_SEED
    seed = _seed_value(seed)
    _LAST_SEED = int(seed)
    os.environ['PYTHONHASHSEED'] = str(seed)
    random.seed(seed)
    np.random.seed(seed)
    _attb_bump_epoch()
    torch.manual_seed(seed)
    _pin_cpu_threads()
    # Pin the backend determinism switches on CPU too: the cuDNN flags are
    # inert without CUDA, while CSA_DETERMINISTIC must still enable torch's
    # deterministic-algorithm mode on a CPU box (a CPU run is a first-class
    # reproduction target).  CUDA RNGs are seeded explicitly below.
    _pin_cuda_determinism()
    if torch.cuda.is_available():
        # manual_seed already covers all devices; the explicit current-device
        # call documents the contract and is harmless.
        torch.cuda.manual_seed(seed)
        torch.cuda.manual_seed_all(seed)
    # TensorFlow is not a dependency of this repo, but a future/embedded
    # TensorFlow path must not become an unseeded RNG source.  Only touch it
    # when the user has already imported it (never import TensorFlow here:
    # that would make every CPU-only run import it needlessly).
    _tf = sys.modules.get('tensorflow')
    if _tf is not None:
        try:
            _tf.random.set_seed(seed)
            try:
                _tf.config.experimental.enable_op_determinism()
            except Exception:
                pass
        except Exception as _tfe:
            print(f'[determinism] could not seed the already-imported TensorFlow RNG ({type(_tfe).__name__}: {_tfe})')
    return seed
_CPU_THREADS_PINNED = None

def rng_fingerprint():
    """Digest of the *current* Python/NumPy/Torch/CUDA RNG state.

    Recorded immediately after `set_seed(seed)` in every training record.  Two
    runs with the same seed on the same stack must produce the same digest;
    a mismatch means some import/construction consumed randomness before the
    run started (and therefore that the seed is not fully controlled).  The
    digest is a diagnostic only: it never enters the resume fingerprint."""
    h = hashlib.sha256()
    h.update(repr(random.getstate()).encode('utf-8', 'replace'))
    _ns = np.random.get_state()
    h.update(str(_ns[0]).encode('ascii', 'replace'))
    h.update(np.asarray(_ns[1], dtype=np.uint64).tobytes())
    h.update(repr((_ns[2], _ns[3], _ns[4])).encode('ascii', 'replace'))
    h.update(torch.get_rng_state().numpy().tobytes())
    if torch.cuda.is_available():
        try:
            for _st in torch.cuda.get_rng_state_all():
                h.update(_st.cpu().numpy().tobytes())
        except Exception:
            # a broken CUDA context is reported elsewhere; the CPU part of
            # the fingerprint is still a useful diagnostic
            pass
    return h.hexdigest()[:16]

def init_core_fingerprint(model):
    """Hash the initialization of the parameter tensors every arm shares.

    A paired-seed design only blocks the *seed*, not the initialization:
    different architectures consume different amounts of RNG, so "seed=3" does
    not by itself prove that the two arms started from the same embedding /
    position / LM-head / final-norm tensors.  This digest covers exactly the
    trunk pieces whose names, shapes and construction order do not depend on
    the attention variant (they are built before the blocks), so equality is a
    real matched-initialization check rather than a tautology.

    It is recorded per training record and `pair_reason` refuses a pair whose
    two records carry different digests.  Records from before this field
    existed carry no digest; a one-sided digest is unverifiable, exactly like
    the other provenance gates.
    """
    h = hashlib.sha256()
    sd = model.state_dict() if hasattr(model, 'state_dict') else {}
    for name in ('tok.weight', 'pos.weight', 'head.weight', 'norm.weight'):
        t = sd.get(name)
        if t is None:
            continue
        arr = t.detach().to('cpu').float().contiguous().numpy()
        h.update(name.encode('ascii', 'replace'))
        h.update(repr(tuple(arr.shape)).encode('ascii', 'replace'))
        h.update(arr.tobytes())
    return h.hexdigest()[:16]

def paired_init_core_audit(records_a, records_b, seeds):
    """Audit the matched-initialization contract for PAIRED seeds.

    ``init_core_fp`` hashes the shared trunk initialization.  It depends on
    the seed, so the valid test is equality between the TWO ARMS at the SAME
    seed; equality across different seeds is neither expected nor required.
    Treating the whole panel as one value set would mark a healthy panel as
    mismatched (every seed has a different init) or, when the field is
    absent, vacuously pass.  This helper performs the per-seed check once so
    the confirmation analysis and its tests share one definition.

    A pair is ``verified`` only when both records carry a non-empty digest
    and the digests are equal.  ``mismatch`` is definite evidence that the
    two arms did not start from the same shared trunk, so the caller must
    drop that pair.  A one-sided or absent digest is ``unverified`` (legacy
    records predate the field): it is reported, never read as equality, and
    does not by itself drop the pair.

    ``pairing_ok`` is ``True`` only when every requested seed is verified,
    ``False`` when at least one pair mismatches, and ``None`` when the
    evidence is merely incomplete.  It is deliberately tri-state: absence of
    evidence is not a pass.
    """
    if not isinstance(records_a, dict) or not isinstance(records_b, dict):
        raise ValueError('paired_init_core_audit: records_a/records_b must be mappings')
    if isinstance(seeds, (str, bytes)):
        raise ValueError('paired_init_core_audit: seeds must be an iterable of integers')
    try:
        seed_list = list(seeds)
    except TypeError:
        raise ValueError('paired_init_core_audit: seeds must be an iterable') from None
    _seen = set()
    norm = []
    for s in seed_list:
        si = _as_seed_int(s)
        if si is None:
            raise ValueError(f'paired_init_core_audit: seed {s!r} is not an integer')
        if si in _seen:
            raise ValueError(f'paired_init_core_audit: duplicate seed {si}')
        _seen.add(si)
        norm.append(si)

    def _val(rec):
        if not isinstance(rec, dict):
            return None
        v = rec.get('init_core_fp')
        # Malformed evidence is unverified, not a value: str(123) == '123'
        # must not let a non-digest become a "match".
        if not isinstance(v, str):
            return None
        s = v.strip()
        return s if s else None

    per_seed = []
    counts = {'verified': 0, 'mismatch': 0, 'unverified': 0, 'missing': 0}
    for s in norm:
        ra, rb = records_a.get(s), records_b.get(s)
        va, vb = _val(ra), _val(rb)
        if ra is None or rb is None:
            status = 'missing'
        elif va is not None and vb is not None:
            status = 'verified' if va == vb else 'mismatch'
        else:
            status = 'unverified'
        counts[status] += 1
        entry = {'seed': int(s), 'status': status}
        if va is not None:
            entry['a'] = va
        if vb is not None:
            entry['b'] = vb
        per_seed.append(entry)
    n_pairs = len(norm)
    mismatch = [e['seed'] for e in per_seed if e['status'] == 'mismatch']
    unverified = [e['seed'] for e in per_seed if e['status'] == 'unverified']
    missing = [e['seed'] for e in per_seed if e['status'] == 'missing']
    if mismatch:
        pairing_ok = False
    elif n_pairs and counts['verified'] == n_pairs:
        pairing_ok = True
    else:
        pairing_ok = None
    return {'n_pairs': int(n_pairs), 'n_verified': int(counts['verified']),
            'n_mismatch': int(counts['mismatch']),
            'n_unverified': int(counts['unverified']),
            'n_missing': int(counts['missing']),
            'verified_seeds': [e['seed'] for e in per_seed if e['status'] == 'verified'],
            'mismatch_seeds': mismatch, 'unverified_seeds': unverified,
            'missing_seeds': missing,
            'pairing_ok': pairing_ok,
            'keep_seeds': [e['seed'] for e in per_seed if e['status'] != 'mismatch'],
            'per_seed': per_seed,
            'definition': ('verified = both arms at the same seed carry an equal non-empty '
                           'init_core_fp; mismatch = both present but different (drop the pair); '
                           'unverified = one-sided/absent digest (legacy, not a match); '
                           'pairing_ok is True only if every requested pair is verified, '
                           'False if any mismatches, None if evidence is incomplete.'),
            'note': ('matched initialization is a pairing validity precondition, not a '
                     'measured outcome; no training or evaluation value is changed')}

def capture_rng_state():
    """Snapshot every RNG stream a short diagnostic may consume.

    Diagnostics such as the small-batch overfit probe and the duplicate-run
    reproducibility probe call ``set_seed`` themselves.  Without a snapshot
    they would advance the process-wide RNG streams and silently couple a
    later training cell to how many probes ran before it.  The returned object
    is opaque: restore it with ``restore_rng_state``.
    """
    state = {'python': random.getstate(), 'numpy': np.random.get_state(), 'torch': torch.get_rng_state()}
    if torch.cuda.is_available():
        try:
            state['cuda'] = torch.cuda.get_rng_state_all()
        except Exception:
            state['cuda'] = None
    else:
        state['cuda'] = None
    return state

def restore_rng_state(state):
    """Restore a snapshot from ``capture_rng_state`` (best effort on CUDA).

    Restoring is what makes the pre-flight checks side-effect free: the
    training cell that follows sees exactly the RNG state it would have seen
    if the checks had never run, so adding/diagnosing a probe cannot change a
    recorded loss curve.  A broken CUDA context is reported by the caller's
    training loop; the CPU streams are still restored here."""
    if not isinstance(state, dict):
        return
    random.setstate(state['python'])
    np.random.set_state(state['numpy'])
    torch.set_rng_state(state['torch'])
    if state.get('cuda') is not None and torch.cuda.is_available():
        try:
            torch.cuda.set_rng_state_all(state['cuda'])
        except Exception:
            pass

class _preserve_rng_state:
    """Context manager: run a diagnostic without perturbing the RNG streams.

    Also restores ``PYTHONHASHSEED`` because ``set_seed`` updates it for child
    processes; a probe must not leave that environment mutation behind."""

    def __enter__(self):
        self._env = os.environ.get('PYTHONHASHSEED')
        self._state = capture_rng_state()
        return self

    def __exit__(self, exc_type, exc, tb):
        restore_rng_state(self._state)
        if self._env is None:
            os.environ.pop('PYTHONHASHSEED', None)
        else:
            os.environ['PYTHONHASHSEED'] = self._env
        return False

def dataloader_generator(seed):
    """A torch.Generator for a future torch DataLoader (scale path).

    The current loader is `batch_iter`, which is seeded directly by the run
    seed.  This helper is for DataLoader-based code: pass it as
    ``DataLoader(..., generator=L.dataloader_generator(seed))`` and pass
    ``worker_init_fn=L.seed_worker`` so worker RNGs are derived from the same
    seed instead of the OS entropy pool."""
    g = torch.Generator()
    g.manual_seed(_seed_value(seed))
    return g

def seed_worker(worker_id):
    """DataLoader worker_init_fn: seed Python/NumPy/Torch from torch's
    per-worker base seed.  PyTorch already seeds its own worker RNG before
    calling this hook; re-seeding it explicitly documents the contract and
    also covers older versions where a custom generator changes the base."""
    _seed = int(torch.initial_seed()) % (2 ** 32)
    os.environ['PYTHONHASHSEED'] = str(_seed)
    random.seed(_seed)
    np.random.seed(_seed)
    torch.manual_seed(_seed)
    _pin_cpu_threads()
    _pin_cuda_determinism()
    if torch.cuda.is_available() and torch.cuda.is_initialized():
        torch.cuda.manual_seed(_seed)
        torch.cuda.manual_seed_all(_seed)

def dataloader_kwargs(seed):
    """DataLoader kwargs that pin BOTH the sampler order and worker RNGs.

    Scale path: `DataLoader(ds, **L.dataloader_kwargs(seed), num_workers=n)`.
    The generator controls shuffling/sampling; worker_init_fn derives each
    worker's Python/NumPy RNG from the same seed tree instead of OS entropy.
    """
    return {'generator': dataloader_generator(seed), 'worker_init_fn': seed_worker}

def deterministic_dataloader(dataset, *, seed=0, **kwargs):
    """Thin `torch.utils.data.DataLoader` wrapper with reproducible seeding.

    Existing caller-supplied `generator` / `worker_init_fn` are respected."""
    from torch.utils.data import DataLoader
    # An explicit None means "not supplied", not "please use OS entropy".
    if kwargs.get('generator') is None:
        kwargs['generator'] = dataloader_generator(seed)
    if kwargs.get('worker_init_fn') is None:
        kwargs['worker_init_fn'] = seed_worker
    return DataLoader(dataset, **kwargs)

def dataloader_contract_check(seed=0, *, num_workers=2, batch_size=4, batches=2, device=None):
    """Exercise a REAL seeded DataLoader, including worker processes.

    `seed_contract_check` draws the Python/NumPy/Torch streams directly and
    simulates the worker hook.  That cannot catch a wiring mistake such as a
    DataLoader built without `generator=`/`worker_init_fn=`, or a worker
    dataset that draws from the OS entropy pool.  This check therefore builds
    the actual `deterministic_dataloader` with `num_workers>0`, iterates the
    same seed twice and a different seed once, and compares the full batch
    stream (sampler order + every per-item Python/NumPy/Torch draw).

    The probe is side-effect free on the process RNG streams and is safe to
    call before a panel; it is skipped into the report rather than raised so a
    caller can decide whether worker processes are required on its platform.
    """
    seed = _seed_value(seed)
    _nw = _exact_count(num_workers, minimum=0)
    _bs = _exact_count(batch_size, minimum=1)
    _nb = _exact_count(batches, minimum=1)
    if _nw is None:
        raise ValueError(f'dataloader_contract_check: num_workers must be a non-negative integer, got {num_workers!r}')
    if _bs is None:
        raise ValueError(f'dataloader_contract_check: batch_size must be a positive integer, got {batch_size!r}')
    if _nb is None:
        raise ValueError(f'dataloader_contract_check: batches must be a positive integer, got {batches!r}')
    num_workers, batch_size, batches = int(_nw), int(_bs), int(_nb)
    try:
        from torch.utils.data import Dataset
    except Exception as e:  # pragma: no cover - torch is a hard dependency
        return {'kind': 'dataloader_contract', 'seed': int(seed),
                'num_workers': num_workers, 'passed': False,
                'diagnosis': f'could not import torch DataLoader: {type(e).__name__}: {e}'}

    class _RNGDataset(Dataset):
        def __init__(self, n):
            self.n = int(n)

        def __len__(self):
            return self.n

        def __getitem__(self, i):
            return torch.tensor([int(i),
                                 int(random.random() * 1e9),
                                 int(np.random.random() * 1e9),
                                 int(torch.randint(0, 2 ** 31 - 1, (1,)).item())],
                                dtype=torch.int64)

    _n_items = max(batch_size * batches * max(1, num_workers), 16)

    def _stream(s):
        if num_workers == 0:
            # Without worker processes the dataset's own Python/NumPy/Torch
            # draws run in the parent; seed them explicitly so the same-seed
            # comparison still tests the loader wiring rather than leftover
            # process-state drift.
            set_seed(s)
        dl = deterministic_dataloader(_RNGDataset(_n_items), batch_size=batch_size,
                                      shuffle=True, seed=s, num_workers=num_workers)
        out = []
        for _b in dl:
            out.append(_b.tolist())
            if len(out) >= batches:
                break
        del dl
        return out

    _fp_before = rng_fingerprint()
    try:
        with _preserve_rng_state():
            a = _stream(seed)
            b = _stream(seed)
            c = _stream(_other_seed(seed))
        error = None
    except Exception as e:
        a = b = c = []
        error = f'{type(e).__name__}: {e}'
    _fp_after = rng_fingerprint()
    checks = {
        'stream_nonempty': bool(a and all(a)),
        'same_seed_reproducible': bool(a and a == b),
        'different_seed_changes_stream': bool(a and a != c),
        'rng_state_preserved': bool(_fp_before == _fp_after),
    }
    failed = [k for k, ok in checks.items() if not ok]
    report = {
        'kind': 'dataloader_contract',
        'created_at': time.strftime('%Y-%m-%dT%H:%M:%S'),
        'code': code_stamp(),
        'seed': int(seed),
        'num_workers': num_workers,
        'batch_size': batch_size,
        'batches': batches,
        'device': str(DEVICE if device is None else device),
        'checks': checks,
        'same_seed_stream': a,
        'other_seed_stream': c,
        'rng_fp_before': _fp_before,
        'rng_fp_after': _fp_after,
        'error': error,
        'passed': bool(not failed and error is None),
        'diagnosis': ('ok' if (not failed and error is None)
                      else ('error: ' + error if error else 'failed checks: ' + ', '.join(failed))),
    }
    return report

def seed_contract_check(seed=0, *, device=None, check_subprocess=False, check_dataloader_workers=False, dataloader_workers=2):
    """Explicit audit of every RNG source a reproducible run depends on.

    `reproducibility_check` proves that a short TRAINING stream repeats; this
    check is cheaper and more direct: it enumerates the seed contract itself
    (Python, NumPy, PyTorch CPU, every CUDA device, an already-imported
    TensorFlow, the DataLoader generator and the DataLoader worker hook), runs
    it twice with the same seed and once with a different seed, and verifies
    that same-seed draws are identical while every stream actually changes.
    The probe is side-effect free on the RNG streams (same
    `_preserve_rng_state` contract as the other pre-flights), so it can run
    before a panel without shifting a recorded loss curve.

    ``check_subprocess=True`` additionally re-executes a tiny draw script in
    two fresh interpreters with the same seed/PYTHONHASHSEED, which catches a
    child-process seeding mismatch that an in-process check cannot see.
    """
    seed = _seed_value(seed)
    _alt_seed = _other_seed(seed)
    keys = ['python', 'numpy', 'torch', 'dataloader_generator']
    if torch.cuda.is_available():
        keys.extend(['cuda', 'cuda_devices'])
    if sys.modules.get('tensorflow') is not None:
        keys.append('tensorflow')

    def _draws(s):
        set_seed(s)
        d = {
            'python': float(random.random()),
            'numpy': float(np.random.random()),
            'torch': float(torch.rand(1).item()),
        }
        if torch.cuda.is_available():
            d['cuda'] = [float(x) for x in torch.rand(2, device='cuda')]
            d['cuda_devices'] = {}
            for _di in range(int(torch.cuda.device_count())):
                with torch.cuda.device(_di):
                    d['cuda_devices'][str(_di)] = [float(x) for x in torch.rand(2, device='cuda')]
        g = dataloader_generator(s)
        d['dataloader_generator'] = [int(x) for x in torch.randint(0, 2 ** 31 - 1, (4,), generator=g)]
        _tf = sys.modules.get('tensorflow')
        if _tf is not None:
            try:
                d['tensorflow'] = float(np.asarray(_tf.random.uniform((1,))).reshape(-1)[0])
            except Exception as _tfe:
                d['tensorflow_error'] = f'{type(_tfe).__name__}: {_tfe}'
        return d

    def _worker_draws(s):
        # Reproduce torch's worker base seed explicitly, then let the hook
        # derive the worker's Python/NumPy/Torch streams from it.
        torch.manual_seed(s)
        seed_worker(0)
        g = dataloader_generator(s)
        return {
            'python': float(random.random()),
            'numpy': float(np.random.random()),
            'torch': float(torch.rand(1).item()),
            'dataloader_generator': [int(x) for x in torch.randint(0, 2 ** 31 - 1, (4,), generator=g)],
        }

    checks = {}
    errors = {}
    _fp_before = rng_fingerprint()
    with _preserve_rng_state():
        try:
            a = _draws(seed)
            b = _draws(seed)
            c = _draws(_alt_seed)
            checks['same_seed_reproducible'] = bool(a == b)
            changed = {}
            for k in keys:
                if k not in a or k not in c:
                    continue
                if k == 'tensorflow' and 'tensorflow_error' in a:
                    changed[k] = None
                    continue
                changed[k] = bool(a[k] != c[k])
            checks['different_seed_changes_streams'] = bool(all(v is not False for v in changed.values()) and changed)
        except Exception as e:
            errors['rng_draws'] = f'{type(e).__name__}: {e}'
            a = b = c = {}
            changed = {}
            checks['same_seed_reproducible'] = False
            checks['different_seed_changes_streams'] = False
        try:
            w1 = _worker_draws(seed)
            w2 = _worker_draws(seed)
            w3 = _worker_draws(_alt_seed)
            checks['worker_seed_reproducible'] = bool(w1 == w2)
            checks['worker_different_seed_changes'] = bool(w1 != w3)
        except Exception as e:
            errors['worker_seed'] = f'{type(e).__name__}: {e}'
            w1 = w2 = w3 = {}
            checks['worker_seed_reproducible'] = False
            checks['worker_different_seed_changes'] = False
        checks['cuda_seeded'] = bool('cuda' in a) if torch.cuda.is_available() else None
        checks['cuda_devices_seeded'] = (bool('cuda_devices' in a and len(a.get('cuda_devices') or {}) == int(torch.cuda.device_count())) if torch.cuda.is_available() else None)
        checks['tensorflow_seeded'] = bool('tensorflow' in a and 'tensorflow_error' not in a) if sys.modules.get('tensorflow') is not None else None
        sub = None
        if check_subprocess:
            code = (
                'import json,random,numpy as np,torch;'
                'import exp_lib as L;'
                'L.set_seed(%d);'
                'print(json.dumps([random.random(),float(np.random.random()),float(torch.rand(1).item())]))' % seed
            )
            env = dict(os.environ)
            env['PYTHONHASHSEED'] = str(seed)
            try:
                outs = [subprocess.check_output([sys.executable, '-c', code], cwd=os.path.dirname(os.path.abspath(__file__)), env=env, text=True, timeout=180).strip().splitlines()[-1] for _ in range(2)]
                sub = {'same_seed_reproducible': bool(outs[0] == outs[1]), 'draws': outs}
                checks['subprocess_seed_reproducible'] = sub['same_seed_reproducible']
            except Exception as e:
                errors['subprocess_seed'] = f'{type(e).__name__}: {e}'
                checks['subprocess_seed_reproducible'] = False
        dl_contract = None
        if check_dataloader_workers:
            # Actual worker PROCESSES, not just the hook's draws: this catches
            # a DataLoader created without the seeded generator/worker_init_fn.
            dl_contract = dataloader_contract_check(
                seed, num_workers=dataloader_workers)
            checks['dataloader_worker_processes'] = bool(dl_contract.get('passed'))
            if not dl_contract.get('passed'):
                errors['dataloader_worker_processes'] = str(dl_contract.get('diagnosis'))
    _fp_after = rng_fingerprint()
    _rng_preserved = bool(_fp_before == _fp_after)
    checks['rng_state_preserved'] = _rng_preserved
    _hash_contract = hashseed_contract()
    # Not a pass/fail check: a plain `python driver.py` launch is
    # hash-randomised before exp_lib can import.  Record the residual gap so a
    # reviewer can see whether this run was launched reproducibly.
    warnings = []
    if not _hash_contract['pinned_at_startup']:
        warnings.append(_hash_contract['note'])
    failed = [k for k, ok in checks.items() if ok is False]
    passed = not failed and not errors
    report = {
        'kind': 'rng_seed_contract',
        'created_at': time.strftime('%Y-%m-%dT%H:%M:%S'),
        'code': code_stamp(),
        'seed': seed,
        'device': str(DEVICE if device is None else device),
        'determinism': determinism_label(),
        'streams': keys,
        'checks': checks,
        'different_seed_changed': changed,
        'draws_same_seed': a,
        'draws_other_seed': c,
        'worker_draws_a': w1,
        'worker_draws_b': w2,
        'worker_draws_other_seed': w3,
        'subprocess': sub,
        'dataloader_contract': dl_contract,
        'hashseed': _hash_contract,
        'warnings': warnings,
        'rng_fp_before': _fp_before,
        'rng_fp_after': _fp_after,
        'rng_state_preserved': _rng_preserved,
        'errors': errors,
        'passed': bool(passed),
        'diagnosis': ('ok' if passed else 'failed/errored RNG streams: ' + ', '.join(failed + sorted(errors))),
    }
    return report

def _pin_cpu_threads():
    global _CPU_THREADS_PINNED
    if _CPU_THREADS_PINNED is None:
        want = os.environ.get('CSA_CPU_THREADS', '').strip()
        try:
            n = max(1, int(want)) if want else 1
        except ValueError:
            print(f'[determinism] CSA_CPU_THREADS={want!r} is not an integer — using 1')
            n = 1
        os.environ.setdefault('OMP_NUM_THREADS', str(n))
        os.environ.setdefault('MKL_NUM_THREADS', str(n))
        _CPU_THREADS_PINNED = n
    else:
        n = _CPU_THREADS_PINNED
    try:
        if int(torch.get_num_threads()) != int(n):
            torch.set_num_threads(n)
    except Exception as e:
        print(f'[determinism] could not pin the CPU thread count to {n} ({type(e).__name__}: {e}) — a CPU run may not be reproducible')
    return n

def pin_tf32(enabled=None):
    """Pin TF32 explicitly instead of inheriting a framework default.

    Reproducibility depends on the actual matmul precision mode; two boxes (or
    two torch versions) with different defaults can otherwise disagree while
    looking identically configured.  ``CSA_TF32=1`` opts in; the default is
    off (highest float32 precision)."""
    if enabled is None:
        enabled = os.environ.get('CSA_TF32', '').strip().lower() in ('1', 'true', 'yes', 'on')
    enabled = bool(enabled)
    try:
        if torch.cuda.is_available():
            torch.backends.cuda.matmul.allow_tf32 = enabled
            torch.backends.cudnn.allow_tf32 = enabled
    except Exception as e:
        print(f'[determinism] could not pin TF32 ({type(e).__name__}: {e})')
    try:
        torch.set_float32_matmul_precision('high' if enabled else 'highest')
    except Exception as e:
        print(f'[determinism] could not set float32_matmul_precision ({type(e).__name__}: {e})')
    return enabled

def _pin_cuda_determinism():
    os.environ.setdefault('CUBLAS_WORKSPACE_CONFIG', ':4096:8')
    os.environ.setdefault('PYTORCH_CUDA_ALLOC_CONF', 'expandable_segments:True')
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False
    pin_tf32()
    mode = os.environ.get('CSA_DETERMINISTIC', '').strip().lower()
    if mode in ('1', 'true', 'yes', 'strict'):
        try:
            torch.use_deterministic_algorithms(True)
            return 'strict'
        except Exception as e:
            print(f"[determinism] CSA_DETERMINISTIC=1 requested but the strict mode could not be enabled ({type(e).__name__}: {e}); falling back to cudnn-deterministic only.  The active level is recorded in each record's `run_cfg`.")
            return 'cudnn'
    if mode in ('warn', 'warn_only'):
        torch.use_deterministic_algorithms(True, warn_only=True)
        return 'warn'
    return 'cudnn'

def determinism_label():
    if torch.are_deterministic_algorithms_enabled():
        return 'strict' if not torch.is_deterministic_algorithms_warn_only_enabled() else 'warn'
    if not torch.cuda.is_available():
        return 'cpu'
    return 'cudnn' if torch.backends.cudnn.deterministic else 'off'

def _hashseed_pinned_value(value):
    """Whether a PYTHONHASHSEED value actually fixes hash randomisation.

    CPython accepts only a decimal uint32 or the literal ``random``; the latter
    deliberately re-randomises the process, so it is not a pin even though the
    environment variable is present.
    """
    if value is None:
        return False
    text = str(value).strip()
    if not text or text.lower() == 'random':
        return False
    try:
        seed = int(text, 10)
    except (TypeError, ValueError, OverflowError):
        return False
    return 0 <= seed <= 2 ** 32 - 1


def hashseed_contract():
    """Report whether the CURRENT interpreter was started hash-seeded.

    ``PYTHONHASHSEED`` is consumed by CPython before any repository module is
    imported, so ``set_seed`` cannot repair an interpreter that was launched
    without it.  The experiment code is written to avoid set/dict iteration
    order, but a future data path must not silently rely on that promise.
    This report separates:

    * ``pinned_at_startup`` — a valid numeric seed was present before
      ``exp_lib`` imported (a re-launched/CI/par.py child has this true);
      ``PYTHONHASHSEED=random`` is not a pin;
    * ``child_seed`` — what every child process we spawn will inherit;
    * ``effective_current_process`` — ``fixed`` only when the startup pin was
      present, else ``randomised``.

    It is evidence, not a hard gate: a normal ``python driver.py`` invocation
    has always been hash-randomised, and failing the whole panel on that would
    be a false alarm.  ``seed_contract_check`` records it alongside the other
    RNG streams and a confirmation driver can require it explicitly.
    """
    env_at_startup = _PYTHONHASHSEED_AT_STARTUP
    # A valid numeric startup value is the actual pin; `random` is explicitly
    # not.  `sys.flags.hash_randomization` is recorded separately as evidence
    # rather than folded into the pin test, so a unit test can exercise this
    # branch by setting the captured startup value in the current process.
    pinned = _hashseed_pinned_value(env_at_startup)
    return {
        'pinned_at_startup': bool(pinned),
        'value_at_startup': env_at_startup,
        'child_seed': os.environ.get('PYTHONHASHSEED'),
        'sys_hash_randomization': bool(getattr(sys.flags, 'hash_randomization', 0)),
        'effective_current_process': ('fixed' if pinned else 'randomised'),
        'note': ('the current interpreter was launched with a fixed PYTHONHASHSEED'
                 if pinned else
                 'the current interpreter was launched WITHOUT PYTHONHASHSEED; '
                 'CPython hash randomisation cannot be changed after startup. '
                 'Child processes are pinned, and this experiment does not depend '
                 'on hash iteration order, but launch with PYTHONHASHSEED=0 for '
                 'bit-identical Python-level set/dict ordering across runs.'),
    }

def _jsonable(v):
    """Recursively convert a config/provenance value to JSON-safe data.
    Sets are sorted so two equal configs always serialise identically."""
    if isinstance(v, dict):
        return {str(k): _jsonable(x) for k, x in v.items()}
    if isinstance(v, (set, frozenset)):
        return sorted((_jsonable(x) for x in v), key=str)
    if isinstance(v, (list, tuple)):
        return [_jsonable(x) for x in v]
    if isinstance(v, np.ndarray):
        return _jsonable(v.tolist())
    if isinstance(v, np.generic):
        return v.item()
    if isinstance(v, (str, int, float, bool)) or v is None:
        return v
    return str(v)

def _git_provenance():
    """HEAD / branch / dirty state, with a bounded dirty-file list.  Never
    raises: a source tarball without .git is still a valid experiment."""
    def _run(*args):
        try:
            p = subprocess.run(['git', *args], cwd=os.path.dirname(os.path.abspath(__file__)), capture_output=True, text=True, timeout=20)
            return p.stdout.strip() if p.returncode == 0 else None
        except Exception:
            return None
    head = _run('rev-parse', 'HEAD')
    branch = _run('rev-parse', '--abbrev-ref', 'HEAD')
    dirty = _run('status', '--porcelain')
    files = dirty.splitlines() if dirty else []
    # A commit id alone does NOT identify a dirty work tree: two runs from the
    # same HEAD with different uncommitted edits would otherwise claim the
    # same code version.  Hash the diff and the status instead of storing the
    # (possibly secret-bearing) contents.  Untracked files are included via
    # the status hash; their contents are left to the operator to archive.
    def _sha(text):
        return hashlib.sha256((text or '').encode('utf-8', 'replace')).hexdigest()[:16]
    diff_text = _run('diff', '--no-color', '--no-ext-diff', 'HEAD')
    return {'git_commit': head, 'git_branch': branch, 'git_dirty': bool(files), 'git_dirty_count': len(files), 'git_dirty_files': files[:20], 'git_status_sha256': _sha(dirty), 'git_diff_sha256': _sha(diff_text)}

def _gpu_names():
    try:
        return [torch.cuda.get_device_name(i) for i in range(torch.cuda.device_count())] if torch.cuda.is_available() else []
    except Exception:
        return []

def _gpu_identity():
    """Per-visible-GPU identity used to explain (not eliminate) cross-machine
    drift: name, UUID, device capacity and compute capability.  Never raises."""
    out = []
    if not torch.cuda.is_available():
        return out
    try:
        n = int(torch.cuda.device_count())
    except Exception:
        return out
    for i in range(n):
        try:
            p = torch.cuda.get_device_properties(i)
            out.append({
                'index': i,
                'name': getattr(p, 'name', None),
                'uuid': str(getattr(p, 'uuid', '')) or None,
                'total_memory_bytes': int(getattr(p, 'total_memory', 0)) or None,
                'major': int(getattr(p, 'major', 0)),
                'minor': int(getattr(p, 'minor', 0)),
            })
        except Exception as e:
            out.append({'index': i, 'error': f'{type(e).__name__}: {e}'})
    return out

def _dependency_fingerprint():
    """Content hashes of the dependency declarations plus installed versions.

    The git commit identifies the source but not the environment.  Two runs
    from the same commit can silently differ because a floating dependency
    range resolved to a newer wheel; recording the lock/manifest hashes and
    the installed package versions makes that visible in every provenance
    block without changing the content-based resume fingerprint."""
    root = os.path.dirname(os.path.abspath(__file__))
    files = {}
    for name in ('requirements.txt', 'requirements.lock', 'requirements-ci.txt',
                 'pyproject.toml'):
        path = os.path.join(root, name)
        try:
            with open(path, 'rb') as fh:
                data = fh.read()
            files[name] = {'sha256': hashlib.sha256(data).hexdigest()[:16], 'bytes': len(data)}
        except OSError:
            files[name] = None
    packages = {}
    try:
        from importlib import metadata as _md
        for pkg in ('torch', 'numpy', 'tokenizers', 'datasets', 'matplotlib', 'tensorflow'):
            try:
                packages[pkg] = _md.version(pkg)
            except Exception:
                packages[pkg] = None
    except Exception as e:
        files['_error'] = f'{type(e).__name__}: {e}'
    return {'files': files, 'packages': packages}

# ---------------------------------------------------------------------------
# Source-tree identity
#
# A git commit identifies the source only while the work tree is clean AND the
# reader still has .git.  The frozen-manifest contract deliberately binds
# CODE_SEMANTICS, not the bytes of exp_lib.py (see the continuous-loop header),
# and a source tarball / dirty work tree has no commit identity at all.  The
# source-tree digest is the content-level complement: it hashes exactly the
# files that can change a measurement or its analysis, so an artifact can be
# tied to the code that produced it without trusting git.  It is evidence, not
# a semantic stamp; it never enters run_cfg / the resume fingerprint.
# ---------------------------------------------------------------------------
_SOURCE_TREE_HASH_CACHE = {}
_SOURCE_TREE_CACHE_CAP = 512
_SOURCE_TREE_CONFIG_FILES = (
    # requirements.lock is deliberately NOT here: it is a machine-specific
    # environment record (README tells every machine to regenerate it), so
    # folding it into the source digest would make the same source look
    # different on a CPU test box and a CUDA experiment box.  The lock's hash
    # and contract live in environment_snapshot() instead.
    'pyproject.toml', 'setup.py', 'setup.cfg', 'requirements.txt',
    'confirmation_frozen.json', 'confirmation_frozen_dynamic.json',
)
_SOURCE_TREE_SKIP_FILES = ('conftest.py',)
_SOURCE_TREE_SKIP_DIRS = {
    '.git', '.github', '.venv', 'venv', 'env', 'ENV', '__pycache__',
    '.ruff_cache', '.pytest_cache', '.mypy_cache', '.cache', 'node_modules',
    'build', 'dist', 'site-packages', 'archive', 'par_jobs',
    'wt103_cache', 'fineweb_cache', 'wt103_raw', 'datasets', 'data', 't',
}
_SOURCE_TREE_SKIP_PREFIXES = ('results_', 'analysis_')


def _source_tree_rel(path, root):
    return os.path.relpath(path, root).replace(os.sep, '/')


def _source_file_sha256(path, st=None):
    """sha256 of one source file, memoised on the full stat identity."""
    global _SOURCE_TREE_HASH_CACHE
    if st is None:
        st = os.stat(path)
    key = (os.path.abspath(path), st.st_dev, st.st_ino, st.st_size,
           st.st_mtime_ns, st.st_ctime_ns)
    ent = _SOURCE_TREE_HASH_CACHE.get(key)
    if ent is not None:
        return ent
    digest = file_sha256(path)
    if len(_SOURCE_TREE_HASH_CACHE) >= _SOURCE_TREE_CACHE_CAP:
        _SOURCE_TREE_HASH_CACHE.clear()
    _SOURCE_TREE_HASH_CACHE[key] = digest
    return digest


def _source_tree_paths(root):
    """Deterministic list of source/config files under ``root``.

    Generated artifact directories are pruned, not walked: a 1M-file results
    tree must not turn a provenance call into an I/O sweep.  README files are
    intentionally outside the scope (they document the project but cannot
    change a measurement; the operational tree is what this digest binds).

    Symlinked files are included only when their target stays inside ``root``.
    A link to an unrelated external file must not make the source digest (and
    every artifact that records it) depend on bytes outside the repository.
    """
    root = os.path.abspath(root)
    root_real = os.path.realpath(root)
    out = []
    seen = set()

    def _inside_root(path):
        try:
            return os.path.commonpath([root_real, os.path.realpath(path)]) == root_real
        except (OSError, ValueError):
            return False

    for rel in _SOURCE_TREE_CONFIG_FILES:
        p = os.path.join(root, rel)
        if os.path.isfile(p) and _inside_root(p):
            out.append(p)
            seen.add(os.path.abspath(p))
    for cur, dirs, names in os.walk(root, followlinks=False):
        dirs[:] = sorted(
            d for d in dirs
            if d not in _SOURCE_TREE_SKIP_DIRS
            and not any(d.startswith(pref) for pref in _SOURCE_TREE_SKIP_PREFIXES)
        )
        for n in sorted(names):
            if not n.endswith('.py'):
                continue
            if n.startswith('test_') or n in _SOURCE_TREE_SKIP_FILES:
                # Tests exercise the measurement code; they do not define it.
                # Keeping them out of the digest means a new CPU test cannot
                # masquerade as a semantic change to a frozen panel.
                continue
            p = os.path.join(cur, n)
            ap = os.path.abspath(p)
            if ap in seen or not os.path.isfile(p) or not _inside_root(p):
                continue
            seen.add(ap)
            out.append(p)
    return sorted(out, key=lambda p: _source_tree_rel(p, root))


def source_tree_manifest(root=None, include=None):
    """Content manifest of the measurement-relevant source tree.

    ``include`` lets a test/audit restrict the manifest to explicit relative
    paths.  The full manifest is the durable form written into a plan snapshot;
    per-record provenance uses ``source_tree_summary`` so it stays small.
    """
    root = os.path.abspath(root or os.path.dirname(os.path.abspath(__file__)))
    root_real = os.path.realpath(root)
    if include is None:
        paths = _source_tree_paths(root)
    else:
        # A bare string is one path, not an iterable of characters.  Repeating
        # the same file must not count its bytes twice (the per-file map keeps
        # one entry), and a symlink may not smuggle in an out-of-tree file.
        if isinstance(include, (str, bytes)):
            include = [include]
        paths = []
        _seen_rel = set()
        for rel in include:
            rel = os.fsdecode(rel) if isinstance(rel, bytes) else str(rel)
            rel = rel.replace('\\', '/')
            p = os.path.join(root, rel)
            ap = os.path.abspath(p)
            if os.path.commonpath([root, ap]) != root:
                raise ValueError(f'source_tree_manifest: {rel!r} escapes {root!r}')
            if not os.path.isfile(ap):
                continue
            try:
                _inside = os.path.commonpath([root_real, os.path.realpath(ap)]) == root_real
            except (OSError, ValueError):
                _inside = False
            if not _inside:
                raise ValueError(
                    f'source_tree_manifest: {rel!r} resolves outside {root!r}')
            rel_norm = _source_tree_rel(ap, root)
            if rel_norm in _seen_rel:
                continue
            _seen_rel.add(rel_norm)
            paths.append(ap)
        paths = sorted(paths, key=lambda p: _source_tree_rel(p, root))
    files = {}
    unreadable = []
    for p in paths:
        rel = _source_tree_rel(p, root)
        try:
            st = os.stat(p)
            digest = _source_file_sha256(p, st)
        except OSError as e:
            unreadable.append({'path': rel, 'error': f'{type(e).__name__}: {e}'})
            continue
        files[rel] = {'sha256': digest, 'bytes': int(st.st_size)}
    # Derive the total from the deduplicated per-file map: duplicate include
    # entries (or two spellings of one path) must not inflate `bytes`.
    total = sum(int(entry['bytes']) for entry in files.values())
    # Hash paths, sizes and per-file digests in sorted order.  Including the
    # path makes a rename visible even when the bytes are unchanged; including
    # the size makes truncation visible even before a digest is compared.
    blob = ''.join(f'{rel}\0{files[rel]["bytes"]}\0{files[rel]["sha256"]}\n'
                   for rel in sorted(files))
    digest = hashlib.sha256(blob.encode('utf-8')).hexdigest()
    return {
        'schema': 1,
        'algorithm': 'sha256(sorted relpath NUL bytes NUL sha256 LF)',
        'sha256': digest,
        'n_files': len(files),
        'bytes': int(total),
        'files': files,
        'unreadable': unreadable,
        'scope': ('all non-generated, non-test *.py under the repo root plus '
                  'pyproject/setup/requirements.txt and both frozen manifests; '
                  'requirements.lock (machine-specific environment), README*.md, '
                  'docs, tests and CI configuration are excluded'),
    }


def source_tree_summary(root=None):
    """Compact source-tree identity for per-record provenance."""
    m = source_tree_manifest(root=root)
    out = {k: m[k] for k in ('schema', 'algorithm', 'sha256', 'n_files',
                            'bytes', 'scope')}
    if m.get('unreadable'):
        out['unreadable'] = m['unreadable']
    return out


def parse_requirements_lock(path=None):
    """Parse a ``name==version`` lock without importing packaging.

    Options (e.g. ``--extra-index-url``) and comments are recorded but ignored
    for the version comparison; ambiguous/duplicate pins are an error rather
    than "last line wins", because that would silently change the environment
    a release was verified against.
    """
    path = os.path.abspath(path or os.path.join(
        os.path.dirname(os.path.abspath(__file__)), 'requirements.lock'))
    out = {'path': path, 'exists': os.path.isfile(path), 'pins': {},
           'options': [], 'invalid': [], 'sha256': None}
    if not out['exists']:
        return out
    with open(path, 'rb') as fh:
        raw = fh.read()
    out['sha256'] = hashlib.sha256(raw).hexdigest()
    text = raw.decode('utf-8', 'replace')
    _pin_re = re.compile(
        r'^([A-Za-z0-9][A-Za-z0-9._-]*)(?:\[[^\]]*\])?\s*==\s*([^\s;]+)$')
    for line in text.splitlines():
        s = line.split('#', 1)[0].strip()
        if not s:
            continue
        if s.startswith('-'):
            out['options'].append(s)
            continue
        # `pip-compile --generate-hashes` puts the hashes on continuation
        # lines (which start with `--hash`, handled above) and may leave a
        # trailing backslash on the pin itself.  Accept both forms so a
        # hash-pinned lock is compared, not silently rejected as malformed.
        s = s.rstrip('\\').strip().split(' --hash', 1)[0].strip()
        m = _pin_re.match(s.split(';', 1)[0].strip())
        if not m:
            out['invalid'].append(s)
            continue
        name = re.sub(r'[-_.]+', '-', m.group(1)).lower()
        ver = m.group(2).strip()
        if name in out['pins']:
            # Even an identical duplicate makes the lock ambiguous (the two
            # lines could acquire different markers/hashes later); the
            # contract is one unambiguous pin per distribution.
            if out['pins'][name]['version'] != ver:
                out['invalid'].append(f'duplicate/conflicting pin: {s}')
            else:
                out['invalid'].append(f'duplicate pin: {s}')
            continue
        out['pins'][name] = {'name': m.group(1), 'version': ver}
    return out


def dependency_contract(lock_path=None):
    """Compare the declared lock with the versions actually installed.

    A lock that is present but incomplete or stale is the reproducibility
    failure mode a release must expose: the same git commit then runs on a
    different numerical stack.  ``partial`` means every pinned entry matches
    but extra installed distributions are not pinned (the lock is not a full
    environment record).  Tooling (pip/setuptools/wheel) is not a runtime
    dependency and is excluded from the coverage check.
    """
    try:
        parsed = parse_requirements_lock(lock_path)
    except OSError as e:
        # Provenance must never crash a training run because a lock file is
        # unreadable; report it as an explicit contract failure instead.
        return {'kind': 'dependency_contract',
                'lock_path': os.path.abspath(str(lock_path or 'requirements.lock')),
                'lock_sha256': None, 'n_pinned': 0, 'options': [],
                'mismatches': [], 'missing': [], 'unpinned_installed': [],
                'invalid': [f'could not read the lock: {type(e).__name__}: {e}'],
                'status': 'invalid',
                'note': 'the lock file exists but could not be read'}
    out = {'kind': 'dependency_contract', 'lock_path': parsed['path'],
           'lock_sha256': parsed['sha256'], 'n_pinned': len(parsed['pins']),
           'options': parsed['options'], 'mismatches': [], 'missing': [],
           'invalid': list(parsed['invalid']), 'unpinned_installed': [],
           'status': 'ok', 'note': ''}
    if not parsed['exists']:
        out['status'] = 'missing_lock'
        out['note'] = 'requirements.lock is absent; the environment is not pinned'
        return out
    if parsed['invalid']:
        out['status'] = 'invalid'
        out['note'] = 'the lock has unparseable/ambiguous entries'
        return out
    installed = {}
    try:
        from importlib import metadata as _md
        for dist in _md.distributions():
            try:
                name = dist.metadata['Name']
                if name:
                    installed[re.sub(r'[-_.]+', '-', str(name)).lower()] = str(dist.version)
            except Exception:
                continue
    except Exception as e:
        out['status'] = 'invalid'
        out['invalid'].append(f'importlib.metadata unavailable: {type(e).__name__}: {e}')
        return out
    for name, ent in sorted(parsed['pins'].items()):
        got = installed.get(name)
        if got is None:
            out['missing'].append({'name': ent['name'], 'expected': ent['version']})
        elif str(got) != str(ent['version']):
            out['mismatches'].append({'name': ent['name'], 'expected': ent['version'],
                                      'installed': str(got)})
    _tooling = {'pip', 'setuptools', 'wheel', 'pkg-resources', 'distribute'}
    out['unpinned_installed'] = sorted(
        n for n in installed if n not in parsed['pins'] and n not in _tooling)
    out['n_installed'] = len(installed)
    out['n_unpinned_installed'] = len(out['unpinned_installed'])
    if out['mismatches'] or out['missing']:
        out['status'] = 'mismatch'
        out['note'] = 'installed versions do not match the lock'
    elif out['unpinned_installed']:
        out['status'] = 'partial'
        out['note'] = ('every pinned entry matches, but the lock does not pin '
                       'all installed runtime distributions')
    else:
        out['note'] = ('every installed runtime distribution is pinned and '
                       'matches (pip/setuptools/wheel excluded as tooling)')
    return out


def environment_snapshot():
    """Compact software/hardware snapshot for experiment tracking."""
    import platform
    import socket
    try:
        _hostname = socket.gethostname()
    except Exception:
        _hostname = None
    env = {
        'python': sys.version.split()[0],
        'hostname': _hostname,
        'process_id': os.getpid(),
        'working_directory': os.getcwd(),
        'executable': sys.executable,
        'platform': platform.platform(),
        'machine': platform.machine(),
        'processor': platform.processor(),
        'cpu_count': os.cpu_count(),
        'torch': torch.__version__,
        'torch_git_version': getattr(torch.version, 'git_version', None),
        'numpy': np.__version__,
        'cuda_available': bool(torch.cuda.is_available()),
        'cuda_version': torch.version.cuda,
        'cudnn_version': torch.backends.cudnn.version() if torch.backends.cudnn.is_available() else None,
        'gpu_names': _gpu_names(),
        'gpu_identity': _gpu_identity(),
        'cuda_device_count': torch.cuda.device_count() if torch.cuda.is_available() else 0,
        'cuda_visible_devices': os.environ.get('CUDA_VISIBLE_DEVICES'),
        'determinism': determinism_label(),
        'cudnn_deterministic': bool(torch.backends.cudnn.deterministic),
        'cudnn_benchmark': bool(torch.backends.cudnn.benchmark),
        'deterministic_algorithms': bool(torch.are_deterministic_algorithms_enabled()),
        'tf32_matmul': bool(torch.backends.cuda.matmul.allow_tf32) if torch.cuda.is_available() else None,
        'tf32_cudnn': bool(torch.backends.cudnn.allow_tf32) if torch.cuda.is_available() else None,
        'fp16_reduced_precision_reduction': bool(torch.backends.cuda.matmul.allow_fp16_reduced_precision_reduction) if torch.cuda.is_available() else None,
        'bf16_reduced_precision_reduction': bool(torch.backends.cuda.matmul.allow_bf16_reduced_precision_reduction) if torch.cuda.is_available() else None,
        'float32_matmul_precision': torch.get_float32_matmul_precision(),
        'cublas_workspace_config': os.environ.get('CUBLAS_WORKSPACE_CONFIG'),
        'cpu_threads': int(torch.get_num_threads()),
        'cpu_interop_threads': int(torch.get_num_interop_threads()) if hasattr(torch, 'get_num_interop_threads') else None,
        'pythonhashseed': os.environ.get('PYTHONHASHSEED'),
        'pythonhashseed_at_startup': _PYTHONHASHSEED_AT_STARTUP,
        'pythonhashseed_pinned_at_startup': bool(
            _hashseed_pinned_value(_PYTHONHASHSEED_AT_STARTUP)),
        'hashseed_contract': hashseed_contract(),
        'tensorflow': getattr(sys.modules.get('tensorflow'), '__version__', None),
        'dependencies': _dependency_fingerprint(),
        'dependency_contract': dependency_contract(),
        'flags': {k: os.environ.get(k) for k in ('CSA_KERNEL', 'CSA_CKPT', 'CSA_DETERMINISTIC', 'CSA_CPU_THREADS', 'CSA_SKIP_OVERFIT', 'CSA_REQUIRE_REPRO', 'CSA_SKIP_REPRO', 'CUBLAS_WORKSPACE_CONFIG')},
        # Every run-control variable, not just the historically documented
        # subset: an unrecorded CSA_*/WT103_*/V12_* flag is an unexplained
        # difference between two otherwise identical runs.  Secrets (tokens,
        # passwords) do not use these prefixes and are never collected.
        'env_flags': {k: os.environ.get(k) for k in sorted(os.environ)
                      if k.startswith(('CSA_', 'WT103_', 'FWEDU_', 'M0_', 'V12_'))},
    }
    for _mod, _key in (('tokenizers', 'tokenizers'), ('datasets', 'datasets')):
        try:
            env[_key] = __import__(_mod).__version__
        except Exception:
            env[_key] = None
    return env

def execution_fingerprint(env=None):
    """Fingerprint of the hardware/software/determinism class of a run.

    Same-seed replication is only guaranteed on the same stack: a different
    GPU architecture, CUDA/cuDNN build, precision policy or thread count can
    change every result.  Paired seed contrasts therefore carry this digest,
    and `pair_reason` refuses two records whose digests disagree.  Hostname and
    process id are deliberately excluded so two machines of the same class can
    still be compared; the GPU UUID is excluded for the same reason (hardware
    model and compute capability are the reproducibility-relevant part).
    """
    env = environment_snapshot() if env is None else env
    gpus = []
    for g in env.get('gpu_identity') or []:
        if not isinstance(g, dict):
            continue
        gpus.append({k: g.get(k) for k in ('name', 'major', 'minor', 'total_memory_bytes')})
    deps = env.get('dependencies') or {}
    fields = {
        'python': env.get('python'),
        'platform': env.get('platform'),
        'machine': env.get('machine'),
        'processor': env.get('processor'),
        'cpu_count': env.get('cpu_count'),
        'torch': env.get('torch'),
        'torch_git_version': env.get('torch_git_version'),
        'numpy': env.get('numpy'),
        'cuda_available': env.get('cuda_available'),
        'cuda_version': env.get('cuda_version'),
        'cudnn_version': env.get('cudnn_version'),
        'cuda_device_count': env.get('cuda_device_count'),
        'gpus': gpus,
        'determinism': env.get('determinism'),
        'cudnn_deterministic': env.get('cudnn_deterministic'),
        'cudnn_benchmark': env.get('cudnn_benchmark'),
        'deterministic_algorithms': env.get('deterministic_algorithms'),
        'tf32_matmul': env.get('tf32_matmul'),
        'tf32_cudnn': env.get('tf32_cudnn'),
        'fp16_reduced_precision_reduction': env.get('fp16_reduced_precision_reduction'),
        'bf16_reduced_precision_reduction': env.get('bf16_reduced_precision_reduction'),
        'float32_matmul_precision': env.get('float32_matmul_precision'),
        'cublas_workspace_config': env.get('cublas_workspace_config'),
        'cpu_threads': env.get('cpu_threads'),
        'cpu_interop_threads': env.get('cpu_interop_threads'),
        'packages': deps.get('packages') if isinstance(deps, dict) else None,
    }
    blob = json.dumps(fields, sort_keys=True, default=str, ensure_ascii=True)
    return hashlib.sha256(blob.encode('utf-8')).hexdigest()[:16]

def execution_environment_reason(ra, rb):
    """Why two records cannot attest same-environment replication, or None.

    Both-present is required for a verdict; legacy records without the digest
    keep the historical permissive path.  This is only about the execution
    environment, not the seed, data or recipe (those have their own gates).
    """
    def _fp(rec):
        v = rec.get('exec_fp')
        if v is None and isinstance(rec.get('hyperparams'), dict):
            v = rec['hyperparams'].get('exec_fp')
        return v
    a, b = _fp(ra), _fp(rb)
    ha = a is not None and str(a) != ''
    hb = b is not None and str(b) != ''
    if ha and hb and str(a) != str(b):
        return (f'different execution environment ({str(a)[:12]}… vs '
                f'{str(b)[:12]}…): same-seed replication is not controlled '
                'across hardware/driver/precision classes')
    return None

def _corpus_prefix_fp(train_ids, cap=None):
    """Fingerprint of the tokenizer-fit prefix, independent of training budget.

    `train_fp` hashes the *served* training stream, so a 5B-token tier and a
    12B-token tier over the same corpus necessarily disagree even when they
    share one tokenizer.  The first `TOKENIZER_FIT_TOKENS` ids are exactly the
    prefix the tokenizer was fitted on, and extending the training cap leaves
    that prefix unchanged.  Hash only that prefix so a scale ladder can attest
    "same corpus/tokenizer" without also requiring "same training volume".
    """
    if train_ids is None:
        return None
    try:
        arr = np.asarray(train_ids)
    except (TypeError, ValueError):
        return None
    if arr.ndim != 1:
        arr = arr.reshape(-1)
    _cap = TOKENIZER_FIT_TOKENS if cap is None else int(cap)
    if _cap <= 0 or arr.size == 0:
        return None
    return _ids_fp(np.ascontiguousarray(arr[:min(int(arr.size), _cap)]))

def _corpus_fp_from_data(data):
    """Budget-independent corpus/tokenizer identity.

    Deliberately excludes `requested_train_tokens`, `train_tokens`, `train_fp`
    and the split lengths: those change when a scale tier trains longer, but
    they do not change the corpus or tokenizer.  The tokenizer-fit prefix
    fingerprint covers the text actually used to fit the BPE (and therefore
    distinguishes different tokenisations even at equal vocabulary width).
    """
    keys = ('dataset', 'source', 'fw_fit_docs', 'vocab_size',
            'corpus_prefix_fp', 'data_extra')
    payload = {k: data.get(k) for k in keys if data.get(k) is not None}
    if not payload.get('corpus_prefix_fp'):
        return None
    blob = json.dumps(_jsonable(payload), sort_keys=True, separators=(',', ':'), ensure_ascii=True)
    return hashlib.sha256(blob.encode('utf-8')).hexdigest()[:16]

def _data_version(data):
    """Stable content digest of the corpus identity recorded in a panel.

    The token fingerprints already hash the exact ids seen; this composite
    makes the *data version* a single field a reader can compare across runs
    (dataset/protocol, token counts, vocabulary and both split fingerprints)
    without knowing which individual fields the loader happened to expose.
    `corpus_fp` (when present) is the budget-independent subset used by the
    scale ladder; `data_version` still identifies the exact served bytes.
    """
    keys = ('dataset', 'source', 'fw_fit_docs', 'requested_train_tokens', 'train_tokens', 'seq_len', 'vocab_size', 'val_sequences', 'train_fp', 'val_fp', 'eval_fp', 'cache_val_fp', 'corpus_fp', 'data_extra')
    payload = {k: data.get(k) for k in keys if data.get(k) is not None}
    blob = json.dumps(_jsonable(payload), sort_keys=True, separators=(',', ':'), ensure_ascii=True)
    return hashlib.sha256(blob.encode('utf-8')).hexdigest()[:16]

def code_provenance():
    """Code + environment provenance block, without any data section.

    Shared by `experiment_provenance` (training/panel records, which append the
    data fingerprints) and by `stamped_analysis` (derived/audit artifacts,
    which have no data of their own — their inputs are other stamped records
    or on-disk panels, so a `data` block here would be misleading)."""
    code = {'code_semantics': CODE_SEMANTICS, 'code_stamp': code_stamp(),
            'kernel_stamp': _kernel_stamp(), **_git_provenance()}
    # Content identity that survives a source tarball / dirty work tree.  It is
    # recorded after the git fields so a reader can compare both: the commit
    # answers "which revision", the tree digest answers "exactly which bytes".
    code['source_tree'] = source_tree_summary()
    return {'code': code, 'environment': environment_snapshot()}

def experiment_provenance(cfg, *, train_ids=None, val_batch=None, vocab=None):
    """Everything needed to identify a panel: code version (semantic stamp
    + git commit + dirty-worktree digest), environment, and the exact data
    bytes seen (token fingerprints + a composite data version)."""
    data = {'dataset': cfg.get('dataset') or 'wikitext', 'requested_train_tokens': cfg.get('n_train_tokens'), 'seq_len': cfg.get('seq_len')}
    for _k in ('cache_dir', 'fw_source', 'fw_fit_docs'):
        if cfg.get(_k) is not None:
            data[_k if _k != 'fw_source' else 'source'] = cfg.get(_k)
    if train_ids is not None:
        data['train_tokens'] = int(len(train_ids))
        data['train_fp'] = _ids_fp(train_ids)
        data['corpus_prefix_fp'] = _corpus_prefix_fp(train_ids)
    if val_batch is not None:
        _vb = np.ascontiguousarray(val_batch).reshape(-1)
        data['val_sequences'] = int(np.asarray(val_batch).shape[0])
        data['val_fp'] = _ids_fp(_vb)
    if vocab is not None:
        data['vocab_size'] = int(vocab)
    _extra = cfg.get('data_extra')
    if isinstance(_extra, dict):
        # Synthetic/task-specific generators (NIAH recipe, corruption modes)
        # must be part of the data identity, not only the human note.
        data['data_extra'] = _jsonable(_extra)
    # Record the source the loader is PINNED to.  The cache metadata records
    # what the bytes were actually built from; this field makes the intent
    # visible in every run/checkpoint record, and `audit_gates data_source`
    # checks the two against each other.  It is deliberately not added to
    # `_data_version` (the content fingerprints already bind the bytes).
    try:
        if data['dataset'] == 'wikitext':
            data['configured_dataset_source'] = wikitext_dataset_source()
        elif data['dataset'] == 'fineweb':
            data['configured_dataset_source'] = fineweb_cache_source(
                data.get('source') or 'sample-10BT')
    except ValueError:
        raise
    except Exception as _dse:
        data['configured_dataset_source'] = {
            'status': 'unresolved',
            'error': f'{type(_dse).__name__}: {_dse}',
        }
    # Compute the composite fingerprint AFTER data_extra is present:
    # `_corpus_fp_from_data` deliberately includes that key, so computing it
    # first made two distinct task/corruption corpora carry the same corpus_fp
    # (the field used by cross-scale corpus binding).
    _cfp = _corpus_fp_from_data(data)
    if _cfp is not None:
        data['corpus_fp'] = _cfp
    data['data_version'] = _data_version(data)
    prov = code_provenance()
    prov['data'] = data
    return prov

def run_hyperparameters(cfg, *, seed, d, n_layers, n_heads, d_head, vocab, mlp_ratio, data_version=None, amp_dtype='auto', eager_batch='auto'):
    """Structured hyper-parameter record (the run_cfg string stays the
    pairing gate; this is the human/machine-readable copy).

    ``amp_dtype`` / ``eager_batch`` must be the values the cell ACTUALLY ran,
    not a fresh inference from the current process's global device.  Callers
    that already have the training record pass its two fields here."""
    hp = {str(k): _jsonable(v) for k, v in cfg.items() if k not in ('seeds', 'variants', 'outdir')}
    hp.update({
        'seed': int(seed),
        'data_seed': int(seed),
        'rng': {
            'python': int(seed),
            'numpy': int(seed),
            'torch': int(seed),
            'cuda': int(seed),
            'tensorflow': int(seed),
            'data': int(seed),
            'eval_sampling': 0,
            'dataloader_generator': int(seed),
            'worker_seed_policy': 'torch.initial_seed() % 2**32',
        },
        'd': int(d),
        'n_layers': int(n_layers),
        'n_heads': int(n_heads),
        'd_head': int(d_head),
        'vocab_size': int(vocab),
        'mlp_ratio': float(mlp_ratio),
        'dataset': cfg.get('dataset') or 'wikitext',
        'exec_fp': execution_fingerprint(),
        'train_knobs': training_knobs(amp_dtype=amp_dtype, eager_batch=eager_batch),
        'determinism': {
            'level': determinism_label(),
            'cudnn_deterministic': bool(torch.backends.cudnn.deterministic),
            'cudnn_benchmark': bool(torch.backends.cudnn.benchmark),
            'deterministic_algorithms': bool(torch.are_deterministic_algorithms_enabled()),
            'tf32_matmul': (bool(torch.backends.cuda.matmul.allow_tf32) if torch.cuda.is_available() else None),
            'fp16_reduced_precision_reduction': (bool(torch.backends.cuda.matmul.allow_fp16_reduced_precision_reduction) if torch.cuda.is_available() else None),
            'bf16_reduced_precision_reduction': (bool(torch.backends.cuda.matmul.allow_bf16_reduced_precision_reduction) if torch.cuda.is_available() else None),
            'cublas_workspace_config': os.environ.get('CUBLAS_WORKSPACE_CONFIG'),
            'cpu_threads': int(torch.get_num_threads()),
            'pythonhashseed': os.environ.get('PYTHONHASHSEED'),
        },
    })
    _knobs = hp['train_knobs']
    hp['amp_dtype'] = _knobs.get('amp_dtype')
    hp['eager_batch'] = _knobs.get('eager_batch')
    if data_version is not None:
        hp['data_version'] = str(data_version)
    return hp

def write_run_manifest(outdir, cfg, run_cfg, prov, summary, sanity=None, reproducibility=None, *, data_contract=None, seed_contract=None, status=None, planned_cells=None, started_at=None, cell_records=None, tracking_verification=None):
    """Merge one panel's provenance/config/outcome summary into
    `outdir/run_manifest.json` under the same flock used by summary.json.

    The per-record `losses` / `ppl_history` curves stay in summary.json (to
    avoid duplicating large arrays); each manifest cell points at its key.
    `sanity` (the small-batch overfit reports), `reproducibility` (the
    duplicate-run seed check), `seed_contract` (the explicit RNG-source
    audit) and `data_contract` (the real batch iterator check) are embedded
    when supplied, or read back from `outdir/overfit_sanity.json` /
    `outdir/reproducibility.json` / `outdir/seed_contract.json` /
    `outdir/data_contract.json` so an auto-preflight is traceable without a
    second manual record.

    `status` / `planned_cells` make the manifest a crash-safe tracking record:
    `run()` writes it with status='running' before the first cell, so a killed
    process still leaves the code version, config, data version and the list
    of planned cells on disk; the final call marks it complete and lists any
    cell that produced no measurement."""
    os.makedirs(outdir, exist_ok=True)

    def _evidence_for_this_panel(doc, path, what):
        """Only evidence stamped with THIS panel's run_cfg may enter the
        manifest.  A run_cfg-less (legacy/hand-written) doc must say
        ``legacy: true`` explicitly; otherwise a stale pre-flight from a reused
        outdir could silently certify a new configuration."""
        if doc is None:
            return None
        if not isinstance(doc, dict):
            print(f'[track] WARNING: {what} evidence is not a JSON object ({type(doc).__name__}) — not embedding it in this panel')
            return None
        _rc = doc.get('run_cfg')
        if _rc is None:
            if doc.get('legacy') is True:
                print(f'[track] WARNING: {what} evidence ({path}) has no run_cfg and is explicitly marked legacy — embedding it as unverified legacy evidence')
                return doc
            print(f'[track] WARNING: {what} evidence ({path}) has NO run_cfg — refusing to embed it (it cannot be tied to this panel; mark legacy=True only for a deliberately imported old record)')
            return None
        if _rc != run_cfg:
            print(f'[track] WARNING: {what} evidence ({path}) belongs to a DIFFERENT run_cfg ({_rc!r} != {run_cfg!r}) — not embedding it in this panel (a stale pre-flight must not certify a new config)')
            return None
        return doc

    if sanity is None:
        _san_path = os.path.join(outdir, 'overfit_sanity.json')
        if os.path.exists(_san_path):
            try:
                with open(_san_path, encoding='utf-8') as _sf:
                    sanity = json.load(_sf)
            except Exception as _se:
                print(f'[track] WARNING: could not read {_san_path} for the run manifest ({type(_se).__name__}: {_se})')
    sanity = _evidence_for_this_panel(sanity, os.path.join(outdir, 'overfit_sanity.json'), 'sanity')
    if reproducibility is None:
        _rep_path = os.path.join(outdir, 'reproducibility.json')
        if os.path.exists(_rep_path):
            try:
                with open(_rep_path, encoding='utf-8') as _rf:
                    reproducibility = json.load(_rf)
            except Exception as _re:
                print(f'[track] WARNING: could not read {_rep_path} for the run manifest ({type(_re).__name__}: {_re})')
    reproducibility = _evidence_for_this_panel(reproducibility, os.path.join(outdir, 'reproducibility.json'), 'reproducibility')
    if data_contract is None:
        _bc_path = os.path.join(outdir, 'data_contract.json')
        if os.path.exists(_bc_path):
            try:
                with open(_bc_path, encoding='utf-8') as _bf:
                    data_contract = json.load(_bf)
            except Exception as _be:
                print(f'[track] WARNING: could not read {_bc_path} for the run manifest ({type(_be).__name__}: {_be})')
    data_contract = _evidence_for_this_panel(data_contract, os.path.join(outdir, 'data_contract.json'), 'data contract')
    if seed_contract is None:
        _sc_path = os.path.join(outdir, 'seed_contract.json')
        if os.path.exists(_sc_path):
            try:
                with open(_sc_path, encoding='utf-8') as _scf:
                    seed_contract = json.load(_scf)
            except Exception as _sce:
                print(f'[track] WARNING: could not read {_sc_path} for the run manifest ({type(_sce).__name__}: {_sce})')
    seed_contract = _evidence_for_this_panel(seed_contract, os.path.join(outdir, 'seed_contract.json'), 'seed contract')
    if cell_records is not None:
        # Custom phases (warmup/NIAH/lenphase) have their own summary keys and
        # metrics (PPL with warm-grid keys, NIAH accuracy, by-length PPL).
        # They build already-normalised cell records and use the same
        # crash-safe manifest/provenance/integrity machinery as run().
        cells = {str(k): dict(v) for k, v in dict(cell_records).items() if isinstance(v, dict)}
    else:
        cells = {}
        for seed in cfg.get('seeds') or []:
            for v in cfg.get('variants') or []:
                key = f'{v}::seed{seed}'
                rec = summary.get(key)
                if not isinstance(rec, dict) or not ppl_is_usable(rec.get('ppl')) or rec.get('synthesized'):
                    continue
                _curves = _cell_curve_data(outdir, rec)
                _losses = rec.get('losses') if isinstance(rec.get('losses'), list) else (_curves.get('losses') if isinstance(_curves.get('losses'), list) else [])
                _loss_nums = [float(x) for x in _losses if isinstance(x, (int, float)) and not isinstance(x, bool)]
                _ph = rec.get('ppl_history') if isinstance(rec.get('ppl_history'), list) else (_curves.get('ppl_history') if isinstance(_curves.get('ppl_history'), list) else [])
                if not _losses and rec.get('curve_n_points') is not None:
                    _loss_nums = []
                cells[key] = {
                    'variant': v,
                    'seed': int(seed),
                    'run_id': rec.get('run_id'),
                    'run_cfg': rec.get('run_cfg'),
                    'started_at': rec.get('started_at'),
                    'finished_at': rec.get('finished_at'),
                    'ppl': rec.get('ppl'),
                    'steps': rec.get('steps'),
                    'tokens_seen': rec.get('tokens_seen'),
                    'params': rec.get('params'),
                    'train_time_s': rec.get('train_time_s'),
                    'final_loss_smoothed': rec.get('final_loss_smoothed'),
                    'rng_fp': rec.get('rng_fp'),
                    'exec_fp': rec.get('exec_fp'),
                    'data_fp': rec.get('data_fp'),
                    'val_fp': rec.get('val_fp'),
                    'data_version': rec.get('data_version') or prov.get('data', {}).get('data_version'),
                    'corpus_fp': rec.get('corpus_fp') or prov.get('data', {}).get('corpus_fp'),
                    'code_stamp': rec.get('_code'),
                    'hyperparams': rec.get('hyperparams'),
                    'curve_summary': {'n_points': (len(_losses) if _losses else int(rec.get('curve_n_points') or 0)),
                                      'first': _loss_nums[0] if _loss_nums else rec.get('curve_first'),
                                      'last': _loss_nums[-1] if _loss_nums else rec.get('curve_last'),
                                      'best': min(_loss_nums) if _loss_nums else rec.get('curve_best'),
                                      'ppl_history_points': (len(_ph) if _ph else int(rec.get('ppl_history_n_points') or 0))},
                    'curve_ref': rec.get('curve_ref') or f'summary.json#{key}.losses',
                    'curve_sha256': rec.get('curve_sha256'),
                    'ppl_history_ref': rec.get('ppl_history_ref') or f'summary.json#{key}.ppl_history',
                    'ppl_history_sha256': rec.get('ppl_history_sha256'),
                    'sanity_ref': rec.get('sanity_ref') or ('overfit_sanity.json' if sanity else None),
                }
    if planned_cells is None:
        planned_cells = [f'{v}::seed{seed}' for seed in cfg.get('seeds') or [] for v in cfg.get('variants') or []]
    planned_cells = [str(_k) for _k in dict.fromkeys(planned_cells)]

    def _curve_ref_ok(cell):
        for _key in ('curve_ref', 'ppl_history_ref'):
            _ref = cell.get(_key) if isinstance(cell, dict) else None
            if not _ref or '#' in str(_ref):
                continue
            if not os.path.exists(os.path.join(outdir, str(_ref))):
                return False
        return True
    # Machine-checkable completeness of the per-cell trace.  A record without
    # provenance/hyperparameters/RNG fingerprint/curve is still a measurement,
    # but it must not silently look as traceable as a complete one.
    #
    # Seed metadata is checked against the RESUME KEY, not against itself: a
    # record copied/mis-keyed under `seed3` with `seed=2` would otherwise count
    # as a third independent seed while actually duplicating the second.
    _seed_mismatch = []
    _seed_ok = 0
    _run_cfg_mismatch = []
    _data_version_mismatch = []
    for _key, _c in cells.items():
        try:
            _expected = int(str(_key).rsplit('::seed', 1)[1])
        except (ValueError, IndexError):
            _seed_mismatch.append(_key)
            continue
        _hp = _c.get('hyperparams') if isinstance(_c.get('hyperparams'), dict) else {}
        _rng = _hp.get('rng') if isinstance(_hp.get('rng'), dict) else {}
        try:
            _vals = [int(_hp.get('seed'))] if _hp.get('seed') is not None else []
            if _hp.get('data_seed') is not None:
                _vals.append(int(_hp.get('data_seed')))
            _vals.extend(int(_rng[k]) for k in ('python', 'numpy', 'torch', 'cuda', 'tensorflow',
                                                'data', 'dataloader_generator') if _rng.get(k) is not None)
            _ok = (bool(_c.get('seed') is not None) and int(_c.get('seed')) == _expected
                   and all(v == _expected for v in _vals))
        except (TypeError, ValueError, OverflowError):
            _ok = False
        if _ok:
            _seed_ok += 1
        else:
            _seed_mismatch.append(_key)
        if _c.get('run_cfg') not in (None, run_cfg):
            _run_cfg_mismatch.append(_key)
        _cell_dv = _c.get('data_version')
        _hp_dv = _hp.get('data_version')
        if _cell_dv is not None and _hp_dv is not None and str(_cell_dv) != str(_hp_dv):
            _data_version_mismatch.append(_key)
    try:
        _declared_seeds = [int(x) for x in (cfg.get('seeds') or [])]
    except (TypeError, ValueError, OverflowError):
        _declared_seeds = []
    _integrity = {
        'n_cells': len(cells),
        'seeds_declared': _declared_seeds,
        'seeds_unique': bool(len(_declared_seeds) == len(set(_declared_seeds))),
        'with_seed_metadata': _seed_ok,
        'seed_metadata_mismatch': _seed_mismatch[:20],
        'with_provenance': sum(1 for c in cells.values() if c.get('data_fp') and c.get('code_stamp')),
        'with_hyperparams': sum(1 for c in cells.values() if c.get('hyperparams')),
        'with_rng_fp': sum(1 for c in cells.values() if c.get('rng_fp')),
        'with_exec_fp': sum(1 for c in cells.values() if c.get('exec_fp')),
        'with_data_version': sum(1 for c in cells.values() if c.get('data_version')),
        'with_curve': sum(1 for c in cells.values() if (c.get('curve_summary') or {}).get('n_points')),
        'with_curve_hash': sum(1 for c in cells.values() if c.get('curve_sha256')),
        'with_sanity_ref': sum(1 for c in cells.values() if c.get('sanity_ref')),
        'with_data_contract': int(bool(isinstance(data_contract, dict) and data_contract.get('passed'))),
        'with_seed_contract': int(bool(isinstance(seed_contract, dict) and seed_contract.get('passed'))),
    }
    # Counts alone let a cell that is missing its code stamp / hyperparameters /
    # data version / RNG fingerprint / curve still look like a normal member of
    # a "complete" panel.  Name the incomplete cells and make panel completion
    # a single machine-readable verdict, so an automated reader cannot mistake
    # a partially traced panel for a fully reproducible one.
    _missing_cells = [str(k) for k in planned_cells if k not in cells]
    _incomplete_cells = []
    _missing_curve_refs = []
    for _k, _c in cells.items():
        _hp2 = _c.get('hyperparams') if isinstance(_c.get('hyperparams'), dict) else {}
        _curve_n = (_c.get('curve_summary') or {}).get('n_points')
        _ref_ok = _curve_ref_ok(_c)
        if not _ref_ok:
            _missing_curve_refs.append(str(_k))
        if not (_c.get('code_stamp') and _hp2 and _c.get('data_version')
                and _c.get('rng_fp') and _curve_n and _ref_ok):
            _incomplete_cells.append(str(_k))
    _integrity['complete_cells'] = len(cells) - len(_incomplete_cells)
    _integrity['incomplete_cells'] = _incomplete_cells[:20]
    _integrity['missing_cells'] = _missing_cells[:20]
    _integrity['missing_curve_refs'] = _missing_curve_refs[:20]
    _integrity['run_cfg_mismatch'] = _run_cfg_mismatch[:20]
    _integrity['data_version_mismatch'] = _data_version_mismatch[:20]
    _integrity['complete'] = bool(not _incomplete_cells and not _missing_cells
                                  and not _seed_mismatch and not _missing_curve_refs
                                  and not _run_cfg_mismatch and not _data_version_mismatch)
    _declared_status = status or 'complete'
    if _declared_status in ('running', 'failed', 'error', 'incomplete'):
        _completion_status = _declared_status
    else:
        _completion_status = 'complete' if _integrity['complete'] else 'incomplete'
    _completion = {
        'status': _completion_status,
        # A panel explicitly declared incomplete/failed/running is not complete
        # just because its recorded cells happen to be trace-complete.  The
        # boolean is a conjunction of the declared terminal state and the
        # per-cell integrity verdict.
        'complete': bool(_integrity['complete'] and _completion_status == 'complete'),
        'n_planned': len(planned_cells),
        'n_measured': len(cells),
        'n_missing': len(_missing_cells),
        'missing_cells': _missing_cells[:20],
        'incomplete_cells': _incomplete_cells[:20],
        'incomplete_reasons': ('missing measurement for every planned cell; '
                               'each measured cell carries code/hyperparameters/'
                               'data_version/rng_fp/curve and seed metadata'
                               if _integrity['complete'] else
                               'panel is not fully traced: see missing_cells / '
                               'incomplete_cells / missing_curve_refs / '
                               'seed_metadata_mismatch / run_cfg_mismatch / '
                               'data_version_mismatch'),
    }
    _prod_evidence = None
    if isinstance(sanity, dict) and isinstance(sanity.get('production_loop'), dict):
        _prod_evidence = bool((sanity.get('production_loop') or {}).get('passed'))
    _evidence = {
        'small_batch_overfit': (bool(sanity.get('passed')) if isinstance(sanity, dict) else None),
        'production_loop_overfit': _prod_evidence,
        'same_machine_reproducibility': (bool(reproducibility.get('passed')) if isinstance(reproducibility, dict) else None),
        'rng_seed_contract': (bool(seed_contract.get('passed')) if isinstance(seed_contract, dict) else None),
        'batch_iterator_contract': (bool(data_contract.get('passed')) if isinstance(data_contract, dict) else None),
    }
    entry = {
        'run_cfg': run_cfg,
        'status': status or 'complete',
        'created_at': started_at or time.strftime('%Y-%m-%dT%H:%M:%S'),
        'updated_at': time.strftime('%Y-%m-%dT%H:%M:%S'),
        'config': _jsonable(cfg),
        'provenance': prov,
        'data_version': prov.get('data', {}).get('data_version'),
        'corpus_fp': prov.get('data', {}).get('corpus_fp'),
        'sanity': sanity,
        'reproducibility': reproducibility,
        'seed_contract': seed_contract,
        'data_contract': data_contract,
        'tracking_verification': tracking_verification,
        'evidence': _evidence,
        'experiment_log': 'experiments.jsonl',
        'tracking_schema': 2,
        'planned_cells': planned_cells,
        'n_planned': len(planned_cells),
        'n_completed': len(cells),
        'missing_cells': _missing_cells,
        'completion': _completion,
        'tracking_integrity': _integrity,
        'cells': cells,
    }
    path = os.path.join(outdir, 'run_manifest.json')

    def _merge(m):
        if not isinstance(m, dict):
            m = {}
        m['manifest_version'] = m.get('manifest_version') or 1
        _prev = m.setdefault('panels', {}).get(run_cfg)
        if isinstance(_prev, dict) and _prev.get('created_at') and status != 'running':
            entry['created_at'] = _prev['created_at']
        m['panels'][run_cfg] = entry
        return m
    locked_json_update(path, _merge)
    return path

def verify_run_tracking(outdir, run_cfg=None, *, require_ppl=True):
    """Independently verify one panel's on-disk trace.

    `write_run_manifest` builds the trace; this function reads it back from
    disk and re-derives the checks a reader would otherwise have to trust:
    every planned cell has a record, a code stamp, hyperparameters including
    the full RNG map, a data version, a final result, and a curve whose
    recorded digest still matches the file.  It is read-only and never touches
    the test split, so it can run at the end of every panel (and by hand on an
    archived outdir).

    Returns a JSON-safe verdict.  Missing legacy fields are reported as
    problems for a current panel; `warnings` carries non-fatal notes.
    """
    problems = []
    warnings = []
    outdir = os.path.abspath(outdir)
    manifest_path = os.path.join(outdir, 'run_manifest.json')
    summary_path = os.path.join(outdir, 'summary.json')
    if not os.path.exists(manifest_path):
        return {'kind': 'run_tracking_verification', 'outdir': outdir,
                'run_cfg': run_cfg, 'passed': False,
                'problems': ['run_manifest.json is missing'],
                'warnings': [], 'n_checked': 0}
    try:
        with open(manifest_path, encoding='utf-8') as f:
            manifest = json.load(f)
    except Exception as e:
        return {'kind': 'run_tracking_verification', 'outdir': outdir,
                'run_cfg': run_cfg, 'passed': False,
                'problems': [f'run_manifest.json cannot be parsed: {type(e).__name__}: {e}'],
                'warnings': [], 'n_checked': 0}
    panels = manifest.get('panels') if isinstance(manifest, dict) else None
    if not isinstance(panels, dict) or not panels:
        return {'kind': 'run_tracking_verification', 'outdir': outdir,
                'run_cfg': run_cfg, 'passed': False,
                'problems': ['run_manifest.json has no panels'], 'warnings': [],
                'n_checked': 0}
    if run_cfg is None:
        # Newest panel by created_at / updated_at; insertion order is the
        # fallback for legacy manifests without timestamps.
        def _stamp(entry):
            return str((entry or {}).get('updated_at') or (entry or {}).get('created_at') or '')
        run_cfg = max(panels, key=lambda k: _stamp(panels.get(k)))
    entry = panels.get(run_cfg)
    if not isinstance(entry, dict):
        return {'kind': 'run_tracking_verification', 'outdir': outdir,
                'run_cfg': run_cfg, 'passed': False,
                'problems': [f'panel {run_cfg!r} is absent from run_manifest.json'],
                'warnings': [], 'n_checked': 0}
    try:
        with open(summary_path, encoding='utf-8') as f:
            summary = json.load(f)
    except Exception as e:
        summary = {}
        problems.append(f'summary.json cannot be parsed: {type(e).__name__}: {e}')
    if not isinstance(summary, dict):
        problems.append('summary.json is not a JSON object')
        summary = {}
    planned = [str(k) for k in (entry.get('planned_cells') or [])]
    if not planned:
        problems.append('panel records no planned_cells')
    cells = entry.get('cells') if isinstance(entry.get('cells'), dict) else {}
    prov_dv = ((entry.get('provenance') or {}).get('data') or {}).get('data_version')
    checked = 0
    for key in planned:
        checked += 1
        rec = summary.get(key)
        cell = cells.get(key)
        if not isinstance(rec, dict):
            problems.append(f'{key}: no summary record')
            continue
        if not isinstance(cell, dict):
            problems.append(f'{key}: no manifest cell entry')
            cell = {}
        if not rec.get('_code'):
            problems.append(f'{key}: record has no code stamp')
        if cell.get('code_stamp') and rec.get('_code') and cell['code_stamp'] != rec.get('_code'):
            problems.append(f'{key}: manifest code_stamp disagrees with the record')
        hp = rec.get('hyperparams') if isinstance(rec.get('hyperparams'), dict) else {}
        if not hp:
            problems.append(f'{key}: record has no hyperparameters')
        if not cell.get('hyperparams'):
            problems.append(f'{key}: manifest cell has no hyperparameters')
        rng = hp.get('rng') if isinstance(hp.get('rng'), dict) else {}
        if not rng:
            problems.append(f'{key}: hyperparameters have no RNG map')
        try:
            _expected = int(str(key).rsplit('::seed', 1)[1])
        except (ValueError, IndexError):
            _expected = None
        if _expected is None:
            problems.append(f'{key}: key does not name a seed')
        else:
            _seed_vals = [hp.get('seed'), hp.get('data_seed')]
            _seed_vals += [rng.get(k) for k in ('python', 'numpy', 'torch', 'cuda', 'tensorflow', 'data', 'dataloader_generator')]
            if any(v is None for v in _seed_vals):
                problems.append(f'{key}: RNG map is incomplete')
            elif any(int(v) != _expected for v in _seed_vals):
                problems.append(f'{key}: seed metadata disagrees with the key')
        dv = rec.get('data_version') or cell.get('data_version')
        if not dv:
            problems.append(f'{key}: record has no data_version')
        elif prov_dv and str(dv) != str(prov_dv):
            problems.append(f'{key}: data_version disagrees with the panel provenance')
        if not rec.get('rng_fp'):
            problems.append(f'{key}: record has no rng_fp')
        if not rec.get('exec_fp'):
            warnings.append(f'{key}: record has no exec_fp (legacy record)')
        if require_ppl and not ppl_is_usable(rec.get('ppl')):
            problems.append(f'{key}: no usable final PPL/result')
        ref = rec.get('curve_ref')
        losses = rec.get('losses') if isinstance(rec.get('losses'), list) else []
        if ref and '#' not in str(ref):
            path = os.path.join(outdir, str(ref))
            if not os.path.exists(path):
                problems.append(f'{key}: curve sidecar {ref!r} is missing')
            else:
                want = rec.get('curve_sha256') or cell.get('curve_sha256')
                got = _file_sha256(path)
                if want and got != want:
                    problems.append(f'{key}: curve sidecar digest no longer matches the record')
                elif not want:
                    warnings.append(f'{key}: curve sidecar has no recorded digest')
                try:
                    with open(path, encoding='utf-8') as f:
                        payload = json.load(f)
                    if not isinstance(payload, dict):
                        problems.append(f'{key}: curve sidecar is not a JSON object')
                    elif not (payload.get('losses') or payload.get('ppl_history')):
                        problems.append(f'{key}: curve sidecar contains no curve data')
                except Exception as e:
                    problems.append(f'{key}: curve sidecar cannot be parsed ({type(e).__name__}: {e})')
        elif not losses and not rec.get('curve_n_points'):
            problems.append(f'{key}: no training curve (inline or sidecar)')
        ph_ref = rec.get('ppl_history_ref')
        if ph_ref and '#' not in str(ph_ref):
            ph_path = os.path.join(outdir, str(ph_ref))
            if not os.path.exists(ph_path):
                problems.append(f'{key}: ppl_history sidecar {ph_ref!r} is missing')
            else:
                want = rec.get('ppl_history_sha256') or cell.get('ppl_history_sha256')
                if want and _file_sha256(ph_path) != want:
                    problems.append(f'{key}: ppl_history sidecar digest no longer matches the record')
    verdict = {
        'kind': 'run_tracking_verification',
        'created_at': time.strftime('%Y-%m-%dT%H:%M:%S'),
        'outdir': outdir,
        'run_cfg': run_cfg,
        'panel_status': entry.get('status'),
        'panel_completion': entry.get('completion'),
        'n_planned': len(planned),
        'n_checked': checked,
        'problems': problems,
        'warnings': warnings,
        'passed': bool(not problems),
    }
    verdict['diagnosis'] = ('ok' if not problems else
                            f'{len(problems)} tracking problem(s); first: {problems[0]}')
    return verdict

_EVAL_TOKENS_PER_CHUNK = 1 << 20


def _eval_row_working_bytes(model, T, d, elem_size, bytes_per_value=8):
    """Conservative per-row activation/workspace estimate for one eval row.

    The dense `T*d` term is only the hidden-state floor.  Long-sequence
    workspace is usually set by the attention workspace instead: a full/sink
    head materialises [nh, rows, T] logits, the CSA indexer scores [T, B_blocks,
    nIH], and HCA's arange expansion is [T, B_blocks].  Estimate the largest of
    those per layer (layers run one at a time under inference_mode) rather than
    the hidden state alone."""
    T = max(1, int(T))
    d = max(1, int(d))
    elem = max(1, int(elem_size))
    per_row = max(1, T * d * elem * max(1, int(bytes_per_value)))
    for blk in getattr(model, 'blocks', []):
        attn = getattr(blk, 'attn', None)
        cfg = getattr(attn, 'cfg', None)
        if cfg is None:
            continue
        nh = max(1, int(getattr(attn, 'nh', 1) or 1))
        kind = getattr(cfg, 'kind', 'full')
        if kind == 'full':
            win = max(0, int(getattr(cfg, 'window', 0) or 0))
            if getattr(attn, 'sink', None) is not None or getattr(cfg, 'full_sink', False):
                span = T
            elif 0 < win < T:
                span = win
            else:
                span = min(T, 1024)
            attn_bytes = 3 * nh * T * span * elem
        else:
            bs = int(getattr(cfg, 'block_size', 0) or 0)
            tgt = int(getattr(cfg, 'target_block_tokens', 0) or 0)
            mn = max(1, int(getattr(cfg, 'min_block', 1) or 1))
            step = max(1, bs or tgt or mn)
            Bm = (T + step - 1) // step
            nih = max(1, int(getattr(cfg, 'n_index_heads', 1) or 1))
            topk = max(1, int(getattr(cfg, 'index_topk', 1) or 1))
            hd = max(1, int(getattr(attn, 'hd', 1) or 1))
            win = max(0, int(getattr(cfg, 'sliding_window', 0) or 0))
            # HCA reads every block (arange expansion), so its effective
            # selection width is Bm; CSA only scores min(topk, Bm) blocks.
            nb_eff = Bm if kind == 'hca' else min(topk, Bm)
            M = nb_eff + win
            gather_bytes = (4 * M * nh * hd + 2 * M * nh) * elem
            index_bytes = min(2 * T * Bm * nih * elem, 384 << 20) if kind != 'hca' else 0
            attn_bytes = max(index_bytes, gather_bytes)
            if kind == 'hca':
                # _arange_exp_cache is a stride-0 expand view: its physical
                # storage is one int32 [Bm] row, not [T, Bm].
                attn_bytes = max(attn_bytes, 4 * Bm)
        per_row = max(per_row, int(attn_bytes))
    return per_row


def _eval_adaptive_chunk(model, val_batch, device, chunk, _free_frac=0.5, _bytes_per_value=8):
    """Bound an evaluation chunk by both token count and currently-free device capacity.

    Rows are independent, so the partition changes no value; it only keeps a
    long-sequence eval from launching a chunk whose attention/indexer
    workspace cannot fit.  The estimate uses the model's actual parameter
    element size (bf16 halves it) and the real per-layer attention shape, not
    just `T*d`; the existing OOM retry remains the final backstop."""
    rows = int(val_batch.shape[0])
    T = int(val_batch.shape[1])
    span = max(1, T - 1)
    chunk = min(max(1, int(chunk)), max(1, _EVAL_TOKENS_PER_CHUNK // span))
    if device.type == 'cuda' and rows > 0:
        try:
            free, _total = torch.cuda.mem_get_info(device)
            d = int(model.tok.weight.shape[1])
            elem = int(model.tok.weight.element_size())
            per_row = _eval_row_working_bytes(model, T, d, elem, _bytes_per_value)
            chunk = min(chunk, max(1, int(free * float(_free_frac)) // per_row))
        except Exception:
            pass
    return max(1, min(chunk, rows))


def _det_segment_sum(n_rows, indices, values, dtype=None, sorted_indices=False):
    """Deterministic scatter-add by stable sort + segmented prefix sums.

    CUDA's ``index_add_``/``index_put_(accumulate=True)`` use atomics, so the
    addition order (and the last-bit result) can depend on thread scheduling.
    Sorting by (index, original position) fixes the order; segment sums are
    then formed with a cumsum and written through ``index_copy_`` (unique
    destinations, no atomics).  Mirrors ``csa_kernels._det_scatter_add``: the
    output keeps the caller's dtype, but floating (and complex) sums accumulate
    in float64/complex128 before the final cast.  A shared prefix from an early
    segment otherwise rounds away every later small segment in fp32, and the
    loss grows with the number of rows/segments.

    ``sorted_indices=True`` promises the flattened indices are already
    non-decreasing (the sampled-eval path maps a sorted global-row table, so
    its per-chunk rows are sorted by construction).  The stable sort is then
    an identity permutation and is skipped; every element keeps the same
    position the sort would have given it, so the segmented sums are
    bit-identical while the sort's time and workspace disappear."""
    idx = indices.reshape(-1).to(torch.int64)
    vals = values.reshape(-1)
    out_dtype = dtype if dtype is not None else vals.dtype
    out = torch.zeros(int(n_rows), device=vals.device, dtype=out_dtype)
    if idx.numel() == 0:
        return out
    valid = (idx >= 0) & (idx < int(n_rows))
    if not bool(valid.all()):
        idx = idx[valid]
        vals = vals[valid]
        if idx.numel() == 0:
            return out
    if out_dtype.is_complex:
        _acc = torch.complex128
    elif out_dtype.is_floating_point:
        _acc = torch.float64
    else:
        # Integer destinations (token counts) stay exact; int64 is the widest
        # representation the destination can require and avoids an unnecessary
        # float round-trip.
        _acc = torch.int64
    if sorted_indices:
        idx_s = idx
        val_s = vals.to(_acc)
    else:
        order = torch.argsort(idx, stable=True)
        idx_s = idx.index_select(0, order)
        val_s = vals.index_select(0, order).to(_acc)
    end = torch.ones_like(idx_s, dtype=torch.bool)
    if idx_s.numel() > 1:
        end[:-1] = idx_s[1:] != idx_s[:-1]
    seg_end = torch.nonzero(end, as_tuple=False).reshape(-1)
    csum = torch.cumsum(val_s, dim=0)
    hi = csum.index_select(0, seg_end)
    lo = torch.zeros_like(hi)
    if seg_end.numel() > 1:
        lo[1:] = csum.index_select(0, seg_end[:-1])
    seg_sum = hi - lo
    seg_id = idx_s.index_select(0, seg_end)
    out.index_copy_(0, seg_id, seg_sum.to(out_dtype))
    return out


def document_index(doc_ids):
    """Compact, deterministic index for an arbitrary per-token document-id array.

    Returns ``(keys, inverse)`` where ``keys`` is the sorted unique document
    id array and ``inverse`` maps every element back to its position in
    ``keys``.  The same ``(keys, inverse)`` pair can be sliced for several
    evaluation lengths/chunks, so document order cannot change between them.

    Document ids are uint64 hashes; converting them to a dense index avoids
    materialising a huge [n_docs] tensor indexed by the raw hash value.  The
    function is intentionally NumPy-only and rejects non-integer / negative
    ids, because a float id such as ``1.5`` would silently become document 1.
    """
    arr = np.asarray(doc_ids)
    if arr.size == 0:
        raise ValueError('document_index: document ids are empty')
    if arr.dtype.kind not in 'iu':
        raise ValueError(
            f'document_index: document ids must be integers, got dtype {arr.dtype}')
    if arr.dtype.kind == 'i' and int(arr.min()) < 0:
        raise ValueError('document_index: document ids must be non-negative')
    keys, inv = np.unique(arr.reshape(-1), return_inverse=True)
    return keys, inv.reshape(arr.shape)


def aggregate_nll_by_document(nll, doc_ids, *, document_index_map=None):
    """Aggregate a per-target NLL matrix into per-DOCUMENT NLL / PPL.

    ``nll`` is a ``[n_rows, span]`` (or flat) tensor/array of next-token NLLs;
    ``doc_ids`` has exactly the same shape and gives the document identity of
    each predicted target token.  Fixed evaluation rows are arbitrary windows,
    so a document can span several rows and a row can mix several documents;
    summing by row and calling each row a document double-counts documents in
    the bootstrap.  This function groups tokens by document identity instead.

    ``document_index_map`` is the ``(keys, inverse)`` returned by
    :func:`document_index` for the FULL target slice.  Supplying it makes
    chunked evaluation use one global document order; when omitted it is
    computed here.  Documents with no target in this slice (the map came from a
    longer prefix) are omitted from the returned vectors rather than reported
    with a zero token count and a NaN PPL: a document that has not started yet
    is not an evaluation unit of this cell.
    """
    if not torch.is_tensor(nll):
        nll = torch.as_tensor(nll)
    arr = np.asarray(doc_ids)
    if tuple(arr.shape) != tuple(nll.shape):
        raise ValueError(
            f'aggregate_nll_by_document: doc_ids shape {arr.shape} != nll shape '
            f'{tuple(nll.shape)}')
    if document_index_map is None:
        keys, inv = document_index(arr)
    else:
        try:
            keys, inv = document_index_map
        except (TypeError, ValueError):
            raise ValueError(
                'aggregate_nll_by_document: document_index_map must be a '
                '(keys, inverse) pair') from None
        keys = np.asarray(keys)
        inv = np.asarray(inv)
        if keys.ndim != 1 or keys.size == 0:
            raise ValueError(
                'aggregate_nll_by_document: document_index_map keys must be a '
                f'non-empty 1-D array, got shape {keys.shape}')
        if keys.dtype.kind not in 'iu':
            raise ValueError(
                'aggregate_nll_by_document: document_index_map keys must be '
                f'integers, got dtype {keys.dtype}')
        if keys.dtype.kind == 'i' and int(keys.min()) < 0:
            raise ValueError(
                'aggregate_nll_by_document: document_index_map keys must be '
                'non-negative')
        if inv.dtype.kind not in 'iu':
            raise ValueError(
                'aggregate_nll_by_document: document_index_map inverse must be '
                f'integers, got dtype {inv.dtype}')
        if inv.size != int(nll.numel()):
            raise ValueError(
                f'aggregate_nll_by_document: index covers {inv.size} targets, '
                f'expected {int(nll.numel())}')
        if inv.size:
            _inv_min = int(inv.min())
            _inv_max = int(inv.max())
            if _inv_min < 0 or _inv_max >= int(keys.size):
                raise ValueError(
                    'aggregate_nll_by_document: document_index_map inverse '
                    f'spans [{_inv_min}, {_inv_max}] but there are only '
                    f'{int(keys.size)} documents')
        inv = inv.reshape(arr.shape)
        # A map for a longer prefix is valid here, but it must still describe
        # THIS slice's identities.  Without this check a stale/mismatched map
        # would silently regroup the same tokens into different documents.
        if not np.array_equal(keys[inv.reshape(-1)], arr.reshape(-1)):
            raise ValueError(
                'aggregate_nll_by_document: document_index_map does not match '
                'doc_ids; refusing to regroup tokens under a different map')
    n_docs = int(keys.size)
    idx = torch.as_tensor(inv.reshape(-1).astype(np.int64, copy=False),
                          dtype=torch.long, device=nll.device)
    vals = nll.reshape(-1)
    nll_doc = _det_segment_sum(n_docs, idx, vals,
                               dtype=torch.float64).detach().cpu().tolist()
    tok_doc = _det_segment_sum(
        n_docs, idx, torch.ones_like(idx), dtype=torch.long
    ).detach().cpu().tolist()
    n_tokens = [int(x) for x in tok_doc]
    nll_values = [float(x) for x in nll_doc]
    # Drop documents that have no target in this slice.  A global map (built
    # on the longest requested prefix) otherwise carries documents that start
    # later, giving them 0 tokens and NaN PPL; that inflates n_docs and makes
    # the per-document vectors length-inconsistent for no measurement reason.
    _present = [i for i, n in enumerate(n_tokens) if n > 0]
    keys_present = np.asarray(keys)[_present]
    nll_values = [nll_values[i] for i in _present]
    n_tokens = [n_tokens[i] for i in _present]
    ppl = [float(_safe_exp_ppl(nll_values[i] / n_tokens[i]))
           for i in range(len(_present))]
    return {
        'doc_granularity': 'document',
        'n_docs': len(_present),
        'nll_per_doc': nll_values,
        'n_tokens_per_doc': n_tokens,
        'ppl_per_doc': ppl,
        'doc_ids': [format(int(k), '016x') for k in keys_present.tolist()],
        'doc_ids_fp': _ids_fp(keys_present),
        'nll_per_doc_total': float(sum(nll_values)),
        'n_tokens_total': int(sum(n_tokens)),
    }


def aggregate_nll_by_article(nll, article_ids, *, document_index_map=None):
    """Aggregate per-target NLL into per-ARTICLE NLL / PPL.

    WikiText rows are lines, not articles; a line-level bootstrap resamples
    paragraphs of the same article and therefore understates the sampling
    uncertainty of an article-level claim.  This is the same deterministic
    segment sum as :func:`aggregate_nll_by_document`, with article-named
    fields so a consumer cannot mistake one unit for the other.

    The pooled totals are identical to the document aggregation for the SAME
    targets (only the grouping differs); the caller keeps both vectors so the
    frozen line-level contract is untouched and the article-level readout is
    additive evidence.
    """
    doc = aggregate_nll_by_document(
        nll, article_ids, document_index_map=document_index_map)
    n_articles = int(doc['n_docs'])
    return {
        'article_granularity': 'article',
        'unit_definition': ('top-level " = Title = " article; rows are lines '
                            'and are not independent of their article'),
        'n_articles': n_articles,
        'nll_per_article': list(doc['nll_per_doc']),
        'n_tokens_per_article': list(doc['n_tokens_per_doc']),
        'ppl_per_article': list(doc['ppl_per_doc']),
        'article_ids': list(doc['doc_ids']),
        'article_ids_fp': doc['doc_ids_fp'],
        'nll_per_article_total': float(doc['nll_per_doc_total']),
        'n_tokens_article_total': int(doc['n_tokens_total']),
        'article_source': 'per_token_article_map',
    }


@torch.inference_mode()
def eval_ppl(model, val_batch, device, chunk=8, eval_rows=None, eval_seed=0, return_stats=False,
             collect_block_stats=False, val_bnd=None, bnd_tol=1):
    # `collect_block_stats=True` enables the compression-report hooks for this
    # same forward pass, so block-length/boundary diagnostics come from it too.
    # A chunk is a set of independent sequences (no cross-row op in the
    # model), so capping it by token count does not change any per-row value.
    _span = max(1, int(val_batch.shape[1]) - 1)
    chunk = _eval_adaptive_chunk(model, val_batch, device, chunk)
    was_training = model.training
    model.eval()
    need_reg_layers = [blk.attn for blk in model.blocks if hasattr(blk.attn, 'need_reg')]
    need_reg_prior = [_a.need_reg for _a in need_reg_layers]
    nll = torch.zeros((), dtype=torch.float64, device=device)
    # Per-ROW NLL (eval-subset uncertainty must be visible, not only the
    # seed-to-seed spread).  A row is a fixed evaluation WINDOW, not
    # necessarily one document: use `eval_length_gen` with a per-token
    # document mapping when a document-level bootstrap is required.  With
    # eval_rows sampling, a row with no sampled target gets 0 tokens and is
    # excluded by the bootstrap consumer.
    _row_nll = torch.zeros(int(val_batch.shape[0]), dtype=torch.float64, device=device) if return_stats else None
    _row_ntok = torch.zeros(int(val_batch.shape[0]), dtype=torch.long, device=device) if return_stats else None
    for _a in need_reg_layers:
        _a.need_reg = False
    if collect_block_stats:
        enable_block_stats(model, True)
    _compression_out = None
    try:
        ntok = 0
        V = None
        _sel = None
        if eval_rows is not None and int(eval_rows) > 0:
            _n_rows = int(val_batch.shape[0])
            _n_tgt = max(0, int(val_batch.shape[1]) - 1)
            _flat = _n_rows * _n_tgt
            _k = min(int(eval_rows), _flat)
            if _k < _flat:
                _g = torch.Generator().manual_seed(int(eval_seed))
                # A full randperm costs O(n_rows*T) memory even for a tiny
                # eval_rows sample (e.g. 1 GB at 4096x32768).  Sampling with
                # replacement and de-duplicating gives the same uniform
                # k-subset distribution with O(k) memory; only near-full
                # samples fall back to the historical permutation.
                if _k * 4 >= _flat:
                    _sel = torch.randperm(_flat, generator=_g)[:_k]
                else:
                    _sel = torch.empty(0, dtype=torch.long)
                    while int(_sel.numel()) < _k:
                        _draw = torch.randint(0, _flat,
                                              (max(16, 2 * int(_k - _sel.numel())),),
                                              generator=_g)
                        _sel = torch.unique(torch.cat([_sel, _draw]), sorted=True)
                    if int(_sel.numel()) > _k:
                        _sel = _sel[torch.randperm(int(_sel.numel()), generator=_g)[:_k]]
                # keep the sorted host copy: per-chunk membership bounds are
                # integer range queries on a sorted table — searchsorted on the
                # host gives the same slice the boolean-mask form selected
                # (host-side integer equivalence, design notes §6.2).
                _sel_host = torch.sort(_sel).values
                _sel_sorted = _sel_host.to(device)
                print(f'[eval_ppl] scoring a uniform sample of {_k}/{_flat} target rows (eval_rows={int(eval_rows)}, eval_seed={int(eval_seed)}) — this is a SAMPLED estimate, not the full-set PPL')
            else:
                print(f'[eval_ppl] eval_rows={int(eval_rows)} covers the whole {_flat}-row target space; scoring the FULL set (this is the population statistic, not a sample)')
        _vhost = None
        if device.type == 'cuda':
            _vdev = _dev_str(device)
            _vc = _PINNED_HOST_CACHE.get('val')
            # In-place mutation of the same tensor keeps its id/shape but
            # changes `_version`; without it the pinned copy served stale rows.
            _vver = getattr(val_batch, '_version', None)
            if (_vc is not None and _vc[0] is val_batch and _vc[1] == tuple(val_batch.shape)
                    and _vc[3] == _vdev and _vc[4] == _vver):
                _vhost = _vc[2]
            else:
                try:
                    _vhost = torch.as_tensor(val_batch).pin_memory()
                    _PINNED_HOST_CACHE['val'] = (val_batch, tuple(val_batch.shape), _vhost,
                                                 _vdev, _vver)
                except RuntimeError:
                    _vhost = torch.as_tensor(val_batch)
        else:
            _vhost = torch.as_tensor(val_batch)
        _async = _vhost.is_pinned()
        _span = max(0, int(val_batch.shape[1]) - 1)

        def _run_rows(i, cur):
            nonlocal ntok, V, nll, _row_nll, _row_ntok
            _lo = _hi = 0
            if _sel is not None:
                # Host-side range count on the sorted selection: chunks with
                # no sampled target contribute nothing to nll/ntok.
                _base = i * _span
                _wide = min(cur, int(val_batch.shape[0]) - i) * _span
                if _wide > 0:
                    _lo = int(torch.searchsorted(_sel_host, _base))
                    _hi = int(torch.searchsorted(_sel_host, _base + _wide))
                if _hi <= _lo:
                    return
            elif _span == 0:
                return
            ids = _vhost[i:i + cur].to(device, non_blocking=_async)
            # Trunk + per-slice LM head; comp_reg / need_reg handling is
            # identical to model(ids) because forward() itself is exactly
            # trunk() followed by head().
            h = model.trunk(ids)
            if _sel is not None:
                _local = _sel_sorted[_lo:_hi] - _base
                _ri = torch.div(_local, _span, rounding_mode='floor')
                _ci = _local - _ri * _span
                # `_row_nll` / `_row_ntok` are indexed by the GLOBAL document
                # row, while `_ri` is chunk-local because it indexes this
                # chunk's `h`/`ids`.  Offset it before the scatters.
                _src_rows = _ri + i
                # gather the selected hidden rows BEFORE the head: each output
                # row of the Linear is an independent function of one hidden
                # row, so head(h[sel]) == head(h)[sel]
                _rows = model.head(h[_ri, _ci, :])
                if V is None:
                    V = _rows.size(-1)
                _tgts = ids[_ri, _ci + 1]
                del _ri, _ci
                _ce = F.cross_entropy(_rows, _tgts, reduction='none').double()
                nll += _ce.sum()
                if return_stats:
                    # Deterministic segmented sum (no CUDA atomics): the
                    # per-document NLL feeding the document bootstrap must be
                    # reproducible on the same machine.
                    # `_src_rows` is non-decreasing: it is derived from the
                    # sorted global selection table, so the stable sort in the
                    # accumulator would be an identity.
                    _row_nll += _det_segment_sum(_row_nll.numel(), _src_rows, _ce, dtype=torch.float64, sorted_indices=True)
                    _row_ntok += _det_segment_sum(_row_ntok.numel(), _src_rows, torch.ones_like(_src_rows), dtype=torch.long, sorted_indices=True)
                ntok += int(_tgts.numel())
                del _rows, _tgts, _ce, _src_rows
            else:
                _tgts = ids[:, 1:]
                for _s0 in range(0, _span, 64):
                    _sl = slice(_s0, min(_s0 + 64, _span))
                    _lg = model.head(h[:, _sl, :])
                    if V is None:
                        V = _lg.size(-1)
                    _ce = F.cross_entropy(_lg.transpose(1, 2), _tgts[:, _sl], reduction='none').double()
                    nll += _ce.sum()
                    if return_stats:
                        _b = int(_ce.shape[0])
                        _row_nll[i:i + _b] += _ce.sum(dim=1)
                        _row_ntok[i:i + _b] += int(_ce.shape[1])
                    del _lg, _ce
                ntok += int(_tgts.numel())
                del _tgts
            del ids, h

        i = 0
        _n_rows = int(val_batch.shape[0])
        while i < _n_rows:
            _cur = min(chunk, _n_rows - i)
            _nll_snap = nll.clone()
            _rn_snap = _row_nll.clone() if return_stats else None
            _rt_snap = _row_ntok.clone() if return_stats else None
            _stats_snap = _snapshot_block_stats(model) if collect_block_stats else None
            try:
                _run_rows(i, _cur)
            except RuntimeError as _oe:
                nll.copy_(_nll_snap)
                if return_stats:
                    _row_nll.copy_(_rn_snap)
                    _row_ntok.copy_(_rt_snap)
                if _stats_snap is not None:
                    _restore_block_stats(_stats_snap)
                if ('out of memory' in str(_oe).lower()) and _cur > 1:
                    if device.type == 'cuda':
                        torch.cuda.empty_cache()
                    chunk = max(1, _cur // 2)
                    print(f'[eval_ppl] device-memory exhaustion; retrying with chunk={chunk}')
                    continue
                raise
            i += _cur
    finally:
        if collect_block_stats:
            try:
                _compression_out = _compression_report_summary(model, int(val_batch.shape[1]), val_bnd, bnd_tol)
            except Exception as _ce:
                print(f'[eval_ppl] WARNING: compression diagnostics failed ({type(_ce).__name__}: {_ce})')
                _compression_out = None
            enable_block_stats(model, False)
        for _a, _prev in zip(need_reg_layers, need_reg_prior):
            _a.need_reg = _prev
        model.train(was_training)
    if not ntok:
        if not return_stats:
            return float('nan')
        _empty = {'ppl': float('nan'), 'nll_sum': float('nan'), 'n_tokens': 0,
                  'nll_per_row': [], 'n_tokens_per_row': [], 'eval_rows': int(eval_rows) if eval_rows is not None else None,
                  'eval_seed': int(eval_seed), 'eval_subset': int(val_batch.shape[0])}
        if collect_block_stats:
            _empty['compression'] = _compression_out
        return _empty
    try:
        ppl = math.exp(nll.item() / ntok)
    except OverflowError:
        ppl = float('inf')
    if not return_stats:
        return ppl
    _out = {
        'ppl': float(ppl),
        'nll_sum': float(nll.item()),
        'n_tokens': int(ntok),
        'nll_per_row': [float(x) for x in _row_nll.detach().cpu().tolist()],
        'n_tokens_per_row': [int(x) for x in _row_ntok.detach().cpu().tolist()],
        'eval_rows': int(eval_rows) if eval_rows is not None else None,
        'eval_seed': int(eval_seed),
        'eval_subset': int(val_batch.shape[0]),
    }
    if collect_block_stats:
        _out['compression'] = _compression_out
    return _out

class _PrefixStats:
    """Diagnostics for the open-block (current-prefix) reading path.

    Accumulates per-query quantities only when the caller enables block stats
    (the validation/eval report), so training keeps its fast path.  Nothing
    here is a loss term or a model input.
    """

    def __init__(self):
        self.n_tok = 0
        self.n_seq = 0
        self.age_sum = 0.0
        self.age_max = 0
        self.age_p95 = []
        self.outside_len_sum = 0.0
        self.outside_nonzero = 0
        self.prefix_len_sum = 0.0
        self.pos_truncated = 0
        self.pref_valid = 0
        self.pref_selected = 0
        self.closed_selected = 0
        self.slots = 0
        self.history_displaced = 0.0
        self.candidate_sum = 0
        self.selected_sum = 0
        self.prefix_mass_sum = 0.0
        self.prefix_mass_n = 0
        self.selected_rows = 0

    def snapshot(self):
        d = dict(self.__dict__)
        d['age_p95'] = list(self.age_p95)
        return d

    def append_from_layer(self, geo, T, topk_idx, sel_valid, cfg, prefix_mass=None, closed_blocks=0):
        if geo is None or T <= 0:
            return
        try:
            t = torch.arange(T, device=geo['offset'].device)
            age = geo['offset'] + 1
            w = int(getattr(cfg, 'sliding_window', 0) or 0)
            # W_t = [max(0, t-w+1), t]; w<=0 means no window, so the whole
            # prefix lies outside it.  U_t length = |[s_t, window_start-1]|.
            w_start = (t - w + 1).clamp_min(0) if w > 0 else (t + 1)
            outside_len = (w_start - geo['start_of_token']).clamp_min(0)
            cap = int(cfg.position_capacity())
            pos_trunc = (geo['offset'] >= cap)
            pref_valid = (geo['valid'] if geo['valid'].ndim == 2 else (geo['plen'][:, None] > 0))
            k = int(topk_idx.shape[1])
            is_pref = topk_idx.long() >= int(closed_blocks)
            pref_sel = (sel_valid & is_pref).sum(1)
            closed_sel = (sel_valid & ~is_pref).sum(1)
            # A closed-only top-k would fill min(k, readable_closed) slots.
            ends = geo['ends']
            readable_closed = torch.searchsorted(ends, t, right=True)
            displaced = (torch.minimum(torch.as_tensor(k, device=t.device),
                                       readable_closed) - closed_sel).clamp_min(0)
            self.n_tok += int(T)
            self.n_seq += 1
            self.age_sum += float(age.sum().item())
            self.age_max = max(self.age_max, int(age.max().item()))
            # Ages are exact integers; int32 halves the retained diagnostic
            # memory versus the int64 device dtype (the summary casts to
            # float32 only when computing the quantiles).
            self.age_p95.append(age.detach().to(torch.int32).cpu())
            self.outside_len_sum += float(outside_len.sum().item())
            self.outside_nonzero += int((outside_len > 0).sum().item())
            self.prefix_len_sum += float(geo['plen'].sum().item())
            self.pos_truncated += int(pos_trunc.sum().item())
            self.pref_valid += int(pref_valid.sum().item())
            self.pref_selected += int(pref_sel.sum().item())
            self.closed_selected += int(closed_sel.sum().item())
            self.slots += int(sel_valid.numel())
            self.candidate_sum += int(int(closed_blocks) + int(geo['token_idx'].shape[1])) * int(T)
            self.selected_sum += int(pref_sel.sum().item()) + int(closed_sel.sum().item())
            self.history_displaced += float(displaced.sum().item())
            self.selected_rows += int((pref_sel > 0).sum().item())
            if prefix_mass is not None:
                pm = prefix_mass.detach().float()
                self.prefix_mass_sum += float(pm.sum().item())
                self.prefix_mass_n += int(pm.numel())
        except Exception:
            # Diagnostics must never take down a training/eval run.
            return

    def summary(self, seq_len=None):
        if self.n_tok <= 0:
            return None
        try:
            flat = torch.cat([x.reshape(-1) for x in self.age_p95]) if self.age_p95 else torch.empty(0)
            p95 = float(torch.quantile(flat.float(), 0.95).item()) if flat.numel() else None
            p50 = float(torch.quantile(flat.float(), 0.50).item()) if flat.numel() else None
        except Exception:
            p95 = p50 = None
        return {
            'n_tokens': int(self.n_tok),
            'n_sequences': int(self.n_seq),
            'prefix_age_mean': self.age_sum / self.n_tok,
            'prefix_age_p50': p50,
            'prefix_age_p95': p95,
            'prefix_age_max': int(self.age_max),
            'outside_window_len_mean': self.outside_len_sum / self.n_tok,
            'outside_window_nonzero_frac': self.outside_nonzero / self.n_tok,
            'prefix_len_mean': self.prefix_len_sum / self.n_tok,
            'position_truncated_frac': self.pos_truncated / self.n_tok,
            'prefix_valid_candidates_mean': self.pref_valid / self.n_tok,
            'prefix_selected_rate': self.pref_selected / max(self.slots, 1),
            'prefix_selected_any_rate': self.selected_rows / self.n_tok,
            'closed_selected_mean': self.closed_selected / self.n_tok,
            'selected_mean': self.selected_sum / self.n_tok,
            'candidates_mean': self.candidate_sum / self.n_tok,
            'unused_slots_mean': (self.slots - self.selected_sum) / self.n_tok,
            'history_displaced_mean': self.history_displaced / self.n_tok,
            'prefix_attention_mass_mean': (self.prefix_mass_sum / self.prefix_mass_n) if self.prefix_mass_n else None,
            'slots': int(self.slots),
        }


def prefix_stats_summary(attn, seq_len=None):
    st = getattr(attn, '_prefix_stats', None)
    if isinstance(st, _PrefixStats):
        return st.summary(seq_len)
    return None

class _BlockStats:
    """Incremental replacement for the per-sequence bincount list.

    compression_report only needs the pooled mean/std/min/max/fractions over
    block lengths.  Each append folds the integer counts into running moments
    and drops the tensor immediately; values are accumulated in float64 so the
    pooled statistics are at least as accurate as the concatenated float32
    form."""

    def __init__(self, min_block=None, max_block=None, position_capacity=None):
        self.min_block = min_block
        self.max_block = max_block
        self.position_capacity = position_capacity
        self.pos_truncated_tokens = 0
        self.pos_truncated_blocks = 0
        self.forced_only = 0
        self.natural_only = 0
        self.forced_and_natural = 0
        self.forced_total = 0
        self.natural_total = 0
        self._lens = []
        self.n = 0
        self.total = 0
        self.blocks = 0
        self.s = 0.0
        self.ss = 0.0
        self.lo = None
        self.hi = None
        self.at_min = 0
        self.at_max = 0
        # GPU counts are queued until a snapshot is requested.
        self._pending = []

    def snapshot(self):
        d = dict(self.__dict__)
        d['_pending'] = list(self._pending)
        d['_lens'] = list(self._lens)
        return d

    def _add(self, a, n_items=1):
        if not a.size:
            return
        a = a.astype(np.float64, copy=False)
        self.n += int(n_items)
        self.blocks += int(a.size)
        self.total += int(a.size)
        self.s += float(a.sum())
        self.ss += float(np.square(a).sum())
        self._lens.append(a.copy())
        self.lo = float(a.min()) if self.lo is None else min(self.lo, float(a.min()))
        self.hi = float(a.max()) if self.hi is None else max(self.hi, float(a.max()))
        if self.min_block is not None:
            self.at_min += int((a <= self.min_block).sum())
        if self.max_block is not None:
            self.at_max += int((a >= self.max_block).sum())
        if self.position_capacity is not None:
            _cap = int(self.position_capacity)
            # A block of length L uses offsets 0..L-1; truncation starts at
            # offset == capacity, i.e. only when L > capacity.
            self.pos_truncated_tokens += int(np.maximum(a - _cap, 0).sum())
            self.pos_truncated_blocks += int((a > _cap).sum())

    def add_segmentation(self, bid, gate_cuts, max_block):
        """Count forced vs natural (and both) non-tail block ends.

        `gate_cuts` is the segmenter's boolean cut row (length n-1).  A block
        end `end < n` is natural when a cut was wanted at `end-1`; it is
        forced when `max_block` is set and the block length equals it.  The
        two categories can overlap.  Only the main dynamic path supplies a
        cut row; callers that cannot distinguish the cause leave these
        counters untouched rather than guessing.
        """
        if gate_cuts is None or bid is None:
            return
        try:
            b = bid.detach() if torch.is_tensor(bid) else torch.as_tensor(bid)
            B = int(b.max().item()) + 1 if b.numel() else 0
            if B <= 0:
                return
            counts = torch.bincount(b.reshape(-1).long(), minlength=B)[:B]
            ends = torch.cumsum(counts, 0)
            g = gate_cuts
            if not torch.is_tensor(g):
                g = torch.as_tensor(g)
            g = g.reshape(-1).to(torch.bool)
            n = int(b.numel())
            non_tail = ends < n
            if int(ends.max().item()) > 0:
                idx = (ends - 1).clamp(0, max(n - 2, 0))
                natural = ((ends - 1) < max(n - 1, 0)) & (idx < g.numel())
                nat = torch.zeros_like(non_tail)
                if g.numel():
                    nat = g[idx] & natural
                nat = nat & non_tail
            else:
                nat = torch.zeros_like(non_tail)
            if max_block is None:
                forced = torch.zeros_like(non_tail)
            else:
                forced = (counts == int(max_block)) & non_tail
            self.forced_only += int((forced & ~nat).sum().item())
            self.natural_only += int((nat & ~forced).sum().item())
            self.forced_and_natural += int((forced & nat).sum().item())
            self.forced_total += int(forced.sum().item())
            self.natural_total += int(nat.sum().item())
        except Exception:
            return

    def append(self, t):
        if torch.is_tensor(t) and t.device.type != 'cpu':
            self._pending.append(t.detach())
            self.n += 1
            return
        if torch.is_tensor(t):
            t = t.detach()
        self._add(np.asarray(t).reshape(-1))

    def _flush(self):
        if not self._pending:
            return
        parts = self._pending
        self._pending = []
        try:
            flat = torch.cat([p.reshape(-1).to(torch.int64) for p in parts])
        except Exception:
            for p in parts:
                self._add(np.asarray(p.detach().cpu()).reshape(-1), n_items=0)
            return
        # `append` already counted each pending sequence in self.n.
        self._add(flat.detach().cpu().numpy(), n_items=0)
        del flat

    def __len__(self):
        self._flush()
        return self.n

    def summary(self, seq_len):
        self._flush()
        if self.n == 0 or self.total == 0:
            return None
        mean = self.s / self.total
        # Match the concatenated form's sample standard deviation
        # (torch.std's default Bessel correction); with a single observation
        # the original reports 0.0.
        if self.total > 1:
            var = max((self.ss - self.s * self.s / self.total) / (self.total - 1), 0.0)
        else:
            var = 0.0
        return {
            'blocks': self.blocks / self.n,
            'avg_len': seq_len / max(self.blocks / self.n, 1.0),
            'len_mean': mean,
            'len_std': math.sqrt(var),
            'len_min': int(self.lo),
            'len_max': int(self.hi),
            'frac_at_min': self.at_min / self.total,
            'frac_at_max': (self.at_max / self.total if self.max_block is not None else None),
            'position_capacity': (int(self.position_capacity) if self.position_capacity is not None else None),
            'position_truncated_tokens': int(self.pos_truncated_tokens),
            'position_truncated_blocks': int(self.pos_truncated_blocks),
            'position_truncated_frac_of_block_tokens': (self.pos_truncated_tokens / max(self.s or 1.0, 1.0)),
            'forced_only': int(self.forced_only),
            'natural_only': int(self.natural_only),
            'forced_and_natural': int(self.forced_and_natural),
            'forced_total': int(self.forced_total),
            'natural_total': int(self.natural_total),
            'len_p50': (float(np.percentile(np.concatenate(self._lens), 50)) if self._lens else mean),
            'len_p95': (float(np.percentile(np.concatenate(self._lens), 95)) if self._lens else mean),
        }

def enable_block_stats(model, on):
    for blk in model.blocks:
        if on:
            _mb = getattr(blk.attn.cfg, 'max_block', None)
            blk.attn._stats = _BlockStats(getattr(blk.attn.cfg, 'min_block', None),
                                          (None if _mb is None else int(_mb)),
                                          position_capacity=getattr(blk.attn.cfg, 'position_capacity', lambda: None)())
            blk.attn._prefix_stats = _PrefixStats()
        else:
            blk.attn._stats = None
            blk.attn._prefix_stats = None
        blk.attn._cuts = [] if on else None


def _snapshot_block_stats(model):
    """Capture every attention layer's block-count / cut state.

    A failed forward may already have appended per-layer counts and cut
    positions.  OOM retries must restore this state together with the NLL
    accumulators, otherwise the partially processed rows are counted twice."""
    snap = []
    for blk in model.blocks:
        attn = blk.attn
        st = getattr(attn, '_stats', None)
        pst = getattr(attn, '_prefix_stats', None)
        cuts = getattr(attn, '_cuts', None)
        snap.append((attn,
                     st.snapshot() if isinstance(st, _BlockStats) else None,
                     list(cuts) if cuts is not None else None,
                     pst.snapshot() if isinstance(pst, _PrefixStats) else None))
    return snap


def _restore_block_stats(snap):
    for attn, state, cuts, pstate in snap:
        if state is not None:
            attn._stats.__dict__.clear()
            attn._stats.__dict__.update(state)
        if cuts is not None:
            attn._cuts[:] = cuts
        if pstate is not None and isinstance(getattr(attn, '_prefix_stats', None), _PrefixStats):
            attn._prefix_stats.__dict__.clear()
            attn._prefix_stats.__dict__.update(pstate)

# Random-cut baseline has two distinct sampling definitions.  They have
# different estimands (a fixed number of cuts per sequence vs a per-position
# independent cut process with a varying count), so their precisions must
# never be averaged, paired or plotted as one series.
BND_RAND_KINDS = ('matched_cut_count', 'per_sequence_independent')
_BND_RAND_ALIASES = {
    'matched_cut_count': 'matched_cut_count',
    'fixed_k': 'matched_cut_count',
    'fixed_block_count': 'matched_cut_count',
    'per_sequence_independent': 'per_sequence_independent',
    'independent': 'per_sequence_independent',
    'independent_cuts': 'per_sequence_independent',
}


def normalize_bnd_rand_kind(kind):
    if kind is None:
        return 'matched_cut_count'
    key = str(kind).strip().lower()
    if key not in _BND_RAND_ALIASES:
        raise ValueError(
            f'unknown bnd_rand kind {kind!r}; expected one of '
            f'{BND_RAND_KINDS} (aliases: fixed_k / independent).  The two '
            'definitions have different estimands and must not be mixed.')
    return _BND_RAND_ALIASES[key]


def boundary_alignment(pred_cuts, gt_mask_row, n, tol=1, provenance=None,
                       detail=None, rand_kind='matched_cut_count'):
    rand_kind = normalize_bnd_rand_kind(rand_kind)
    gt = np.nonzero(np.asarray(gt_mask_row)[:n - 1])[0] + 1
    pred = np.asarray(pred_cuts)
    P, G = (len(pred), len(gt))
    if P == 0 or G == 0:
        if provenance is not None:
            provenance.setdefault('bnd_rand_exact', True)
            provenance.setdefault('bnd_rand_kind', rand_kind)
            provenance.setdefault('bnd_rand_definition',
                                  'fixed_block_count' if rand_kind == 'matched_cut_count'
                                  else 'per_sequence_independent')
        if detail is not None:
            detail.update({'tp': 0, 'fp': P, 'fn': G, 'n_pred': P, 'n_gt': G})
        return (0.0, 0.0, 0.0, 0.0)
    hits, ghits = _greedy_match_counts(pred, gt, tol)
    if detail is not None:
        detail.update({'tp': int(hits), 'fp': int(P - hits), 'fn': int(G - ghits),
                       'n_pred': int(P), 'n_gt': int(G)})
    prec, rec = (hits / P, ghits / G)
    f1 = 2 * prec * rec / max(prec + rec, 1e-09)
    n_pos = max(n - 1, 1)
    _approx = []
    rand_prec = _random_cut_precision(P, None, n_pos, tol, G, gt,
                                      approx_flag=_approx, kind=rand_kind)
    if provenance is not None:
        provenance['bnd_rand_exact'] = provenance.get('bnd_rand_exact', True) and (not _approx)
        provenance.setdefault('bnd_rand_kind', rand_kind)
        provenance.setdefault('bnd_rand_definition',
                              'fixed_block_count' if rand_kind == 'matched_cut_count'
                              else 'per_sequence_independent')
    return (prec, rec, f1, rand_prec)

def _mask_runs(near, n_pos, tol):
    near_arr = np.asarray(near)
    m = near_arr[1:n_pos + 1].astype(bool)
    if not m.any():
        return np.zeros(0, dtype=int)
    if tol == 0:
        # With tol=0 the neighbourhood of a boundary is the boundary itself,
        # so every True lane is exactly one boundary -- including adjacent
        # boundaries, which form a longer run and cannot be split by the
        # run-length rules below (those are only meaningful for tol>0).
        return np.nonzero(m)[0] + 1
    d = np.diff(np.concatenate([[0], m.view(np.int8), [0]]))
    starts = np.nonzero(d == 1)[0]
    ends = np.nonzero(d == -1)[0]
    lens = ends - starts
    left_touch = bool(near_arr[0]) if near_arr.size else False
    out, ok = ([], True)
    for s, e, L in zip(starts, ends, lens):
        if s == 0 and e == m.size:
            # A run covering the whole sequence can come from one boundary at
            # the centre OR from several boundaries whose neighbourhoods tile
            # it; the post-slice mask cannot distinguish them.
            ok = False
            break
        if s == 0:
            if left_touch:
                # Position 0 is inside the neighbourhood, so the leftmost
                # possible boundary is 1; only a length-(tol+1) run pins it.
                if L == tol + 1:
                    out.append(0)
                else:
                    ok = False
                    break
            else:
                # Position 0 is outside every neighbourhood: the unique
                # minimum boundary is tol+1, and only its full 2*tol+1 run is
                # unambiguous.
                if L == 2 * tol + 1:
                    out.append(tol)
                else:
                    ok = False
                    break
        elif e == m.size:
            # The right edge is clipped by the sequence end: only the
            # one-sided length-(tol+1) run pins the final boundary.
            if L == tol + 1:
                out.append(m.size - 1)
            else:
                ok = False
                break
        else:
            # A fully interior neighbourhood has exactly 2*tol+1 lanes.
            if L == 2 * tol + 1:
                out.append((s + e - 1) // 2)
            else:
                ok = False
                break
    if ok:
        return np.asarray(sorted(set(out)), dtype=int) + 1
    return None

def _random_cut_precision(P, near, n_pos, tol, G, gt_bounds=None, approx_flag=None,
                          kind='matched_cut_count'):
    kind = normalize_bnd_rand_kind(kind)
    if P <= 0 or G <= 0 or n_pos <= 0:
        return 0.0
    if gt_bounds is None:
        if near is None:
            print('[stats] WARNING: `_random_cut_precision` got neither a `near` mask nor `gt_bounds`; the baseline is UNCOMPUTABLE for this call (returning 0.0) rather than being scored against an inflated reference set.  Pass `gt_bounds`.')
            print(f'[stats] bnd_rand kind for this call: {kind!r}; this value must not be pooled with the other definition.')
            return 0.0
        _runs = _mask_runs(near, n_pos, tol)
        if _runs is None:
            print('[stats] WARNING: `_random_cut_precision` got a `near` mask it cannot decompose into boundary neighbourhoods and no `gt_bounds`; the baseline is UNCOMPUTABLE for this call (returning 0.0) rather than being scored against an inflated reference set.  Pass `gt_bounds`.')
            return 0.0
        gt = _runs
    else:
        gt = np.asarray(gt_bounds).astype(int)
        gt = gt[(gt >= 1) & (gt <= n_pos)]
    if gt.size == 0:
        return 0.0
    gt = np.unique(gt)
    clusters, cur = ([], [int(gt[0])])
    for g in gt[1:]:
        g = int(g)
        if g - cur[-1] <= 2 * tol + 1:
            cur.append(g)
        else:
            clusters.append(cur)
            cur = [g]
    clusters.append(cur)
    if kind == 'per_sequence_independent':
        # Each eligible slot is cut independently with p so that the EXPECTED
        # number of cuts is P.  The count is therefore random and the estimand
        # differs from the matched-count baseline above; callers must keep the
        # two kinds separate.  The closed form is the expected number of GT
        # boundaries whose neighbourhood contains at least one cut, divided by
        # the expected number of cuts.  It is a coverage probability, not the
        # exact greedy-match expectation, so mark it as sampled/non-exact for
        # pooling purposes.
        if approx_flag is not None:
            approx_flag.append(('per_sequence_independent', BND_RAND_KINDS[0]))
        p = min(1.0, float(P) / float(n_pos))
        expected = 0.0
        for cl in clusters:
            lo, hi = (max(min(cl) - tol, 1), min(max(cl) + tol, n_pos))
            w = max(1, hi - lo + 1)
            expected += len(cl) * (1.0 - (1.0 - p) ** w)
        # p is clamped at 1 when P > n_pos; the expected number of cuts is
        # then n_pos, not P.  Dividing by P would understate the coverage
        # probability of the definition the caller asked for.  For the normal
        # P <= n_pos case keep the historical denominator (bit-identical to
        # the pre-existing formula rather than merely mathematically equal).
        expected_cuts = float(P) if P <= n_pos else float(n_pos)
        return float(min(expected / max(expected_cuts, 1e-12), 1.0))
    if P >= n_pos:
        return float(min(gt.size, P) / P)
    expect_frac = 0.0
    for cl in clusters:
        lo, hi = (max(min(cl) - tol, 1), min(max(cl) + tol, n_pos))
        win = list(range(lo, hi + 1))
        expect_frac += _cluster_expected_matches(win, cl, tol, P, n_pos, approx_flag)
    return float(expect_frac / P)

def _log_ways_ratio(w, r, n_pos, P):
    a, b, c = (n_pos - w, P - r, P)
    if r < 0 or a < 0 or b < 0 or (c < 0) or (r > w) or (b > a):
        return float('-inf')
    return _lgamma_comb(w, r) + _lgamma_comb(a, b) - _lgamma_comb(n_pos, c)

def _lgamma_comb(n, k):
    if k < 0 or k > n:
        return float('-inf')
    if k == 0 or k == n:
        return 0.0
    return math.lgamma(n + 1) - math.lgamma(k + 1) - math.lgamma(n - k + 1)
_AMP_WORK_CAP = (1 << 12) - 1
_AMP_FALLBACK_DRAWS = 2048

def _cluster_expected_matches(win, cl, tol, P, n_pos, approx_flag=None):
    w = len(win)
    if w <= 0 or P <= 0:
        return 0.0
    cl_t = tuple((int(b) for b in cl))
    A = [int(p) for p in win if any((abs(int(p) - b) <= tol for b in cl_t))]
    a = len(A)
    if a == 0:
        return 0.0
    rmax = min(P, a)
    _cl_arr = np.asarray(cl_t)
    _ord = np.argsort(_cl_arr, kind='stable')
    _pre = (_cl_arr[_ord], _ord)
    T = [0] * (rmax + 1)
    _comp_T = _component_match_tables(A, cl_t, tol, rmax, _pre)
    a_max = max((a_c for _tbl, a_c in _comp_T.values()), default=0)
    any_sampled = any((tbl == [] for tbl, _a in _comp_T.values()))
    if not any_sampled:
        T = _convolve_component_T(_comp_T, rmax)
    else:
        _work = _subset_work(a_max, rmax)
        if approx_flag is not None:
            approx_flag.append((a_max, _AMP_WORK_CAP, _work))
        print(f'[stats] WARNING: `_random_cut_precision` is APPROXIMATING: a single candidate component holds {a_max} positions and needs {_work} subset scorings, past the enumeration limit of {_AMP_WORK_CAP}, so `bnd_rand` (and hence `bnd_excess`) for this sample is a Monte-Carlo estimate ({_AMP_FALLBACK_DRAWS} draws), NOT the exact probability the other panels report.  Record it as `bnd_rand_exact: False` and do not pool it with the exact readings.')
        seed = (int(n_pos) * 1000003 + int(P) * 10007 + int(tol) * 101 + int(a) * 17 + cl_t[0]) % 2 ** 32
        rng = np.random.default_rng(seed)
        wts = []
        for r in range(1, rmax + 1):
            outside = P - r
            if outside < 0 or outside > n_pos - a:
                continue
            lw = _log_ways_ratio(a, r, n_pos, P)
            if lw == float('-inf'):
                continue
            wts.append((r, lw))
        if not wts:
            return 0.0
        nb_r = len(wts)
        order = sorted(range(nb_r), key=lambda i: -wts[i][1])
        if nb_r > _AMP_FALLBACK_DRAWS:
            # More candidate sizes than the draw limit: keep the top-weight
            # sizes, one draw each, so the actual number of draws never
            # exceeds the declared _AMP_FALLBACK_DRAWS limit.
            _keep = set(order[:_AMP_FALLBACK_DRAWS])
            draws = [1 if i in _keep else 0 for i in range(nb_r)]
        else:
            per = max(1, _AMP_FALLBACK_DRAWS // nb_r)
            draws = [per] * nb_r
            for i in range(_AMP_FALLBACK_DRAWS - per * nb_r):
                draws[order[i % nb_r]] += 1
        total = 0.0
        for i, (r, lw) in enumerate(wts):
            n_draw = draws[i]
            if n_draw <= 0:
                continue
            subs = [_sample_r_subset(rng, A, r) for _ in range(n_draw)]
            s = _score_subsets_components(subs, _comp_T, cl_t, tol, _pre)
            total += math.exp(lw) * (s / n_draw)
        return float(total)
    total = 0.0
    for r in range(0, rmax + 1):
        outside = P - r
        if outside < 0 or outside > n_pos - a:
            continue
        if not r:
            continue
        if not (comb(a, r) and comb(n_pos - a, outside)):
            continue
        mean_r = T[r] / comb(a, r)
        if mean_r == 0.0:
            continue
        total += math.exp(_log_ways_ratio(a, r, n_pos, P)) * mean_r
    return float(total)

def _match_components(A, cl_t, tol):
    parent = {}

    def find(x):
        parent.setdefault(x, x)
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = (root, parent[x])
        return root

    def union(x, y):
        rx, ry = (find(x), find(y))
        if rx != ry:
            parent[rx] = ry
    if A:
        A_arr = np.asarray(A)
        for gi, b in enumerate(cl_t):
            lo = int(np.searchsorted(A_arr, b - tol, side='left'))
            hi = int(np.searchsorted(A_arr, b + tol, side='right'))
            for pi in range(lo, hi):
                union(('c', pi), ('g', gi))
    comps = {}
    for pi, p in enumerate(A):
        comps.setdefault(find(('c', pi)), ([], []))[0].append(int(p))
    for gi, b in enumerate(cl_t):
        comps.setdefault(find(('g', gi)), ([], []))[1].append(int(b))
    out = []
    for key in sorted(comps, key=repr):
        pos, bnd = comps[key]
        if pos:
            out.append((pos, bnd))
    return out

def _sorted_pre(b_t):
    if not b_t:
        z = np.zeros(0, dtype=int)
        return (z, z)
    arr = np.asarray(b_t)
    o = np.argsort(arr, kind='stable')
    return (arr[o], o)

def _subset_work(w, rmax):
    if w <= 0 or rmax <= 0:
        return 0
    r_hi = min(rmax, w)
    total = 0
    c = 1
    for r in range(0, r_hi + 1):
        if r:
            c = c * (w - r + 1) // r
        if r:
            total += c
    return total

def _component_match_tables(A, cl_t, tol, rmax, _pre):
    tables = {}
    for pos, bnd in _match_components(A, cl_t, tol):
        r_c = min(rmax, len(pos))
        b_t = tuple(bnd)
        c_pre = _sorted_pre(b_t)
        if _subset_work(len(pos), r_c) <= _AMP_WORK_CAP:
            tbl = [0] * (r_c + 1)
            for rr in range(1, r_c + 1):
                subs = list(_subsets(pos, rr))
                if subs:
                    tbl[rr] = int(sum(_greedy_match_count_batch(subs, c_pre[0], c_pre[1], tol)))
            tables[tuple(pos), b_t] = (tbl, len(pos))
        else:
            tables[tuple(pos), b_t] = ([], len(pos))
    return tables

def _convolve_component_T(tables, rmax):
    items = [(tbl, a_c) for tbl, a_c in tables.values() if tbl]
    if not items:
        return [0] * (rmax + 1)
    choice = [0.0] * (rmax + 1)
    choice[0] = 1.0
    wsum = [0.0] * (rmax + 1)
    for tbl, a_c in items:
        rc_max = min(rmax, a_c)
        term = [0.0] * (rmax + 1)
        mean = [0.0] * (rmax + 1)
        for r in range(0, rc_max + 1):
            term[r] = float(comb(a_c, r))
            if r:
                mean[r] = tbl[r] / comb(a_c, r)
        new_choice = [0.0] * (rmax + 1)
        new_wsum = [0.0] * (rmax + 1)
        for i in range(rmax + 1):
            if choice[i] == 0.0 and wsum[i] == 0.0:
                continue
            for r in range(0, rc_max + 1):
                if i + r > rmax or term[r] == 0.0:
                    continue
                new_choice[i + r] += choice[i] * term[r]
                new_wsum[i + r] += wsum[i] * term[r] + choice[i] * term[r] * mean[r]
        choice, wsum = (new_choice, new_wsum)
    return [int(round(wsum[r])) for r in range(rmax + 1)]

def _sample_r_subset(rng, A, r):
    return tuple(np.sort(rng.choice(A, size=r, replace=False)))

def _score_subsets_components(subs, tables, cl_t, tol, _pre):
    _owner_cache = getattr(_score_subsets_components, '_owner_cache', None)
    if _owner_cache is None:
        _owner_cache = _score_subsets_components._owner_cache = {}
    if len(_owner_cache) >= 64 and id(tables) not in _owner_cache:
        _owner_cache.clear()
    cached = _owner_cache.get(id(tables))
    if cached is None:
        owner = {}
        for pos, bnd in tables:
            b_t = tuple(bnd)
            c_pre = _sorted_pre(b_t)
            for p in pos:
                owner[p] = (b_t, c_pre)
        cached = (owner, tables)
        _owner_cache[id(tables)] = cached
    owner = cached[0]
    by_comp = {}
    for si, sub in enumerate(subs):
        for p in sub:
            hit = owner.get(p)
            if hit is None:
                continue
            b_t, c_pre = hit
            per_sub = by_comp.get(b_t)
            if per_sub is None:
                per_sub = by_comp[b_t] = (c_pre, {})
            pts = per_sub[1].get(si)
            if pts is None:
                per_sub[1][si] = [p]
            else:
                pts.append(p)
    total = 0
    for _b_t, (c_pre, per_sub) in by_comp.items():
        sids = sorted(per_sub)
        pieces = [tuple(sorted(per_sub[si])) for si in sids]
        for v in _greedy_match_count_batch(pieces, c_pre[0], c_pre[1], tol):
            total += v
    return total

def _subsets(items, r):
    return itertools.combinations(items, r)

def _greedy_match_counts(pred, gt, tol, _pre=None):
    pred = np.sort(np.asarray(pred))
    P, G = (len(pred), len(gt))
    if P == 0 or G == 0:
        return (0, 0)
    if _pre is not None:
        gt_sorted, order = _pre
    else:
        gt_arr = np.asarray(gt)
        order = np.argsort(gt_arr, kind='stable')
        gt_sorted = gt_arr[order]
    lo_all = np.searchsorted(gt_sorted, np.asarray(pred) - tol, side='left')
    hi_all = np.searchsorted(gt_sorted, np.asarray(pred) + tol, side='right')
    cand = []
    for pi in range(P):
        p = pred[pi]
        for j in range(int(lo_all[pi]), int(hi_all[pi])):
            gi = int(order[j])
            cand.append((abs(p - gt[gi]), pi, gi))
    cand.sort()
    used_p, used_g = (set(), set())
    for _, pi, gi in cand:
        if pi not in used_p and gi not in used_g:
            used_p.add(pi)
            used_g.add(gi)
    return (len(used_p), len(used_g))

def _greedy_match_count_batch(subsets, gt_sorted, order, tol):
    # `_greedy_match_counts` sorts the predicate before its rank tie-break, so
    # the batched form must canonicalise every subset the same way.  Using the
    # caller's order made the match count depend on how a subset happened to
    # be constructed (its rank, not its value, broke distance ties).
    subs = [tuple(sorted(s)) for s in subsets]
    n_sub = len(subs)
    if n_sub == 0:
        return []
    counts = np.zeros(n_sub, dtype=np.int64)
    sizes = np.fromiter((len(s) for s in subs), dtype=np.int64, count=n_sub)
    if sizes.sum() == 0:
        return counts.tolist()
    flat = np.fromiter((int(p) for s in subs for p in s), dtype=np.int64, count=int(sizes.sum()))
    cut_rank = np.concatenate([np.arange(int(k), dtype=np.int64) for k in sizes]) if n_sub else np.zeros(0, dtype=np.int64)
    owner = np.repeat(np.arange(n_sub, dtype=np.int64), sizes)
    lo = np.searchsorted(gt_sorted, flat - tol, side='left')
    hi = np.searchsorted(gt_sorted, flat + tol, side='right')
    cnt = (hi - lo).astype(np.int64)
    total = int(cnt.sum())
    if total:
        row_owner = np.repeat(owner, cnt)
        starts = np.repeat(lo, cnt)
        offs = np.arange(total, dtype=np.int64) - np.repeat(np.cumsum(cnt) - cnt, cnt)
        bnd_idx = starts + offs
        gi = order[bnd_idx]
        pi_local = np.repeat(flat, cnt)
        pi_rank = np.repeat(cut_rank, cnt)
        dist = np.abs(pi_local - gt_sorted[bnd_idx])
        order_rows = np.lexsort((gi, pi_rank, dist, row_owner))
        used_p, used_g = (set(), set())
        prev_sid = -1
        for idx in order_rows:
            sid = int(row_owner[idx])
            if sid != prev_sid:
                if prev_sid >= 0:
                    counts[prev_sid] = len(used_p)
                used_p, used_g = (set(), set())
                prev_sid = sid
            p_i = int(pi_rank[idx])
            g_i = int(gi[idx])
            if p_i not in used_p and g_i not in used_g:
                used_p.add(p_i)
                used_g.add(g_i)
        if prev_sid >= 0:
            counts[prev_sid] = len(used_p)
    return counts.tolist()

def compression_report(model, val_batch, device, n_sample=64, val_bnd=None,
                       bnd_tol=1, bnd_rand_kind='matched_cut_count'):
    bnd_rand_kind = normalize_bnd_rand_kind(bnd_rand_kind)
    was_training = model.training
    model.eval()
    enable_block_stats(model, True)
    need_reg_layers = [blk.attn for blk in model.blocks if hasattr(blk.attn, 'need_reg')]
    need_reg_prior = [_a.need_reg for _a in need_reg_layers]
    for _a in need_reg_layers:
        _a.need_reg = False
    try:
        return _compression_report_impl(model, val_batch, device, n_sample,
                                        val_bnd, bnd_tol,
                                        bnd_rand_kind=bnd_rand_kind)
    finally:
        for _a, _prev in zip(need_reg_layers, need_reg_prior):
            _a.need_reg = _prev
        enable_block_stats(model, False)
        model.train(was_training)

def _compression_report_summary(model, seq_len, val_bnd=None, bnd_tol=1,
                                bnd_rand_kind='matched_cut_count'):
    bnd_rand_kind = normalize_bnd_rand_kind(bnd_rand_kind)
    report = {}
    # every dynamic layer's delta_logit (same scalars, same floats).
    _dl_layers = [(li, blk.attn.delta_logit) for li, blk in enumerate(model.blocks)
                  if blk.attn.cfg.dynamic and getattr(blk.attn, 'delta_logit', None) is not None]
    _dl_vals = {}
    if _dl_layers:
        _dl_vals = {li: float(v) for (li, _), v in zip(_dl_layers, torch.stack([p.detach() for _, p in _dl_layers]).tolist())}
    for li, blk in enumerate(model.blocks):
        attn = blk.attn
        st = attn._stats
        kind = attn.cfg.kind
        if st is None or kind == 'full' or len(st) == 0:
            continue
        if isinstance(st, _BlockStats):
            entry = st.summary(seq_len)
            if entry is None:
                continue
        else:
            lens = torch.cat([t if torch.is_tensor(t) else torch.as_tensor(t) for t in st]).float()
            n_blocks = sum((t.numel() for t in st)) / len(st)
            _mb = getattr(attn.cfg, 'max_block', None)
            _frac_max = (float('nan') if _mb is None else (lens >= int(_mb)).float().mean())
            _sc = torch.stack([lens.mean(), lens.std() if lens.numel() > 1 else torch.zeros((), device=lens.device, dtype=lens.dtype), lens.min().float(), lens.max().float(), (lens <= attn.cfg.min_block).float().mean(), torch.as_tensor(_frac_max, device=lens.device, dtype=lens.dtype)])
            _vals = _sc.tolist()
            entry = {'blocks': n_blocks, 'avg_len': seq_len / max(n_blocks, 1.0), 'len_mean': _vals[0], 'len_std': _vals[1], 'len_min': int(_vals[2]), 'len_max': int(_vals[3]), 'frac_at_min': _vals[4], 'frac_at_max': _vals[5]}
            del _sc, _vals
        _ps = prefix_stats_summary(attn, seq_len)
        if getattr(attn.cfg, 'dynamic', False) or getattr(attn.cfg, 'chunking', 'fixed') != 'fixed':
            # The chunking DATA path (similarity signal / strict cut rule /
            # geometry bounds) must be comparable across the arms in a
            # dynamic-vs-fixed or ablation contrast; record it per layer.
            entry['chunking_protocol'] = chunking_protocol(attn.cfg)
        _ob_cfg = {
            'open_block_mode': getattr(attn.cfg, 'open_block_mode', 'closed'),
            'open_block_scope': getattr(attn.cfg, 'open_block_scope', 'full_prefix'),
            'selection_budget': getattr(attn.cfg, 'selection_budget', 'shared_topk'),
            'max_block': getattr(attn.cfg, 'max_block', None),
            'max_block_tokens': getattr(attn.cfg, 'max_block', None),
            'max_block_effective': (int(getattr(attn.cfg, 'max_block')) if getattr(attn.cfg, 'max_block', None) is not None else seq_len),
            'pool_position_capacity': int(getattr(attn.cfg, 'position_capacity', lambda: 0)()),
            'pool_position_policy': getattr(attn.cfg, 'pool_position_policy', 'truncate'),
        }
        if _ob_cfg['open_block_mode'] != 'closed':
            entry['open_block_config'] = _ob_cfg
            if _ps is not None:
                entry['open_block'] = _ps
        if attn.cfg.dynamic and getattr(attn, 'delta_logit', None) is not None:
            entry['delta'] = _dl_vals[li]
        if val_bnd is not None and attn._cuts:
            n_seq_ref = min(len(attn._cuts), val_bnd.shape[0])
            if n_seq_ref < len(attn._cuts):
                print(f'[compression_report] WARNING: {len(attn._cuts)} sequences of cuts but only {val_bnd.shape[0]} reference masks — scoring the first {n_seq_ref} only')
            ps, rs, fs, rps = ([], [], [], [])
            _tp = _fp = _fn = _n_pred = _n_gt = 0
            _cuts = attn._cuts
            _prov = {}
            # The integers transferred are exactly the per-sequence values
            # (index transport, design notes §6.1), segmented on the host.
            _tcut_ix = [si for si in range(n_seq_ref) if torch.is_tensor(_cuts[si])]
            _tcut_host = {}
            if _tcut_ix:
                _tlens = [int(_cuts[si].numel()) for si in _tcut_ix]
                _tflat = torch.cat([_cuts[si].reshape(-1) for si in _tcut_ix]).cpu().numpy()
                _toff = 0
                for si, _tln in zip(_tcut_ix, _tlens):
                    _tcut_host[si] = _tflat[_toff:_toff + _tln]
                    _toff += _tln
                del _tflat
            for si in range(n_seq_ref):
                c = _tcut_host.get(si) if si in _tcut_host else _cuts[si]
                _d = {}
                p, r_, f_, rp = boundary_alignment(
                    c, val_bnd[si], seq_len, tol=bnd_tol,
                    provenance=_prov, detail=_d,
                    rand_kind=bnd_rand_kind)
                ps.append(p)
                rs.append(r_)
                fs.append(f_)
                rps.append(rp)
                _tp += int(_d.get('tp', 0))
                _fp += int(_d.get('fp', 0))
                _fn += int(_d.get('fn', 0))
                _n_pred += int(_d.get('n_pred', 0))
                _n_gt += int(_d.get('n_gt', 0))
            if n_seq_ref:
                entry['bnd_prec'] = float(np.mean(np.asarray(ps)))
                entry['bnd_rec'] = float(np.mean(np.asarray(rs)))
                entry['bnd_f1'] = float(np.mean(np.asarray(fs)))
                entry['bnd_f1_average'] = 'macro_over_sequences'
                entry['bnd_prec_micro'] = float(_tp / _n_pred) if _n_pred else 0.0
                entry['bnd_rec_micro'] = float(_tp / _n_gt) if _n_gt else 0.0
                _pm, _rm = entry['bnd_prec_micro'], entry['bnd_rec_micro']
                entry['bnd_f1_micro'] = (float(2 * _pm * _rm / (_pm + _rm))
                                         if (_pm + _rm) else 0.0)
                entry['bnd_tp'] = int(_tp)
                entry['bnd_fp'] = int(_fp)
                entry['bnd_fn'] = int(_fn)
                entry['bnd_rand'] = float(np.mean(np.asarray(rps)))
                entry['bnd_excess'] = entry['bnd_prec'] - entry['bnd_rand']
                entry['bnd_rand_exact'] = bool(_prov.get('bnd_rand_exact', True))
                entry['bnd_rand_kind'] = str(_prov.get('bnd_rand_kind') or bnd_rand_kind)
                entry['bnd_rand_definition'] = str(
                    _prov.get('bnd_rand_definition')
                    or ('fixed_block_count' if entry['bnd_rand_kind'] == 'matched_cut_count'
                        else 'per_sequence_independent'))
                if not entry['bnd_rand_exact']:
                    print(f'[compression_report] WARNING: `bnd_rand` for L{li}_{kind} is a SAMPLED estimate, not the exact expectation, so `bnd_excess` carries Monte-Carlo error — recorded as `bnd_rand_exact: False` and it must not be pooled with the exact panels.')
            else:
                print('[compression_report] WARNING: no reference sequence to score (n_seq_ref=0) — boundary metrics OMITTED rather than published as nan')
            entry['bnd_n_seq'] = n_seq_ref
        tag = 'dyn' if attn.cfg.dynamic else 'fix'
        report[f'L{li}_{kind}_{tag}'] = entry
    return report


@torch.inference_mode()
def _compression_report_impl(model, val_batch, device, n_sample, val_bnd, bnd_tol,
                             *, bnd_rand_kind='matched_cut_count'):
    report = {}
    seq_len = val_batch.shape[1]
    if int(n_sample) < 1:
        raise ValueError(f'compression_report: n_sample must be >= 1, got {n_sample!r}; the report is an average over the sequences it scores, so there is nothing to measure with no sequence scored')
    n_used = min(n_sample, val_batch.shape[0])
    _row_chunk = _eval_adaptive_chunk(model, np.asarray(val_batch), device,
                                      min(16, _EVAL_TOKENS_PER_CHUNK // max(seq_len, 1)))
    _row_chunk = max(1, min(_row_chunk, n_used))
    # inference_mode (the decorator) already covers the forward pass.  The
    # sampled sequences are independent, so the row grouping does not change
    # any value.
    _r0 = 0
    while _r0 < n_used:
        _cur = min(_row_chunk, n_used - _r0)
        # A failed forward may already have appended per-layer block counts
        # (the stats hook runs layer by layer).  Snapshot them so the retry
        # cannot count the partially-processed rows twice.
        _stats_snap = _snapshot_block_stats(model)
        # as_tensor accepts numpy arrays AND torch tensors (eval_ppl already
        # uses it).
        ids = None
        try:
            ids = torch.as_tensor(np.asarray(val_batch[_r0:_r0 + _cur])).to(device)
            _ = model(ids, logits_tail=1)
        except RuntimeError as _oe:
            del ids
            if ('out of memory' in str(_oe).lower()) and _cur > 1:
                _restore_block_stats(_stats_snap)
                if device.type == 'cuda':
                    torch.cuda.empty_cache()
                _row_chunk = max(1, _cur // 2)
                print(f'[compression_report] device-memory exhaustion; retrying with row_chunk={_row_chunk}')
                continue
            raise
        del ids
        _r0 += _cur
    return _compression_report_summary(model, int(seq_len), val_bnd, bnd_tol,
                                        bnd_rand_kind=bnd_rand_kind)

def is_no_decay(name):
    if any((k in name for k in ('delta_logit', 'B_pos', 'W_aZ', 'W_bZ', 'sink', 'tok.weight', 'pos.weight', 'fuse_conv', 'q_norm', 'kv_norm'))):
        return True
    return name == 'g' or name.endswith('.g')

def is_delta_param(name):
    return 'delta_logit' in name

# ---- 受控变量描述符：优化器 / 调度 / 裁剪 / 数据增强 ----
# 对比实验要求「除待验证模块外，优化器、学习率策略、训练轮数、数据增强等设置
# 必须完全一致」。这些设置是 train_variant 内的模块常量，对所有臂天然一致，
# 但 run_cfg 指纹并不显式记录它们——一旦扩规模时为某条臂单独改优化器/调度
# （或将来引入数据增强），两条记录仍可能通过 `pair_reason` 的同 run_cfg 门槛
# 而被静默配对。这里把同一组常量导出成 `training_knobs()` 描述符，随每条记录
# 落盘；`pair_reason` 对两条都带该字段的记录额外要求逐字段相等（缺字段的记录
# 不受影响），审计则把该描述符打印出来「证明」两臂共享优化器与调度，而不是
# 只靠断言。
OPT_ADAMW_BETAS = (0.9, 0.999)
OPT_ADAMW_EPS = 1e-08
GRAD_CLIP_NORM = 1.0
LR_FLOOR_MULT = 0.1
BOUNDARY_PG_COEF = 1.0
LR_COSINE_AMP = 0.45

def optimizer_param_groups(model):
    """Split trainable parameters exactly as the production trainer does."""
    decay = [p for n_, p in model.named_parameters()
             if p.requires_grad and (not is_no_decay(n_)) and (not is_delta_param(n_))]
    no_decay = [p for n_, p in model.named_parameters()
                if p.requires_grad and is_no_decay(n_) and (not is_delta_param(n_))]
    delta = [p for n_, p in model.named_parameters()
             if p.requires_grad and is_delta_param(n_)]
    return decay, no_decay, delta

def build_optimizer(model, *, lr, weight_decay, delta_lr_mult=10.0):
    """Build the production AdamW optimizer (three groups, foreach=True).

    The overfit/reproducibility pre-flights use this function too, so a
    parameter-grouping change can no longer pass a hand-rolled probe while
    breaking the real training loop.
    """
    decay, no_decay, delta = optimizer_param_groups(model)
    groups = [
        {'params': decay, 'weight_decay': float(weight_decay), 'lr_scale': 1.0},
        {'params': no_decay, 'weight_decay': 0.0, 'lr_scale': 1.0},
        {'params': delta, 'weight_decay': 0.0, 'lr_scale': float(delta_lr_mult)},
    ]
    return torch.optim.AdamW(groups, lr=float(lr), betas=OPT_ADAMW_BETAS,
                             eps=OPT_ADAMW_EPS, foreach=True)

def training_knobs(*, amp_dtype='auto', eager_batch='auto'):
    """Canonical, JSON-safe descriptor of the optimisation / schedule /
    gradient-clipping / augmentation / precision settings shared by every arm
    of a controlled panel.

    ``amp_dtype`` and ``eager_batch`` default to the mode that `train_variant`
    will actually use on this machine.  Callers that implement their own
    training loop (for example v7's fp32 warm-up loop) pass their concrete
    values so the record describes what ran instead of what the default would
    have been.  Keeping both fields in this descriptor makes them enter the
    resume fingerprint (`training_knobs_fingerprint`) and the per-record
    pairing gate, so an old fp32 / row-by-row cell can never be silently
    reused by a bf16 / batched-twin run.
    """
    if amp_dtype == 'auto':
        amp_dtype = _active_amp()
    if eager_batch == 'auto':
        eager_batch = _eager_batch_active()
    return {
        'optimizer': 'AdamW',
        'foreach': True,
        'betas': list(OPT_ADAMW_BETAS),
        'eps': OPT_ADAMW_EPS,
        'param_groups': 'decay (wd) | no-decay (wd=0) | delta_logit (wd=0, lr x delta_lr_mult)',
        'grad_clip_norm': GRAD_CLIP_NORM,
        'lr_schedule': 'linear_warmup_then_cosine',
        'lr_floor_mult': LR_FLOOR_MULT,
        'lr_cosine_amp': LR_COSINE_AMP,
        'augmentation': 'none',
        'amp_dtype': amp_dtype,
        'amp_grad_scaler': amp_dtype == 'fp16',
        'eager_batch': bool(eager_batch),
    }

def training_knobs_fingerprint(*, amp_dtype='auto', eager_batch='auto'):
    """Short, stable digest of the shared optimisation/training descriptor.

    `run_cfg` already pins lr / wd / warmup / steps / tokens / architecture /
    data, but it deliberately does not carry the optimizer identity, betas,
    eps, LR-schedule shape, grad-clip, augmentation or the numerical
    implementation mode (AMP dtype / batched eager twin).  Those live in the
    per-record `train_knobs` copy, which `pair_reason` checks at analysis
    time.  Putting this digest in the resume fingerprint makes a changed
    descriptor invalidate earlier cells just like a changed lr.
    Unset/legacy fingerprints simply decode without a `tk` field.
    """
    if amp_dtype == 'auto' and eager_batch == 'auto':
        _knobs = training_knobs()
    else:
        _knobs = training_knobs(amp_dtype=amp_dtype, eager_batch=eager_batch)
    blob = json.dumps(_knobs, sort_keys=True, separators=(',', ':'),
                      ensure_ascii=True)
    return hashlib.sha256(blob.encode('utf-8')).hexdigest()[:12]

_CKPT_PEAK_MEMO = {}


def _ckpt_geom_key(n_param, n_layers, d, mlp_ratio, batch_size, seq_len, cfgs, n_heads=8, d_head=32):
    kinds = ','.join(str(getattr(c, 'kind', 'full')) for c in (cfgs or []))
    return (hex(int(n_param)), int(n_layers), int(d), round(float(mlp_ratio), 4),
            int(batch_size), int(seq_len), int(n_heads), int(d_head), kinds)


def _auto_ckpt_mode(device, n_param, n_layers, d, mlp_ratio, batch_size, seq_len, cfgs, n_heads=8, d_head=32):
    # Explicit CSA_CKPT always wins.  Otherwise, on a CUDA box, fall back to
    # activation recomputation when the estimated working set is large.  The
    # recomputed forward is the same pure function, so values and gradients
    # are unchanged (the contract documented at the top).
    if os.environ.get('CSA_CKPT', '').strip():
        return None, None
    if device.type != 'cuda' or not torch.cuda.is_available():
        return None, None
    try:
        free, _total = torch.cuda.mem_get_info(device)
    except Exception:
        return None, None
    tok = max(1, int(batch_size)) * max(1, int(seq_len))
    hidden = max(1, int(round(int(d) * float(mlp_ratio))))
    act = int(n_layers) * tok * (hidden + 8 * int(d)) * 4
    seq = max(1, int(seq_len))
    batch = max(1, int(batch_size))
    extra = 0
    nh = max(1, int(n_heads))
    hd = max(1, int(d_head))
    for c in cfgs:
        kind = getattr(c, 'kind', 'full')
        if kind in ('csa', 'hca'):
            step = max(1, int(getattr(c, 'block_size', 0) or getattr(c, 'target_block_tokens', 0) or getattr(c, 'min_block', 1) or 1))
            Bm = (seq + step - 1) // step
            nih = max(1, int(getattr(c, 'n_index_heads', 1) or 1))
            topk = max(1, int(getattr(c, 'index_topk', 1) or 1))
            win = max(0, int(getattr(c, 'sliding_window', 0) or 0))
            nb_eff = Bm if kind == 'hca' else min(topk, Bm)
            M = nb_eff + win
            index_bytes = seq * Bm * nih * 4
            gather_bytes = (4 * M * nh * hd + 2 * M * nh) * 4
            extra += batch * max(index_bytes, gather_bytes)
            if kind == 'hca':
                extra += batch * seq * Bm * 4
        elif kind == 'full':
            win = max(0, int(getattr(c, 'window', 0) or 0))
            if getattr(c, 'full_sink', False):
                span = seq
            elif 0 < win < seq:
                span = win
            else:
                span = min(seq, 1024)
            extra += batch * 3 * nh * seq * span * 4
    need = act + int(extra) + 16 * int(n_param)
    _peak = _CKPT_PEAK_MEMO.get(_ckpt_geom_key(n_param, n_layers, d, mlp_ratio, batch_size, seq_len, cfgs, n_heads=n_heads, d_head=d_head))
    if _peak:
        need = max(need, int(_peak))
    if free >= need + need // 3:
        return None, need
    has_gate = any(getattr(c, 'chunking', '') == 'cosine_learnable' for c in cfgs)
    # Block-level recompute cannot cover the gate-mean side channel; those
    # arms use the MLP-level fallback.
    mode = 'mlp' if (has_gate or free >= (need * 3) // 4) else 'block'
    return mode, need

_CURVE_MAX_POINTS = 200000
_CURVE_SIDECAR_INLINE_PPL = 4096


def _file_sha256(path, *, chunk=1 << 20):
    """SHA-256 of an artifact file, or None when it cannot be read.

    Tracking currently records a *path* for a curve sidecar.  A path alone
    cannot distinguish the curve written by this cell from a later edit or a
    file copied in from another run.  Storing the digest turns the reference
    into an auditable pointer; the verifier can then recompute it.
    """
    try:
        h = hashlib.sha256()
        with open(path, 'rb') as f:
            while True:
                b = f.read(int(chunk))
                if not b:
                    break
                h.update(b)
        return h.hexdigest()
    except (OSError, TypeError, ValueError):
        return None


def _curve_sidecar_rel(key):
    safe = ''.join(ch if (ch.isalnum() or ch in '._:-') else '_' for ch in str(key))
    return f'curves/{safe}.json'


def _write_cell_curve(outdir, key, rec):
    """Move per-cell curve arrays out of the shared summary file.

    The summary is rewritten (and re-parsed) under the panel lock after every
    cell; embedding a 200k-point loss curve makes that work grow with
    cells x curve length.  Each cell's arrays go to its own sidecar and the
    summary keeps only scalar metadata plus a reference."""
    losses = rec.get('losses') if isinstance(rec.get('losses'), list) else []
    delta = rec.get('delta_trace') if isinstance(rec.get('delta_trace'), dict) else {}
    ph = rec.get('ppl_history') if isinstance(rec.get('ppl_history'), list) else []
    diag = rec.get('opt_diag') if isinstance(rec.get('opt_diag'), dict) else {}
    move_ph = len(ph) > _CURVE_SIDECAR_INLINE_PPL
    payload = {}
    if losses:
        payload['losses'] = losses
    if delta:
        payload['delta_trace'] = delta
    if move_ph:
        payload['ppl_history'] = ph
    if diag:
        payload['opt_diag'] = diag
    if not payload:
        return None, losses, ph, move_ph
    rel = _curve_sidecar_rel(key)
    try:
        atomic_write_json(os.path.join(outdir, rel), payload, indent=0)
    except Exception as _e:
        print(f'[track] WARNING: could not write curve sidecar {rel} ({type(_e).__name__}: {_e}); keeping this cell\'s curves inline')
        return None, losses, ph, False
    if diag:
        rec.pop('opt_diag', None)
        rec['opt_diag_ref'] = rel
        rec['opt_diag_n_points'] = len(diag.get('step') or [])
    return rel, losses, ph, move_ph


def _cell_curve_data(outdir, rec):
    ref = rec.get('curve_ref') if isinstance(rec, dict) else None
    if not ref:
        return {}
    try:
        with open(os.path.join(outdir, ref), encoding='utf-8') as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _reduce_curve_values(vals, max_points):
    """Downsample a loss curve while preserving spikes and non-finite points.

    A plain ``linspace`` stride can drop a one-step NaN/explosion between two
    retained samples, making a diverged long run look clean in the artifact.
    Each bin therefore keeps its first/last index, its finite min/max and the
    first non-finite index.  The result is sorted and bounded by
    ``max_points`` (7 slots per bin).
    """
    n = len(vals)
    max_points = int(max_points)
    if max_points < 1:
        # A zero-point budget cannot retain any sample.  Returning the
        # historical fixed set would silently exceed the caller's bound.
        return []
    if n <= max_points:
        return list(vals)
    nb = max(1, max_points // 7)
    first = [-1] * nb
    last = [-1] * nb
    mini = [-1] * nb
    maxi = [-1] * nb
    badi = [-1] * nb
    minv = [0.0] * nb
    maxv = [0.0] * nb
    for i, v in enumerate(vals):
        b = min(nb - 1, (i * nb) // n)
        if first[b] < 0:
            first[b] = i
        last[b] = i
        try:
            f = float(v)
        except (TypeError, ValueError, OverflowError):
            f = None
        if f is None or not math.isfinite(f):
            if badi[b] < 0:
                badi[b] = i
            continue
        if mini[b] < 0 or f < minv[b]:
            mini[b] = i
            minv[b] = f
        if maxi[b] < 0 or f > maxv[b]:
            maxi[b] = i
            maxv[b] = f
    keep = set()
    for i in range(nb):
        for _ix in (first[i], mini[i], maxi[i], badi[i], last[i]):
            if _ix >= 0:
                keep.add(int(_ix))
    if n:
        keep.add(n - 1)
    _keep = sorted(keep)
    if len(_keep) > max_points:
        # The bin heuristic keeps up to five landmarks per bin, which is more
        # than a very small budget allows.  Keep the last point and the first
        # non-finite/extreme points when they fit, then fill chronologically.
        _bad = _mini = _maxi = None
        _minv = _maxv = None
        for _i, _v in enumerate(vals):
            try:
                _f = float(_v)
            except (TypeError, ValueError, OverflowError):
                _f = None
            if _f is None or not math.isfinite(_f):
                if _bad is None:
                    _bad = _i
                continue
            if _mini is None or _f < _minv:
                _mini, _minv = _i, _f
            if _maxi is None or _f > _maxv:
                _maxi, _maxv = _i, _f
        _sel = []
        for _ix in (n - 1, _bad, _mini, _maxi, 0):
            if _ix is not None and 0 <= _ix < n and _ix not in _sel:
                _sel.append(int(_ix))
                if len(_sel) >= max_points:
                    break
        if len(_sel) < max_points:
            for _ix in _keep:
                if _ix not in _sel:
                    _sel.append(_ix)
                    if len(_sel) >= max_points:
                        break
        _keep = sorted(_sel)
    return [vals[i] for i in _keep]


def _curve_extend(dst, new):
    dst.extend(new)
    if len(dst) > 2 * _CURVE_MAX_POINTS:
        dst[:] = _reduce_curve_values(dst, _CURVE_MAX_POINTS)


def _reduce_curve_points(points, max_points):
    """Downsample ``[step, value]`` trace points without losing spikes/NaN.

    ``_reduce_curve_values`` scores plain scalars; a per-layer delta trace stores
    point pairs, so the spike test must look at the value column.  Bins keep
    their first/last index, finite min/max and first non-finite index.
    """
    n = len(points)
    max_points = int(max_points)
    if max_points < 1:
        return []
    if n <= max_points:
        return list(points)
    nb = max(1, max_points // 7)

    def _value(point):
        if isinstance(point, (list, tuple)) and len(point) >= 2:
            return point[1]
        return point

    first = [-1] * nb
    last = [-1] * nb
    mini = [-1] * nb
    maxi = [-1] * nb
    badi = [-1] * nb
    minv = [0.0] * nb
    maxv = [0.0] * nb
    for i, point in enumerate(points):
        b = min(nb - 1, (i * nb) // n)
        if first[b] < 0:
            first[b] = i
        last[b] = i
        try:
            f = float(_value(point))
        except (TypeError, ValueError, OverflowError):
            f = None
        if f is None or not math.isfinite(f):
            if badi[b] < 0:
                badi[b] = i
            continue
        if mini[b] < 0 or f < minv[b]:
            mini[b] = i
            minv[b] = f
        if maxi[b] < 0 or f > maxv[b]:
            maxi[b] = i
            maxv[b] = f
    keep = set()
    for i in range(nb):
        for _ix in (first[i], mini[i], maxi[i], badi[i], last[i]):
            if _ix >= 0:
                keep.add(int(_ix))
    if n:
        keep.add(n - 1)
    _keep = sorted(keep)
    if len(_keep) > max_points:
        _bad = _mini = _maxi = None
        _minv = _maxv = None
        for _i, _point in enumerate(points):
            try:
                _f = float(_value(_point))
            except (TypeError, ValueError, OverflowError):
                _f = None
            if _f is None or not math.isfinite(_f):
                if _bad is None:
                    _bad = _i
                continue
            if _mini is None or _f < _minv:
                _mini, _minv = _i, _f
            if _maxi is None or _f > _maxv:
                _maxi, _maxv = _i, _f
        _sel = []
        for _ix in (n - 1, _bad, _mini, _maxi, 0):
            if _ix is not None and 0 <= _ix < n and _ix not in _sel:
                _sel.append(int(_ix))
                if len(_sel) >= max_points:
                    break
        if len(_sel) < max_points:
            for _ix in _keep:
                if _ix not in _sel:
                    _sel.append(_ix)
                    if len(_sel) >= max_points:
                        break
        _keep = sorted(_sel)
    return [points[i] for i in _keep]


_LEDGER_CURVE_MAX_POINTS = 20000


def _ledger_curve(values, max_points=_LEDGER_CURVE_MAX_POINTS):
    """Bound the curves embedded in the append-only JSONL ledger.

    The full curve is already in the per-cell sidecar / summary; a 200k-point
    array in every ledger line grows the trace quadratically with panel size.
    Small curves stay byte-identical for readers of old ledgers; a long curve
    is spike-preserving downsampled and annotated with its true length.
    """
    vals = list(values) if isinstance(values, (list, tuple)) else []
    n = len(vals)
    if n <= int(max_points):
        return vals, n, False
    return _reduce_curve_values(vals, int(max_points)), n, True


def _ledger_curve_points(points, max_points=_LEDGER_CURVE_MAX_POINTS):
    pts = list(points) if isinstance(points, (list, tuple)) else []
    n = len(pts)
    if n <= int(max_points):
        return pts, n, False
    return _reduce_curve_points(pts, int(max_points)), n, True


def _curve_append_point(dst, point):
    dst.append(point)
    if len(dst) > 2 * _CURVE_MAX_POINTS:
        dst[:] = _reduce_curve_points(dst, _CURVE_MAX_POINTS)


def distributed_info():
    """Return ``(rank, world_size, active)`` for a torchrun/DDP launch.

    Initialises the default process group on first use when ``WORLD_SIZE > 1``
    and no group exists yet.  Single-process runs return ``(0, 1, False)`` and
    never touch torch.distributed, so the historical path is unchanged."""
    if not torch.distributed.is_available():
        return (0, 1, False)
    if torch.distributed.is_initialized():
        return (torch.distributed.get_rank(), torch.distributed.get_world_size(), torch.distributed.get_world_size() > 1)
    try:
        world = int(os.environ.get('WORLD_SIZE', '1') or 1)
    except ValueError:
        world = 1
    if world <= 1:
        return (0, 1, False)
    backend = 'nccl' if torch.cuda.is_available() else 'gloo'
    torch.distributed.init_process_group(backend=backend)
    return (torch.distributed.get_rank(), torch.distributed.get_world_size(), True)


def is_main_process():
    return distributed_info()[0] == 0


def _all_ranks_agree(local_ok, distributed, device):
    """Rank-agreed boolean for a branch that runs DDP collectives.

    A per-rank condition (finite loss, finite gradient norm) must be reduced
    before choosing whether to enter backward/step: if one rank skips and a
    peer enters the DDP gradient collective, the job deadlocks.  Outside a
    multi-process launch this is exactly the caller's local boolean.
    """
    if not distributed:
        return bool(local_ok)
    flag = torch.tensor([1 if bool(local_ok) else 0], dtype=torch.int32,
                        device=device)
    torch.distributed.all_reduce(flag, op=torch.distributed.ReduceOp.MIN)
    return bool(int(flag.item()))


def _amp_requested():
    """Mixed-precision mode for the training path.

    CUDA training defaults to bf16 autocast with fp32 master parameters;
    ``CSA_AMP=fp16`` additionally uses a GradScaler, and ``CSA_AMP=0``
    (or false/no/off) opts back into the pure-fp32 path.  The chosen dtype is
    recorded in each result so fp32 and autocast runs never mix silently."""
    v = os.environ.get('CSA_AMP', '').strip().lower()
    if v in ('0', 'false', 'no', 'off'):
        return None
    if v in ('', '1', 'true', 'yes', 'on', 'bf16', 'bfloat16'):
        return 'bf16'
    if v in ('fp16', 'float16', 'half'):
        return 'fp16'
    print(f'[amp] CSA_AMP={v!r} is not recognised (use bf16/fp16/0) — staying in fp32 instead of silently changing the numerical path')
    return None


def _active_amp(device=None):
    """The autocast dtype the training path uses on ``device``.

    The fp32 path is the historical, bitwise-stable one; AMP only applies on
    CUDA.  Keeping this helper separate lets `training_knobs()` record the
    concrete choice on a CPU analysis box (None) without pretending that a
    GPU job ran in fp32."""
    if device is None:
        device = DEVICE
    if getattr(device, 'type', str(device)) != 'cuda':
        return None
    _amp = _amp_requested()
    # bf16 is requested unconditionally on CUDA, but pre-Ampere
    # GPUs (V100/T4) cannot run it.  Failing here with a clear message beats
    # training under a silently different numerical path and then having the
    # frozen confirmation binding reject or mis-certify every record.
    if _amp == 'bf16' and not torch.cuda.is_bf16_supported():
        raise RuntimeError('this GPU does not support bf16 (pre-Ampere); set CSA_AMP=fp16 to train under the fp16 autocast path, or move the frozen run to an Ampere-or-newer GPU — do not run the frozen confirmation in fp32/bf16-mismatch mode')
    return _amp


def _normalise_amp_mode(v):
    """Canonical ``None`` / ``'bf16'`` / ``'fp16'`` spelling of an AMP mode."""
    if v is None:
        return None
    s = str(v).strip().lower()
    if s in ('', 'none', 'fp32', 'float32', 'off', '0', 'false', 'no'):
        return None
    if s in ('bf16', 'bfloat16'):
        return 'bf16'
    if s in ('fp16', 'float16', 'half'):
        return 'fp16'
    raise ValueError(f"unknown amp_dtype {v!r} (use bf16/fp16/fp32 or auto)")


def _normalise_eager_batch(v):
    if v is None:
        return None
    if isinstance(v, (bool, np.bool_)):
        return bool(v)
    if isinstance(v, str):
        s = v.strip().lower()
        if s in ('', 'auto'):
            return None
        if s in ('1', 'true', 'yes', 'on'):
            return True
        if s in ('0', 'false', 'no', 'off'):
            return False
        raise ValueError(f"unknown eager_batch {v!r} (use true/false or auto)")
    if isinstance(v, numbers.Integral):
        if int(v) in (0, 1):
            return bool(int(v))
    elif isinstance(v, numbers.Real):
        f = float(v)
        if math.isfinite(f) and f in (0.0, 1.0):
            return bool(int(f))
    # A typo such as 'flase', NaN or 1.5 must not silently select the batched
    # backend; make the caller state the mode explicitly.
    raise ValueError(f"unknown eager_batch {v!r} (use true/false or auto)")


def _resolve_impl_modes(cfg=None, *, device=None):
    """Resolve ``(amp_dtype, eager_batch)`` for one concrete run.

    Explicit values in ``cfg`` always win, so a planner / report process and a
    par.py child can recompute the same resume fingerprint from a persisted
    manifest without probing their own CUDA state.  Only when the config says
    ``auto`` (or omits the key) AND a concrete ``device`` is supplied is the
    mode inferred locally.  With neither, the machine-independent canonical
    default (fp32 / row-by-row) is used.

    A frozen config naming a mode the device cannot provide is an error, not a
    silent downgrade: the record would otherwise claim an implementation it
    did not run.
    """
    cfg = {} if cfg is None else cfg
    amp_raw = cfg.get('amp_dtype', 'auto')
    eb_raw = cfg.get('eager_batch', 'auto')
    amp_auto = isinstance(amp_raw, str) and amp_raw.strip().lower() == 'auto'
    eb_auto = _normalise_eager_batch(eb_raw) is None

    if amp_auto:
        amp = _active_amp(device) if device is not None else None
    else:
        amp = _normalise_amp_mode(amp_raw)
        if amp is not None and device is not None and getattr(device, 'type', str(device)) != 'cuda':
            raise RuntimeError(f'run config requires amp_dtype={amp!r} but device={device} cannot provide CUDA autocast; pass amp_dtype=fp32 or run on CUDA instead of silently changing the numerical path')
    if eb_auto:
        eb = _eager_batch_active(device, cfg.get('batch_size')) if device is not None else False
    else:
        eb = bool(_normalise_eager_batch(eb_raw))
        if eb and device is not None and not _eager_batch_active(device, cfg.get('batch_size')):
            raise RuntimeError(f'run config requires eager_batch={eb!r} but device={device}/backend cannot provide the batched CUDA twin; pass eager_batch=false or fix the runtime instead of silently changing the implementation')
    return amp, bool(eb)


def _is_finite_number(v):
    return _finite_scalar(v) is not None


def data_seed_for_rank(seed, rank):
    """Domain-safe per-rank data seed for DDP.

    Rank 0 keeps the single-process stream unchanged.  Other ranks get a
    deterministic SplitMix64 derivation instead of ``seed + rank``, which can
    overflow the NumPy/PyTorch seed domain and can silently collide with a
    different declared seed (seed=0/rank=1 vs seed=1/rank=0).
    """
    seed = _seed_value(seed)
    rank = int(rank)
    if rank < 0:
        raise ValueError(f'rank must be non-negative, got {rank}')
    if rank == 0:
        return seed
    mixed = _splitmix64_u64((int(seed) << 32) ^ (rank & 0xFFFFFFFF))
    return int(mixed % (MAX_SEED + 1))

def _fixed_train_eval_batch(train_ids, seq_len, batch_size, device, seed):
    """One deterministic batch used ONLY to measure training CE on a fixed
    distribution.  It has its own RNG stream, so it cannot perturb the training
    batch order."""
    gen = batch_iter(train_ids, seq_len, batch_size, device, seed=int(seed) ^ 0x5F3759DF)
    try:
        return next(gen)
    finally:
        try:
            gen.close()
        except Exception:
            pass


def _audit_sample_flat(arr, max_tokens):
    """Deterministic, bounded sample of a flat token stream for data audits.

    A scale-up corpus can hold billions of ids; scanning all of it on every
    training cell would make the guard itself a cost centre.  When the array is
    larger than ``max_tokens`` we read equally spaced windows (the same strategy
    as ``audit_corpus_split``) and report that the check was sampled.
    """
    flat = np.asarray(arr).reshape(-1)
    n = int(flat.size)
    _max = _exact_count(max_tokens, minimum=1)
    if _max is None:
        raise ValueError(
            f'_audit_sample_flat needs a positive integer max_tokens, got {max_tokens!r}')
    max_tokens = int(_max)
    if n <= max_tokens:
        return flat, False
    # The budget can be smaller than the historical 16 windows.  Shrinking the
    # window count (and keeping width >= 1) makes the bound hold even for
    # max_tokens=1; the old fixed 16 windows returned 16 elements for a
    # one-token budget, so the audit's stated cost was exceeded 16x.
    n_windows = min(16, max_tokens)
    width = max(1, max_tokens // n_windows)
    starts = np.linspace(0, max(0, n - width), num=n_windows, dtype=np.int64)
    parts = [flat[int(s):int(s) + width] for s in starts]
    return np.concatenate(parts) if parts else flat[:0], True


def audit_token_data(train_ids, val_batch, vocab, *, max_sample_tokens=2_000_000):
    """Pre-training data contract for the NaN/Inf triage path.

    The prompt's first NaN suspect is the data, so the trainer records an
    explicit, machine-checkable answer instead of a free-text "data checked"
    claim.  Integer token caches cannot contain NaN/Inf, but a float feature
    cache can; both are checked here.  Out-of-vocabulary or negative ids and
    non-finite float values abort the run before a model is built.  The
    training stream is sampled deterministically when it is large; the
    validation split is scanned in full because it is bounded by ``val_seqs``.
    """
    _max = _exact_count(max_sample_tokens, minimum=1)
    if _max is None:
        raise ValueError(f'audit_token_data needs a positive integer max_sample_tokens, got {max_sample_tokens!r}')
    max_sample_tokens = int(_max)
    vocab = int(vocab)
    out = {'kind': 'token_data_audit', 'status': 'ok', 'vocab': vocab,
           'max_sample_tokens': max_sample_tokens, 'sections': {}}

    def _check(arr, name, *, sample):
        arr = np.asarray(arr)
        if arr.size == 0:
            raise ValueError(f'{name}: token array is empty')
        flat = arr.reshape(-1)
        values, sampled = _audit_sample_flat(flat, max_sample_tokens) if sample else (flat, False)
        is_bool = (np.dtype(arr.dtype).kind == 'b')
        is_float = np.dtype(arr.dtype).kind in 'fc'
        n_nonfinite = 0
        if is_float:
            try:
                n_nonfinite = int(values.size - np.isfinite(values).sum())
            except (TypeError, ValueError, OverflowError):
                n_nonfinite = int(values.size)
        if n_nonfinite:
            raise ValueError(f'{name}: {n_nonfinite} non-finite (NaN/Inf) value(s) in the checked '
                             f'{values.size:,} token(s); fix the data before training')
        if is_float or is_bool or not np.issubdtype(arr.dtype, np.integer):
            raise TypeError(f'{name}: expected integer token ids, got dtype {arr.dtype}'
                            + (' (all finite, but token ids must be integral)' if is_float and not n_nonfinite else ''))
        try:
            lo = int(values.min())
            hi = int(values.max())
        except (TypeError, ValueError, OverflowError):
            raise ValueError(f'{name}: could not read the token-id range') from None
        n_out = int(np.count_nonzero((values < 0) | (values >= vocab)))
        if n_out:
            raise ValueError(f'{name}: {n_out} token id(s) outside vocab [0, {vocab}) '
                             f'(checked range [{lo}, {hi}])')
        return {'dtype': np.dtype(arr.dtype).str, 'n_tokens': int(flat.size),
                'n_checked': int(values.size), 'sampled': bool(sampled),
                'n_nonfinite': int(n_nonfinite), 'n_out_of_range': int(n_out),
                'min_id': lo, 'max_id': hi}

    out['sections']['train'] = _check(train_ids, 'training ids', sample=True)
    if val_batch is not None:
        out['sections']['validation'] = _check(val_batch, 'validation ids', sample=False)
    else:
        out['sections']['validation'] = None
    out['checks'] = {
        'integer_ids': True,
        'range_ok': True,
        'finite_ok': True,
        'train_sampled': bool(out['sections']['train']['sampled']),
        'validation_scanned_in_full': val_batch is not None,
    }
    return out


def _check_token_batch(x, y, vocab, *, step=None):
    """Fail fast on a corrupted batch before it reaches the model."""
    for name, t in (('inputs', x), ('targets', y)):
        if not torch.is_tensor(t):
            raise TypeError(f'batch {name} is not a tensor (step={step})')
        if t.ndim != 2 or t.numel() == 0:
            raise ValueError(f'batch {name} must be a non-empty 2-D tensor, got shape {tuple(t.shape)} (step={step})')
        if t.dtype not in (torch.int8, torch.int16, torch.int32, torch.int64, torch.uint8):
            raise TypeError(f'batch {name} must contain integer token ids, got {t.dtype} (step={step})')
    if x.shape[0] != y.shape[0] or x.shape[1] != y.shape[1]:
        raise ValueError(f'batch inputs/targets shape mismatch: {tuple(x.shape)} vs {tuple(y.shape)} (step={step})')
    try:
        lo = int(x.min().item())
        hi = int(x.max().item())
    except Exception:
        return
    if lo < 0 or hi >= int(vocab):
        raise ValueError(f'batch token id range [{lo}, {hi}] outside vocab [0, {int(vocab)}) at step={step}')
    if bool((y < 0).any().item()) or int(y.max().item()) >= int(vocab):
        raise ValueError(f'batch target ids outside vocab [0, {int(vocab)}) at step={step}')


_PARAM_FINITE_CHECK = os.environ.get('CSA_PARAM_FINITE_CHECK', 'sample').strip().lower()


def _params_all_finite(model):
    flags = [torch.isfinite(p).all() for p in model.parameters() if p.numel()]
    if not flags:
        return True
    return bool(torch.stack(flags).all().item())


class _HashingWriter:
    """File proxy that hashes bytes as `torch.save` writes them.

    Hashing the same bytes on the way out avoids a second full-file read for
    the checkpoint digest."""

    __slots__ = ('_f', '_h')

    def __init__(self, f, h):
        self._f = f
        self._h = h

    def write(self, data):
        self._h.update(data)
        return self._f.write(data)

    def flush(self):
        return self._f.flush()

    def __getattr__(self, name):
        return getattr(self._f, name)


def _atomic_torch_save(obj, path, hash_out=None):
    d = os.path.dirname(os.path.abspath(path))
    os.makedirs(d, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=d, prefix=os.path.basename(path) + '.', suffix='.tmp')
    os.close(fd)
    h = hashlib.sha256() if hash_out is not None else None
    try:
        if h is None:
            torch.save(obj, tmp)
        else:
            with open(tmp, 'wb') as f:
                torch.save(obj, _HashingWriter(f, h))
        os.replace(tmp, path)
        if hash_out is not None:
            hash_out.append(h.hexdigest())
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


def _checkpoint_payload(model, *, variant, seed, step, val_ppl, train_ce, health, extra=None):
    # Keep the tensors where they live; torch.save streams each storage to the
    # file.  Loaders already use map_location='cpu' (error_analysis / v7_supp).
    sd = {k: v.detach() for k, v in model.state_dict().items()}
    payload = {'format': 'csa-analysis-ckpt-v1', 'variant': variant, 'seed': int(seed),
               'step': int(step), 'val_ppl': val_ppl, 'train_ce_fixed': train_ce,
               # The checkpoint must name the implementation that wrote it.
               # CKPT_CODE is the base semantics and omits the kernel suffix,
               # so a kernel-mode checkpoint was labelled eager.
               'curve_health': health, 'code': code_stamp(), 'sd': sd}
    if extra:
        payload.update(extra)
    return payload


def _save_analysis_checkpoint(path, model, meta):
    _sha = []
    _atomic_torch_save(_checkpoint_payload(model, **meta), path, hash_out=_sha)
    try:
        size = os.path.getsize(path)
    except OSError:
        size = None
    return {'path': path, 'bytes': size, 'sha256': (_sha[0] if _sha else None),
            'step': int(meta.get('step') or 0)}


def _percentile(vals, q):
    xs = []
    for v in vals:
        try:
            fv = float(v)
        except (TypeError, ValueError, OverflowError):
            continue
        if math.isfinite(fv):
            xs.append(fv)
    xs.sort()
    if not xs:
        return None
    if len(xs) == 1:
        return xs[0]
    pos = (len(xs) - 1) * float(q)
    lo = int(math.floor(pos))
    hi = int(math.ceil(pos))
    if lo == hi:
        return xs[lo]
    return xs[lo] + (xs[hi] - xs[lo]) * (pos - lo)


@torch.inference_mode()
def measure_efficiency(model, ids, device, warmup=1, iters=5, decode_tokens=8):
    """Measure prefill / prefix-prefill timing and allocator peaks.

    There is no KV cache in the model, so the decode number is explicitly a
    PREFIX-PREFILL measurement (it re-runs the whole prefix), not incremental
    decode.  Results are reported as p50/p95 wall-clock plus tokens/s and
    allocator peaks."""
    was = model.training
    model.eval()
    ids = torch.as_tensor(ids)
    if ids.ndim == 1:
        ids = ids[None, :]
    if ids.ndim != 2 or int(ids.shape[0]) < 1 or int(ids.shape[1]) < 1:
        raise ValueError(
            f'measure_efficiency needs a non-empty 1-D/2-D token table, got '
            f'shape {tuple(ids.shape)}')
    _warm = _exact_count(warmup, minimum=0)
    _iters = _exact_count(iters, minimum=1)
    _dec = _exact_count(decode_tokens, minimum=1)
    if _warm is None:
        raise ValueError(f'warmup must be a non-negative integer, got {warmup!r}')
    if _iters is None:
        raise ValueError(f'iters must be a positive integer, got {iters!r}')
    if _dec is None:
        raise ValueError(f'decode_tokens must be a positive integer, got {decode_tokens!r}')
    warmup, iters, decode_tokens = int(_warm), int(_iters), int(_dec)
    ids = ids.to(device)
    try:
        for _ in range(max(0, int(warmup))):
            model(ids)
        if device.type == 'cuda':
            torch.cuda.synchronize(device)
            torch.cuda.reset_peak_memory_stats(device)
        pre = []
        for _ in range(max(1, int(iters))):
            t0 = time.perf_counter()
            model(ids)
            if device.type == 'cuda':
                torch.cuda.synchronize(device)
            pre.append((time.perf_counter() - t0) * 1000.0)
        n_dec = min(max(1, int(decode_tokens)), max(1, int(ids.shape[1]) - 1))
        dec = []
        for t in range(max(1, int(ids.shape[1]) - n_dec), int(ids.shape[1]) + 1):
            t0 = time.perf_counter()
            model(ids[:, :t])
            if device.type == 'cuda':
                torch.cuda.synchronize(device)
            dec.append((time.perf_counter() - t0) * 1000.0)
        out = {'status': 'ok', 'n_tokens': int(ids.shape[1]), 'batch': int(ids.shape[0]),
               'device': str(device), 'torch': torch.__version__,
               'prefill_ms_p50': _percentile(pre, 0.50), 'prefill_ms_p95': _percentile(pre, 0.95),
               'prefix_prefill_ms_p50': _percentile(dec, 0.50),
               'prefix_prefill_ms_p95': _percentile(dec, 0.95),
               'tokens_per_s_prefill': (1000.0 * int(ids.shape[0]) * int(ids.shape[1]) / _percentile(pre, 0.50)) if _percentile(pre, 0.50) else None,
               'decode_has_kv_cache': False,
               'decode_metric': 'prefix_prefill (no KV cache; re-runs the whole prefix)'}
        if device.type == 'cuda':
            out['peak_mem_allocated_mb'] = torch.cuda.max_memory_allocated(device) / (1 << 20)
            out['peak_mem_reserved_mb'] = torch.cuda.max_memory_reserved(device) / (1 << 20)
        return out
    finally:
        model.train(was)


@torch.inference_mode()
def measure_efficiency_sweep(model, ids, device, *, lengths=(512, 2048), batches=(1,),
                             warmup=1, iters=3):
    """Batch x sequence-length latency/throughput sweep on ONE checkpoint.

    `measure_efficiency` answers "how fast is this one input"; a claim that an
    architecture is cheaper needs the shape dependence too (batch 1 vs 8,
    short vs long).  CUDA timings use events (so kernel launch is included but
    host-side jitter is not); CPU timings use perf_counter.  The output records
    the device, torch/triton versions and TF32 state so two rows are only
    compared when they were measured under the same conditions.

    There is still no KV cache in this model: the sweep measures full-prefix
    prefill, and `decode_has_kv_cache=False` is recorded rather than pretending
    this is incremental decoding.
    """
    was = model.training
    model.eval()
    arr = torch.as_tensor(ids)
    if arr.ndim == 1:
        arr = arr[None, :]
    if arr.ndim != 2 or int(arr.shape[0]) < 1 or int(arr.shape[1]) < 1:
        raise ValueError(
            f'measure_efficiency_sweep needs a non-empty 1-D/2-D token table, '
            f'got shape {tuple(arr.shape)}')
    try:
        _lens_raw = list(lengths)
    except TypeError:
        raise ValueError(f'lengths must be an iterable of positive integers, got {lengths!r}') from None
    if not _lens_raw:
        raise ValueError('lengths must contain at least one sequence length')
    _lens = []
    for _x in _lens_raw:
        _n = _exact_count(_x, minimum=1)
        if _n is None:
            raise ValueError(f'lengths must contain positive integers, got {_x!r}')
        _lens.append(int(_n))
    try:
        _batches_raw = list(batches)
    except TypeError:
        raise ValueError(f'batches must be an iterable of positive integers, got {batches!r}') from None
    if not _batches_raw:
        raise ValueError('batches must contain at least one batch size')
    _batches = []
    for _x in _batches_raw:
        _n = _exact_count(_x, minimum=1)
        if _n is None:
            raise ValueError(f'batches must contain positive integers, got {_x!r}')
        _batches.append(int(_n))
    _warm = _exact_count(warmup, minimum=0)
    _iters = _exact_count(iters, minimum=1)
    if _warm is None:
        raise ValueError(f'warmup must be a non-negative integer, got {warmup!r}')
    if _iters is None:
        raise ValueError(f'iters must be a positive integer, got {iters!r}')
    warmup, iters = int(_warm), int(_iters)
    arr = arr.to(device)
    max_len = int(min(arr.shape[1], max(_lens)))
    if not any(0 < int(x) <= max_len for x in _lens):
        raise ValueError(
            f'none of lengths={_lens} fits the token table width '
            f'{int(arr.shape[1])}; refusing to return an empty sweep as success')
    _skipped_lens = sorted({int(x) for x in _lens
                            if not (0 < int(x) <= max_len)})
    out = {'status': 'ok', 'device': str(device), 'torch': torch.__version__,
           'triton': None, 'tf32': None, 'rows': [],
           'requested_seq_lens': sorted({int(x) for x in _lens}),
           'skipped_seq_lens': _skipped_lens,
           'decode_has_kv_cache': False,
           'decode_metric': 'prefix_prefill (no KV cache)',
           'measurement': ('cuda events' if device.type == 'cuda' else 'cpu perf_counter')}
    if _skipped_lens:
        # A requested length wider than the token table is not measured.  Keep
        # it visible instead of returning a shorter grid that still claims
        # status=ok (the all-lengths-invalid case already raises).
        out['skipped_seq_lens_reason'] = (
            f'requested length(s) {_skipped_lens} exceed the token table width '
            f'{int(arr.shape[1])}; they were not measured')
    try:
        import triton  # noqa: F401
        out['triton'] = getattr(triton, '__version__', None)
    except Exception:
        out['triton'] = None
    try:
        out['tf32'] = bool(torch.backends.cuda.matmul.allow_tf32) if device.type == 'cuda' else None
    except Exception:
        pass
    try:
        for bs in _batches:
            for L in [int(x) for x in _lens if 0 < int(x) <= max_len]:
                base = arr[:, :L]
                if base.shape[0] < bs:
                    reps = (bs + base.shape[0] - 1) // base.shape[0]
                    batch = base.repeat(reps, 1)[:bs]
                else:
                    batch = base[:bs]
                for _ in range(max(0, int(warmup))):
                    model(batch)
                times = []
                if device.type == 'cuda':
                    torch.cuda.synchronize(device)
                    torch.cuda.reset_peak_memory_stats(device)
                for _ in range(max(1, int(iters))):
                    if device.type == 'cuda':
                        _s = torch.cuda.Event(enable_timing=True)
                        _e = torch.cuda.Event(enable_timing=True)
                        _s.record()
                        model(batch)
                        _e.record()
                        torch.cuda.synchronize(device)
                        times.append(float(_s.elapsed_time(_e)))
                    else:
                        _t0 = time.perf_counter()
                        model(batch)
                        times.append((time.perf_counter() - _t0) * 1000.0)
                p50 = _percentile(times, 0.50)
                row = {'batch': bs, 'seq_len': L,
                       'prefill_ms_p50': p50, 'prefill_ms_p95': _percentile(times, 0.95),
                       'tokens_per_s': (1000.0 * bs * L / p50) if p50 else None}
                if device.type == 'cuda':
                    row['peak_mem_allocated_mb'] = torch.cuda.max_memory_allocated(device) / (1 << 20)
                    row['peak_mem_reserved_mb'] = torch.cuda.max_memory_reserved(device) / (1 << 20)
                out['rows'].append(row)
    finally:
        model.train(was)
    out['measured_seq_lens'] = sorted({int(r['seq_len']) for r in out['rows']})
    return out


def train_variant(variant, train_ids, val_batch, vocab, *, seed=0, d=256, n_layers=6, n_heads=8, d_head=32, seq_len=512, batch_size=12, steps=1500, lr=0.0003, weight_decay=0.1, warmup=50, comp_lambda=0.05, delta_lr_mult=10.0, eval_every=0, eval_subset=128, val_bnd=None, device=DEVICE, log_every=100, mlp_ratio=4, deadline_ts=None, return_model=False, distributed=False, save_ckpt=None, ckpt_dir=None, diag_every=None, measure_eff=False, measure_eff_sweep=False, amp_dtype='auto', eager_batch='auto', early_stop_patience=None, early_stop_min_delta=0.0):
    if steps < 1:
        raise ValueError(f'train_variant needs steps >= 1, got steps={steps}')
    if early_stop_patience is None:
        _es_patience = None
        _es_min_delta = 0.0
    else:
        if (isinstance(early_stop_patience, (bool, np.bool_))
                or not isinstance(early_stop_patience, (int, np.integer))
                or int(early_stop_patience) < 1):
            raise ValueError(f'early_stop_patience must be a positive integer or None, got {early_stop_patience!r}')
        if isinstance(early_stop_min_delta, (bool, np.bool_)):
            raise ValueError(f'early_stop_min_delta must be a finite non-negative number, got {early_stop_min_delta!r}')
        try:
            _es_min_delta = float(early_stop_min_delta)
        except (TypeError, ValueError, OverflowError):
            raise ValueError(f'early_stop_min_delta must be a finite non-negative number, got {early_stop_min_delta!r}') from None
        if not math.isfinite(_es_min_delta) or _es_min_delta < 0.0:
            raise ValueError(f'early_stop_min_delta must be a finite non-negative number, got {early_stop_min_delta!r}')
        if not (eval_every and int(eval_every) > 0):
            raise ValueError('early_stop_patience needs eval_every > 0 so the validation curve is measured')
        _es_patience = int(early_stop_patience)
    seed = set_seed(seed)
    # Data is the first suspect on the NaN/Inf triage path.  Record an actual
    # contract check (range/dtype/finiteness) rather than a free-text claim.
    _data_audit = audit_token_data(train_ids, val_batch, vocab)
    _rng_fp = rng_fingerprint()
    _exec_fp = execution_fingerprint()
    _attb_bump_epoch()
    _amp, _ = _resolve_impl_modes({'amp_dtype': amp_dtype, 'eager_batch': False}, device=device)
    _amp_dtype = torch.bfloat16 if _amp == 'bf16' else (torch.float16 if _amp == 'fp16' else None)
    _scaler = torch.amp.GradScaler('cuda', enabled=(_amp == 'fp16')) if _amp is not None else None
    if _amp is not None:
        print(f'[amp] training autocast dtype={_amp} grad_scaler={_amp == "fp16"} (fp32 master weights)')
    _save_mode = str(save_ckpt or '').strip().lower()
    if _save_mode not in ('', 'none', 'off', '0', 'best', 'final', 'both'):
        print(f'[ckpt] ignoring unknown save_ckpt={save_ckpt!r} (use best/final/both/none)')
        _save_mode = ''
    if _save_mode in ('none', 'off', '0'):
        _save_mode = ''
    _nan_events = []
    _rank, _world, _dist = (0, 1, False)
    if distributed:
        _rank, _world, _dist = distributed_info()
        if not _dist:
            raise RuntimeError('train_variant(distributed=True) needs a torchrun WORLD_SIZE > 1 launch')
    nan_guard_state(reset=True)
    if variant in PARAM_MATCHED | PARAM_MATCHED_V7 and float(mlp_ratio) == 4.0:
        raise ValueError(f'{variant} is a PARAM-MATCHED baseline but was given the default mlp_ratio=4; its MLP must be widened to match its sparse reference arm, or the comparison is not parameter-controlled. Pass mlp_ratio=variant_mlp_ratio(variant, vocab, d=..., n_layers=..., n_heads=..., d_head=..., seq_len=...).')
    cfgs = make_layer_cfgs(n_layers, variant)
    # Validate an explicitly requested eager mode against this environment before
    # claiming it in the record; the concrete per-variant choice is still
    # `_uses_batched_eager` (a variant with no CSA/HCA layer never takes the
    # batched twin even when the backend is available).
    _resolve_impl_modes({'amp_dtype': amp_dtype, 'eager_batch': eager_batch,
                         'batch_size': batch_size}, device=device)
    _eager_batch_used = _uses_batched_eager(cfgs, device, batch_size)
    model = SmallGPT(vocab, d, n_layers, n_heads, d_head, seq_len, cfgs, mlp_ratio=mlp_ratio).to(device)
    _inner_model = model
    # Matched-initialization evidence for paired seeds: the shared trunk is
    # built before the variant-specific blocks, so two arms at the same seed
    # must hash identically.  This is what turns "paired by seed" into an
    # actual check rather than an assumption.
    _init_core_fp = init_core_fingerprint(_inner_model)
    if _dist and _world > 1:
        _dev_ids = [device] if device.type == 'cuda' else None
        model = torch.nn.parallel.DistributedDataParallel(
            model, device_ids=_dev_ids,
            output_device=(_dev_ids[0] if _dev_ids else None),
            gradient_as_bucket_view=True)
    n_param = count_params(model)
    print(f'\n[{variant} seed={seed}] params={n_param / 1000000.0:.2f}M  mlp_ratio={mlp_ratio:.2f}  layers={[c.kind for c in cfgs]}')
    # foreach=True pins the multi-tensor AdamW implementation.  Foreach applies
    # the same per-element IEEE op chain as the single-tensor form (lerp /
    # addcmul / sqrt are elementwise, so every element sees the identical
    # rounding sequence), so the update is bit-identical to the single-tensor
    # form, and on CUDA it pins the already-default foreach path.
    opt = build_optimizer(_inner_model, lr=lr, weight_decay=weight_decay,
                          delta_lr_mult=delta_lr_mult)
    _, _, delta_params = optimizer_param_groups(_inner_model)
    if delta_params:
        print(f'    delta_logit params: {len(delta_params)} (lr x{delta_lr_mult:g})')

    def lr_at(step):
        if warmup > 0 and step < warmup:
            return lr * (step + 1) / warmup
        t = (step - warmup) / max(steps - warmup, 1)
        return lr * (LR_FLOOR_MULT + LR_COSINE_AMP * (1.0 + math.cos(math.pi * t)))
    # lr_scale is only ever set at optimizer construction (never mutated), so
    # the per-group multiplier list is captured once here.
    _lr_scales = [g.get('lr_scale', 1.0) for g in opt.param_groups]
    # In DDP each rank consumes a different data shard; the global batch is
    # batch_size * world_size (recorded below).  Single-process runs keep the
    # same seed exactly.
    _data_seed = data_seed_for_rank(seed, _rank) if _dist else seed
    bpe = batch_iter(train_ids, seq_len, batch_size, device, seed=_data_seed)
    _eval_batch = val_batch[:eval_subset] if val_batch is not None else None
    _eval_subset_fp = _ids_fp(np.ascontiguousarray(np.asarray(_eval_batch)).reshape(-1)) if _eval_batch is not None else None
    _fixed_eval = None
    if eval_every and train_ids is not None and int(eval_every) > 0:
        try:
            _fixed_eval = _fixed_train_eval_batch(train_ids, seq_len, batch_size, device, seed)
        except Exception as _fe:
            print(f'[health] WARNING: could not build the fixed train-eval batch ({type(_fe).__name__}: {_fe}); training CE will not be tracked')
            _fixed_eval = None
    _diag_stride = max(1, int(diag_every) if diag_every else max(1, int(steps) // 1000))
    # Lightweight token-range/shape checks stay at roughly every 1% of the run
    # (plus step 0 and any post-anomaly window), not once per 1024 steps: a
    # single corrupted window can poison all later checkpoints.
    _token_check_every = max(1, int(steps) // 100)
    _diag = {'step': [], 'ce': [], 'total_loss': [], 'comp_reg': [], 'boundary_pg': [],
             'grad_norm_pre_clip': [], 'update_norm': [], 'lr': [], 'clipped': [],
             'update_skipped': [], 'amp_scale': []}
    _diag_events = {}
    _clip_steps = 0
    _skipped_steps = 0
    _nonfinite_loss_steps = 0
    _nonfinite_grad_steps = 0
    _first_bad_step = None
    _scaler_overflows = 0
    _scaler_scale_min = None
    _best_val_ppl = None
    _best_step = None
    _last_subset_ppl = None
    _checkpoints = {}
    _health_history = []
    _last_train_ce = None
    _early_stop = (None if _es_patience is None else
                   {'patience': _es_patience, 'min_delta': _es_min_delta,
                    'stopped': False, 'stopped_step': None,
                    'planned_steps': int(steps), 'best_val_ppl': None,
                    'best_step': None, 'reason': 'patience not reached'})
    if device.type == 'cuda':
        try:
            torch.cuda.reset_peak_memory_stats(device)
        except Exception:
            pass
    t0 = time.time()
    losses = []
    _lbuf = []
    _loss_stage = None
    _loss_ev = None
    if device.type == 'cuda':
        try:
            _loss_stage = torch.empty(512, dtype=torch.float32, pin_memory=True)
            _loss_ev = torch.cuda.Event()
        except Exception:
            _loss_stage = None
            _loss_ev = None

    def _flush_loss_buffer():
        if not _lbuf:
            return
        if _loss_stage is not None and len(_lbuf) <= _loss_stage.numel():
            _staged = _loss_stage[:len(_lbuf)]
            _staged.copy_(torch.stack(_lbuf), non_blocking=True)
            _loss_ev.record()
            _loss_ev.synchronize()
            _curve_extend(losses, _staged.tolist())
        else:
            _curve_extend(losses, torch.stack(_lbuf).tolist())
        _lbuf.clear()
    ppl_hist = []
    _ce_baseline = 0.0
    delta_trace = {}
    model.train()
    truncated = False
    # Cyclic GC is disabled for the step loop; collections still run at a
    # fixed cadence and the original GC state is restored on every exit path.
    _gc_relief = gc.isenabled()
    _ckpt_saved = _CKPT['on']
    _auto_ckpt, _auto_need = _auto_ckpt_mode(device, n_param, n_layers, d, mlp_ratio, batch_size, seq_len, cfgs, n_heads=n_heads, d_head=d_head)
    if _auto_ckpt:
        _CKPT['on'] = _auto_ckpt
        try:
            _free_now, _ = torch.cuda.mem_get_info(device)
            print(f'[ckpt] auto mode={_auto_ckpt} estimated_working_set={_auto_need / (1 << 30):.2f}GiB free_before={_free_now / (1 << 30):.2f}GiB (includes indexer/attention workspace)')
        except Exception:
            print(f'[ckpt] auto mode={_auto_ckpt} estimated_working_set={(_auto_need or 0) / (1 << 30):.2f}GiB')
    _ckpt_effective = _CKPT['on']

    def _do_save(tag, step_no, val_ppl, train_ce):
        if not _save_mode or not ckpt_dir:
            return
        if tag == 'best' and _save_mode not in ('best', 'both'):
            return
        if tag == 'final' and _save_mode not in ('final', 'both'):
            return
        try:
            path = os.path.join(ckpt_dir, f'{variant}_seed{seed}_{tag}.pt')
            _h = classify_training_health(_health_history)
            _checkpoints[tag] = _save_analysis_checkpoint(path, _inner_model, {
                'variant': variant, 'seed': seed, 'step': step_no,
                'val_ppl': val_ppl, 'train_ce': train_ce, 'health': _h,
                'extra': {'train_fp': _ids_fp(train_ids),
                          'eval_fp': _ids_fp(np.ascontiguousarray(np.asarray(val_batch)).reshape(-1)) if val_batch is not None else None,
                          'rng_fp': _rng_fp, 'params': int(n_param),
                          # The matched-initialization digest travels with the
                          # weights, not only with the training summary: the
                          # confirmation evaluator must be able to verify the
                          # pair without trusting a separately persisted
                          # summary file.
                          'init_core_fp': _init_core_fp,
                          'open_block_config': open_block_config(_inner_model),
                          # Enough geometry to rebuild the model for
                          # post-hoc error analysis without guessing defaults.
                          'cfg': cfgs, 'vocab': int(vocab), 'd': int(d),
                          'n_layers': int(n_layers), 'n_heads': int(n_heads),
                          'd_head': int(d_head), 'train_len': int(seq_len),
                          'max_seq': int(seq_len), 'mlp_ratio': float(mlp_ratio)}})
            print(f'  [ckpt] saved {tag} checkpoint {path} (step={step_no}, val_ppl={val_ppl})')
        except Exception as _se:
            print(f'[ckpt] WARNING: could not save {tag} checkpoint ({type(_se).__name__}: {_se}); the run continues, but this weight is unavailable for post-hoc analysis')

    if _gc_relief:
        gc.disable()
    try:
        for step in range(steps):
            if deadline_ts is not None and time.time() > deadline_ts:
                print(f'  [cap] HARD cap reached before step {step} - truncating; this run is NOT recorded (raise RUN_CAP and re-run to retry it)')
                truncated = True
                break
            if device.type == 'cuda' and step and step % 256 == 0:
                _attb_bump_epoch()
            base = lr_at(step)
            for g, _ls in zip(opt.param_groups, _lr_scales):
                g['lr'] = base * _ls
            x, y = next(bpe)
            # Corruption checks are a startup / anomaly guard: first batch,
            # roughly every 1% of the run, and again after any non-finite event.
            if step == 0 or step % _token_check_every == 0 or _first_bad_step is not None:
                try:
                    _check_token_batch(x, y, vocab, step=step + 1)
                except (TypeError, ValueError, OverflowError) as _be:
                    raise RuntimeError(f'[data] bad training batch at step {step + 1}: {_be}') from _be
                if step == 0:
                    # A wrong input/target shift leaves every token in range but
                    # trains the model to predict its own input.  It is a data
                    # pipeline fault, not an optimisation problem.
                    try:
                        _shift_ok = bool(x.shape == y.shape and x.shape[1] > 0
                                         and torch.equal(y[:, :-1], x[:, 1:]))
                    except Exception:
                        _shift_ok = False
                    _data_audit['label_shift'] = {
                        'checked': True, 'ok': _shift_ok,
                        'n_rows': int(x.shape[0]), 'n_tokens': int(x.numel())}
                    if not _shift_ok:
                        raise RuntimeError(
                            '[data] training inputs/targets are not a one-token causal shift; '
                            'investigate the loader before training further')
            _comp_item = float('nan')
            _pg_item = 0.0
            _loss_item = float('nan')
            _gn_pre = None
            _gn_post = None
            _update_norm = None
            _is_diag_step = (step % _diag_stride == 0 or step == steps - 1)
            _step_ok = True
            with torch.autocast(device_type='cuda', dtype=(_amp_dtype or torch.bfloat16),
                                enabled=(_amp is not None)):
                # Go through the (possibly DDP-wrapped) module's forward so
                # DDP can install its gradient-sync hooks; custom attributes
                # and methods always live on `_inner_model` because
                # DistributedDataParallel does not proxy them.
                ce = model(x, targets=y, vocab=vocab)
                del x, y
                _comp = getattr(_inner_model, 'comp_reg', None)
                _blp = getattr(_inner_model, 'boundary_logp', None)
                _ce_item = None
                _comp_item = None
                if _blp is not None:
                    # REINFORCE needs the current CE scalar to form its
                    # advantage; this arm is the only one that reads it per
                    # step.
                    _ce_item = float(ce.detach().item())
                    _comp_item = float(_comp.detach().item()) if _comp is not None else 0.0
                    _adv = _ce_item - float(_ce_baseline)
                    _bdec = max(int(getattr(_inner_model, 'boundary_decisions', 0) or 0), 1)
                    _pg = -_adv * _blp / _bdec
                    _pg_item = float(_pg.detach().item())
                    loss = ce + comp_lambda * _inner_model.comp_reg + BOUNDARY_PG_COEF * _pg
                    _ce_baseline = 0.99 * float(_ce_baseline) + 0.01 * _ce_item
                else:
                    loss = ce + comp_lambda * _inner_model.comp_reg
                _loss_item = float(loss.detach().item())
                # CE / comp_reg are diagnostics on the ordinary path; read
                # them only on logging/diagnostic steps (or after a bad loss).
                _need_scalars = (_is_diag_step or not math.isfinite(_loss_item)
                                 or (log_every and (step % log_every == 0 or step == steps - 1)))
                if _need_scalars:
                    if _ce_item is None:
                        _ce_item = float(ce.detach().item())
                    if _comp_item is None:
                        _comp_item = float(_comp.detach().item()) if _comp is not None else 0.0
                else:
                    _ce_item = float('nan')
                    _comp_item = 0.0
            _loss_finite_local = bool(math.isfinite(_loss_item))
            # Branch on the rank-agreed value, not on this rank's local loss:
            # a rank whose own shard happened to be finite used to enter
            # backward while a peer skipped it, deadlocking DDP.
            _loss_ok = _all_ranks_agree(_loss_finite_local,
                                        _dist and _world > 1, device)
            _step_ok = _loss_ok
            if not _loss_ok:
                _skipped_steps += 1
                _nonfinite_loss_steps += 1
                if _first_bad_step is None:
                    _first_bad_step = step + 1
                _nan_events.append({'step': step + 1, 'kind': 'loss', 'loss': _loss_item,
                                    'ce': _ce_item, 'comp_reg': _comp_item,
                                    'boundary_pg': _pg_item, 'lr': base,
                                    'rank_local_finite': _loss_finite_local,
                                    'rank': int(_rank)})
                _where = ('this rank' if not _loss_finite_local
                          else f'another rank (rank {int(_rank)} loss is finite)')
                print(f'  [nan] non-finite loss at step {step + 1} ({_where}; ce={_ce_item}, comp={_comp_item}, pg={_pg_item}); skipping the optimizer update on every rank')
                opt.zero_grad(set_to_none=True)
                if _scaler is not None:
                    # GradScaler.update() consumes/reset the found-inf state.
                    # Leaving it pending makes the next unscale_/step keep
                    # skipping and blocks the scale reduction (they are
                    # paired even when backward was skipped for a bad loss).
                    _scaler.update()
            elif _scaler is not None:
                _scale_before = float(_scaler.get_scale())
                _scaler.scale(loss).backward()
                _scaler.unscale_(opt)
                _gn = torch.nn.utils.clip_grad_norm_(model.parameters(), GRAD_CLIP_NORM)
                _gn_pre = float(_gn.detach().item()) if torch.is_tensor(_gn) else float(_gn)
                _grad_ok = _all_ranks_agree(math.isfinite(_gn_pre),
                                            _dist and _world > 1, device)
                if not _grad_ok:
                    _step_ok = False
                    _skipped_steps += 1
                    _nonfinite_grad_steps += 1
                    if _first_bad_step is None:
                        _first_bad_step = step + 1
                    _nan_events.append({'step': step + 1, 'kind': 'grad', 'grad_norm': _gn_pre,
                                        'loss': _loss_item, 'ce': _ce_item, 'amp_scale': _scale_before,
                                        'lr': base})
                    print(f'  [nan] non-finite gradient norm at step {step + 1}; zeroing grads and skipping the update')
                    opt.zero_grad(set_to_none=True)
                    # unscale_() has marked found_inf; update() is what
                    # consumes that state and lowers the scale.  Skipping it
                    # leaves the scale too high and the overflow state set.
                    _scaler.update()
                else:
                    _gn_post = min(_gn_pre, float(GRAD_CLIP_NORM))
                    _clip_steps += int(_gn_pre > GRAD_CLIP_NORM)
                    _ub = _param_change_sample(_inner_model, max_per_tensor=256).clone() if _is_diag_step else None
                    _scaler.step(opt)
                    _scaler.update()
                    if _ub is not None:
                        try:
                            _update_norm = float((_param_change_sample(_inner_model, max_per_tensor=256) - _ub).norm().item())
                        except Exception:
                            _update_norm = None
                _scale_after = float(_scaler.get_scale())
                _scaler_scale_min = _scale_after if _scaler_scale_min is None else min(_scaler_scale_min, _scale_after)
                if _scale_after < _scale_before:
                    _scaler_overflows += 1
            else:
                loss.backward()
                _gn = torch.nn.utils.clip_grad_norm_(model.parameters(), GRAD_CLIP_NORM)
                _gn_pre = float(_gn.detach().item()) if torch.is_tensor(_gn) else float(_gn)
                _grad_ok = _all_ranks_agree(math.isfinite(_gn_pre),
                                            _dist and _world > 1, device)
                if not _grad_ok:
                    _step_ok = False
                    _skipped_steps += 1
                    _nonfinite_grad_steps += 1
                    if _first_bad_step is None:
                        _first_bad_step = step + 1
                    _nan_events.append({'step': step + 1, 'kind': 'grad', 'grad_norm': _gn_pre,
                                        'loss': _loss_item, 'ce': _ce_item, 'lr': base})
                    print(f'  [nan] non-finite gradient norm at step {step + 1}; zeroing grads and skipping the update')
                    opt.zero_grad(set_to_none=True)
                else:
                    _gn_post = min(_gn_pre, float(GRAD_CLIP_NORM))
                    _clip_steps += int(_gn_pre > GRAD_CLIP_NORM)
                    _ub = _param_change_sample(_inner_model, max_per_tensor=256).clone() if _is_diag_step else None
                    opt.step()
                    if _ub is not None:
                        try:
                            _update_norm = float((_param_change_sample(_inner_model, max_per_tensor=256) - _ub).norm().item())
                        except Exception:
                            _update_norm = None
            # The default is a low-frequency sample (step 0, after anomalies,
            # and every 1024 steps) so a corrupted update cannot run for an
            # entire panel unnoticed; CSA_PARAM_FINITE_CHECK=full scans every
            # 256 steps and =off disables it.
            _param_full = _PARAM_FINITE_CHECK in ('always', 'full', '1', 'true', 'on')
            _param_sample = _PARAM_FINITE_CHECK in ('sample', 'auto')
            _param_check_due = (
                (_param_full and (step % 256 == 0 or _first_bad_step is not None))
                or (_param_sample and (step == 0 or _first_bad_step is not None
                                       or (step + 1) % 1024 == 0)))
            if (_step_ok and _param_check_due
                    and not _params_all_finite(_inner_model)):
                _nan_events.append({'step': step + 1, 'kind': 'param', 'loss': _loss_item,
                                    'grad_norm': _gn_pre, 'lr': base})
                raise FloatingPointError(f'non-finite parameter values after step {step + 1}; aborting instead of training on corrupted weights')
            # Gradients are not needed after the update.
            opt.zero_grad(set_to_none=True)
            _ce_d = ce.detach()
            _lbuf.append(_ce_d)
            # The loss buffer stores the detached CE tensor; `final_loss_smoothed`
            # is derived from the full recorded curve at the end (not from
            # sparse scalar reads, which are NaN on most steps).
            # Drop this step's graph/scalar references before the next forward.
            del loss, ce
            _inner_model.comp_reg = None
            if len(_lbuf) >= 512:
                _flush_loss_buffer()
            if step % _diag_stride == 0 or step == steps - 1 or not _step_ok:
                _diag_events[step + 1] = {'step': step + 1, 'ce': _ce_item, 'total_loss': _loss_item,
                                          'comp_reg': _comp_item, 'boundary_pg': _pg_item,
                                          'grad_norm_pre_clip': _gn_pre, 'update_norm': _update_norm,
                                          'lr': base,
                                          'clipped': bool(_gn_pre is not None and math.isfinite(_gn_pre) and _gn_pre > GRAD_CLIP_NORM),
                                          'update_skipped': (not _step_ok),
                                          'amp_scale': (float(_scaler.get_scale()) if _scaler is not None else None)}
                for _k in _diag:
                    _diag[_k].append(_diag_events[step + 1].get(_k))
            if (step + 1) % 1024 == 0:
                gc.collect()
            if eval_every and ((step + 1) % eval_every == 0 or step == steps - 1):
                if val_batch is not None:
                    _sub_stats = eval_ppl(_inner_model, _eval_batch, device, return_stats=True)
                    sub_ppl = float(_sub_stats.get('ppl', float('nan')))
                    ppl_hist.append([step + 1, sub_ppl])
                    _ci = _nll_doc_ci(_sub_stats.get('nll_per_row'), _sub_stats.get('n_tokens_per_row'))
                else:
                    sub_ppl = float('nan')
                    _ci = {'ppl': None, 'doc_ce_sem': None, 'ppl_ci95_low': None,
                           'ppl_ci95_high': None, 'n_docs': 0}
                _train_ce = None
                if _fixed_eval is not None:
                    try:
                        _train_ce, _train_acc = _lm_batch_metrics(_inner_model, _fixed_eval[0], _fixed_eval[1], vocab)
                    except Exception as _te:
                        print(f'[health] WARNING: fixed train-CE evaluation failed ({type(_te).__name__}: {_te}); train CE stays unmonitored at this point')
                        _train_ce = None
                # None = not measured (infra missing/failed); NaN = measured
                # and non-finite.  classify_training_health counts only the
                # latter as a non-finite curve point.  `*_final` fields must
                # describe the LAST measurement, not the last finite one: a
                # run whose final eval is non-finite must not report an
                # earlier step's PPL as its final value.
                _last_train_ce = _train_ce
                _val_ce = math.log(sub_ppl) if (_is_finite_number(sub_ppl) and sub_ppl > 0) else float('nan')
                _entry = {'step': step + 1, 'val_ppl': sub_ppl, 'val_ce': _val_ce,
                          'train_ce': _train_ce,
                          'gap': (_val_ce - _train_ce) if (math.isfinite(_val_ce) and _is_finite_number(_train_ce)) else None,
                          'val_ci95_low': _ci.get('ppl_ci95_low'),
                          'val_ci95_high': _ci.get('ppl_ci95_high'),
                          'val_doc_ce_sem': _ci.get('doc_ce_sem'),
                          'val_n_docs': _ci.get('n_docs')}
                _health_history.append(_entry)
                _last_subset_ppl = sub_ppl
                if _is_finite_number(sub_ppl) and sub_ppl > 0 and (_best_val_ppl is None or sub_ppl < _best_val_ppl):
                    _best_val_ppl = sub_ppl
                    _best_step = step + 1
                    _do_save('best', step + 1, sub_ppl, _last_train_ce)
                if _early_stop is not None and val_batch is not None:
                    _es = early_stop_decision(_health_history, patience=_es_patience,
                                              min_delta=_es_min_delta)
                    _early_stop.update({'best_val_ppl': _es.get('best_val_ppl'),
                                        'best_step': _es.get('best_step'),
                                        'stale_evals': _es.get('stale_evals')})
                    if _es.get('should_stop'):
                        _early_stop.update({'stopped': True, 'stopped_step': step + 1,
                                            'reason': (f'validation PPL did not improve by >{_es_min_delta:g} '
                                                       f'for {_es_patience} consecutive eval(s)')})
                        print(f'  [early-stop] stopped at step {step + 1}/{steps}: {_early_stop["reason"]}; '
                              f'best val PPL {_best_val_ppl} at step {_best_step}')
                        break
            if log_every and (step % log_every == 0 or step == steps - 1):
                if _lbuf:
                    _flush_loss_buffer()
                _lv = float(losses[-1])
                _dls = [(li, getattr(blk.attn, 'delta_logit', None)) for li, blk in enumerate(_inner_model.blocks)]
                _dls = [(li, dl) for li, dl in _dls if dl is not None]
                if _dls:
                    # (no_grad: 纯读取 Parameter 的值做日志，不需要 autograd 节点)
                    with torch.no_grad():
                        for li, _v in zip([li for li, _ in _dls], torch.stack([dl for _, dl in _dls]).tolist()):
                            _curve_append_point(delta_trace.setdefault(f'L{li}', []), [step, float(_v)])
                _gn_txt = f'{_gn_pre:.3g}' if (_gn_pre is not None and math.isfinite(_gn_pre)) else 'n/a'
                print(f'  step {step:4d}  loss {_lv:.4f}  ce {_ce_item:.4f}  comp {_comp_item:.3g}  grad {_gn_txt}  lr {opt.param_groups[0]['lr']:.2e}  ({(time.time() - t0) / max(step + 1, 1) * 1000:.0f}ms/step)')
    except BaseException:
        # Best-effort distributed cleanup: if one rank fails mid-step the
        # others can otherwise block forever in the next collective/barrier.
        if _dist and _world > 1:
            try:
                torch.distributed.destroy_process_group()
            except Exception:
                pass
        raise
    finally:
        _CKPT['on'] = _ckpt_saved
        if _gc_relief:
            gc.enable()
    wall = time.time() - t0
    _steps_completed = min(int(steps), int(step) + 1)
    if truncated:
        del model, opt, bpe
        gc.collect()
        if device.type == 'cuda':
            torch.cuda.empty_cache()
        return {'variant': variant, 'seed': seed, 'cap_truncated': True, 'steps_done': step, 'train_time_s': wall}
    if deadline_ts is not None and time.time() > deadline_ts:
        print('  [cap] HARD cap reached before the final evaluation - truncating; this run is NOT recorded (raise RUN_CAP and re-run to retry it)')
        del model, opt, bpe
        gc.collect()
        if device.type == 'cuda':
            torch.cuda.empty_cache()
        return {'variant': variant, 'seed': seed, 'cap_truncated': True, 'steps_done': _steps_completed, 'train_time_s': wall}
    if _dist and _world > 1 and _rank != 0:
        # Non-zero ranks have no file-writing role; wait for rank 0's final
        # evaluation so the whole job exits together.
        torch.distributed.barrier()
        _res = {'variant': variant, 'seed': seed, 'ppl': float('nan'),
                'params': n_param, 'steps': steps, 'steps_completed': _steps_completed,
                'train_time_s': wall,
                'distributed_rank': _rank, 'distributed_world_size': _world,
                'tokens_seen': _steps_completed * batch_size * seq_len * _world}
        if _lbuf:
            _flush_loss_buffer()
        _res['losses'] = [float(v) for v in losses]
        if return_model:
            _res['model'] = _inner_model
        return _res
    if val_batch is None:
        ppl, stats = (float('nan'), {})
        _eval_stats = {'ppl': float('nan'), 'nll_sum': float('nan'), 'n_tokens': 0,
                       'nll_per_row': [], 'n_tokens_per_row': [], 'eval_rows': None,
                       'eval_seed': 0, 'eval_subset': 0}
    else:
        # Final measurement uses the FULL fixed validation batch;
        # `eval_subset` only controls the per-eval-step history.
        # Keeping this distinction byte-compatible matters: `_run_fp` pins the
        # full val fingerprint, and changing the final row count without a
        # CODE_SEMANTICS bump would silently mix two PPL definitions on resume.
        _eval_stats = eval_ppl(_inner_model, val_batch, device, return_stats=True,
                               collect_block_stats=True, val_bnd=val_bnd)
        ppl = float(_eval_stats['ppl'])
        # Reuse the statistics collected during the PPL forward.
        stats = _eval_stats.get('compression')
        if stats is None:
            stats = compression_report(_inner_model, val_batch, device, val_bnd=val_bnd)
        print(f'[{variant} seed={seed}] val PPL = {ppl:.3f}  (n_tok={_eval_stats["n_tokens"]}, nll={_eval_stats["nll_sum"]:.6f})')
        print(f'    block-length diagnostics: {json.dumps(stats, default=float)}')
    if _lbuf:
        _flush_loss_buffer()
    losses = [float(v) for v in losses]
    _curve_summary = _finite_curve(losses)
    # True final-window mean: the last 50 recorded training steps, not the
    # last 50 diagnostic scalar reads.  The latter are NaN on most steps
    # (reading CE every step would add a GPU sync), so the old value could be
    # an average of points spread over a large fraction of the run.
    _tail_losses = [v for v in losses[-50:] if math.isfinite(v)]
    _final_loss_smoothed = (sum(_tail_losses) / len(_tail_losses)) if _tail_losses else None
    _train_health = classify_train_loss_curve(losses)
    if _health_history:
        _health = classify_training_health(_health_history)
    else:
        _train_status = _train_health.get('status')
        _health = {'status': ('nonfinite' if _train_status == 'nonfinite' else 'unmonitored'),
                   'reason': ('no validation eval points (eval_every=0 or no val_batch); '
                              f'training-loss curve status={_train_status} ({_train_health.get("reason")})'),
                   'n_points': 0, 'best_step': None, 'best_val_ppl': None,
                   'final_val_ppl': None, 'final_minus_best': None,
                   'train_curve_status': _train_status}
    _grad_vals = [float(v) for v in _diag.get('grad_norm_pre_clip', []) if _is_finite_number(v)]
    _upd_vals = [float(v) for v in _diag.get('update_norm', []) if _is_finite_number(v)]
    _opt_summary = {
        'n_steps': int(steps), 'n_steps_completed': int(_steps_completed),
        'n_diag_points': len(_diag.get('step', [])),
        'grad_norm_mean': (sum(_grad_vals) / len(_grad_vals)) if _grad_vals else None,
        'grad_norm_max': max(_grad_vals) if _grad_vals else None,
        'update_norm_mean': (sum(_upd_vals) / len(_upd_vals)) if _upd_vals else None,
        'update_norm_max': max(_upd_vals) if _upd_vals else None,
        'clip_steps': int(_clip_steps),
        'clip_fraction': (float(_clip_steps) / max(1, int(_steps_completed))),
        'skipped_updates': int(_skipped_steps),
        'nonfinite_loss_steps': int(_nonfinite_loss_steps),
        'nonfinite_grad_steps': int(_nonfinite_grad_steps),
        'first_bad_step': _first_bad_step,
        'amp_scaler_overflows': int(_scaler_overflows),
        'amp_scaler_scale_min': _scaler_scale_min,
        'diag_stride': int(_diag_stride),
        'nan_guard': nan_guard_state(),
        'events': _nan_events[:20],
    }
    _instability = diagnose_training_instability(
        {'opt_diag_summary': _opt_summary, 'amp_dtype': _amp,
         'train_knobs': training_knobs(amp_dtype=_amp, eager_batch=_eager_batch_used),
         'curve_health': _health, 'health_history': _health_history,
         'train_curve_health': _train_health, 'losses': losses,
         'data_audit': _data_audit})
    _peak = {}
    if device.type == 'cuda':
        try:
            _peak_alloc = int(torch.cuda.max_memory_allocated(device))
            _peak = {'max_memory_allocated_mb': _peak_alloc / (1 << 20),
                     'max_memory_reserved_mb': torch.cuda.max_memory_reserved(device) / (1 << 20)}
            _gk = _ckpt_geom_key(n_param, n_layers, d, mlp_ratio, batch_size, seq_len, cfgs, n_heads=n_heads, d_head=d_head)
            _CKPT_PEAK_MEMO[_gk] = max(int(_CKPT_PEAK_MEMO.get(_gk, 0)), _peak_alloc)
        except Exception:
            _peak = {}
    if _save_mode and ckpt_dir:
        _do_save('final', int(_steps_completed), float(ppl) if _is_finite_number(ppl) else None, _last_train_ce)
    _efficiency = None
    _efficiency_sweep = None
    if measure_eff:
        try:
            if _eval_batch is not None:
                _eff_ids = np.ascontiguousarray(np.asarray(_eval_batch)[:min(4, len(_eval_batch))])
            elif _fixed_eval is not None:
                _eff_ids = _fixed_eval[0].detach().cpu().numpy()[:min(4, int(_fixed_eval[0].shape[0]))]
            else:
                _eff_ids = None
            if _eff_ids is not None and len(_eff_ids):
                _efficiency = measure_efficiency(_inner_model, _eff_ids, device, warmup=1, iters=5, decode_tokens=4)
                if measure_eff_sweep:
                    # A single (batch, length) point cannot support an
                    # efficiency claim at a new scale.  Two lengths at batch 1
                    # keep the extra cost small while exposing the shape
                    # dependence (the full sweep API supports larger grids).
                    _sweep_lens = sorted({min(512, int(_eff_ids.shape[1])), int(_eff_ids.shape[1])})
                    _sweep_lens = [n for n in _sweep_lens if 0 < n <= int(_eff_ids.shape[1])]
                    _efficiency_sweep = measure_efficiency_sweep(
                        _inner_model, _eff_ids, device,
                        lengths=tuple(_sweep_lens or [int(_eff_ids.shape[1])]),
                        batches=(1,), warmup=1, iters=3)
        except Exception as _ee:
            print(f'[efficiency] WARNING: measurement failed ({type(_ee).__name__}: {_ee})')
            _efficiency = {'status': 'error', 'error': f'{type(_ee).__name__}: {_ee}'}
            _efficiency_sweep = {'status': 'error', 'error': f'{type(_ee).__name__}: {_ee}'}
    # `tokens_seen` counts DRAWS, not unique tokens: training windows are
    # sampled with replacement and overlap heavily, so a 3000-step run over an
    # 8M-token cache does not consume 18.4M distinct tokens.  Record an
    # explicit coverage estimate instead of letting readers infer uniqueness.
    if _early_stop is not None:
        _early_stop['steps_completed'] = int(_steps_completed)
        if not _early_stop.get('stopped'):
            _early_stop['reason'] = 'patience not reached; ran to the planned step'
    _draws = int(_steps_completed) * int(batch_size) * int(_world)
    _n_train = int(len(train_ids)) if hasattr(train_ids, '__len__') else 0
    _uniq_frac = None
    if _n_train > 0:
        _p = min(float(seq_len) / float(_n_train), 1.0)
        _uniq_frac = (1.0 if _p >= 1.0 else float(1.0 - math.exp(_draws * math.log1p(-_p))))
    result = {'variant': variant, 'seed': seed, 'data_seed': int(_data_seed), 'exec_fp': _exec_fp, 'ppl': ppl, 'params': n_param, 'losses': losses, 'stats': stats, 'steps': steps, 'steps_completed': int(_steps_completed), 'early_stop': _early_stop, 'tokens_seen': _steps_completed * batch_size * seq_len * _world,
              'tokens_seen_unique_estimate': (int(round(_n_train * _uniq_frac)) if _uniq_frac is not None else None),
              'tokens_seen_unique_frac_estimate': _uniq_frac,
              'token_accounting_note': 'tokens_seen counts window draws; unique-token coverage is an estimate under independent uniform window draws, not a measurement',
              'data_audit': _data_audit,
              'train_time_s': wall, 'train_tokens_per_s': ((_steps_completed * batch_size * seq_len * _world) / wall if wall and wall > 0 else None), 'distributed_rank': _rank, 'distributed_world_size': _world, 'final_loss_smoothed': _final_loss_smoothed, 'final_loss_smoothed_window': 50, 'final_loss_smoothed_n': len(_tail_losses), 'ppl_history': ppl_hist, 'delta_trace': delta_trace, 'train_knobs': training_knobs(amp_dtype=_amp, eager_batch=_eager_batch_used), 'amp_dtype': _amp, 'amp_grad_scaler': bool(_scaler is not None), 'eager_batch': _eager_batch_used, 'ckpt_mode': _ckpt_effective, 'ckpt_estimated_bytes': _auto_need, 'rng_fp': _rng_fp, 'init_core_fp': _init_core_fp, 'data_fp': _ids_fp(train_ids),
              # The token-level evidence behind the reported PPL.
              # `nll_sum / n_tokens` is the pooled-NLL estimator; the per-row
              # rows let a report bootstrap DOCUMENT uncertainty instead of
              # treating the seed as the only source of error.
              'nll_sum': _eval_stats.get('nll_sum'), 'n_tokens': _eval_stats.get('n_tokens'),
              'nll_per_row': _eval_stats.get('nll_per_row'), 'n_tokens_per_row': _eval_stats.get('n_tokens_per_row'),
              'eval_rows': _eval_stats.get('eval_rows'), 'eval_seed': _eval_stats.get('eval_seed'),
              'eval_subset': _eval_stats.get('eval_subset'),
              'eval_subset_fp': _eval_subset_fp, 'eval_subset_rows': len(_eval_batch) if _eval_batch is not None else 0,
              'eval_fp': _ids_fp(np.ascontiguousarray(val_batch).reshape(-1)) if val_batch is not None else None,
              'param_breakdown': param_breakdown(_inner_model),
              'kv_cache_elements_per_token': kv_cache_elements_per_token(_inner_model),
              'train_objective': train_objective(_inner_model, comp_lambda=comp_lambda, delta_lr_mult=delta_lr_mult),
              'chunking_protocol': model_chunking_protocols(_inner_model),
              'open_block_config': open_block_config(_inner_model),
              'curve_summary': _curve_summary,
              'curve_health': _health, 'health_history': _health_history,
              'train_curve_health': _train_health,
              'train_ce_fixed_final': _last_train_ce,
              'train_val_gap_final': _health.get('gap_last'),
              'best_step': _best_step, 'best_val_ppl': _best_val_ppl,
              'best_val_ppl_subset': _best_val_ppl,
              'final_subset_val_ppl': _last_subset_ppl,
              'final_full_val_ppl': (float(ppl) if _is_finite_number(ppl) else None),
              'final_minus_best': (float(_last_subset_ppl - _best_val_ppl)
                                   if (_is_finite_number(_last_subset_ppl) and _best_val_ppl is not None) else None),
              'opt_diag': _diag, 'opt_diag_summary': _opt_summary,
              'instability_diagnosis': _instability,
              'peak_memory': _peak, 'efficiency': _efficiency,
              'efficiency_sweep': _efficiency_sweep,
              'checkpoints': _checkpoints}
    if return_model:
        result['_model'] = _inner_model
    else:
        del model
    del opt, bpe
    gc.collect()
    if _dist and _world > 1:
        torch.distributed.barrier()
    return result

@torch.no_grad()
def _lm_batch_metrics(model, x, y, vocab, chunk=64, ignore_index=None):
    """Mean cross-entropy and next-token accuracy on one fixed batch.

    With ``ignore_index`` set, both the loss and the accuracy are reduced over
    the valid targets only (the same denominator the caller's training loss
    uses).  The historical non-masked path keeps its exact reduction order.
    """
    was_training = model.training
    model.eval()
    try:
        h = model.trunk(x)
        dev = h.device
        total = torch.zeros((), dtype=torch.float64, device=dev)
        correct = torch.zeros((), dtype=torch.long, device=dev)
        n = 0
        n_cols = min(int(x.shape[1]), int(y.shape[1]))
        for s in range(0, n_cols, chunk):
            sl = slice(s, min(s + chunk, n_cols))
            lg = model.head(h[:, sl, :])
            tg = y[:, sl]
            if ignore_index is None:
                total += F.cross_entropy(lg.reshape(-1, vocab), tg.reshape(-1), reduction='sum').double()
                correct += (lg.argmax(-1) == tg).sum()
                n += int(tg.numel())
            else:
                valid = tg != int(ignore_index)
                if bool(valid.any()):
                    lgf = lg.reshape(-1, vocab)[valid.reshape(-1)]
                    tgf = tg.reshape(-1)[valid.reshape(-1)]
                    total += F.cross_entropy(lgf, tgf, reduction='sum').double()
                    correct += (lg.argmax(-1)[valid] == tg[valid]).sum()
                    n += int(valid.sum())
        if n == 0:
            # Every target was masked: the batch has no measurement, not a
            # perfect zero loss.
            return float('nan'), float('nan')
        return (float(total.item()) / n), (float(correct.item()) / n)
    finally:
        model.train(was_training)

@torch.inference_mode()
def classify_token_error(*, ce, entropy, margin, rare_target, target_id, topk_ids, vocab):
    """Heuristic triage for one bad case.

    The labels are deliberately phrased as review prompts, not verdicts:
    ``annotation_or_rare_target`` still needs a human to check the annotation,
    ``ambiguous_context`` means the model distribution is close to uniform,
    and ``confident_model_blind_spot`` means low-entropy, high-margin and high
    CE (the model is wrong while sure).  ``target_outside_topk`` is a supporting
    fact, not a cause by itself.
    """
    try:
        ce = float(ce)
        entropy = float(entropy)
        margin = float(margin)
        vocab = int(vocab)
    except (TypeError, ValueError, OverflowError):
        return {'primary': 'unmeasured', 'causes': [], 'target_in_topk': None}
    if not math.isfinite(ce):
        return {'primary': 'unmeasured', 'causes': [], 'target_in_topk': None}
    tids = []
    for t in (topk_ids or []):
        try:
            tids.append(int(t))
        except (TypeError, ValueError, OverflowError):
            continue
    try:
        target_id = int(target_id)
    except (TypeError, ValueError, OverflowError):
        target_id = None
    in_topk = (target_id in tids) if (tids and target_id is not None) else None
    uniform = math.log(vocab) if vocab > 1 else 0.0
    causes = []
    if bool(rare_target):
        causes.append('annotation_or_rare_target')
    if math.isfinite(entropy) and (entropy >= 0.8 * uniform
                                   or (math.isfinite(margin) and margin <= 0.5)):
        causes.append('ambiguous_context')
    if (math.isfinite(entropy) and math.isfinite(margin)
            and entropy <= 0.5 * uniform and margin >= 2.0):
        causes.append('confident_model_blind_spot')
    if in_topk is False:
        causes.append('target_outside_topk')
    if not causes:
        causes.append('mixed_unclear')
    priority = ('annotation_or_rare_target', 'ambiguous_context',
                'confident_model_blind_spot', 'target_outside_topk', 'mixed_unclear')
    primary = next((c for c in priority if c in causes), 'mixed_unclear')
    return {'primary': primary, 'causes': causes, 'target_in_topk': in_topk}


def _context_target_counts(vb, ctx_len, *, max_positions=None):
    """Map each observed prefix to the next-token counts seen in this split.

    Used ONLY to flag that an apparently wrong target is not uniquely
    determined by its prefix: the same prefix occurs with a different next
    token elsewhere in the evaluated rows (label inconsistency or genuine
    ambiguity).  It does not decide which label is correct.

    ``max_positions`` bounds the scan for scale-up runs.  When the evaluated
    split is larger, equally spaced rows are scanned and the returned metadata
    says the scan was incomplete; an unbounded prefix dictionary over a
    multi-million-token validation split is not an acceptable hidden cost.
    """
    n_rows, seq = int(vb.shape[0]), int(vb.shape[1])
    span = seq - 1
    if span < 1:
        return {}, 0, {'n_rows_total': n_rows, 'n_rows_scanned': 0,
                       'n_positions_per_row': 0,
                       'n_positions_scanned': 0, 'max_positions': max_positions,
                       'complete': True, 'rows': []}
    ctx_len = max(1, min(int(ctx_len), span))
    scan_rows = list(range(n_rows))
    positions_per_row = span
    complete = True
    if max_positions is not None:
        _max = _exact_count(max_positions, minimum=1)
        if _max is None:
            raise ValueError(f'_context_target_counts needs a positive integer max_positions, got {max_positions!r}')
        total = n_rows * span
        if total > int(_max):
            complete = False
            # Scan complete rows when the budget covers at least one; when the
            # budget is smaller than one row, scan the prefix that fits instead
            # of silently exceeding `max_positions` (the bound must hold for a
            # single long sequence too, not only for many short rows).
            full_rows = int(_max) // max(1, span)
            if full_rows >= 1:
                n_scan = min(max(1, n_rows), full_rows)
                positions_per_row = span
            else:
                n_scan = min(max(1, n_rows), 1)
                positions_per_row = int(_max)
            if n_rows <= 0:
                scan_rows = []
            else:
                scan_rows = [int(r) for r in
                             np.unique(np.linspace(0, n_rows - 1, num=n_scan, dtype=np.int64))]
    out = {}
    for r in scan_rows:
        row = vb[r]
        for pos in range(positions_per_row):
            start = max(0, pos + 1 - ctx_len)
            key = row[start:pos + 1].tobytes()
            tgt = int(row[pos + 1])
            d = out.get(key)
            if d is None:
                out[key] = {tgt: 1}
            else:
                d[tgt] = d.get(tgt, 0) + 1
    meta = {'n_rows_total': n_rows, 'n_rows_scanned': len(scan_rows),
            'n_positions_per_row': positions_per_row,
            'n_positions_scanned': len(scan_rows) * positions_per_row,
            'max_positions': max_positions, 'complete': complete}
    if not complete:
        meta['rows'] = scan_rows
    return out, ctx_len, meta


def _token_frequency_table(flat_ids, vocab, *, chunk=1 << 24):
    """Exact token counts accumulated in bounded chunks.

    ``np.bincount(np.asarray(ids, dtype=np.int64))`` materialises an 8-byte
    copy of the ENTIRE corpus first: 40 GB on a 5B-token scale-up before the
    count table itself is allocated.  Integer chunk additions return the
    identical counts while keeping the temporary at O(chunk), so the rare-
    target diagnostic remains usable at the corpus sizes this project targets.
    """
    arr = np.asarray(flat_ids).reshape(-1)
    V = int(vocab)
    if V < 1:
        raise ValueError(f'_token_frequency_table needs vocab >= 1, got {vocab!r}')
    step = _exact_count(chunk, minimum=1)
    if step is None:
        raise ValueError(f'_token_frequency_table needs a positive chunk, got {chunk!r}')
    if arr.dtype == np.bool_ or not np.issubdtype(arr.dtype, np.integer):
        raise TypeError(f'_token_frequency_table needs integer ids, got dtype {arr.dtype}')
    out = np.zeros(V, dtype=np.int64)
    for s in range(0, int(arr.size), int(step)):
        _part = arr[s:s + int(step)]
        if _part.size:
            # bincount accepts every integer width here; only the small chunk
            # is converted internally, never the whole corpus.
            out += np.bincount(_part, minlength=V)
    return out


@torch.inference_mode()
def analyze_errors(model, val_batch, vocab, device, *, tokenizer=None, top_n=50,
                   top_tokens=100, chunk=8, val_bnd=None, train_ids=None,
                   context_tokens=16, topk=5, context_scan_max_positions=None,
                   reference='bigram', reference_alpha=0.1,
                   reference_interpolation=0.5,
                   reference_max_fit_tokens=20_000_000):
    """Per-token / per-sequence error analysis for one checkpoint.

    Returns the worst sequences, worst tokens (with decoded context when a
    tokenizer is available), position buckets, rare-token flags and entropy
    statistics.  This is the input to `error_analysis.py`'s JSONL/Markdown
    artifacts; it deliberately runs on validation data only."""
    import heapq as _heapq
    was_training = model.training
    model.eval()
    vb = np.asarray(val_batch)
    if vb.ndim != 2 or vb.shape[1] < 2:
        raise ValueError(f'analyze_errors needs a 2-D val_batch with >=2 tokens, got {vb.shape}')
    n_rows, seq = int(vb.shape[0]), int(vb.shape[1])
    span = seq - 1
    V = int(vocab)
    # The artifact claims the next-token labels were range-checked.  Actually
    # enforce it here: a float array or an out-of-vocabulary id would either
    # crash cross_entropy half-way through a long scoring pass or, worse,
    # produce a partial artifact that looks measured.
    if not np.issubdtype(vb.dtype, np.integer):
        raise TypeError(f'analyze_errors needs integer token ids, got dtype {vb.dtype}')
    try:
        _min_id, _max_id = int(vb.min()), int(vb.max())
    except (TypeError, ValueError, OverflowError):
        raise ValueError('analyze_errors could not read the token-id range') from None
    if _min_id < 0 or _max_id >= V:
        raise ValueError(f'analyze_errors token ids out of range [{_min_id}, {_max_id}] for vocab {V}')
    # A negative token budget asks torch.topk for a negative k; zero is a
    # valid "inventory only the whole-split tally" request.
    _top_tokens = _exact_count(top_tokens, minimum=0)
    if _top_tokens is None:
        raise ValueError(f'analyze_errors needs a non-negative integer top_tokens, got {top_tokens!r}')
    top_tokens = int(_top_tokens)
    # A zero budget is a valid "do not inventory sequences" request; the old
    # max(1, int(top_n)) silently returned one row and accepted negatives.
    _top_n = _exact_count(top_n, minimum=0)
    if _top_n is None:
        raise ValueError(f'analyze_errors needs a non-negative integer top_n, got {top_n!r}')
    top_n = int(_top_n)
    _chunk = _exact_count(chunk, minimum=1)
    if _chunk is None:
        raise ValueError(f'analyze_errors needs a positive integer chunk, got {chunk!r}')
    chunk = int(_chunk)
    _ctx_tokens = _exact_count(context_tokens, minimum=0)
    if _ctx_tokens is None:
        raise ValueError(f'analyze_errors needs a non-negative integer context_tokens, got {context_tokens!r}')
    context_tokens = int(_ctx_tokens)
    # Prefix -> next-token evidence for the bad-case review.  Only built when
    # an inventory was requested, so a zero-budget call stays cheap.
    _ctx_counts = None
    _ctx_len_used = None
    _ctx_scan = None
    if top_tokens > 0:
        _ctx_counts, _ctx_len_used, _ctx_scan = _context_target_counts(
            vb, min(16, max(1, span)), max_positions=context_scan_max_positions)
    # "Rare target" is a claim about the TRAINING frequency.  An empty or
    # malformed training sample is not a frequency table of all-zero counts:
    # reading it that way would label every token `annotation_or_rare_target`
    # and manufacture a cause that has no evidence behind it.
    freq = None
    freq_problem = None
    rare_basis = 'unavailable: no train_ids'
    if train_ids is not None:
        try:
            _tr = np.asarray(train_ids)
        except Exception as exc:
            _tr = None
            freq_problem = f'unreadable train_ids ({type(exc).__name__})'
        if _tr is not None:
            if _tr.size == 0:
                freq_problem = 'empty train_ids: token frequencies are unmeasured'
            elif not np.issubdtype(_tr.dtype, np.integer) or np.issubdtype(_tr.dtype, np.bool_):
                freq_problem = f'train_ids dtype {_tr.dtype} is not an integer token type'
            else:
                _flat_tr = _tr.reshape(-1)
                _lo, _hi = int(_flat_tr.min()), int(_flat_tr.max())
                if _lo < 0 or _hi >= V:
                    freq_problem = f'train_ids out of range [{_lo}, {_hi}] for vocab {V}'
                else:
                    # Chunked integer accumulation: no whole-corpus int64
                    # copy at scale (see _token_frequency_table).
                    try:
                        freq = _token_frequency_table(_flat_tr, V)
                    except (MemoryError, ValueError, TypeError, OverflowError) as _fe:
                        freq = None
                        freq_problem = (f'train-frequency table could not be '
                                        f'accumulated ({type(_fe).__name__}: {_fe})')
                    if freq is not None and freq.shape[0] != V:
                        freq_problem = f'frequency table has {freq.shape[0]} rows, expected {V}'
                        freq = None
        if freq is not None:
            rare_basis = 'train_frequency'
        elif freq_problem:
            print(f'[analyze_errors] WARNING: rare-target flag disabled: {freq_problem}; '
                  'targets will not be labelled rare/annotation candidates')
    else:
        freq_problem = None
    # ------------------------------------------------------------------
    # Empirical reference floor for the bad-case review.
    #
    # A high CE alone cannot distinguish "the model missed a predictable
    # continuation" from "the label is intrinsically hard/noisy".  A smoothed
    # count model fitted on the TRAINING stream is a cheap control: when the
    # reference gets a token right and the neural model does not, that is
    # direct evidence of a model blind spot rather than annotation noise;
    # when both miss, the target needs a manual label check before it is
    # blamed on the model.  The reference is fixed (not tuned on validation)
    # so it cannot flatter itself on the reported rows.
    _ref_mode = 'none' if reference is None else str(reference).lower()
    if _ref_mode not in ('none', 'unigram', 'bigram'):
        raise ValueError(f'reference must be one of none/unigram/bigram, got {reference!r}')
    _ref_order = 1 if _ref_mode == 'unigram' else 2
    _ref_counts = None
    _ref_problem = None
    _ref_meta = None
    if _ref_mode != 'none':
        _ref_cap = None if reference_max_fit_tokens is None else _exact_count(reference_max_fit_tokens, minimum=1)
        if reference_max_fit_tokens is not None and _ref_cap is None:
            raise ValueError(f'reference_max_fit_tokens must be a positive integer or None, got {reference_max_fit_tokens!r}')
        if train_ids is None:
            _ref_problem = 'no train_ids: the reference floor cannot be fitted'
        else:
            try:
                _tr_raw = np.asarray(train_ids)
                if _tr_raw.size == 0:
                    raise ValueError('empty train_ids')
                if (_tr_raw.dtype == np.bool_ or _tr_raw.dtype == object
                        or not np.issubdtype(_tr_raw.dtype, np.integer)):
                    raise TypeError(f'train_ids dtype {_tr_raw.dtype} is not an integer token type')
                _tr_flat = _tr_raw.reshape(-1)
                _lo, _hi = int(_tr_flat.min()), int(_tr_flat.max())
                if _lo < 0 or _hi >= V:
                    raise ValueError(f'train_ids out of range [{_lo}, {_hi}] for vocab {V}')
                _n_source = int(_tr_flat.size)
                _fit_ids = _tr_flat if _ref_cap is None else _tr_flat[:_ref_cap]
                if _ref_order == 1:
                    _uni = np.bincount(np.asarray(_fit_ids, dtype=np.int64),
                                       minlength=V).astype(np.float64)
                    _ref_counts = (_uni, np.empty(0, dtype=np.int64),
                                   np.zeros(V, dtype=np.int64),
                                   np.empty(0, dtype=np.int64))
                else:
                    _ref_counts = _ngram_train_counts(np.asarray(_fit_ids, dtype=np.int64), V)
                _ref_meta = {
                    'mode': _ref_mode, 'order': _ref_order,
                    'alpha': float(reference_alpha),
                    'interpolation': (0.0 if _ref_order == 1 else float(reference_interpolation)),
                    'fit_token_policy': ('full' if _ref_cap is None else 'deterministic_prefix'),
                    'max_fit_tokens': _ref_cap,
                    'n_fit_tokens': int(_fit_ids.size),
                    'n_source_tokens': _n_source,
                    'fit_truncated': bool(_fit_ids.size < _n_source),
                }
            except Exception as _re:
                _ref_problem = f'{type(_re).__name__}: {_re}'
                _ref_counts = None
        if _ref_counts is None:
            print(f'[analyze_errors] WARNING: reference floor disabled: {_ref_problem}; '
                  'bad cases will not report model-vs-reference evidence')
    bnd_np = np.asarray(val_bnd) if val_bnd is not None else None
    if bnd_np is not None and bnd_np.shape != vb.shape:
        print(f'[analyze_errors] WARNING: boundary mask shape {bnd_np.shape} != val_batch shape {vb.shape} — boundary-token statistics are OMITTED rather than computed from a misaligned/truncated mask')
        bnd_np = None
    tok = tokenizer
    tok_warned = False

    def _decode(ids):
        nonlocal tok_warned
        if tok is None:
            return None
        try:
            return tok.decode([int(x) for x in ids])
        except Exception as e:
            if not tok_warned:
                print(f'[errors] WARNING: tokenizer decode failed ({type(e).__name__}: {e}); ids will be reported without text')
                tok_warned = True
            return None

    seq_rows = []
    tok_heap = []
    buckets = collections.defaultdict(lambda: {'n': 0, 'ce_sum': 0.0})
    n_targets = 0
    n_nonfinite = 0
    # Whole-split reference-floor accumulators.  They are only reported when
    # a fitted reference exists; an unavailable reference stays `None`, never
    # a fabricated zero.
    _ref_stats = {
        'n_paired': 0, 'model_ce_sum': 0.0, 'reference_ce_sum': 0.0,
        'n_model_correct': 0, 'n_reference_correct': 0,
        'n_both_correct': 0, 'n_both_wrong': 0,
        'n_model_only_correct': 0, 'n_reference_only_correct': 0,
        'n_both_wrong_unexplained': 0,
    }
    _ref_row_delta_sum = np.zeros(n_rows, dtype=np.float64)
    _ref_row_n = np.zeros(n_rows, dtype=np.int64)

    def _bucket(pos, tgt):
        frac = pos / max(1, span)
        if frac < 0.1:
            b = 'position:first10%'
        elif frac < 0.5:
            b = 'position:10-50%'
        elif frac < 0.9:
            b = 'position:50-90%'
        else:
            b = 'position:last10%'
        return b

    # Vectorised bucket accumulation: one bincount per chunk.
    _bucket_names = ['position:first10%', 'position:10-50%', 'position:50-90%',
                     'position:last10%', 'target:rare(<=5 train occurrences)',
                     'target:common', 'target:boundary-token']
    _nb = len(_bucket_names)
    _bsum = torch.zeros(_nb, dtype=torch.float64, device=device)
    _bcnt = torch.zeros(_nb, dtype=torch.long, device=device)
    _cause_names_all = ['annotation_or_rare_target', 'ambiguous_context',
                        'confident_model_blind_spot', 'target_outside_topk',
                        'mixed_unclear']
    _all_sum = torch.zeros(len(_cause_names_all), dtype=torch.float64, device=device)
    _all_cnt = torch.zeros(len(_cause_names_all), dtype=torch.long, device=device)
    _freq_t = None
    if freq is not None:
        try:
            _freq_t = torch.as_tensor(freq, dtype=torch.long, device=device)
        except Exception:
            _freq_t = None
    _kk = min(max(1, int(topk)), int(V))
    for r0 in range(0, n_rows, max(1, int(chunk))):
        r1 = min(n_rows, r0 + max(1, int(chunk)))
        ids = torch.as_tensor(np.ascontiguousarray(vb[r0:r1]), dtype=torch.long, device=device)
        h = model.trunk(ids)
        # Per-chunk reference scores keep the memory profile bounded: a full
        # (rows x length) NLL/top-1 pair for a large validation split would be
        # a hidden multi-hundred-MB allocation.  The count tables are built
        # once (capped), only the scoring is streamed.
        _ref_chunk = None
        if _ref_counts is not None:
            try:
                _ref_chunk = ngram_reference_score(
                    None, np.ascontiguousarray(vb[r0:r1, :seq]), V,
                    order=_ref_order, alpha=reference_alpha,
                    interpolation=reference_interpolation,
                    _counts=_ref_counts)
            except Exception as _rce:
                _ref_counts = None
                _ref_problem = f'reference scoring failed: {type(_rce).__name__}: {_rce}'
                print(f'[analyze_errors] WARNING: reference floor disabled: {_ref_problem}')
        row_nll = np.zeros(r1 - r0, dtype=np.float64)
        row_n = np.zeros(r1 - r0, dtype=np.int64)
        for s0 in range(0, span, 64):
            s1 = min(s0 + 64, span)
            lg = model.head(h[:, s0:s1, :])
            tg = ids[:, s0 + 1:s1 + 1]
            ce = F.cross_entropy(lg.transpose(1, 2), tg, reduction='none')
            _b, _s = int(ce.shape[0]), int(ce.shape[1])
            ce_f = ce.detach().float()
            finite = torch.isfinite(ce_f)
            if not bool(finite.all()):
                n_nonfinite += int((~finite).sum())
            ce_safe = torch.where(finite, ce_f, torch.zeros_like(ce_f))
            row_nll += ce_safe.double().sum(dim=1).cpu().numpy()
            row_n += finite.sum(dim=1).cpu().numpy()
            # Entropy from one log_softmax table (no separate softmax/log
            # copies); top-k works directly on the fp32 logits.
            lg_work = lg.float()
            logp = torch.log_softmax(lg_work, dim=-1)
            ent = -(logp * logp.exp()).sum(-1)
            del logp
            topv, topi = torch.topk(lg_work, _kk, dim=-1)
            pred = topi[..., 0]
            # With topk=1 there is no second logit, so the top-1/top-2 margin
            # is unmeasured.  A zero here is not a measured margin: the
            # `margin <= 0.5` / `>= 2.0` rules would then label every token
            # ambiguous (and make the blind-spot cause unreachable).  A NaN
            # is the explicit "not measured" value; the classifier already
            # skips non-finite margins and keeps the entropy rules.
            margin = ((topv[..., 0] - topv[..., 1]) if _kk > 1
                      else torch.full_like(topv[..., 0], float('nan')))
            del lg_work, topv
            # Bucket ids for every token at once.
            pos = torch.arange(s0, s1, device=device, dtype=torch.float64)[None, :]
            frac = pos / max(1, span)
            bidx = ((frac >= 0.1).to(torch.long) + (frac >= 0.5).to(torch.long)
                    + (frac >= 0.9).to(torch.long)).expand(_b, _s)
            if _freq_t is not None:
                _ft = _freq_t[tg.clamp(0, _freq_t.numel() - 1)]
                rare = _ft <= 5
            else:
                rare = torch.zeros((_b, _s), dtype=torch.bool, device=device)
            if bnd_np is not None and bnd_np.shape == vb.shape:
                _bnd = torch.as_tensor(np.ascontiguousarray(bnd_np[r0:r1, s0 + 1:s1 + 1]),
                                       dtype=torch.bool, device=device)
            else:
                _bnd = torch.zeros((_b, _s), dtype=torch.bool, device=device)
            _flat_b = bidx.reshape(-1)
            _flat_ce = ce_safe.reshape(-1).double()
            _flat_fin = finite.reshape(-1)
            _flat_rare = rare.reshape(-1)
            # A non-finite token is an unmeasured target: exclude it from the
            # bucket denominators instead of counting it as CE=0, which would
            # make a diverged evaluation look artificially good.
            _bsum[:4] += torch.bincount(_flat_b[_flat_fin], weights=_flat_ce[_flat_fin], minlength=4)
            _bcnt[:4] += torch.bincount(_flat_b[_flat_fin], minlength=4)
            _sel_rare = _flat_rare & _flat_fin
            _bsum[4] += _flat_ce[_sel_rare].sum()
            _bcnt[4] += int(_sel_rare.sum())
            _sel_common = (~_flat_rare) & _flat_fin
            _bsum[5] += _flat_ce[_sel_common].sum()
            _bcnt[5] += int(_sel_common.sum())
            _sel_bnd = _bnd.reshape(-1) & _flat_fin
            _bsum[6] += _flat_ce[_sel_bnd].sum()
            _bcnt[6] += int(_sel_bnd.sum())
            # Whole-split cause tally (not only the worst tokens).  The
            # priority order matches classify_token_error so the worst-token
            # inventory and the population shares use one definition.
            _uniform = math.log(max(V, 2))
            _flat_ent = ent.reshape(-1)
            _flat_margin = margin.reshape(-1)
            _flat_top = topi.reshape(-1, _kk)
            _flat_tg = tg.reshape(-1)
            _flat_in_topk = (_flat_top == _flat_tg[:, None]).any(dim=1)
            _amb = ((_flat_ent >= 0.8 * _uniform) | (_flat_margin <= 0.5)) & _flat_fin
            _blind = ((_flat_ent <= 0.5 * _uniform) & (_flat_margin >= 2.0)) & _flat_fin
            _m_rare = _flat_rare & _flat_fin
            _m_amb = (~_flat_rare) & _amb
            _m_blind = (~_flat_rare) & (~_amb) & _blind
            _m_out = (~_flat_rare) & (~_amb) & (~_blind) & (~_flat_in_topk) & _flat_fin
            _m_mixed = (~_flat_rare) & (~_amb) & (~_blind) & _flat_in_topk & _flat_fin
            _ref_nll = _ref_top = None
            if _ref_chunk is not None:
                _ref_nll = torch.as_tensor(
                    np.ascontiguousarray(_ref_chunk['nll'][:, s0:s1].reshape(-1)),
                    dtype=torch.float64, device=device)
                _ref_top = torch.as_tensor(
                    np.ascontiguousarray(_ref_chunk['top1_ids'][:, s0:s1].reshape(-1)),
                    dtype=torch.long, device=device)
                _ref_pair = torch.isfinite(_ref_nll) & _flat_fin
                _n_ref_pair = int(_ref_pair.sum())
                if _n_ref_pair:
                    _model_ok = (pred.reshape(-1) == _flat_tg) & _ref_pair
                    _ref_ok = (_ref_top == _flat_tg) & _ref_pair
                    _both_ok = _model_ok & _ref_ok
                    _both_bad = (~_model_ok) & (~_ref_ok) & _ref_pair
                    _model_only = _model_ok & (~_ref_ok)
                    _ref_only = (~_model_ok) & _ref_ok
                    _unexplained = _both_bad & (~_m_rare) & (~_m_amb)
                    _ref_stats['n_paired'] += _n_ref_pair
                    _ref_stats['model_ce_sum'] += float(_flat_ce[_ref_pair].sum())
                    _ref_stats['reference_ce_sum'] += float(_ref_nll[_ref_pair].sum())
                    _ref_stats['n_model_correct'] += int(_model_ok.sum())
                    _ref_stats['n_reference_correct'] += int(_ref_ok.sum())
                    _ref_stats['n_both_correct'] += int(_both_ok.sum())
                    _ref_stats['n_both_wrong'] += int(_both_bad.sum())
                    _ref_stats['n_model_only_correct'] += int(_model_only.sum())
                    _ref_stats['n_reference_only_correct'] += int(_ref_only.sum())
                    _ref_stats['n_both_wrong_unexplained'] += int(_unexplained.sum())
                    _delta = _flat_ce - _ref_nll
                    _row_delta = torch.where(_ref_pair.reshape(_b, _s),
                                             _delta.reshape(_b, _s),
                                             torch.zeros((_b, _s), dtype=torch.float64,
                                                         device=device))
                    _ref_row_delta_sum[r0:r1] += _row_delta.sum(dim=1).cpu().numpy()
                    _ref_row_n[r0:r1] += _ref_pair.reshape(_b, _s).sum(dim=1).cpu().numpy()
                    del _model_ok, _ref_ok, _both_ok, _both_bad, _model_only, _ref_only
                    del _unexplained, _delta, _row_delta, _ref_pair
            for _ci, _mask in enumerate((_m_rare, _m_amb, _m_blind, _m_out, _m_mixed)):
                _all_sum[_ci] += _flat_ce[_mask].sum()
                _all_cnt[_ci] += int(_mask.sum())
            del _flat_ent, _flat_margin, _flat_top, _flat_tg, _flat_in_topk
            del _amb, _blind, _m_rare, _m_amb, _m_blind, _m_out, _m_mixed
            n_targets += int(_flat_fin.sum())
            # Only the chunk's top candidates enter the Python heap; the
            # per-token loop is bounded by top_tokens, not by B*T.
            _sel_n = min(int(top_tokens), _b * _s)
            _pick_val, _pick_idx = torch.topk(torch.where(finite.reshape(-1), ce_f.reshape(-1),
                                                          torch.full_like(ce_f.reshape(-1), float('inf'))),
                                              _sel_n)
            _finite_pick = torch.isfinite(_pick_val)
            if bool(_finite_pick.any()):
                _pick_idx = _pick_idx[_finite_pick]
                _pi = _pick_idx.cpu().numpy()
                _pv = _pick_val[_finite_pick].cpu().numpy()
                _pr = (pred.reshape(-1).index_select(0, _pick_idx)).cpu().numpy()
                _pe = (ent.reshape(-1).index_select(0, _pick_idx)).cpu().numpy()
                _pm = (margin.reshape(-1).index_select(0, _pick_idx)).cpu().numpy()
                _pt = (tg.reshape(-1).index_select(0, _pick_idx)).cpu().numpy()
                _prr = (rare.reshape(-1).index_select(0, _pick_idx)).cpu().numpy()
                _ptop = (topi.reshape(-1, _kk).index_select(0, _pick_idx)).cpu().numpy()
                _pref_ce = (_ref_nll.index_select(0, _pick_idx).cpu().numpy()
                            if _ref_nll is not None else None)
                _pref_pred = (_ref_top.index_select(0, _pick_idx).cpu().numpy()
                              if _ref_top is not None else None)
                for _k in range(len(_pi)):
                    _lin = int(_pi[_k])
                    _pos = s0 + (_lin % _s)
                    rec = (float(_pv[_k]), r0 + (_lin // _s), _pos, int(_pt[_k]),
                           int(_pr[_k]), float(_pe[_k]), float(_pm[_k]),
                           [int(x) for x in _ptop[_k]], bool(_prr[_k]),
                           (float(_pref_ce[_k]) if _pref_ce is not None else None),
                           (int(_pref_pred[_k]) if _pref_pred is not None else None))
                    if len(tok_heap) < int(top_tokens):
                        _heapq.heappush(tok_heap, rec)
                    elif rec[0] > tok_heap[0][0]:
                        _heapq.heapreplace(tok_heap, rec)
            del lg, tg, ce, ce_f, ce_safe, finite, pred, margin, topi, ent
            del bidx, rare, _bnd, _flat_b, _flat_ce, _flat_fin
        for i in range(r1 - r0):
            n = int(row_n[i])
            if n <= 0:
                # Every target in this row was unmeasured; it contributes no
                # mean and must not enter the worst-sequence ranking as 0.
                continue
            ce_mean = float(row_nll[i] / n)
            seq_rows.append((ce_mean, r0 + i, float(row_nll[i]), n))
        del h, ids
    _bsum_cpu = _bsum.detach().cpu().tolist()
    _bcnt_cpu = _bcnt.detach().cpu().tolist()
    for _name, _n, _sm in zip(_bucket_names, _bcnt_cpu, _bsum_cpu):
        buckets[_name] = {'n': int(_n), 'ce_sum': float(_sm)}
    seq_rows.sort(key=lambda t: t[0], reverse=True)
    worst_seqs = []
    for ce_mean, row, nll, n in seq_rows[:top_n]:
        recs = [t for t in tok_heap if t[1] == row]
        worst_seqs.append({'row': int(row), 'mean_ce': ce_mean, 'nll': nll, 'n_tokens': int(n),
                           'top_worst_token_from_sample': (max(recs)[0] if recs else None),
                           'context': _decode(vb[row].tolist()),
                           'ids': [int(x) for x in vb[row].tolist()]})
    worst_tokens = []
    cause_counts = collections.Counter()
    n_ctx_ambiguous = 0
    for rec in sorted(tok_heap, key=lambda t: t[0], reverse=True)[:max(1, int(top_tokens))]:
        c, row, pos, tgt, pred, ent, margin, tids, rare, ref_ce, ref_pred = rec
        lo = max(0, pos - int(context_tokens))
        hi = min(span, pos + int(context_tokens) + 1)
        ctx_ids = [int(x) for x in vb[row, lo:hi + 1].tolist()]
        ctgt = int(vb[row, pos + 1])
        _triage = classify_token_error(ce=c, entropy=ent, margin=margin,
                                       rare_target=rare, target_id=tgt,
                                       topk_ids=tids, vocab=V)
        _ref_verdict = None
        _ref_correct = None
        _model_correct = None
        if ref_ce is not None and ref_pred is not None:
            _model_correct = bool(int(pred) == int(tgt))
            _ref_correct = bool(int(ref_pred) == int(tgt))
            if _model_correct and _ref_correct:
                _ref_verdict = 'both_correct'
            elif _model_correct:
                _ref_verdict = 'model_surpasses_reference'
            elif _ref_correct:
                _ref_verdict = 'reference_catches_model_miss'
                _triage['causes'].append('reference_catches_model_miss')
            else:
                _ref_verdict = 'both_miss_check_label'
                _triage['causes'].append('reference_also_miss')
        cause_counts[_triage['primary']] += 1
        _ctx_variants = None
        _ctx_support = None
        if _ctx_counts is not None:
            _cs = max(0, pos + 1 - int(_ctx_len_used))
            _cd = _ctx_counts.get(vb[row, _cs:pos + 1].tobytes())
            if _cd:
                _ctx_variants = len(_cd)
                _ctx_support = int(sum(_cd.values()))
        if _ctx_variants is not None and _ctx_variants > 1:
            n_ctx_ambiguous += 1
        _tr_count = None
        _tr_frac = None
        if freq is not None and 0 <= ctgt < int(len(freq)):
            _tr_count = int(freq[ctgt])
            _tr_frac = float(_tr_count / max(1, int(freq.sum())))
        worst_tokens.append({
            'row': int(row), 'position': int(pos), 'ce': c, 'target_id': tgt,
            'pred_id': pred, 'entropy': ent, 'margin': margin,
            'topk_ids': tids, 'topk_text': [_decode([x]) for x in tids],
            'rare_target': bool(rare),
            'target_train_count': _tr_count,
            'target_train_fraction': _tr_frac,
            'target_text': _decode([ctgt]),
            'pred_text': _decode([pred]),
            'context_text': _decode(ctx_ids),
            'context_ids': ctx_ids,
            'target_in_topk': _triage['target_in_topk'],
            'cause_primary': _triage['primary'],
            'causes': _triage['causes'],
            'reference_order': (_ref_order if ref_ce is not None else None),
            'reference_pred_id': ref_pred,
            'reference_pred_text': (_decode([ref_pred]) if ref_pred is not None else None),
            'reference_ce': ref_ce,
            'reference_correct': _ref_correct,
            'model_correct_vs_reference': _model_correct,
            'reference_verdict': _ref_verdict,
            'model_minus_reference_ce': ((c - ref_ce)
                                         if (ref_ce is not None and math.isfinite(ref_ce)) else None),
            'same_context_target_variants': _ctx_variants,
            'same_context_support': _ctx_support,
            'same_context_ambiguous': (bool(_ctx_variants > 1) if _ctx_variants is not None else None),
            'is_boundary_token': (bool(bnd_np[row, pos + 1]) if (bnd_np is not None and bnd_np.shape == vb.shape) else None),
        })
    _all_sum_cpu = _all_sum.detach().cpu().tolist()
    _all_cnt_cpu = _all_cnt.detach().cpu().tolist()
    _all_total = sum(_all_cnt_cpu)
    cause_counts_all = {}
    for _name, _n, _sm in zip(_cause_names_all, _all_cnt_cpu, _all_sum_cpu):
        cause_counts_all[_name] = {
            'n': int(_n), 'share': (float(_n) / _all_total if _all_total else None),
            'mean_ce': (float(_sm) / _n if _n else None)}
    out_buckets = {}
    for k, v in buckets.items():
        out_buckets[k] = {'n': int(v['n']),
                          'mean_ce': (v['ce_sum'] / v['n']) if v['n'] else None,
                          'perplexity': (math.exp(min(v['ce_sum'] / v['n'], 700.0)) if v['n'] else None)}
    ent_vals = [t[5] for t in tok_heap if math.isfinite(t[5])]
    model.train(was_training)
    _pooled_ce = (sum(x[2] for x in seq_rows) / n_targets) if n_targets else None
    _ref_comparison = None
    if _ref_mode != 'none':
        _n_paired = int(_ref_stats['n_paired'])
        if _n_paired <= 0:
            _ref_comparison = {
                'available': False,
                'reason': _ref_problem or 'no finite paired target positions',
                'fit': _ref_meta,
                'complete': False,
            }
        else:
            _model_ce = _ref_stats['model_ce_sum'] / _n_paired
            _ref_ce = _ref_stats['reference_ce_sum'] / _n_paired
            _row_ok = _ref_row_n > 0
            _row_means = (_ref_row_delta_sum[_row_ok] / _ref_row_n[_row_ok]
                          if bool(_row_ok.any()) else np.asarray([], dtype=np.float64))
            _row_se = None
            _row_ci = None
            if _row_means.size >= 2:
                _row_se = float(np.std(_row_means, ddof=1) / math.sqrt(_row_means.size))
                _row_ci = [float(np.mean(_row_means) - 1.96 * _row_se),
                           float(np.mean(_row_means) + 1.96 * _row_se)]
            _n_model_only = int(_ref_stats['n_model_only_correct'])
            _n_ref_only = int(_ref_stats['n_reference_only_correct'])
            _n_both_wrong = int(_ref_stats['n_both_wrong'])
            _n_unexplained = int(_ref_stats['n_both_wrong_unexplained'])
            _ref_comparison = {
                'available': True,
                'complete': bool(_ref_problem is None),
                'reason': _ref_problem,
                'fit': _ref_meta,
                'n_paired_targets': _n_paired,
                'model_ce': float(_model_ce),
                'reference_ce': float(_ref_ce),
                'excess_ce_model_minus_reference': float(_model_ce - _ref_ce),
                'n_model_correct': int(_ref_stats['n_model_correct']),
                'n_reference_correct': int(_ref_stats['n_reference_correct']),
                'n_both_correct': int(_ref_stats['n_both_correct']),
                'n_both_wrong': _n_both_wrong,
                'n_model_only_correct': _n_model_only,
                'n_reference_only_correct': _n_ref_only,
                'n_both_wrong_unexplained': _n_unexplained,
                'share_model_only_correct': (float(_n_model_only) / _n_paired),
                'share_reference_only_correct': (float(_n_ref_only) / _n_paired),
                'share_both_wrong': (float(_n_both_wrong) / _n_paired),
                'share_both_wrong_unexplained': (float(_n_unexplained) / _n_paired),
                'row_mean_excess_ce': (float(np.mean(_row_means)) if _row_means.size else None),
                'row_excess_ce_se': _row_se,
                'row_excess_ce_ci95': _row_ci,
                'n_rows_with_paired_targets': int(_row_means.size),
                'note': ('The reference is a fixed smoothed count model fitted on the '
                         'training stream (not tuned on these validation rows). A token that '
                         'the reference gets right and the model misses is a model blind-spot '
                         'candidate; one that BOTH miss needs a manual label check before it '
                         'is called annotation noise. The row-level CI groups by document and '
                         'is the uncertainty to quote, not the token-level count.'),
            }
    return {'kind': 'token_error_analysis', 'rows': n_rows, 'seq_len': seq,
            'n_targets': int(n_targets), 'n_nonfinite_tokens': int(n_nonfinite),
            'mean_ce': _pooled_ce,
            'pooled_ppl': (math.exp(min(_pooled_ce, 700.0)) if _pooled_ce is not None else None),
            'buckets': out_buckets,
            'worst_sequences': worst_seqs,
            'worst_tokens': worst_tokens,
            'cause_counts': dict(cause_counts),
            'cause_counts_all': cause_counts_all,
            'cause_counts_all_note': 'whole-split heuristic tally over finite targets; cause thresholds are triage heuristics, not labels',
            'reference_comparison': _ref_comparison,
            'reference_basis': (_ref_meta.get('mode') if _ref_meta else None),
            'reference_problem': _ref_problem,
            'cause_guide': {
                'annotation_or_rare_target': 'check the target annotation and the training frequency; a rare token can be correct but under-trained',
                'ambiguous_context': 'the distribution is near-uniform or the top-2 margin is tiny; inspect the context and decide whether the task is genuinely ambiguous',
                'confident_model_blind_spot': 'the model is confidently wrong; look for a systematic context feature it has not learned',
                'target_outside_topk': 'the target is outside the sampled top-k; check whether this is a tokenization/label-shift issue or a real model miss',
                'mixed_unclear': 'no single heuristic explains this case; read the full context before changing the model',
                'reference_catches_model_miss': 'a training-count reference predicts this target correctly while the model does not; treat it as a model blind spot (feature/context coverage), not annotation noise',
                'reference_also_miss': 'the model and the training-count reference both miss this target; check the label/prefix before blaming the model — this is the annotation-error or intrinsically hard population',
            },
            'entropy': {'max': (max(ent_vals) if ent_vals else None),
                        'mean': (sum(ent_vals) / len(ent_vals) if ent_vals else None)},
            'context_ambiguity': {
                'context_len': _ctx_len_used,
                'n_worst_reviewed': len(worst_tokens),
                'n_ambiguous_worst': int(n_ctx_ambiguous),
                'n_contexts_with_multiple_targets': (sum(1 for _d in _ctx_counts.values() if len(_d) > 1)
                                                     if _ctx_counts is not None else None),
                'n_positions_with_ambiguous_context': (sum(sum(_d.values()) for _d in _ctx_counts.values() if len(_d) > 1)
                                                       if _ctx_counts is not None else None),
                'scan': _ctx_scan,
                'scan_complete': (None if _ctx_scan is None else bool(_ctx_scan.get('complete'))),
                'note': ('same prefix in the evaluated validation rows has more than one observed next token; '
                         'this is label inconsistency or genuine ambiguity, not proof of an annotation error'),
                'scan_note': (None if (_ctx_scan is None or _ctx_scan.get('complete'))
                              else 'prefix-ambiguity counts are from a bounded row/position sample; '
                                   'they are not whole-split totals (see scan metadata)')},
            'tokenizer_available': tok is not None,
            'rare_target_basis': rare_basis,
            'rare_target_problem': freq_problem,
            'label_check': {'next_token_shift': 'target = ids[t+1]; checked range [0, vocab) before scoring',
                            'range_checked': True, 'min_id': _min_id, 'max_id': _max_id,
                            'n_targets': int(n_targets), 'n_out_of_range': 0}}


@torch.inference_mode()
def compare_token_errors(model_a, model_b, val_batch, vocab, device, *, tokenizer=None,
                         top_n=50, chunk=8):
    """Paired per-token CE comparison between two checkpoints.

    Answers "on which positions does arm B lose to arm A" instead of only
    comparing aggregate PPL.  Positive ``delta = ce_b - ce_a`` means B is
    worse at that exact token."""
    vb = np.asarray(val_batch)
    if vb.ndim != 2 or vb.shape[1] < 2:
        raise ValueError(f'compare_token_errors needs a 2-D val_batch, got {vb.shape}')
    if not np.issubdtype(vb.dtype, np.integer):
        raise TypeError(f'compare_token_errors needs integer token ids, got dtype {vb.dtype}')
    _V = int(vocab)
    _lo, _hi = int(vb.min()), int(vb.max())
    if _lo < 0 or _hi >= _V:
        raise ValueError(f'compare_token_errors token ids out of range [{_lo}, {_hi}] for vocab {_V}')
    n_rows, seq = int(vb.shape[0]), int(vb.shape[1])
    span = seq - 1
    _top_n = _exact_count(top_n, minimum=0)
    if _top_n is None:
        raise ValueError(f'compare_token_errors needs a non-negative integer top_n, got {top_n!r}')
    top_n = int(_top_n)
    _chunk = _exact_count(chunk, minimum=1)
    if _chunk is None:
        raise ValueError(f'compare_token_errors needs a positive integer chunk, got {chunk!r}')
    chunk = int(_chunk)

    def _matrix(model):
        was = model.training
        model.eval()
        out = np.empty((n_rows, span), dtype=np.float32)
        try:
            for r0 in range(0, n_rows, max(1, int(chunk))):
                r1 = min(n_rows, r0 + max(1, int(chunk)))
                ids = torch.as_tensor(np.ascontiguousarray(vb[r0:r1]), dtype=torch.long, device=device)
                h = model.trunk(ids)
                for s0 in range(0, span, 64):
                    s1 = min(s0 + 64, span)
                    lg = model.head(h[:, s0:s1, :])
                    tg = ids[:, s0 + 1:s1 + 1]
                    ce = F.cross_entropy(lg.transpose(1, 2), tg, reduction='none')
                    out[r0:r1, s0:s1] = ce.detach().float().cpu().numpy()
                del h, ids
        finally:
            model.train(was)
        return out

    ca = _matrix(model_a)
    cb = _matrix(model_b)
    # A paired comparison must use the SAME token positions in both arms.
    # Independent nanmeans silently compare different supports (e.g. arm B
    # looks better because its hardest tokens evaluated to NaN and were
    # dropped).  Report the common finite support and compute the headline
    # means/delta on it.
    fa = np.isfinite(ca)
    fb = np.isfinite(cb)
    paired = fa & fb
    n_finite_a = int(fa.sum())
    n_finite_b = int(fb.sum())
    n_paired = int(paired.sum())
    n_total = int(ca.size)
    mean_a_paired = float(np.mean(ca[paired])) if n_paired else None
    mean_b_paired = float(np.mean(cb[paired])) if n_paired else None
    diff = cb - ca
    flat = np.where(paired, diff, -np.inf).reshape(-1)
    k = min(top_n, int(flat.size))
    if k <= 0:
        idx = np.array([], dtype=np.int64)
    else:
        idx = np.argpartition(flat, -k)[-k:]
        idx = idx[np.argsort(flat[idx])[::-1]]
    tok = tokenizer
    tok_warned = False

    def _decode(ids):
        nonlocal tok_warned
        if tok is None:
            return None
        try:
            return tok.decode([int(x) for x in ids])
        except Exception as e:
            if not tok_warned:
                print(f'[errors] WARNING: tokenizer decode failed ({type(e).__name__}: {e})')
                tok_warned = True
            return None

    out = []
    for i in idx:
        row, pos = int(i // span), int(i % span)
        if not (math.isfinite(float(ca[row, pos])) and math.isfinite(float(cb[row, pos]))):
            continue
        lo, hi = max(0, pos - 16), min(span, pos + 17)
        out.append({'row': row, 'position': pos,
                    'target_id': int(vb[row, pos + 1]),
                    'ce_a': float(ca[row, pos]), 'ce_b': float(cb[row, pos]),
                    'delta_b_minus_a': float(diff[row, pos]),
                    'target_text': _decode([int(vb[row, pos + 1])]),
                    'context_text': _decode([int(x) for x in vb[row, lo:hi + 1]])})
    return {'kind': 'paired_token_error_comparison', 'rows': n_rows, 'seq_len': seq,
            'n_tokens': n_total,
            'n_finite_a': n_finite_a, 'n_finite_b': n_finite_b,
            'n_paired_finite': n_paired,
            'paired_finite_frac': (float(n_paired) / n_total if n_total else None),
            # Headline means use the common finite support; the per-arm
            # all-finite means are kept separately for coverage inspection.
            'mean_ce_a': mean_a_paired, 'mean_ce_b': mean_b_paired,
            'mean_ce_a_all_finite': (float(np.mean(ca[fa])) if n_finite_a else None),
            'mean_ce_b_all_finite': (float(np.mean(cb[fb])) if n_finite_b else None),
            'mean_delta_b_minus_a': ((mean_b_paired - mean_a_paired)
                                     if n_paired else None),
            'n_nonfinite_a': int(n_total - n_finite_a),
            'n_nonfinite_b': int(n_total - n_finite_b),
            'b_worse_at_n': int(np.sum(paired & (diff > 0))),
            'a_worse_at_n': int(np.sum(paired & (diff < 0))),
            'worst_tokens_for_b': out}


def _batch_arrays(batch, vocab=None):
    """Validate/convert an explicit ``(inputs, targets)`` probe batch.

    Task-specific training loops (e.g. NIAH) build their own next-token
    tensors, so the generic overfit probe must accept that exact batch rather
    than only a 1-D token stream.  Returns int64 numpy arrays; both are 2-D,
    same row count, inputs at least as long as targets (a next-token target
    table is often one column shorter)."""
    if not isinstance(batch, (tuple, list)) or len(batch) != 2:
        raise ValueError('overfit batch must be a (inputs, targets) pair')
    x = np.asarray(batch[0])
    y = np.asarray(batch[1])
    if x.ndim != 2 or y.ndim != 2:
        raise ValueError(f'overfit batch inputs/targets must be 2-D, got {x.shape} and {y.shape}')
    if x.shape[0] != y.shape[0]:
        raise ValueError(f'overfit batch row mismatch: inputs {x.shape[0]} vs targets {y.shape[0]}')
    if x.shape[1] < y.shape[1]:
        raise ValueError(f'overfit batch targets are longer than inputs ({y.shape[1]} > {x.shape[1]})')
    if not np.issubdtype(x.dtype, np.integer) or not np.issubdtype(y.dtype, np.integer):
        raise TypeError('overfit batch inputs/targets must be integer token ids')
    x = np.ascontiguousarray(x, dtype=np.int64)
    y = np.ascontiguousarray(y, dtype=np.int64)
    if vocab is not None:
        # -100 / other ignore sentinels are allowed in targets; every other id
        # must address a real embedding row, or the probe would silently test a
        # different (wrapped-index) model than the training path.
        xv = x.reshape(-1)
        if xv.size and (int(xv.min()) < 0 or int(xv.max()) >= int(vocab)):
            raise ValueError(f'overfit batch inputs span [{int(xv.min())}, {int(xv.max())}], outside vocab [0, {int(vocab)})')
    return x, y

def _param_change_sample(model, max_per_tensor=4096):
    """Small, deterministic per-tensor sample for the overfit probe.

    Comparing a fixed small sample avoids duplicating the whole parameter
    vector (and its grad) just to answer "did the optimizer move anything?".
    The sample spans the tensor uniformly, including its first and last
    element."""
    parts = []
    for p in model.parameters():
        flat = p.detach().reshape(-1)
        n = int(flat.numel())
        if n == 0:
            continue
        if n <= max_per_tensor:
            parts.append(flat)
        else:
            idx = torch.linspace(0, n - 1, steps=int(max_per_tensor),
                                 device=flat.device).round().long()
            parts.append(flat.index_select(0, idx))
    return torch.cat(parts) if parts else torch.empty(0)


def _overfit_sanity_check_impl(variant='full', *, seed=0, steps=300, lr=3e-3, d=64, n_layers=2, n_heads=4, d_head=16, seq_len=32, batch_size=2, vocab=256, train_ids=None, batch=None, ignore_index=None, device=None, target_loss=0.05, target_acc=0.99, mlp_ratio=None, grad_clip=1.0):
    """Small-batch overfit sanity check (necessary, not sufficient).

    Take ONE fixed batch (the first batch from the real ``batch_iter``
    training loader when ``train_ids`` is given, passed explicitly as
    ``batch=(inputs, targets)``, or synthetic ids when neither is supplied),
    disable every regulariser (weight decay = 0, the compression penalty = 0;
    the model has no dropout), and optimise only that batch.  A correct
    training path drives the LM loss towards 0 and the next-token accuracy
    towards 100%.  Failure means a serious plumbing fault (loss not connected
    to the graph, gradients not applied, wrong labels, etc.) — do NOT launch a
    full run until it passes.

    ``batch`` exists for task-specific training loops (NIAH, masked next-token
    targets): the probe then exercises the actual input/label tensors and the
    ``ignore_index`` convention of that loop, not merely random ids.

    Passing does NOT prove the data pipeline / augmentation / label mapping is
    correct, so keep the intermediate-result checks as well.

    Returns a JSON-safe report; `passed` is False when any criterion fails.
    """
    if int(d) != int(n_heads) * int(d_head):
        raise ValueError(f'overfit_sanity_check: d={d} must equal n_heads*d_head={n_heads}*{d_head}')
    if batch is not None and train_ids is not None:
        raise ValueError('overfit_sanity_check: pass either train_ids or batch, not both')
    _steps = _exact_count(steps, minimum=1)
    if _steps is None:
        raise ValueError(f'overfit_sanity_check: steps must be a positive integer, got {steps!r}')
    _seq = _exact_count(seq_len, minimum=1)
    if _seq is None:
        raise ValueError(f'overfit_sanity_check: seq_len must be a positive integer, got {seq_len!r}')
    _bs = _exact_count(batch_size, minimum=1)
    if _bs is None:
        raise ValueError(f'overfit_sanity_check: batch_size must be a positive integer, got {batch_size!r}')
    _vocab = _exact_count(vocab, minimum=1)
    if _vocab is None:
        raise ValueError(f'overfit_sanity_check: vocab must be a positive integer, got {vocab!r}')
    steps, seq_len, batch_size, vocab = int(_steps), int(_seq), int(_bs), int(_vocab)
    if ignore_index is not None and (isinstance(ignore_index, (bool, np.bool_))
                                     or not isinstance(ignore_index, numbers.Integral)):
        raise ValueError(f'overfit_sanity_check: ignore_index must be an integer or None, got {ignore_index!r}')
    device = DEVICE if device is None else (device if isinstance(device, torch.device) else torch.device(device))
    seed = set_seed(seed)
    _rng_fp = rng_fingerprint()
    _label_shift_ok = None
    _batch_contract = None
    _loader_mode = None
    _ign = None if ignore_index is None else int(ignore_index)
    ids_full = None
    if batch is not None:
        x_np, y_np = _batch_arrays(batch, vocab=vocab)
        batch_size, seq_len = int(x_np.shape[0]), int(x_np.shape[1])
        _data_fp = _ids_fp(x_np.reshape(-1)) + ':' + _ids_fp(y_np.reshape(-1))
        _data_source = 'batch'
        x = torch.from_numpy(x_np).to(device)
        y = torch.from_numpy(y_np).to(device)
        _loader_mode = 'explicit_batch'
        if ignore_index is None:
            _ign = -100
        _batch_contract = bool(x.shape[0] == y.shape[0] and y.shape[1] <= x.shape[1])
        # Explicit batches may be task-specific (NIAH/masked targets), so the
        # next-token shift is REPORTED but not required here.
        _label_shift_ok = bool(y.shape == x.shape and y.shape[1] > 1
                               and torch.equal(y[:, :-1], x[:, 1:]))
    elif train_ids is not None:
        arr = np.asarray(train_ids)
        if arr.ndim != 1:
            raise ValueError('overfit_sanity_check: train_ids must be one-dimensional')
        if len(arr) < seq_len + 1:
            raise ValueError(f'overfit_sanity_check: need at least seq_len+1={seq_len + 1} tokens, got {len(arr)}')
        _loader = batch_iter(arr, int(seq_len), int(batch_size), device, seed=int(seed))
        try:
            x, y = next(_loader)
        finally:
            del _loader
        x_np = x.detach().cpu().numpy()
        y_np = y.detach().cpu().numpy()
        _data_fp = _ids_fp(x_np.reshape(-1)) + ':' + _ids_fp(y_np.reshape(-1))
        _data_source = 'train_ids'
        _loader_mode = 'batch_iter'
        _label_shift_ok = bool(y.shape == x.shape and y.shape[1] > 0
                               and torch.equal(y[:, :-1], x[:, 1:]))
        _batch_contract = bool(x.shape[0] == y.shape[0] and y.shape[1] == x.shape[1])
    else:
        _rng = np.random.default_rng(int(seed))
        chunk = _rng.integers(0, max(int(vocab), 1), size=(int(batch_size), seq_len + 1), dtype=np.int64)
        _data_fp = _ids_fp(chunk.reshape(-1))
        _data_source = 'synthetic'
        _loader_mode = 'synthetic'
        ids_full = torch.from_numpy(chunk).to(device)
        x, y = ids_full[:, :-1], ids_full[:, 1:]
        _label_shift_ok = bool(y.shape == x.shape and y.shape[1] > 0
                               and torch.equal(y[:, :-1], x[:, 1:]))
    # The synthetic/repository loader paths are next-token LM by contract; the
    # explicit task batches above are not.  Only the contract paths make the
    # label shift and near-chance initial loss PASS criteria.
    _label_shift_required = _data_source in ('synthetic', 'train_ids')
    _initial_chance_required = _label_shift_required
    if mlp_ratio is None:
        mlp_ratio = variant_mlp_ratio(variant, vocab, d=d, n_layers=n_layers, n_heads=n_heads, d_head=d_head, seq_len=seq_len, matched=PARAM_MATCHED | PARAM_MATCHED_V7)
    cfgs = make_layer_cfgs(n_layers, variant)
    model = SmallGPT(vocab, d, n_layers, n_heads, d_head, seq_len, cfgs, mlp_ratio=mlp_ratio).to(device)
    _p_before = _param_change_sample(model).clone()
    opt = build_optimizer(model, lr=lr, weight_decay=0.0, delta_lr_mult=1.0)

    _loss_path = 'forward' if _ign in (None, -100) else 'ce_loss'

    def _loss_consistency():
        with torch.no_grad():
            if _loss_path == 'forward':
                _trained = float(model(x, targets=y, vocab=vocab).detach())
            else:
                _trained = float(model.ce_loss(x, y, vocab, ignore_index=_ign).detach())
            _measured = float(_lm_batch_metrics(model, x, y, vocab, ignore_index=_ign)[0])
        if not (math.isfinite(_trained) and math.isfinite(_measured)):
            return {'trained_loss': _trained, 'measured_ce': _measured,
                    'abs_diff': None, 'rel_diff': None,
                    'tolerance': None, 'passed': False}
        _abs = abs(_trained - _measured)
        _rel = _abs / max(abs(_measured), 1e-12)
        _tol = max(1e-5, 1e-4 * abs(_measured))
        return {'trained_loss': _trained, 'measured_ce': _measured,
                'abs_diff': _abs, 'rel_diff': _rel,
                'tolerance': _tol, 'passed': bool(_abs <= _tol)}

    initial_loss, initial_acc = _lm_batch_metrics(model, x, y, vocab, ignore_index=_ign)
    _initial_loss_consistency = _loss_consistency()
    loss_curve = []
    acc_curve = []
    grad_norm_curve = []
    _nonfinite_step = None
    grad_norm = float('nan')
    grad_finite = True
    n_grad_none = 0
    _none_names = []
    _n_trainable = 0
    _n_with_grad = 0
    model.train()
    for step in range(int(steps)):
        if _loss_path == 'forward':
            ce = model(x, targets=y, vocab=vocab)
        else:
            ce = model.ce_loss(x, y, vocab, ignore_index=_ign)
        opt.zero_grad(set_to_none=True)
        ce.backward()
        _gs = []
        _none = 0
        _none_names = []
        _n_trainable = 0
        for _n, p in model.named_parameters():
            if not p.requires_grad:
                continue
            _n_trainable += 1
            if p.grad is None:
                _none += 1
                if len(_none_names) < 50:
                    _none_names.append(_n)
                continue
            _gs.append(p.grad.detach())
        if _gs:
            try:
                _norms = torch.stack(
                    [v.to(torch.float64) for v in torch._foreach_norm(_gs)]
                ).cpu().tolist()
            except Exception:
                _norms = [float(torch.linalg.vector_norm(g)) for g in _gs]
            grad_finite = all(math.isfinite(_x) for _x in _norms)
            grad_norm = math.sqrt(math.fsum(_x * _x for _x in _norms)) if grad_finite else float('inf')
        else:
            grad_norm = 0.0
            grad_finite = False
        n_grad_none = _none
        _n_with_grad = len(_gs)
        grad_norm_curve.append(float(grad_norm))
        _l = float(ce.detach())
        loss_curve.append(_l)
        # Check BEFORE the optimizer update: a non-finite loss/gradient must
        # never be written into the parameters.
        if (not math.isfinite(_l)) or (not grad_finite):
            _nonfinite_step = step + 1
            break
        if grad_clip:
            torch.nn.utils.clip_grad_norm_(model.parameters(), float(grad_clip))
        opt.step()
        if (step + 1) % max(1, int(steps) // 20) == 0 or step == int(steps) - 1:
            _a = _lm_batch_metrics(model, x, y, vocab, ignore_index=_ign)[1]
            acc_curve.append([step + 1, _a])
    final_loss, final_acc = _lm_batch_metrics(model, x, y, vocab, ignore_index=_ign)
    _final_loss_consistency = _loss_consistency()
    _loss_consistency_ok = bool(_initial_loss_consistency['passed'] and _final_loss_consistency['passed'])
    _p_after = _param_change_sample(model)
    params_changed = not bool(torch.equal(_p_before, _p_after))
    _finite_losses = [v for v in loss_curve if math.isfinite(float(v))]
    best_loss = min(_finite_losses) if _finite_losses else float('nan')
    # A correct optimizer must also move the loss DOWN, not merely end below
    # the target by luck.  Keep this in `passed`: a path that starts below the
    # target and never updates (lr=0) must still fail.
    loss_decreased = bool(math.isfinite(initial_loss) and math.isfinite(final_loss) and final_loss < initial_loss)
    _chance = math.log(max(int(vocab), 2))
    _initial_near_chance = bool(math.isfinite(initial_loss) and abs(float(initial_loss) - _chance) <= max(0.5 * _chance, 1.0))
    _finite_curve = all(math.isfinite(float(v)) for v in loss_curve)
    # A wrong label shift or an initial loss nowhere near log(vocab) is a data
    # plumbing fault even if the model can still memorise the fixed batch, so
    # these diagnostics are part of the verdict for the next-token paths (the
    # explicit task-batch path keeps them as diagnostics only).  The batch
    # contract must never be False; None means "not applicable".
    _passed = bool(
        math.isfinite(final_loss) and final_loss <= float(target_loss)
        and final_acc >= float(target_acc) and grad_finite and params_changed
        and math.isfinite(best_loss) and best_loss <= float(target_loss)
        and loss_decreased and _finite_curve and _nonfinite_step is None
        and _batch_contract is not False
        and (not _label_shift_required or bool(_label_shift_ok))
        and (not _initial_chance_required or _initial_near_chance)
        and _loss_consistency_ok)
    passed = _passed
    # Intermediate-result evidence kept alongside the pass/fail bit: a sanity
    # check that only reports "PASS" hides WHICH part of the pipeline was
    # exercised.
    report = {
        'kind': 'small_batch_overfit_sanity',
        'variant': variant,
        'seed': int(seed),
        'code': code_stamp(),
        'determinism': determinism_label(),
        'device': str(device),
        'steps': int(steps),
        'lr': float(lr),
        'batch_shape': [int(batch_size), int(seq_len)],
        'vocab_size': int(vocab),
        'architecture': {'d': int(d), 'n_layers': int(n_layers), 'n_heads': int(n_heads), 'd_head': int(d_head)},
        'mlp_ratio': float(mlp_ratio),
        'ignore_index': _ign,
        'label_contract': {
            'source': _data_source,
            'ignore_index': _ign,
            'n_scored_targets': int((y != _ign).sum()) if _ign is not None else int(y.numel()),
            'n_targets': int(y.numel()),
        },
        'data_source': _data_source,
        'loader_mode': _loader_mode,
        'loss_path': _loss_path,
        'data_fp': _data_fp,
        'rng_fp': _rng_fp,
        'regularization': {'weight_decay': 0.0, 'comp_lambda': 0.0, 'dropout': 0.0, 'augmentation': 'none'},
        'initial_loss': float(initial_loss),
        'initial_accuracy': float(initial_acc),
        'loss_contract': {'initial': _initial_loss_consistency,
                          'final': _final_loss_consistency},
        'final_loss': float(final_loss),
        'final_accuracy': float(final_acc),
        'best_loss': float(best_loss),
        'loss_decreased': bool(loss_decreased),
        'loss_reduction': float(initial_loss - final_loss) if math.isfinite(initial_loss) and math.isfinite(final_loss) else None,
        'loss_curve': [float(v) for v in loss_curve],
        'accuracy_curve': acc_curve,
        'grad_norm_curve': grad_norm_curve,
        'grad_norm_last': float(grad_norm),
        'nonfinite_step': _nonfinite_step,
        'grad_all_finite': bool(grad_finite),
        'params_without_grad': int(n_grad_none),
        'params_without_grad_names': list(_none_names),
        'trainable_params': int(_n_trainable),
        'params_with_grad': int(_n_with_grad),
        'grad_coverage': (float(_n_with_grad) / float(_n_trainable) if _n_trainable else 0.0),
        'params_changed': bool(params_changed),
        'batch_reused': True,
        'target_loss': float(target_loss),
        'target_accuracy': float(target_acc),
        'expected_initial_loss_log_vocab': float(_chance),
        'label_shift_required': bool(_label_shift_required),
        'pass_criteria': {
            'finite_final_loss_below_target': bool(math.isfinite(final_loss) and final_loss <= float(target_loss)),
            'accuracy_above_target': bool(final_acc >= float(target_acc)),
            'gradients_finite': bool(grad_finite),
            'parameters_changed': bool(params_changed),
            'best_loss_below_target': bool(math.isfinite(best_loss) and best_loss <= float(target_loss)),
            'loss_decreased': bool(loss_decreased),
            'loss_curve_all_finite': bool(_finite_curve and _nonfinite_step is None),
            'batch_contract_not_failed': bool(_batch_contract is not False),
            'labels_are_next_token_shift': (bool(_label_shift_ok) if _label_shift_required else None),
            'initial_loss_near_log_vocab': (bool(_initial_near_chance) if _initial_chance_required else None),
            'loss_reduction_matches_mean_ce': bool(_loss_consistency_ok),
        },
        'intermediate_checks': {
            'labels_are_next_token_shift': _label_shift_ok,
            'batch_contract_ok': _batch_contract,
            'initial_loss_near_log_vocab': _initial_near_chance,
            'loss_curve_all_finite': bool(_finite_curve),
            'grad_all_finite': bool(grad_finite),
            'params_changed': bool(params_changed),
            'loss_decreased': bool(loss_decreased),
            'grad_coverage': (float(_n_with_grad) / float(_n_trainable) if _n_trainable else 0.0),
            'loss_reduction_matches_mean_ce': bool(_loss_consistency_ok),
        },
    }
    report['passed'] = passed
    report['failed_criteria'] = [k for k, ok in report['pass_criteria'].items() if ok is False]
    if passed:
        report['diagnosis'] = 'ok'
    elif not (grad_finite and params_changed):
        report['diagnosis'] = 'no/finite gradients or parameters did not update'
    elif not loss_decreased:
        report['diagnosis'] = 'loss did not decrease on the fixed batch (optimizer/step or graph is not wired through)'
    elif _label_shift_required and not _label_shift_ok:
        report['diagnosis'] = 'labels are not the next-token shift of the inputs (label construction/order bug)'
    elif _initial_chance_required and not _initial_near_chance:
        report['diagnosis'] = 'initial loss is far from log(vocab) (wrong label map, vocabulary mismatch or broken initialisation)'
    elif not _loss_consistency_ok:
        report['diagnosis'] = 'the reported training loss does not match the mean cross-entropy over the scored targets (loss reduction/denominator bug)'
    elif _batch_contract is False:
        report['diagnosis'] = 'the explicit batch violates the shape/label contract'
    elif not (_finite_curve and _nonfinite_step is None):
        report['diagnosis'] = 'the loss/gradient curve became non-finite before the target was reached'
    else:
        report['diagnosis'] = 'loss did not converge on a single repeated batch within the step limit'
    del model, opt, ids_full, x, y
    gc.collect()
    if device.type == 'cuda':
        torch.cuda.empty_cache()
    return report

def overfit_sanity_check(variant='full', *, seed=0, steps=300, lr=3e-3, d=64, n_layers=2, n_heads=4, d_head=16, seq_len=32, batch_size=2, vocab=256, train_ids=None, batch=None, ignore_index=None, device=None, target_loss=0.05, target_acc=0.99, mlp_ratio=None, grad_clip=1.0):
    """Side-effect-free wrapper around the small-batch overfit probe.

    The probe deliberately reseeds the process to ``seed`` and then trains a
    tiny model.  Saving/restoring every RNG stream around it keeps the probe
    from changing the stream seen by the real training cell that follows, so
    the diagnostic itself can never alter a recorded loss curve.  The report
    additionally records the before/after RNG fingerprint as evidence that
    the preservation contract held.
    """
    _fp_before = rng_fingerprint()
    with _preserve_rng_state():
        report = _overfit_sanity_check_impl(variant, seed=seed, steps=steps, lr=lr, d=d, n_layers=n_layers, n_heads=n_heads, d_head=d_head, seq_len=seq_len, batch_size=batch_size, vocab=vocab, train_ids=train_ids, batch=batch, ignore_index=ignore_index, device=device, target_loss=target_loss, target_acc=target_acc, mlp_ratio=mlp_ratio, grad_clip=grad_clip)
    _fp_after = rng_fingerprint()
    report['rng_fp_before'] = _fp_before
    report['rng_fp_after'] = _fp_after
    report['rng_state_preserved'] = bool(_fp_before == _fp_after)
    report.setdefault('pass_criteria', {})['rng_state_preserved'] = bool(report['rng_state_preserved'])
    if not report['rng_state_preserved']:
        # A diagnostic that mutates the process RNG streams is itself a
        # reproducibility fault: the training cell after it would see a
        # different data order than the same run without the probe.
        report['passed'] = False
        report['failed_criteria'] = list(report.get('failed_criteria') or []) + ['rng_state_preserved']
        report['diagnosis'] = 'the overfit probe did not restore the process RNG state'
    return report

_OVERFIT_GUARD = {}
# Reports of the checks that actually ran (the boolean guard above is the
# resume cache; this is the evidence written into the run manifest).  Keyed
# like _OVERFIT_GUARD by (variant, source, ...).
_OVERFIT_REPORTS = {}

_OVERFIT_ARCH = {'d': 64, 'n_layers': 2, 'n_heads': 4, 'd_head': 16}

def _probe_arch(arch=None):
    """Effective probe architecture: the tiny default, overridden by the
    caller-supplied keys (a scaling driver can probe the architecture family
    it is about to train — d/n_heads/d_head geometry mismatches that a 4-head
    probe can never see are caught before the panel starts)."""
    _arch = dict(_OVERFIT_ARCH)
    if arch:
        for _k in _arch:
            if arch.get(_k) is not None:
                _arch[_k] = int(arch[_k])
    return _arch

def _overfit_probe_config(*, seed, steps, seq_len, batch_size, vocab, target_loss, target_acc, arch=None, mlp_ratio=None, ignore_index=None, source='synthetic', data_fp=None, device=None):
    """Exact probe configuration that a cached PASS is allowed to certify.

    A pass only proves that THIS tiny run can overfit (same step count, batch
    size, sequence length, targets, architecture, MLP width, ignore-index
    convention, data batch and code semantics).  Without these fields in the
    cache key a lax probe (e.g. one step, target_loss=100) would silently
    satisfy a later strict probe, turning the safety gate into a formality.
    The code stamp is included because changing the trainer/loss must
    invalidate an old pass even when the numeric knobs look identical.  The
    data source/fingerprint is kept separate (`_overfit_probe_semantics`) so a
    synthetic pass can still be subsumed by a real-data pass of the same
    model/probe geometry.
    """
    cfg = {
        'schema': 2,
        'seed': int(seed),
        'steps': int(steps),
        'seq_len': int(seq_len),
        'batch_size': int(batch_size),
        'vocab': int(vocab),
        'target_loss': float(target_loss),
        'target_accuracy': float(target_acc),
        'architecture': _probe_arch(arch),
        'mlp_ratio': (None if mlp_ratio is None else float(mlp_ratio)),
        'ignore_index': (None if ignore_index is None else int(ignore_index)),
        'source': str(source),
        'data_fp': (None if data_fp is None else str(data_fp)),
        # The probe certifies THIS execution target.  A CPU pass cannot attest
        # that the CUDA kernel path applies gradients; including the device and
        # the environment class in the cache key prevents a cached pass from
        # crossing hardware/software boundaries.
        'device': str(DEVICE if device is None else device),
        'determinism': determinism_label(),
        'exec_fp': execution_fingerprint(),
        'code': code_stamp(),
    }
    return cfg

def _overfit_probe_digest(cfg):
    blob = json.dumps(cfg, sort_keys=True, separators=(',', ':'), ensure_ascii=True)
    return hashlib.sha256(blob.encode('utf-8')).hexdigest()[:16]

def _overfit_probe_semantics(cfg):
    """Digest of everything except WHERE the batch came from.

    A passed real-data probe of the same architecture/MLP/step/target
    configuration subsumes the synthetic probe; a different corpus does not
    invalidate the model-plumbing certificate, but the data certificate itself
    is still keyed by the full config (source + fingerprint)."""
    sem = {k: v for k, v in (cfg or {}).items() if k not in ('source', 'data_fp')}
    blob = json.dumps(sem, sort_keys=True, separators=(',', ':'), ensure_ascii=True)
    return hashlib.sha256(blob.encode('utf-8')).hexdigest()[:16]

def probe_seq_len(seq_len, *, min_blocks=128, cap=256):
    """Sequence length for the pre-flight probe.

    A 64-token probe never exercises the real block geometry (max_block=128,
    HCA block_size=64).  Use the panel's own length up to ``cap`` so at least
    one multi-block schedule is covered without running the full-scale probe;
    short panels keep their own (already short) length.  ``cap`` can be
    overridden with ``CSA_PROBE_SEQ``.
    """
    raw = os.environ.get('CSA_PROBE_SEQ', '').strip()
    if raw:
        try:
            return max(2, int(raw))
        except ValueError:
            print(f'[overfit] CSA_PROBE_SEQ={raw!r} is not an integer — using the automatic probe length')
    s = max(2, int(seq_len))
    return min(s, int(cap)) if s >= int(min_blocks) else s

def overfit_reports(*, source=None):
    """Copy of the small-batch reports gathered in this process, optionally
    filtered to source 'synthetic' or 'data'.  Pure read for tracking."""
    return {k: dict(v) for k, v in _OVERFIT_REPORTS.items() if source is None or k[1] == source}

def overfit_reports_for(variants, *, source=None, probe_semantics=None, probe_key=None, data_fp=None):
    """Exact-match evidence recovery for a panel.

    `run()` must persist only the probes that certify the CURRENT config: a
    report written under different or looser settings must not be attached to a
    new panel.  Matching is by probe semantics
    (architecture/MLP/steps/targets/ignore-index), optional source and data
    fingerprint, and optionally the full probe digest."""
    _want = set(variants)
    out = []
    for (_v, _src, *rest), _r in _OVERFIT_REPORTS.items():
        if _v not in _want:
            continue
        if source is not None and _src != source:
            continue
        if probe_semantics is not None and _r.get('guard_probe_semantics') != probe_semantics:
            continue
        if probe_key is not None and _r.get('guard_probe_key') != probe_key:
            continue
        if data_fp is not None and (_v, _src, *rest) and len(rest) >= 2 and rest[1] != data_fp:
            continue
        out.append(dict(_r))
    return out

def _overfit_ratio_for(mlp_ratio, variant):
    if isinstance(mlp_ratio, dict):
        return mlp_ratio.get(variant)
    return mlp_ratio

def _production_loop_sanity_check_impl(variant='full', *, seed=0, steps=150, lr=1e-2,
                                      d=32, n_layers=1, n_heads=4, d_head=8,
                                      seq_len=16, batch_size=2, vocab=64,
                                      train_ids=None, device=None,
                                      target_loss=0.05, target_acc=0.99,
                                      mlp_ratio=None):
    """Overfit ONE fixed window through the REAL `train_variant` loop.

    The hand-rolled small-batch probe proves the model/loss/label plumbing.
    This companion check proves the production trainer (optimizer groups,
    scheduler, clipping, loss assembly, PPL/eval path) actually applies the
    updates: a bug in `train_variant` cannot hide behind a separately written
    probe loop.
    """
    if int(d) != int(n_heads) * int(d_head):
        raise ValueError(f'production_loop_sanity_check: d={d} must equal n_heads*d_head={n_heads}*{d_head}')
    _steps = _exact_count(steps, minimum=1)
    if _steps is None:
        raise ValueError(f'production_loop_sanity_check: steps must be a positive integer, got {steps!r}')
    _seq = _exact_count(seq_len, minimum=1)
    if _seq is None:
        raise ValueError(f'production_loop_sanity_check: seq_len must be a positive integer, got {seq_len!r}')
    _bs = _exact_count(batch_size, minimum=1)
    if _bs is None:
        raise ValueError(f'production_loop_sanity_check: batch_size must be a positive integer, got {batch_size!r}')
    _vocab = _exact_count(vocab, minimum=1)
    if _vocab is None:
        raise ValueError(f'production_loop_sanity_check: vocab must be a positive integer, got {vocab!r}')
    steps, seq_len, batch_size, vocab = int(_steps), int(_seq), int(_bs), int(_vocab)
    device = DEVICE if device is None else (device if isinstance(device, torch.device) else torch.device(device))
    seed = set_seed(seed)
    rng = np.random.default_rng((seed + 7919) % (MAX_SEED + 1))
    if train_ids is None:
        window = rng.integers(0, vocab, size=seq_len + 1, dtype=np.int64)
        source = 'synthetic'
    else:
        arr = np.asarray(train_ids)
        if arr.ndim != 1:
            raise ValueError('production_loop_sanity_check: train_ids must be one-dimensional')
        if arr.size < seq_len + 1:
            raise ValueError(f'production_loop_sanity_check: need at least seq_len+1={seq_len + 1} tokens, got {arr.size}')
        start = int(rng.integers(0, int(arr.size) - int(seq_len)))
        window = np.ascontiguousarray(arr[start:start + seq_len + 1], dtype=np.int64)
        source = 'train_ids'
    if mlp_ratio is None:
        mlp_ratio = variant_mlp_ratio(variant, vocab, d=d, n_layers=n_layers,
                                      n_heads=n_heads, d_head=d_head,
                                      seq_len=seq_len,
                                      matched=PARAM_MATCHED | PARAM_MATCHED_V7)
    val = np.tile(window[None, :seq_len], (batch_size, 1)).astype(np.int64, copy=False)
    rec = train_variant(variant, window, val, vocab, seed=seed, d=d,
                        n_layers=n_layers, n_heads=n_heads, d_head=d_head,
                        seq_len=seq_len, batch_size=batch_size, steps=steps,
                        lr=lr, weight_decay=0.0, warmup=0, comp_lambda=0.0,
                        delta_lr_mult=1.0, eval_every=0, eval_subset=0,
                        val_bnd=None, device=device, log_every=0,
                        diag_every=1, measure_eff=False, amp_dtype='fp32',
                        eager_batch=False, return_model=True,
                        save_ckpt='none', ckpt_dir=None,
                        early_stop_patience=None)
    model = rec.pop('_model', None)
    try:
        if rec.get('cap_truncated'):
            final_loss = final_acc = float('nan')
            losses = []
            opt = {}
        else:
            losses = [float(v) for v in (rec.get('losses') or [])]
            x = torch.from_numpy(np.tile(window[:-1], (batch_size, 1))).to(device)
            y = torch.from_numpy(np.tile(window[1:], (batch_size, 1))).to(device)
            try:
                final_loss, final_acc = _lm_batch_metrics(model, x, y, vocab)
            finally:
                del x, y
            opt = rec.get('opt_diag_summary') if isinstance(rec.get('opt_diag_summary'), dict) else {}
    finally:
        del model
        gc.collect()
        if device.type == 'cuda':
            torch.cuda.empty_cache()
    finite = all(math.isfinite(v) for v in losses)
    best_loss = min(losses) if losses else float('nan')
    initial_loss = losses[0] if losses else float('nan')
    loss_decreased = bool(math.isfinite(initial_loss) and math.isfinite(final_loss)
                          and final_loss < initial_loss)
    skipped = int(opt.get('skipped_updates') or 0)
    nonfinite_loss = int(opt.get('nonfinite_loss_steps') or 0)
    nonfinite_grad = int(opt.get('nonfinite_grad_steps') or 0)
    grad_max = opt.get('grad_norm_max')
    update_max = opt.get('update_norm_max')
    grad_ok = (grad_max is not None and math.isfinite(float(grad_max)) and float(grad_max) > 0.0)
    params_changed = bool(update_max is not None and math.isfinite(float(update_max))
                          and float(update_max) > 0.0)
    criteria = {
        'all_steps_completed': bool(not rec.get('cap_truncated')
                                    and int(rec.get('steps_completed') or 0) == steps),
        'no_skipped_updates': bool(skipped == 0),
        'no_nonfinite_loss_steps': bool(nonfinite_loss == 0),
        'no_nonfinite_grad_steps': bool(nonfinite_grad == 0),
        'gradients_finite_and_nonzero': bool(grad_ok),
        'parameters_changed': bool(params_changed),
        'loss_curve_all_finite': bool(finite),
        'loss_decreased': bool(loss_decreased),
        'final_loss_below_target': bool(math.isfinite(final_loss) and final_loss <= float(target_loss)),
        'accuracy_above_target': bool(math.isfinite(final_acc) and final_acc >= float(target_acc)),
    }
    passed = all(criteria.values())
    report = {
        'kind': 'production_loop_overfit_sanity',
        'variant': variant,
        'seed': int(seed),
        'code': code_stamp(),
        'device': str(device),
        'steps': steps,
        'lr': float(lr),
        'seq_len': seq_len,
        'batch_size': batch_size,
        'vocab_size': vocab,
        'architecture': {'d': int(d), 'n_layers': int(n_layers),
                         'n_heads': int(n_heads), 'd_head': int(d_head)},
        'mlp_ratio': float(mlp_ratio),
        'data_source': source,
        'data_fp': _ids_fp(window),
        'optimizer': 'build_optimizer/AdamW',
        'losses': losses,
        'initial_loss': float(initial_loss),
        'final_loss': float(final_loss),
        'best_loss': float(best_loss),
        'final_accuracy': float(final_acc),
        'loss_decreased': bool(loss_decreased),
        'grad_norm_max': grad_max,
        'update_norm_max': update_max,
        'params_changed': bool(params_changed),
        'skipped_updates': skipped,
        'nonfinite_loss_steps': nonfinite_loss,
        'nonfinite_grad_steps': nonfinite_grad,
        'target_loss': float(target_loss),
        'target_accuracy': float(target_acc),
        'pass_criteria': criteria,
        'passed': passed,
        'failed_criteria': [k for k, ok in criteria.items() if not ok],
    }
    report['diagnosis'] = ('ok' if passed else
                           'the production training loop did not overfit the fixed window '
                           '(see failed_criteria)')
    return report

def production_loop_sanity_check(variant='full', *, seed=0, **kwargs):
    """RNG-preserving wrapper around the production-loop overfit probe."""
    _fp_before = rng_fingerprint()
    with _preserve_rng_state():
        report = _production_loop_sanity_check_impl(variant, seed=seed, **kwargs)
    _fp_after = rng_fingerprint()
    report['rng_fp_before'] = _fp_before
    report['rng_fp_after'] = _fp_after
    report['rng_state_preserved'] = bool(_fp_before == _fp_after)
    report['pass_criteria']['rng_state_preserved'] = bool(report['rng_state_preserved'])
    if not report['rng_state_preserved']:
        report['passed'] = False
        report['failed_criteria'] = list(report.get('failed_criteria') or []) + ['rng_state_preserved']
        report['diagnosis'] = 'the production-loop probe did not restore the process RNG state'
    return report

def overfit_guard(variants, *, seed=0, steps=200, seq_len=64, batch_size=2, vocab=1024, train_ids=None, batch=None, ignore_index=None, mlp_ratio=None, force=False, target_loss=0.05, target_acc=0.99, arch=None, device=None):
    """Run `overfit_sanity_check` once per variant per process and hard-stop
    on failure.  Called automatically by `run()` before the first panel and by
    the length/checkpoint phases, so every training driver inherits the check.

    The in-process cache is keyed by the FULL probe configuration (seed, step
    count, shape, targets, architecture, MLP width, ignore-index convention,
    data source/fingerprint, code) as well as the corpus bytes, so a lenient
    probe can never certify a stricter one.  `arch` optionally overrides the
    probe architecture (d/n_layers/n_heads/d_head): pass the panel's own
    geometry on the scale ladder so the probe exercises the same head/layer
    shapes the real run will use; unset it for the tiny default probe.
    `mlp_ratio` accepts a scalar or a per-variant mapping.  `batch` accepts a
    task-specific ``(inputs, targets)`` pair (NIAH/masked next-token targets)
    and `ignore_index` carries that loop's label convention; passing either
    `batch` or `train_ids` runs the data-path probe.  `CSA_SKIP_OVERFIT=1` is
    the explicit escape hatch (e.g. a diagnostic box with a deliberately broken
    batch); it prints a loud skip line instead.  Passing is necessary, not
    sufficient."""
    if os.environ.get('CSA_SKIP_OVERFIT', '').strip().lower() in ('1', 'true', 'yes', 'on'):
        print('[overfit] guard SKIPPED (CSA_SKIP_OVERFIT is set) — this run has no small-batch safety check')
        return []
    if batch is not None and train_ids is not None:
        raise ValueError('overfit_guard: pass either train_ids or batch, not both')
    seed = _seed_value(seed)
    variants = list(variants)
    _arch = _probe_arch(arch)
    _ign = None
    _data_fp = None
    if batch is not None:
        src = 'batch'
        _x, _y = _batch_arrays(batch, vocab=vocab)
        seq_len, batch_size = int(_x.shape[1]), int(_x.shape[0])
        _data_fp = _ids_fp(_x.reshape(-1)) + ':' + _ids_fp(_y.reshape(-1))
        _ign = -100 if ignore_index is None else int(ignore_index)
    elif train_ids is not None:
        src = 'data'
        _arr = np.asarray(train_ids)
        _data_fp = _ids_fp(_arr if _arr.ndim == 1 else np.ascontiguousarray(_arr).reshape(-1))
        _ign = None if ignore_index is None else int(ignore_index)
    else:
        src = 'synthetic'
        _ign = None if ignore_index is None else int(ignore_index)
    if _arch != _OVERFIT_ARCH:
        print(f"[overfit] probe architecture override: d={_arch['d']} n_layers={_arch['n_layers']} n_heads={_arch['n_heads']} d_head={_arch['d_head']} (default tiny probe is d={_OVERFIT_ARCH['d']}/{_OVERFIT_ARCH['n_layers']}L/{_OVERFIT_ARCH['n_heads']}H)" )
    _probe_cfgs = {}
    _cfg_keys = {}
    _semantics = {}
    for v in variants:
        _pc = _overfit_probe_config(seed=seed, steps=steps, seq_len=seq_len, batch_size=batch_size, vocab=vocab, target_loss=target_loss, target_acc=target_acc, arch=_arch, mlp_ratio=_overfit_ratio_for(mlp_ratio, v), ignore_index=_ign, source=src, data_fp=_data_fp, device=device)
        _probe_cfgs[v] = _pc
        _cfg_keys[v] = _overfit_probe_digest(_pc)
        _semantics[v] = _overfit_probe_semantics(_pc)

    def _key(v):
        if src in ('data', 'batch'):
            return (v, src, int(vocab), _data_fp, _cfg_keys[v])
        return (v, 'synthetic', _cfg_keys[v])

    def _known(v):
        # Only a PASSED check may certify a variant.  A cached failure must be
        # retried (or re-raised) on the next call: treating any present key as
        # "already checked" would let a caller that caught the first failure
        # bypass the hard stop on a later phase in the same process.
        if _OVERFIT_GUARD.get(_key(v)) is True:
            return True
        if src == 'synthetic':
            # A passed data/batch probe of the same model/probe geometry
            # subsumes the synthetic plumbing check.
            for _k in list(_OVERFIT_GUARD):
                if (_k[0] == v and _k[1] in ('data', 'batch')
                        and _OVERFIT_GUARD.get(_k) is True
                        and (_OVERFIT_REPORTS.get(_k) or {}).get('guard_probe_semantics') == _semantics[v]):
                    return True
        return False

    todo = [v for v in variants if force or not _known(v)]
    if not todo:
        return []
    reports = []
    for v in todo:
        r = overfit_sanity_check(v, seed=seed, steps=steps, d=_arch['d'], n_layers=_arch['n_layers'], n_heads=_arch['n_heads'], d_head=_arch['d_head'], seq_len=seq_len, batch_size=batch_size, vocab=vocab, train_ids=(train_ids if src == 'data' else None), batch=(batch if src == 'batch' else None), ignore_index=_ign, mlp_ratio=_overfit_ratio_for(mlp_ratio, v), target_loss=target_loss, target_acc=target_acc, device=device)
        r['guard_probe_config'] = _probe_cfgs[v]
        r['guard_probe_key'] = _cfg_keys[v]
        r['guard_probe_semantics'] = _semantics[v]
        _key_v = _key(v)
        _OVERFIT_GUARD[_key_v] = bool(r['passed'])
        _OVERFIT_REPORTS[_key_v] = r
        reports.append(r)
        print(f"[overfit] {v:<24} loss {r['initial_loss']:.3f} -> {r['final_loss']:.4f}  acc {r['final_accuracy'] * 100:.1f}%  grad_finite={r['grad_all_finite']}  params_changed={r['params_changed']}  {'PASS' if r['passed'] else 'FAIL'}")
        if not r['passed']:
            raise RuntimeError(f'small-batch overfit sanity check FAILED for `{v}` ({r["diagnosis"]}) — do NOT start or continue this run; this points at a gradient/loss/label plumbing fault.  Inspect the returned report and set CSA_SKIP_OVERFIT=1 only if you deliberately accept the risk.')
    return reports

_REPRO_GUARD = {}
_REPRO_REPORTS = {}

_REPRO_ARCH = {'d': 32, 'n_layers': 1, 'n_heads': 4, 'd_head': 8}

def _repro_probe_arch(arch=None):
    got = dict(_REPRO_ARCH)
    if arch:
        for _k in got:
            if arch.get(_k) is not None:
                got[_k] = int(arch[_k])
    return got

def _repro_batch(seed, *, batch_size, seq_len, vocab, train_ids=None):
    """Fixed probe batch + its identity.

    With ``train_ids`` the batch is a deterministic slice of the REAL token
    stream (the same corpus the panel trains on); otherwise it is synthetic.
    The generator is separate from the model's PyTorch RNG stream."""
    _rng = np.random.default_rng((_seed_value(seed) + 7919) % (MAX_SEED + 1))
    if train_ids is not None:
        arr = np.asarray(train_ids).reshape(-1)
        need = int(seq_len) + 1
        if arr.size < need:
            raise ValueError(f'reproducibility probe: need at least seq_len+1={need} tokens, got {arr.size}')
        starts = _rng.integers(0, int(arr.size) - int(seq_len), size=int(batch_size))
        chunk = np.stack([arr[int(s):int(s) + int(seq_len) + 1] for s in starts]).astype(np.int64, copy=False)
        return chunk[:, :-1], chunk[:, 1:], _ids_fp(chunk.reshape(-1)), 'train_ids'
    chunk = _rng.integers(0, max(int(vocab), 1), size=(int(batch_size), int(seq_len) + 1), dtype=np.int64)
    return chunk[:, :-1], chunk[:, 1:], _ids_fp(chunk.reshape(-1)), 'synthetic'

def _repro_tiny_losses(variant, seed, *, steps=3, d=32, n_layers=1, n_heads=4, d_head=8, seq_len=16, batch_size=2, vocab=64, lr=0.003, train_ids=None, mlp_ratio=None, device=None):
    """Run one very short, fully seeded training stream and return its losses.

    Uses a fixed batch (sampled from its own NumPy generator, so the data
    stream cannot consume the model's PyTorch RNG) and disables weight decay.
    Two calls with the same ``seed`` must agree bit-for-bit on the same stack;
    that is the property the pre-flight reproducibility guard checks.  The
    architecture/MLP/data are caller-selectable so a scale panel can repeat
    its REAL geometry instead of a tiny proxy."""
    device = DEVICE if device is None else (device if isinstance(device, torch.device) else torch.device(device))
    seed = set_seed(seed)
    x_np, y_np, _data_fp, _src = _repro_batch(seed, batch_size=batch_size, seq_len=seq_len, vocab=vocab, train_ids=train_ids)
    x = torch.from_numpy(np.ascontiguousarray(x_np)).to(device)
    y = torch.from_numpy(np.ascontiguousarray(y_np)).to(device)
    if mlp_ratio is None:
        mlp_ratio = variant_mlp_ratio(variant, int(vocab), d=int(d), n_layers=int(n_layers), n_heads=int(n_heads), d_head=int(d_head), seq_len=int(seq_len), matched=PARAM_MATCHED | PARAM_MATCHED_V7)
    cfgs = make_layer_cfgs(int(n_layers), variant)
    model = SmallGPT(int(vocab), int(d), int(n_layers), int(n_heads), int(d_head), int(seq_len), cfgs, mlp_ratio=mlp_ratio).to(device)
    opt = build_optimizer(model, lr=lr, weight_decay=0.0, delta_lr_mult=1.0)
    model.train()
    losses = []
    try:
        for _ in range(int(steps)):
            ce = model.ce_loss(x, y, int(vocab))
            opt.zero_grad(set_to_none=True)
            ce.backward()
            opt.step()
            losses.append(float(ce.detach()))
    finally:
        del model, opt, x, y, x_np, y_np
        gc.collect()
        if device.type == 'cuda':
            torch.cuda.empty_cache()
    return losses

def _repro_probe_config(*, seed, steps, tol, arch, seq_len, batch_size, vocab, mlp_ratio, data_fp, train_ids, lr=0.003, device=None):
    return {
        'schema': 3,
        'seed': int(seed),
        'steps': int(steps),
        'tol': float(tol),
        'lr': float(lr),
        'architecture': _repro_probe_arch(arch),
        'seq_len': int(seq_len),
        'batch_size': int(batch_size),
        'vocab': int(vocab),
        'mlp_ratio': (None if mlp_ratio is None else float(mlp_ratio)),
        'data_source': ('train_ids' if train_ids is not None else 'synthetic'),
        'data_fp': (None if data_fp is None else str(data_fp)),
        'device': str(DEVICE if device is None else device),
        'determinism': determinism_label(),
        'code': code_stamp(),
    }

def _repro_probe_digest(cfg):
    blob = json.dumps(cfg, sort_keys=True, separators=(',', ':'), ensure_ascii=True)
    return hashlib.sha256(blob.encode('utf-8')).hexdigest()[:16]

def reproducibility_check(variant='full', *, seed=0, steps=3, tol=1e-06, device=None, arch=None, train_ids=None, vocab=None, mlp_ratio=None, seq_len=None, batch_size=2, lr=0.003):
    """Two identical short runs + one different-seed run, compared.

    This is the automated version of "same seed, same result on this box":
    the same seed must reproduce the complete short loss curve (exactly on
    CPU; within ``tol`` on a GPU whose kernels are not bitwise deterministic),
    while a different seed must actually change it.  `arch`/`train_ids` let a
    scale panel repeat its REAL architecture on a small fixed slice of the REAL
    corpus rather than a tiny synthetic proxy.  The report is persisted with
    the panel, so a reproducibility problem is visible instead of being an
    assumption.  The check never changes the RNG state of the following
    training cell."""
    device = DEVICE if device is None else (device if isinstance(device, torch.device) else torch.device(device))
    seed = _seed_value(seed)
    _steps = _exact_count(steps, minimum=1)
    if _steps is None:
        raise ValueError(f'reproducibility_check: steps must be a positive integer, got {steps!r}')
    steps = int(_steps)
    _bs = _exact_count(batch_size, minimum=1)
    if _bs is None:
        raise ValueError(f'reproducibility_check: batch_size must be a positive integer, got {batch_size!r}')
    batch_size = int(_bs)
    try:
        _lr = float(lr)
        _tol = float(tol)
    except (TypeError, ValueError, OverflowError):
        raise ValueError(f'reproducibility_check: lr/tol must be finite numbers, got lr={lr!r} tol={tol!r}') from None
    if not math.isfinite(_lr) or not math.isfinite(_tol) or _tol < 0:
        raise ValueError(f'reproducibility_check: lr/tol must be finite (tol >= 0), got lr={lr!r} tol={tol!r}')
    lr, tol = _lr, _tol
    _arch = _repro_probe_arch(arch)
    if vocab is None:
        vocab = (int(np.max(train_ids)) + 1) if train_ids is not None else 64
    if seq_len is None:
        seq_len = 16
    _seq = _exact_count(seq_len, minimum=1)
    if _seq is None:
        raise ValueError(f'reproducibility_check: seq_len must be a positive integer, got {seq_len!r}')
    seq_len = int(_seq)
    # Resolve the data identity once, using the SAME generator the losses use.
    _x, _y, _data_fp, _src = _repro_batch(seed, batch_size=batch_size, seq_len=seq_len, vocab=vocab, train_ids=train_ids)
    _fp_before = rng_fingerprint()
    _kw = dict(steps=steps, d=_arch['d'], n_layers=_arch['n_layers'], n_heads=_arch['n_heads'], d_head=_arch['d_head'], seq_len=seq_len, batch_size=batch_size, vocab=int(vocab), lr=lr, train_ids=train_ids, mlp_ratio=mlp_ratio, device=device)
    with _preserve_rng_state():
        a = _repro_tiny_losses(variant, seed, **_kw)
        b = _repro_tiny_losses(variant, seed, **_kw)
        c = _repro_tiny_losses(variant, _other_seed(seed), **_kw)
    _fp_after = rng_fingerprint()
    _rng_preserved = bool(_fp_before == _fp_after)
    _n = min(len(a), len(b))
    max_diff = max((abs(a[i] - b[i]) for i in range(_n)), default=float('inf'))
    different_seed_diff = max((abs(a[i] - c[i]) for i in range(min(len(a), len(c)))), default=0.0)
    finite = all(math.isfinite(v) for v in a + b + c)
    bitwise = bool(a == b)
    passed = bool(finite and max_diff <= float(tol) and different_seed_diff > 0.0
                  and _rng_preserved)
    r = {
        'kind': 'duplicate_run_reproducibility',
        'variant': variant,
        'seed': int(seed),
        'code': code_stamp(),
        'steps': int(steps),
        'tol': float(tol),
        'lr': float(lr),
        'device': str(device),
        'determinism': determinism_label(),
        'architecture': _arch,
        'mlp_ratio': (None if mlp_ratio is None else float(mlp_ratio)),
        'seq_len': int(seq_len),
        'batch_size': int(batch_size),
        'data_source': _src,
        'data_fp': _data_fp,
        'same_seed_losses_a': a,
        'same_seed_losses_b': b,
        'different_seed_losses': c,
        'max_abs_diff_same_seed': float(max_diff),
        'bitwise_identical': bitwise,
        'different_seed_changes_curve': bool(different_seed_diff > 0.0),
        'different_seed_max_abs_diff': float(different_seed_diff),
        'all_finite': bool(finite),
        'rng_fp_before': _fp_before,
        'rng_fp_after': _fp_after,
        'rng_state_preserved': _rng_preserved,
        'passed': passed,
    }
    if not passed:
        if not finite:
            r['diagnosis'] = 'non-finite loss in a tiny seeded run'
        elif max_diff > float(tol):
            r['diagnosis'] = 'same seed did not reproduce the short loss curve on this machine/stack'
        elif not _rng_preserved:
            r['diagnosis'] = 'the reproducibility probe did not restore the process RNG state'
        else:
            r['diagnosis'] = 'a different seed produced the identical loss curve (seed is not wired into the run)'
    else:
        r['diagnosis'] = 'ok'
    return r

def _repro_guard_base(*, seed=0, steps=3, tol=1e-06, arch=None, vocab=None, mlp_ratio=None, seq_len=None, batch_size=2, train_ids=None, data_fp=None, lr=0.003, device=None):
    """Exact cache key shared by the guard and run()'s evidence recovery.

    Strictly a description of the probe that produced a PASS: changing the
    tolerance, step count, architecture, MLP width, sequence length, vocab,
    device, determinism level, data stream or code invalidates the cached
    certificate.  A pass under a loose tolerance must never be reused for a
    stricter request."""
    _fp = data_fp
    if _fp is None and train_ids is not None:
        _arr = np.asarray(train_ids)
        _fp = _ids_fp(_arr if _arr.ndim == 1 else np.ascontiguousarray(_arr).reshape(-1))
    return _repro_probe_digest(_repro_probe_config(seed=seed, steps=steps, tol=tol, arch=arch, seq_len=(16 if seq_len is None else seq_len), batch_size=batch_size, vocab=(64 if vocab is None else vocab), mlp_ratio=mlp_ratio, data_fp=_fp, train_ids=train_ids, lr=lr, device=device))

def reproducibility_guard(variants, *, seed=0, steps=3, tol=1e-06, force=False, arch=None, train_ids=None, vocab=None, mlp_ratio=None, seq_len=None, batch_size=2, seeds=None, strict=None, lr=0.003, device=None):
    """Run ``reproducibility_check`` once per (variant, seed, probe config) per process.

    Mirrors ``overfit_guard``: results are cached as evidence, a skip env var
    is explicit and loud, and a failure is a warning unless the caller sets
    ``CSA_REQUIRE_REPRO=1`` (or passes ``strict=True``).  The cache key
    includes the full probe configuration -- tolerance, code stamp, seed,
    device, architecture, MLP width, sequence length, vocabulary and data
    fingerprint -- so a loose/synthetic probe cannot certify a real one.
    ``seeds`` lets a panel check its first and last seed; ``arch`` and
    ``train_ids`` make it exercise the real architecture on a small slice of
    the real corpus.  Returns the reports that ran in this call."""
    if os.environ.get('CSA_SKIP_REPRO', '').strip().lower() in ('1', 'true', 'yes', 'on'):
        print('[repro] guard SKIPPED (CSA_SKIP_REPRO is set) — this run has no same-machine seed check')
        return []
    _want_strict = (os.environ.get('CSA_REQUIRE_REPRO', '').strip().lower() in ('1', 'true', 'yes', 'on')) if strict is None else bool(strict)
    _device = DEVICE if device is None else device
    _arch = _repro_probe_arch(arch)
    if vocab is None:
        vocab = (int(np.max(train_ids)) + 1) if train_ids is not None else 64
    if seq_len is None:
        seq_len = 16
    _raw_seeds = list(seeds if seeds is not None else [seed])
    _parsed_seeds = []
    for _raw in _raw_seeds:
        try:
            _parsed_seeds.append(_seed_value(_raw))
        except ValueError as _se:
            raise ValueError(f'reproducibility_guard seeds must be integers in [0, {MAX_SEED}], got {_raw_seeds!r}') from _se
    _seed_list = list(dict.fromkeys(_parsed_seeds))
    _full_data_fp = None
    if train_ids is not None:
        _arr = np.asarray(train_ids)
        _full_data_fp = _ids_fp(_arr if _arr.ndim == 1 else np.ascontiguousarray(_arr).reshape(-1))
    _base_cache = {}

    def _base_for(v, sd):
        key = (v, sd)
        if key not in _base_cache:
            _base_cache[key] = _repro_guard_base(seed=sd, steps=steps, tol=tol, arch=_arch, vocab=vocab, mlp_ratio=_overfit_ratio_for(mlp_ratio, v), seq_len=seq_len, batch_size=batch_size, train_ids=train_ids, data_fp=_full_data_fp, lr=lr, device=_device)
        return _base_cache[key]

    # As in overfit_guard, a cached FAILURE is not a certificate: retry it so a
    # later phase cannot silently inherit the failed status as "already done".
    todo = [(v, sd) for v in variants for sd in _seed_list if force or _REPRO_GUARD.get((v, _base_for(v, sd))) is not True]
    reports = []
    for v, sd in todo:
        r = reproducibility_check(v, seed=sd, steps=steps, tol=tol, arch=_arch, train_ids=train_ids, vocab=vocab, mlp_ratio=_overfit_ratio_for(mlp_ratio, v), seq_len=seq_len, batch_size=batch_size, lr=lr, device=_device)
        _base = _base_for(v, sd)
        r['guard_probe_key'] = _base
        r['guard_probe_config'] = _repro_probe_config(seed=sd, steps=steps, tol=tol, arch=_arch, seq_len=seq_len, batch_size=batch_size, vocab=vocab, mlp_ratio=_overfit_ratio_for(mlp_ratio, v), data_fp=r.get('data_fp'), train_ids=train_ids, lr=lr, device=_device)
        key = (v, _base)
        _REPRO_GUARD[key] = bool(r['passed'])
        _REPRO_REPORTS[key] = r
        reports.append(r)
        print(f"[repro] {v:<24} seed={sd} same-seed max|Δ|={r['max_abs_diff_same_seed']:.3e}  different-seed Δ={r['different_seed_max_abs_diff']:.3e}  bitwise={r['bitwise_identical']}  {'PASS' if r['passed'] else 'FAIL'}")
        if not r['passed']:
            _msg = f"same-machine reproducibility check FAILED for `{v}` seed={sd} ({r['diagnosis']})"
            if _want_strict:
                raise RuntimeError(_msg + ' — strict reproducibility is required for this run. Correct the seed/kernel nondeterminism or explicitly opt out (CSA_REQUIRE_REPRO=0).')
            print(f'[repro] WARNING: {_msg}; the panel will record the failure (set CSA_REQUIRE_REPRO=1 to make it fatal, CSA_SKIP_REPRO=1 to skip)')
    return reports

def reproducibility_reports_for(variants, *, probe_key=None, data_fp=None):
    """Exact-match recovery of reproducibility evidence for the current panel."""
    _want = set(variants)
    out = []
    for _k, _r in _REPRO_REPORTS.items():
        if _k[0] not in _want:
            continue
        if probe_key is not None and _k[1] != probe_key:
            continue
        if data_fp is not None and _r.get('data_fp') != data_fp:
            continue
        out.append(dict(_r))
    return out

def reproducibility_reports():
    """Copy of the reproducibility reports gathered in this process."""
    return {k: dict(v) for k, v in _REPRO_REPORTS.items()}

class TimeGuard:
    BASE = (256, 6, 512, 12)

    def __init__(self, cap):
        self.total_hours = float(cap['total_hours'])
        self.margin = float(cap.get('margin', 0.93))
        self.already = float(cap.get('already_hours', 0.0))
        self.state_path = cap.get('state_path', 'run_time_state.json')
        # 内核模式使用独立的状态文件：两档速率标定不可互相污染（同一
        # state 文件会把 eager 的 sps 标定用于内核单元）。
        # 幂等：cap_spec() 导出的就是已盖章路径，par.py 子进程按它重建
        # TimeGuard 时不得再加一次后缀。
        if _kernel_stamp() and not self.state_path.endswith('.k'):
            self.state_path = self.state_path + '.k'
        self.state = self._load_state()

    def _load_state(self):
        st = {'booked_seconds': 0.0, 'norm_sps': None, 'sps_by_class': {}, 'runs': 0}
        if os.path.exists(self.state_path):
            try:
                with open(self.state_path, encoding='utf-8') as f:
                    st.update(json.load(f))
            except Exception as e:
                print(f'[cap] FATAL: {self.state_path} exists but cannot be parsed ({type(e).__name__}: {e}).  Refusing to start with a silently RESET state (booked time would read as 0) — move it aside to start fresh.')
                raise
        return st

    def _save(self):
        atomic_write_json(self.state_path, self.state)

    def cap_spec(self):
        """Plain-dict spec of this guard, enough for a child process (par.py)
        to rebuild an equivalent TimeGuard against the same shared state file."""
        return dict(total_hours=self.total_hours, margin=self.margin, already_hours=self.already, state_path=self.state_path)

    @staticmethod
    def _class_key(d, n_layers, seq_len, batch_size, variant=None):
        """Calibration key for one (geometry, variant) class.

        Geometry alone is too coarse on the B-tier ladder: a dense full-attention
        arm and a sparse CSA arm with the same shapes can differ by a large
        factor, so one shared rate would systematically under- or over-book
        cells.  `variant=None` keeps the historical geometry-only key used by
        the v7-v12 drivers, so existing state files stay valid."""
        base = str((int(d), int(n_layers), int(seq_len), int(batch_size)))
        return base if variant is None else f'{base}|{variant}'

    def book(self, seconds, token=None):
        """Reserve (seconds > 0) or refund (seconds < 0) projected run time
        against the shared state WITHOUT touching the run counter or the
        calibration.  Parallel cell workers pre-book their estimate before
        training and refund it after recording the actual seconds, so the
        booked total always converges to the true sum while concurrently
        launching children still see the shared headroom shrink.

        With `token`, the reservation is recorded per-booking (with the
        booking process pid) so `reconcile()` can refund reservations whose
        process died before refunding (killed child / instance shutdown) —
        without this, a killed parallel cell starves every later phase with
        a phantom reservation."""
        try:
            import fcntl
        except ImportError:
            fcntl = None
        _lock_f = None
        if fcntl is not None:
            _lock_f = open(self.state_path + '.lock', 'a')
            fcntl.flock(_lock_f, fcntl.LOCK_EX)
        try:
            self.state = self._load_state()
            if token is None:
                self.state['booked_seconds'] += float(seconds)
                if 'bookings' in self.state:
                    self.state['booked_untracked'] = float(self.state.get('booked_untracked', 0.0)) + float(seconds)
            else:
                bookings = self.state.setdefault('bookings', {})
                if 'booked_untracked' not in self.state:
                    # First tokenised booking coexisting with a pre-bookings
                    # state (e.g. the parent's data-load record_run, or any
                    # serial phase that ran before this parallel one): every
                    # second booked so far has no per-token representation,
                    # so it ALL becomes the untracked remainder.  Defaulting
                    # it to 0 would erase those seconds from the
                    # booked total on the next refund's recompute — the cap
                    # would then never fill in parallel mode.
                    self.state['booked_untracked'] = max(0.0, float(self.state.get('booked_seconds', 0.0)) - sum(float(b.get('seconds', 0.0)) for b in bookings.values()))
                if seconds > 0:
                    bookings[str(token)] = {'seconds': float(seconds), 'pid': int(os.getpid()), 'ts': time.time()}
                else:
                    bookings.pop(str(token), None)
                legacy = float(self.state['booked_untracked'])
                self.state['booked_seconds'] = legacy + sum(float(b.get('seconds', 0.0)) for b in bookings.values())
            self._save()
        finally:
            if _lock_f is not None:
                try:
                    fcntl.flock(_lock_f, fcntl.LOCK_UN)
                finally:
                    _lock_f.close()

    @staticmethod
    def _pid_alive(pid):
        try:
            os.kill(int(pid), 0)
            return True
        except ProcessLookupError:
            return False
        except PermissionError:
            return True
        except (OSError, AttributeError):
            return True  # 无法判定（非 posix 等）时按存活处理，绝不误退

    def reconcile(self):
        """Refund per-token bookings whose recording process is no longer
        alive (crash/kill recovery).  Old state files without a `bookings`
        map are untouched: their `booked_seconds` is preserved as
        `booked_untracked` once any tokenised booking coexists."""
        try:
            import fcntl
        except ImportError:
            fcntl = None
        _lock_f = None
        if fcntl is not None:
            _lock_f = open(self.state_path + '.lock', 'a')
            fcntl.flock(_lock_f, fcntl.LOCK_EX)
        try:
            self.state = self._load_state()
            bookings = self.state.get('bookings') or {}
            if not bookings:
                return 0.0
            total = float(self.state.get('booked_seconds', 0.0))
            tracked = sum(float(b.get('seconds', 0.0)) for b in bookings.values())
            self.state['booked_untracked'] = max(0.0, total - tracked)
            refunded = 0.0
            now = time.time()
            for tok in sorted(bookings):
                b = bookings[tok]
                est_s = float(b.get('seconds', 0.0))
                dead = not self._pid_alive(b.get('pid', -1))
                # A live child can hold a booking for at most its dispatcher
                # watchdog horizon (par.py SIGKILLs run/warm/lenphase cells at
                # max(3*est, est+1h); every other kind is capped at 12 h).  A
                # booking older than that CANNOT have a live owner: the pid
                # reading is a reuse artifact (an instance reboot recycles
                # pids — this driver's own auto-shutdown makes that the common
                # case), and without an age fallback the phantom reservation
                # would starve every later cell behind the cap forever.
                horizon = max(4.0 * est_s, 13.0 * 3600.0)
                too_old = b.get('ts') is not None and (now - float(b['ts'])) > horizon
                if dead or too_old:
                    refunded += est_s
                    bookings.pop(tok, None)
                    _why = 'dead pid' if dead else f'phantom: age {(now - float(b["ts"])) / 3600:.1f} h exceeds the watchdog horizon {horizon / 3600:.1f} h'
                    print(f'[cap] reconcile: refunded {est_s / 3600:.2f} h from booking {tok} ({_why}, pid {b.get("pid")})')
            self.state['booked_seconds'] = self.state['booked_untracked'] + sum(float(b['seconds']) for b in bookings.values())
            self._save()
            return refunded
        finally:
            if _lock_f is not None:
                try:
                    fcntl.flock(_lock_f, fcntl.LOCK_UN)
                finally:
                    _lock_f.close()

    def spent_hours(self):
        self.state = self._load_state()
        return self.already + self.state['booked_seconds'] / 3600.0

    def remaining_hours(self):
        return self.total_hours - self.spent_hours()

    def cap_hours(self):
        return self.total_hours * self.margin

    def record_run(self, seconds, steps_done, d, n_layers, seq_len, batch_size, calib_seconds=None, variant=None):
        try:
            import fcntl
        except ImportError:
            fcntl = None
        _lock_f = None
        if fcntl is not None:
            _lock_f = open(self.state_path + '.lock', 'a')
            fcntl.flock(_lock_f, fcntl.LOCK_EX)
        try:
            self.state = self._load_state()
            self.state['booked_seconds'] += float(seconds)
            if 'bookings' in self.state:
                # Keep the invariant booked_seconds == booked_untracked + Σ
                # bookings: recorded actual seconds have no per-token
                # representation, so they accrue to the untracked remainder.
                # Without this the next token refund's recompute silently
                # drops every recorded second from the booked total (the run
                # -time cap then meters nothing in parallel mode).
                self.state['booked_untracked'] = float(self.state.get('booked_untracked', 0.0)) + float(seconds)
            if steps_done and steps_done > 0:
                self.state['runs'] += 1
                if calib_seconds is None or not calib_seconds > 0:
                    calib_seconds = seconds
                f = self._wallclock_factor(d, n_layers, seq_len, batch_size)
                sps = calib_seconds / steps_done
                norm = sps / f
                prev = self.state.get('norm_sps')
                self.state['norm_sps'] = norm if prev is None else 0.7 * prev + 0.3 * norm
                by_class = self.state.setdefault('sps_by_class', {})
                key = self._class_key(d, n_layers, seq_len, batch_size, variant)
                cprev = by_class.get(key)
                by_class[key] = sps if cprev is None else 0.7 * cprev + 0.3 * sps
            self._save()
        finally:
            if _lock_f is not None:
                try:
                    fcntl.flock(_lock_f, fcntl.LOCK_UN)
                finally:
                    _lock_f.close()

    @classmethod
    def _depth_factor(cls, n_layers):
        return n_layers / 6.0

    @classmethod
    def _compute_factor(cls, d, n_layers, seq_len, batch_size):
        return (d / 256.0) ** 2 * cls._depth_factor(n_layers) * (seq_len / 512.0) ** 1.5 * (batch_size / 12.0)

    @classmethod
    def _calib_exponent(cls):
        return 1.75

    @classmethod
    def _wallclock_factor(cls, d, n_layers, seq_len, batch_size):
        f = cls._compute_factor(d, n_layers, seq_len, batch_size)
        df = cls._depth_factor(n_layers)
        return f / df * df ** cls._calib_exponent()

    def estimate_seconds(self, steps, d=256, n_layers=6, seq_len=512, batch_size=12, variant=None):
        by_class = self.state.get('sps_by_class') or {}
        key = self._class_key(d, n_layers, seq_len, batch_size, variant)
        exact = by_class.get(key)
        if exact is None and variant is not None:
            exact = by_class.get(self._class_key(d, n_layers, seq_len, batch_size, None))
        if exact is not None:
            return steps * exact * 1.15
        norm = self.state.get('norm_sps')
        if norm is None:
            norm = 0.35
        f = self._wallclock_factor(d, n_layers, seq_len, batch_size)
        return steps * norm * f * 1.15

    def note_watchdog_kill(self, elapsed_seconds, steps, d=256, n_layers=6, seq_len=512, batch_size=12, variant=None):
        """Lift the calibrated per-step floor after a dispatcher-watchdog kill
        (par.py).  A cell killed at `elapsed_seconds` demonstrably needs MORE
        than that for `steps` steps, so its true sps exceeds
        elapsed/steps — yet a killed cell never records a run, so without
        this hook the calibration (and hence the watchdog bound
        max(3*est, est+1h) derived from it) would stay wrong and the same
        healthy cell would be killed at the same wall-clock point on every
        resume (uncalibrated hardware, CPU workers).  Lifting the floor
        to the kill time itself makes the next bound ~3.45x larger, so the
        retry window grows geometrically until a healthy cell fits; a truly
        hung cell is still killed on every attempt, just later."""
        if not steps or int(steps) <= 0 or not float(elapsed_seconds) > 0:
            return
        floor = float(elapsed_seconds) / int(steps)
        try:
            import fcntl
        except ImportError:
            fcntl = None
        _lock_f = None
        if fcntl is not None:
            _lock_f = open(self.state_path + '.lock', 'a')
            fcntl.flock(_lock_f, fcntl.LOCK_EX)
        try:
            self.state = self._load_state()
            by_class = self.state.setdefault('sps_by_class', {})
            key = self._class_key(d, n_layers, seq_len, batch_size, variant)
            prev = by_class.get(key)
            if prev is None or floor > float(prev):
                by_class[key] = floor
            f = self._wallclock_factor(d, n_layers, seq_len, batch_size)
            norm_floor = floor / f
            norm = self.state.get('norm_sps')
            if norm is None or norm_floor > float(norm):
                self.state['norm_sps'] = norm_floor
            self._save()
        finally:
            if _lock_f is not None:
                try:
                    fcntl.flock(_lock_f, fcntl.LOCK_UN)
                finally:
                    _lock_f.close()
        print(f'[cap] watchdog kill noted: the pace floor for (d={d}, L={n_layers}, seq={seq_len}, bs={batch_size}) is now >= {floor:.3f} s/step so the next attempt gets a wider watchdog bound')

    def can_start(self, est_seconds):
        projected = self.spent_hours() + est_seconds / 3600.0
        return projected <= self.cap_hours()

    def deadline_ts(self):
        headroom = max(self.cap_hours() - self.spent_hours(), 0.0)
        return time.time() + headroom * 3600.0

    def report(self):
        self.state = self._load_state()
        print('\n==================== usage report ====================')
        print(f'  booked GPU time : {self.state['booked_seconds'] / 3600:.2f} h ({self.state.get('runs', 0)} runs)')
        for key, sps in sorted((self.state.get('sps_by_class') or {}).items()):
            print(f'  calibrated rate : {sps:.3f} s/step  (d, L, seq, batch = {key})')
        if self.state.get('norm_sps'):
            print(f'  normalised rate : {self.state['norm_sps']:.3f} s/step (base class d=256 / 6L / seq512 / batch12)')
        print('======================================================')
PARAM_MATCHED = {'full_matched', 'full_sw128_matched'}
PARAM_MATCHED_V7 = {'full_rope', 'full_sw128_matched_rope'}

_MLP_RATIO_MEMO = {}

def variant_mlp_ratio(variant, vocab, *, d=256, n_layers=6, n_heads=8, d_head=32, seq_len=512, matched=None, ref_variant='csa_dynamic'):
    if matched is None:
        matched = PARAM_MATCHED
    if variant not in matched:
        return 4.0
    # The ratio is a pure function of these arguments (the parameter count
    # of a freshly-initialised SmallGPT depends only on shapes; the build
    # runs under torch.random.fork_rng, so skipping a repeat build leaves
    # the caller's RNG stream untouched either way) — memoise it on the
    # full argument tuple.
    _mkey = (variant, int(vocab), int(d), int(n_layers), int(n_heads), int(d_head), int(seq_len), tuple(sorted((str(_x) for _x in matched))), str(ref_variant))
    _hit = _MLP_RATIO_MEMO.get(_mkey)
    if _hit is not None:
        return _hit

    def n_params(v, ratio):
        with torch.random.fork_rng():
            cfgs = make_layer_cfgs(n_layers, v)
            m = SmallGPT(vocab, d, n_layers, n_heads, d_head, seq_len, cfgs, mlp_ratio=ratio)
            n = count_params(m)
            del m
        return n
    p_full = n_params(variant, 4)
    p_ref = n_params(ref_variant, 4)
    ratio = 4 + (p_ref - p_full) / (2.0 * d * d * n_layers)
    if ratio == 4.0:
        ratio = math.nextafter(4.0, 0.0)
    if ratio <= 1.0:
        raise RuntimeError(f'[{variant}] param-matched mlp_ratio would be {ratio:.2f} (<= 1): the reference arm {ref_variant} already has fewer/equal params — param matching is impossible for this variant/config')
    print(f'[{variant}] matched mlp_ratio = {ratio:.2f} ({p_full / 1000000.0:.2f}M -> target {p_ref / 1000000.0:.2f}M params vs {ref_variant})')
    _MLP_RATIO_MEMO[_mkey] = ratio
    return ratio

def _tag_of(rec):
    if isinstance(rec, dict) and 'protocol' in rec and (rec['protocol'] is not None):
        return str(rec['protocol'])
    if isinstance(rec, dict) and rec.get('warm_steps') is not None:
        return f'w{rec['warm_steps']}'
    return ''

def legacy_warm_tags(summary):
    _legacy = {}
    for key, rec in summary.items():
        if not isinstance(rec, dict) or 'seed' not in rec or 'ppl' not in rec:
            continue
        if not ppl_is_usable(rec.get('ppl')) or rec.get('synthesized'):
            continue
        if 'protocol' in rec and rec['protocol'] is not None or rec.get('warm_steps') is not None:
            continue
        m = _WARM_KEY_RE.match(str(key))
        _var = rec.get('variant')
        if _var is None:
            _var = str(key).split('::', 1)[0]
        _legacy.setdefault(str(_var), set()).add(m.group(1) if m else None)
    return {v: frozenset(tags) for v, tags in _legacy.items() if None not in tags}

def record_tag(rec, key, legacy_ok):
    if 'protocol' in rec and rec['protocol'] is not None or rec.get('warm_steps') is not None:
        return _tag_of(rec)
    m = _WARM_KEY_RE.match(str(key))
    if not m:
        return ''
    ok = legacy_ok
    if isinstance(ok, dict):
        _var = rec.get('variant')
        if _var is None:
            _var = str(key).split('::', 1)[0]
        ok = ok.get(str(_var))
        if ok is None:
            return ''
    if m.group(1) in ok:
        return f'w{m.group(1)}'
    return ''

def _group_params(recs):
    for r in recs:
        v = _as_seed_int(r.get('params'))
        if v is not None and v > 0:
            return v
    return None

def _pooled_ppl_from_records(recs, *, estimand=None):
    """Token-pooled PPL: exp(sum NLL / sum N tokens) over all seeds.

    This is the desired estimator; the arithmetic mean of per-seed
    PPLs is kept as `ppl_mean_arithmetic` for backward compatibility but is no
    longer the primary aggregate when token counts exist.  Records that predate
    `nll_sum`/`n_tokens` cannot be pooled and fall back explicitly.

    ``estimand`` defaults to each record's own declaration.  A group that mixes
    nested-holdout and full-validation records has no single estimand: pooling
    would sum NLLs from two different samples and then label the result as one
    of them, so it returns ``(None, None, None)``.  A caller that deliberately
    falls the whole group back to full validation passes ``estimand=False``.
    """
    recs = list(recs)
    declared = {r.get('ppl_estimation_rows') == 'nested_validation_holdout'
                for r in recs if isinstance(r, dict)}
    if estimand is None:
        if len(declared) > 1:
            return None, None, None
        estimand = next(iter(declared)) if declared else False
    nlls, nts = [], []
    for r in recs:
        # When the primary estimate is the nested holdout, the matching
        # accounting is nll_sum_holdout/n_tokens_holdout.  A missing halfword
        # cannot fall back to the full-validation totals: the pooled value and
        # the record's primary PPL would then describe different samples.
        if bool(estimand) and r.get('ppl_estimation_rows') == 'nested_validation_holdout':
            nll = _finite_scalar(r.get('nll_sum_holdout'))
            nt = _exact_count(r.get('n_tokens_holdout'), minimum=1)
            if nll is None or nt is None:
                # Some writers persist only the holdout per-row arrays.  Their
                # totals describe the same sample and can recover the missing
                # accounting; the full-validation totals never can.
                _rn = r.get('nll_per_row_holdout')
                _rt = r.get('n_tokens_per_row_holdout')
                if (isinstance(_rn, list) and isinstance(_rt, list)
                        and _rn and len(_rn) == len(_rt)):
                    _vals = [_finite_scalar(v) for v in _rn]
                    _toks = [_exact_count(v, minimum=1) for v in _rt]
                    if (all(v is not None for v in _vals)
                            and all(v is not None for v in _toks)):
                        nll = float(sum(_vals))
                        nt = int(sum(_toks))
        else:
            nll = _finite_scalar(r.get('nll_sum'))
            nt = _exact_count(r.get('n_tokens'), minimum=1)
        if nll is None or nt is None:
            return None, None, None
        nlls.append(nll)
        nts.append(nt)
    total_n, total_t = float(sum(nlls)), float(sum(nts))
    if total_t <= 0:
        return None, None, None
    _pooled = _safe_exp_ppl(total_n / total_t)
    if _pooled is None or not math.isfinite(_pooled) or _pooled < 1.0:
        return None, None, None
    return _pooled, total_n, int(total_t)

def _record_primary_ppl(rec):
    """The per-seed PPL on the same rows as the record's primary aggregate.

    `_pooled_ppl_from_records` switches to the nested holdout accounting when
    `ppl_estimation_rows` says the estimate is a held-out-row one.  Any
    per-seed contrast must use the same number; reading `ppl` (full
    validation) next to a pooled holdout aggregate would mix two samples.
    Legacy records without a holdout marker keep `ppl`.

    A record that DECLARES the nested estimand but lacks every holdout
    accounting field is unverifiable and returns None.  Falling back to the
    full-validation `ppl` here would silently restore the selection rows that
    the nested split exists to remove.
    """
    if not isinstance(rec, dict):
        return None
    if rec.get('ppl_estimation_rows') == 'nested_validation_holdout':
        _h = _finite_scalar(rec.get('ppl_holdout'))
        if _h is not None:
            return _h if ppl_is_usable(_h) else None
        _nll = _finite_scalar(rec.get('nll_sum_holdout'))
        _nt = _exact_count(rec.get('n_tokens_holdout'), minimum=1)
        if _nll is not None and _nt is not None:
            _v = _safe_exp_ppl(_nll / _nt)
            return _v if ppl_is_usable(_v) else None
        _rn = rec.get('nll_per_row_holdout')
        _rt = rec.get('n_tokens_per_row_holdout')
        if (isinstance(_rn, list) and isinstance(_rt, list)
                and _rn and len(_rn) == len(_rt)):
            _vals = [_finite_scalar(v) for v in _rn]
            _toks = [_exact_count(v, minimum=1) for v in _rt]
            if (all(v is not None for v in _vals)
                    and all(v is not None for v in _toks)):
                _tot_t = int(sum(_toks))
                if _tot_t > 0:
                    _v = _safe_exp_ppl(float(sum(_vals)) / _tot_t)
                    return _v if ppl_is_usable(_v) else None
        return None
    _v = _finite_scalar(rec.get('ppl'))
    return _v if ppl_is_usable(_v) else None


def _paired_primary_delta(rec_a, rec_b):
    """(a − b) on the PRIMARY estimand, or None when either side is unmeasured.

    Every paired display/test in this module must use this helper rather than
    raw ``ppl``: a nested record's ``ppl`` is the full-validation value, which
    includes the rows that selected its hyper-parameters.

    The two records must also declare the SAME estimand.  Subtracting a
    full-validation PPL from a held-out-row PPL produces a number on neither
    sample, even though both individual values are finite.
    """
    _a_nested = rec_a.get('ppl_estimation_rows') == 'nested_validation_holdout'
    _b_nested = rec_b.get('ppl_estimation_rows') == 'nested_validation_holdout'
    if _a_nested != _b_nested:
        return None
    _a, _b = _record_primary_ppl(rec_a), _record_primary_ppl(rec_b)
    if _a is None or _b is None:
        return None
    return float(_a) - float(_b)


def _seed_t_ci(ppls, alpha=0.05):
    alpha = _validated_alpha(alpha, context='_seed_t_ci alpha')
    n = len(ppls)
    if n < 2:
        return None
    mu = float(np.mean(ppls))
    sd = float(np.std(ppls, ddof=1))
    try:
        tc = _t_critical(1.0 - alpha, n - 1)
    except Exception:
        return None
    half = tc * sd / math.sqrt(n)
    return [mu - half, mu + half]

def _primary_row_arrays(rec):
    """Per-row NLL/token arrays for the record's PRIMARY estimand.

    A nested record's reported PPL is the held-out-row estimate, so its
    intervals must bootstrap `nll_per_row_holdout`/`n_tokens_per_row_holdout`.
    Returning None when those are absent keeps a missing holdout accounting
    from silently falling back to the full-validation rows.
    """
    if not isinstance(rec, dict):
        return None
    if rec.get('ppl_estimation_rows') == 'nested_validation_holdout':
        nll = rec.get('nll_per_row_holdout')
        ntok = rec.get('n_tokens_per_row_holdout')
        if nll is None or ntok is None:
            return None
        return nll, ntok
    return rec.get('nll_per_row'), rec.get('n_tokens_per_row')


def _doc_bootstrap_ppl_ci(recs, *, n_boot=2000, seed=20261018):
    """Row-level bootstrap CI for the pooled PPL (legacy name kept).

    The historical name says "document", but the records it consumes expose
    only per-ROW NLL.  A fixed eval row is a window that can split or merge
    documents, so resampling rows preserves within-row correlation but is not
    a document bootstrap.  Use ``eval_length_gen(doc_ids=...)`` (which records
    `nll_per_doc` / `n_tokens_per_doc`) when the document-level estimand is
    required.  If any record lacks per-row NLL, no CI is invented — the caller
    must see the missing-evidence state rather than a narrow interval computed
    from the
    wrong unit.
    """
    recs = list(recs)
    _nested_flags = {r.get('ppl_estimation_rows') == 'nested_validation_holdout'
                     for r in recs if isinstance(r, dict)}
    if len(_nested_flags) > 1:
        # Bootstrap rows from two different evaluation samples are not one
        # document panel, even when their lengths happen to match.
        return None
    rows = []
    for r in recs:
        _arrays = _primary_row_arrays(r)
        if _arrays is None:
            return None
        nll, ntok = _arrays
        if not isinstance(nll, list) or not isinstance(ntok, list) or len(nll) != len(ntok) or not nll:
            return None
        _tok = [_exact_count(v) for v in ntok]
        if any(v is None for v in _tok):
            return None
        _nll = np.asarray(nll, dtype=float)
        if not np.isfinite(_nll).all():
            return None
        rows.append((_nll, np.asarray(_tok, dtype=np.int64)))
    if len({len(a) for a, _ in rows}) != 1:
        return None
    R = len(rows[0][0])
    if R == 0:
        return None
    nll_mat = np.stack([a for a, _ in rows], axis=0)          # [S, R]
    ntok_mat = np.stack([b for _, b in rows], axis=0)         # [S, R]
    rng = np.random.default_rng(int(seed))
    nll_col = nll_mat.sum(axis=0)
    ntok_col = ntok_mat.sum(axis=0)
    vals = np.empty(int(n_boot), dtype=float)
    # Multinomial bootstrap counts: a single [chunk, R] count matrix is reused
    # across draws.  Size the chunk so a very large document panel does not
    # allocate 256 * R counts at once.
    _chunk = _bootstrap_draw_chunk(R)
    _b = 0
    while _b < int(n_boot):
        _nb = min(_chunk, int(n_boot) - _b)
        counts = rng.multinomial(R, np.full(R, 1.0 / R, dtype=float), size=_nb)
        nt = counts @ ntok_col
        nn = counts @ nll_col
        ok = nt > 0
        out = np.full(_nb, np.nan, dtype=float)
        out[ok] = np.exp(nn[ok] / nt[ok])
        vals[_b:_b + _nb] = out
        _b += _nb
    vals = vals[np.isfinite(vals) & (vals > 0)]
    if vals.size < max(20, int(0.5 * n_boot)):
        return None
    lo, hi = np.percentile(vals, [2.5, 97.5])
    return [float(lo), float(hi)]

def _combined_seed_doc_ci(recs, *, n_boot=2000, seed=20261018, conf=0.95):
    """Two-level (seed x document) uncertainty disclosure for the pooled PPL.

    The seed-level interval (`ppl_ci95_seed_t`) answers "how much does
    TRAINING noise move the number"; the document bootstrap
    (`ppl_ci95_doc_bootstrap`) answers "how much does the EVALUATION SUBSET
    move it".  Neither alone bounds the reported pooled PPL, because both
    sources act at once — a small seed CI next to a wide doc CI is not a
    precise measurement.  This helper estimates both components on the
    log-PPL scale (PPL is multiplicative; the interval is exponentiated back
    at the end) and combines them as independent variance sources:

      se_seed  = std_s(log pooled_ppl_s, ddof=1) / sqrt(S)
      se_doc   = bootstrap SD of the log pooled PPL over document resamples
      se_combined = sqrt(se_seed^2 + se_doc^2)
      ci95     = exp(mean_s log pooled_ppl_s  +-  t_{S-1, conf} * se_combined)

    The component ratio is reported too: it says whether precision is bought
    by more seeds or by more evaluation documents, which is the actionable
    question a small-n panel faces.  This is a disclosed two-source
    approximation, not a fitted hierarchical random-effects model; when a
    component is unmeasurable (S<2, records without per-row NLL, or fewer
    than two scored documents) the status says so explicitly and the missing
    component is never silently treated as zero."""
    recs = list(recs)
    _nested_flags = {r.get('ppl_estimation_rows') == 'nested_validation_holdout'
                     for r in recs if isinstance(r, dict)}
    rows = []
    _mixed_estimands = len(_nested_flags) > 1
    for r in recs:
        _arrays = _primary_row_arrays(r)
        if _arrays is None:
            rows = None
            break
        nll, ntok = _arrays
        if not isinstance(nll, list) or not isinstance(ntok, list) or len(nll) != len(ntok) or not nll:
            rows = None
            break
        _tok = [_exact_count(v) for v in ntok]
        _nll = np.asarray(nll, dtype=float)
        if any(v is None for v in _tok) or not np.isfinite(_nll).all():
            rows = None
            break
        rows.append((_nll, np.asarray(_tok, dtype=np.int64)))
    if isinstance(rows, list):
        if len({len(a) for a, _ in rows}) != 1:
            rows = None
    if isinstance(rows, list):
        nll_mat = np.stack([a for a, _ in rows], axis=0)          # [S, R]
        ntok_mat = np.stack([b for _, b in rows], axis=0)          # [S, R]
        keep = ntok_mat.sum(axis=0) > 0
        n_dropped = int((~keep).sum())
        nll_mat = nll_mat[:, keep]
        ntok_mat = ntok_mat[:, keep]
        if not np.isfinite(nll_mat).all() or not np.isfinite(ntok_mat).all() or (ntok_mat < 0).any():
            rows = None
    out = {'status': 'unverifiable', 'n_seeds': len(recs), 'n_docs': None,
           'n_docs_dropped_zero_token': None,
           'se_seed_logppl': None, 'se_doc_logppl': None,
           'se_combined_logppl': None, 'ci95_ppl': None,
           'component_ratio_seed_over_doc': None, 'conf': None,
           'method': 'two-source variance combination on log-PPL (seed training noise x evaluation-document bootstrap); approximation, not a fitted hierarchical model'}
    if _mixed_estimands:
        out['reason'] = ('records mix nested-holdout and full-validation row '
                         'samples; the seed and document components would come '
                         'from two different evaluation sets')
        return out
    # Coverage, draw count and RNG seed identify the interval.  Never build a
    # 95% interval while echoing conf=True/1.0, and never let a fractional
    # n_boot silently become a different draw count.
    try:
        _conf = _validated_alpha(conf, context='_combined_seed_doc_ci conf')
    except ValueError as e:
        out['reason'] = str(e)
        return out
    _nb = _as_seed_int(n_boot)
    if _nb is None or _nb < 20:
        out['reason'] = (f'n_boot={n_boot!r} must be an integer >= 20 for a '
                         'percentile bootstrap')
        return out
    _seed = _as_seed_int(seed)
    if _seed is None:
        out['reason'] = f'seed={seed!r} is not an integer; draws are not reproducible'
        return out
    out['conf'] = float(_conf)
    S = len(recs)
    if S < 1:
        return out
    # Seed-level component: per-seed pooled PPL over the SAME doc set.
    seed_logppl = None
    if rows is not None:
        per_tok = nll_mat.sum(axis=1) / np.maximum(ntok_mat.sum(axis=1), 1e-30)
        # Cross-entropy is zero for a perfectly predicted token, so a zero
        # log-PPL is a valid measurement (PPL=1), not a missing component.
        ok = np.isfinite(per_tok) & (per_tok >= 0)
        if ok.sum() == S and S >= 2:
            # nll/tokens is already cross-entropy = log(PPL); do not log it a
            # second time or the reported interval is not a PPL interval.
            lp = per_tok
            seed_logppl = lp
            out['se_seed_logppl'] = float(lp.std(ddof=1) / math.sqrt(S))
            out['n_docs'] = int(nll_mat.shape[1])
            out['n_docs_dropped_zero_token'] = n_dropped
        elif ok.sum() == S:
            out['n_docs'] = int(nll_mat.shape[1])
            out['n_docs_dropped_zero_token'] = n_dropped
    # Doc-level component: bootstrap SD of log pooled PPL over doc resamples
    # (seed-pooled NLL/ntok columns, the same pooled estimator the doc CI
    # uses, taken on the log scale).
    if rows is not None and nll_mat.shape[1] >= 2:
        rng = np.random.default_rng(_seed)
        nll_col = nll_mat.sum(axis=0)
        ntok_col = ntok_mat.sum(axis=0)
        R = int(nll_mat.shape[1])
        draws = np.empty(int(_nb), dtype=float)
        _chunk = _bootstrap_draw_chunk(R)
        _b = 0
        while _b < int(_nb):
            _nb_draw = min(_chunk, int(_nb) - _b)
            counts = rng.multinomial(R, np.full(R, 1.0 / R, dtype=float), size=_nb_draw)
            nt = counts @ ntok_col
            nn = counts @ nll_col
            with np.errstate(divide='ignore', invalid='ignore'):
                # nn/nt is already the pooled log-PPL (CE) of the resample.
                lp_draw = np.where((nt > 0) & np.isfinite(nn), nn / np.maximum(nt, 1e-30), np.nan)
                lp_draw = np.where(np.isfinite(lp_draw) & (lp_draw >= 0), lp_draw, np.nan)
            draws[_b:_b + _nb_draw] = lp_draw
            _b += _nb_draw
        draws = draws[np.isfinite(draws)]
        if draws.size >= max(20, int(0.5 * _nb)):
            sd = float(draws.std(ddof=1))
            if sd < 1e-12:
                # Identical documents: the bootstrap SD is pure float noise.
                # Report the component as exactly zero so the ratio field is
                # not a 1e16 number that reads like a measurement.
                sd = 0.0
            out['se_doc_logppl'] = sd
            if out['n_docs'] is None:
                out['n_docs'] = R
                out['n_docs_dropped_zero_token'] = n_dropped
    if out['se_seed_logppl'] is None and out['se_doc_logppl'] is None:
        out['status'] = 'unverifiable'
        return out
    if out['se_seed_logppl'] is None:
        out['status'] = 'seed_component_unverifiable'
        return out
    if out['se_doc_logppl'] is None:
        out['status'] = 'doc_component_unverifiable'
        return out
    se_s = out['se_seed_logppl']
    se_d = out['se_doc_logppl']
    out['se_combined_logppl'] = float(math.sqrt(se_s * se_s + se_d * se_d))
    if se_d > 0:
        out['component_ratio_seed_over_doc'] = float(se_s / se_d)
    try:
        tc = _t_critical(float(_conf), S - 1)
    except Exception:
        tc = None
    if tc is not None and math.isfinite(tc):
        m = float(seed_logppl.mean())
        out['ci95_ppl'] = [float(_safe_exp_ppl(m - tc * out['se_combined_logppl'])),
                           float(_safe_exp_ppl(m + tc * out['se_combined_logppl']))]
        out['status'] = 'ok'
    else:
        out['status'] = 'ci_unavailable'
    return out

def paired_row_bootstrap_delta(pairs, *, n_boot=1000, seed=20261018, conf=0.95):
    """Evaluation-row bootstrap CI for a PAIRED token-weighted PPL difference.

    Seed-level tests answer "is the sign stable across training draws"; they do
    not quantify how much the fixed evaluation rows move the effect.  This
    helper resamples the SAME rows for both arms and every shared seed (paired
    by row), recomputes each arm's token-pooled PPL, and returns the percentile
    CI of mean_s(PPL_a - PPL_b).  It is an evaluation-sample interval only: the
    training-seed component is deliberately NOT bootstrapped here, so it must
    not be quoted as a total uncertainty interval and does not replace the
    exact sign-flip test.

    ``pairs`` is [(record_a, record_b), ...] for shared seeds.  Every record
    must expose per-row NLL and token counts for the SAME rows; nested holdout
    records must carry the holdout row arrays.  Missing/mismatched accounting
    returns an explicit ``unverifiable`` status rather than a narrow interval
    computed from a different sample.
    """
    pairs = list(pairs or [])
    out = {'status': 'unverifiable', 'n_pairs': len(pairs), 'n_rows': None,
           'n_boot': None, 'n_boot_valid': 0, 'mean_delta': None,
           'ci95_delta_ppl': None, 'conf': None,
           'method': 'paired evaluation-row bootstrap of mean_s(PPL_a - PPL_b); '
                     'row-level uncertainty only, not training-seed uncertainty'}
    # The interval's coverage and draw count are part of the measurement.
    # Silently substituting 95% when conf=True/1.5 was passed (while echoing
    # conf=1.0 in the output) would describe an interval that was never built.
    try:
        _conf = _validated_alpha(conf, context='paired_row_bootstrap_delta conf')
    except ValueError as e:
        out['reason'] = str(e)
        return out
    _nb = _as_seed_int(n_boot)
    if _nb is None or _nb < 20:
        out['reason'] = (f'n_boot={n_boot!r} must be an integer >= 20 for a '
                         'percentile bootstrap')
        return out
    _seed = _as_seed_int(seed)
    if _seed is None:
        out['reason'] = f'seed={seed!r} is not an integer; draws are not reproducible'
        return out
    out['n_boot'] = int(_nb)
    out['conf'] = float(_conf)

    def _arrays(rec):
        if not isinstance(rec, dict):
            return None
        nested = rec.get('ppl_estimation_rows') == 'nested_validation_holdout'
        nll = rec.get('nll_per_row_holdout') if nested else rec.get('nll_per_row')
        ntok = rec.get('n_tokens_per_row_holdout') if nested else rec.get('n_tokens_per_row')
        if nested and (nll is None or ntok is None):
            return None
        if not isinstance(nll, list) or not isinstance(ntok, list) or len(nll) != len(ntok) or not nll:
            return None
        _tok = [_exact_count(v) for v in ntok]
        if any(v is None for v in _tok):
            return None
        try:
            _nll = np.asarray(nll, dtype=float)
        except (TypeError, ValueError, OverflowError):
            return None
        if not np.isfinite(_nll).all():
            return None
        return _nll, np.asarray(_tok, dtype=np.int64)

    if not pairs:
        out['reason'] = 'no shared paired seeds'
        return out
    A, B = [], []
    _estimands = set()
    for a, b in pairs:
        _a, _b = _arrays(a), _arrays(b)
        if _a is None or _b is None:
            out['reason'] = 'a paired record lacks per-row NLL/token accounting for the estimand'
            return out
        _a_nested = (isinstance(a, dict)
                     and a.get('ppl_estimation_rows') == 'nested_validation_holdout')
        _b_nested = (isinstance(b, dict)
                     and b.get('ppl_estimation_rows') == 'nested_validation_holdout')
        if _a_nested != _b_nested:
            out['reason'] = ('the two arms of a pair declare different estimands '
                             '(nested holdout vs full validation); their row '
                             'intervals are not paired')
            return out
        _estimands.add(_a_nested)
        A.append(_a)
        B.append(_b)
    if len(_estimands) > 1:
        out['reason'] = ('the shared pairs mix nested-holdout and full-validation '
                         'estimands; the interval would average two different samples')
        return out
    R = len(A[0][0])
    if R < 2:
        out['reason'] = f'only {R} evaluation row(s); a row bootstrap needs at least 2'
        return out
    if any(len(x[0]) != R or len(y[0]) != R for x, y in zip(A, B)):
        out['reason'] = 'paired records score different row counts'
        return out
    nll_a = np.stack([x[0] for x in A], axis=0)       # [S, R]
    tok_a = np.stack([x[1] for x in A], axis=0)
    nll_b = np.stack([x[0] for x in B], axis=0)
    tok_b = np.stack([x[1] for x in B], axis=0)
    if (tok_a < 0).any() or (tok_b < 0).any():
        out['reason'] = 'negative per-row token count'
        return out
    # Point estimate on the full rows, equal weight per seed (the same
    # estimand the paired contrast uses).
    def _seed_ppls(nll, tok):
        _den = tok.sum(axis=1).astype(float)
        _ok = _den > 0
        _ppl = np.full(_den.shape, np.nan, dtype=float)
        _ppl[_ok] = np.exp(nll.sum(axis=1)[_ok] / _den[_ok])
        return _ppl
    _pa, _pb = _seed_ppls(nll_a, tok_a), _seed_ppls(nll_b, tok_b)
    _ok = np.isfinite(_pa) & np.isfinite(_pb)
    if not _ok.any():
        out['reason'] = 'no seed has a positive-token pooled PPL in both arms'
        return out
    out['n_rows'] = int(R)
    out['n_seeds_used'] = int(_ok.sum())
    out['mean_delta'] = float(np.mean(_pa[_ok] - _pb[_ok]))
    rng = np.random.default_rng(_seed)
    vals = np.full(int(_nb), np.nan, dtype=float)
    _chunk = _bootstrap_draw_chunk(R)
    _b = 0
    while _b < int(_nb):
        _nb_draw = min(_chunk, int(_nb) - _b)
        counts = rng.multinomial(R, np.full(R, 1.0 / R, dtype=float), size=_nb_draw)
        def _draw(nll, tok):
            nt = counts @ tok.T.astype(float)          # [nb, S]
            nn = counts @ nll.T                         # [nb, S]
            with np.errstate(divide='ignore', invalid='ignore'):
                ppl = np.exp(nn / np.where(nt > 0, nt, np.nan))
            return np.where(np.isfinite(ppl), ppl, np.nan)
        da = _draw(nll_a, tok_a)
        db = _draw(nll_b, tok_b)
        diff = da - db
        _valid = np.isfinite(diff)
        _cnt = _valid.sum(axis=1)
        _sum = np.where(_valid, diff, 0.0).sum(axis=1)
        vals[_b:_b + _nb_draw] = np.where(_cnt > 0, _sum / np.maximum(_cnt, 1), np.nan)
        _b += _nb_draw
    vals = vals[np.isfinite(vals)]
    out['n_boot_valid'] = int(vals.size)
    if vals.size < max(20, int(0.5 * int(_nb))):
        out['reason'] = 'too few finite bootstrap draws'
        return out
    _a = 1.0 - _conf
    lo, hi = np.percentile(vals, [100.0 * _a / 2.0, 100.0 * (1.0 - _a / 2.0)])
    out['ci95_delta_ppl'] = [float(lo), float(hi)]
    out['status'] = 'ok'
    out['note'] = ('paired rows keep the two arms on the same evaluation documents; '
                   'the interval covers row-sampling uncertainty only.  It is not a '
                   'substitute for the seed-level exact sign-flip p-value.')
    return out

def measurement_semantics_key(rec):
    """Identity of the code semantics that produced a measurement.

    `run_cfg` normally carries the code-stamp suffix, but legacy records may
    omit it (or predate the suffix).  Two records measured under different
    `_code` stamps are not two seeds of one experiment: preprocessing, the
    collectives' reduction order or a kernel path may differ.  Aggregation and
    arm summaries therefore key on this explicit value *in addition to*
    `run_cfg`; a missing stamp is its own `<unverified>` class rather than a
    wildcard that merges with a verified one.
    """
    if not isinstance(rec, dict):
        return '<unverified>'
    c = rec.get('_code')
    if c is None or str(c) == '':
        return '<unverified>'
    return str(c)


def aggregate(summary):

    def _protocol_tag(rec, key=None):
        if key is None:
            return _tag_of(rec)
        return record_tag(rec, key, _legacy_warm_ok)
    _legacy_warm_ok = legacy_warm_tags(summary)
    per_variant = {}
    for key, rec in summary.items():
        if not isinstance(rec, dict) or 'ppl' not in rec or 'seed' not in rec:
            continue
        if not ppl_is_usable(rec.get('ppl')) or rec.get('synthesized'):
            continue
        # A non-integer seed has no draw identity.  Counting it as an extra
        # seed would fabricate n (and pair it with no other reader).
        if _as_seed_int(rec.get('seed')) is None:
            print(f'[aggregate] WARNING: record {key!r} carries a non-integer seed ({rec.get("seed")!r}) — excluded from aggregation')
            continue
        v = rec.get('variant')
        if v is None:
            v = str(key).split('::', 1)[0]
        # A variant is the arm identity used as a dict key.  A malformed
        # non-string arm id (e.g. a JSON object) is unhashable and would crash
        # the whole aggregation; an invalid identity is no more usable than an
        # invalid seed, so exclude it explicitly instead of coercing it.
        if not isinstance(v, str) or not v:
            print(f'[aggregate] WARNING: record {key!r} carries a non-string/empty variant ({v!r}) — excluded from aggregation')
            continue
        per_variant.setdefault((v, _protocol_tag(rec, key)), []).append(rec)
    def _seed_key(s):
        # JSON round-trips can leave the same seed as 0 or "0"; the rest of the
        # readers normalise through `_as_seed_int`.  Keying dedup/pairing on the
        # raw value would count one seed twice and fabricate an extra n.
        n = _as_seed_int(s)
        return s if n is None else n
    _dups = {}
    for k, recs in per_variant.items():
        cnt = {}
        for r in recs:
            s = _seed_key(r['seed'])
            cnt[s] = cnt.get(s, 0) + 1
        bad = sorted((s for s, c in cnt.items() if c > 1))
        if bad:
            _dups[k] = bad
    if _dups:
        raise ValueError('aggregate: these (variant, protocol) groups hold more than one record for the same seed, so their PPL is ambiguous: ' + '; '.join((f'{v}/{t or '-'}->seeds {s}' for (v, t), s in sorted(_dups.items()))) + '. Remove the stale duplicates (or give the records distinct `protocol` tags) before aggregating.  A record whose value was never MEASURED (an `error` record, or a `synthesized` reconstruction) can carry no PPL and is IGNORED here — drop it from the summary instead of re-labelling it, because a protocol tag only silences this guard, it does not make the number real.')
    # A single (variant, protocol) group must be scored on ONE corpus and ONE
    # validation slice.  A mixed group would make ppl_pooled/dPPL meaningless;
    # refuse it here rather than letting a report average two different
    # evaluation sets that happen to share a run_cfg.
    _fp_conflicts = {}
    for (v, tag), recs in per_variant.items():
        # `eval_fp` is part of the paired identity too: same train/val but a
        # different fixed evaluation slice makes the pooled PPL a mixture of
        # two target sets (pair_reason already refuses such pairs).
        for _k in ('data_fp', 'val_fp', 'eval_fp', 'eval_subset_fp',
                   'holdout_row_fp'):
            _vals = sorted({str(r.get(_k)) for r in recs
                            if r.get(_k) is not None and str(r.get(_k)) != ''})
            if len(_vals) > 1:
                _fp_conflicts.setdefault((v, tag), {})[_k] = _vals
    if _fp_conflicts:
        raise ValueError('aggregate: these (variant, protocol) groups mix different corpus/evaluation fingerprints, so their PPL values are not comparable: '
                         + '; '.join(f'{v}/{t or '-'}: ' + ', '.join(f'{k}={[x[:12] + "…" for x in vals]}' for k, vals in sorted(d.items()))
                                     for (v, t), d in sorted(_fp_conflicts.items()))
                         + '. Report the fingerprint classes separately (they are different data/slices), do not pool them.')
    _multi = {}
    for (v, tag), recs in per_variant.items():
        _multi.setdefault(v, []).append(tag)
    _multi = {v: t for v, t in _multi.items() if len(t) > 1}
    if _multi:
        print('[aggregate] WARNING: these variants hold MULTIPLE protocol groups and are reported per-group, NOT pooled across groups (pooling would fake extra seeds): ' + ', '.join((f'{v}->{t}' for v, t in sorted(_multi.items()))))

    def _cfg_fp(rec):
        # Exact integer identity: int(1000.5) would collapse a different
        # capacity into the 1000-parameter group and pool two models as seeds.
        _p = _as_seed_int(rec.get('params'))
        if _p is not None and _p <= 0:
            _p = None
        return json.dumps([rec.get('run_cfg'), _p,
                           [rec.get(k) for k in PAIR_STEP_KEYS],
                           measurement_semantics_key(rec)],
                          sort_keys=True, default=str)

    def _steps_ok(recs):
        if len(recs) < 2:
            return True
        return len({_cfg_fp(r) for r in recs}) == 1

    def _by_seed(recs):
        out, dup = ({}, [])
        for r in recs:
            s = _seed_key(r['seed'])
            if s in out:
                dup.append(s)
            out[s] = r
        return (out, dup)

    def _paired(recs, base_recs):
        self_map, dup_a = _by_seed(recs)
        base_map, dup_b = _by_seed(base_recs)
        assert not dup_a and (not dup_b), (sorted(set(dup_a)), sorted(set(dup_b)))
        out, skipped = ([], [])
        for s, r in self_map.items():
            b = base_map.get(s)
            if b is None:
                continue
            reason = pair_reason(r, b)
            if reason is not None:
                skipped.append((s, reason))
                continue
            _delta = _paired_primary_delta(r, b)
            if _delta is None:
                skipped.append((s, 'primary estimand missing (nested record without holdout PPL/NLL accounting)'))
                continue
            out.append(_delta)
        return (out, skipped)
    agg = {}
    _split_groups = []
    _group_records = {}

    def _agg_key(v, tag, fp_idx=None):
        key = v if not tag else f'{v}#{tag}'
        return key if fp_idx is None else f'{key}@cfg{fp_idx}'
    for (v, tag), recs in per_variant.items():
        if _steps_ok(recs):
            _split_groups.append(((v, tag, None), recs))
            _group_records[v, tag, None] = recs
            continue
        _subs = {}
        for r in recs:
            _subs.setdefault(_cfg_fp(r), []).append(r)
        # the `@cfg` suffix is a digest of the config fingerprint itself, so a
        # resume pass cannot reshuffle which group a published key refers to
        _ordered = sorted(_subs.items(), key=lambda kv: kv[0])
        print(f'[aggregate] WARNING: `{_agg_key(v, tag)}` holds records from {len(_ordered)} different run_cfg/load/parameter-count/code-semantics configurations — pooling them would average incompatible runs (or two different MODEL WIDTHS or CODE STAMPS, which are not two seeds of one model) and fake extra seeds.  Reported per configuration instead.')
        for _fp, _rs in _ordered:
            _i = hashlib.sha1(_fp.encode('utf-8')).hexdigest()[:8]
            _split_groups.append(((v, tag, _i), _rs))
            _group_records[v, tag, _i] = _rs
    for (_v, _tag, _fp_idx), recs in _split_groups:
        v, tag = (_v, _tag)
        key = _agg_key(v, tag, _fp_idx)
        def _seed_sort_key(r):
            s = r.get('seed')
            if isinstance(s, (int, float)) and (not isinstance(s, bool)) and math.isfinite(float(s)):
                return (0, float(s), '')
            return (1, 0.0, str(s))
        _recs_sorted = sorted(recs, key=_seed_sort_key)
        recs = _recs_sorted
        # Every per-seed statistic must target the record's PRIMARY estimand.
        # For a nested record `ppl` is the full-validation value, which still
        # contains the rows used to select its hyper-parameters; the seed
        # mean/std/interval would then describe a different (leaky) sample
        # than `ppl_primary` and the paired dPPL column.
        _primary_vals = [_record_primary_ppl(r) for r in recs]
        _n_primary_missing = sum(v is None for v in _primary_vals)
        _nested_flags = {r.get('ppl_estimation_rows') == 'nested_validation_holdout'
                         for r in recs}
        _mixed_estimands = len(_nested_flags) > 1
        if _mixed_estimands:
            print(f'[aggregate] WARNING: {key}: the group mixes nested-holdout and '
                  'full-validation records — per-seed values and pooled NLL would come '
                  'from two different samples; the whole group falls back to '
                  'full-validation PPL and nested claims are NOT supported for it')
        if _n_primary_missing or _mixed_estimands:
            if _n_primary_missing and not _mixed_estimands:
                print(f'[aggregate] WARNING: {key}: {_n_primary_missing}/{len(recs)} record(s) declare the nested estimand but lack holdout accounting — the whole group falls back to full-validation PPL so the numbers stay on one sample; nested claims are NOT supported for this group')
            ppls = np.array([r['ppl'] for r in recs], dtype=float)
            _primary_estimand = 'full_validation_fallback'
            _pooled, _nll_total, _ntok_total = _pooled_ppl_from_records(
                recs, estimand=False)
        else:
            ppls = np.array(_primary_vals, dtype=float)
            _primary_estimand = (
                'nested_validation_holdout'
                if _nested_flags == {True}
                else 'full_validation')
            _pooled, _nll_total, _ntok_total = _pooled_ppl_from_records(recs)
        _sorted = np.sort(ppls)
        _med = float(np.median(_sorted))
        _q1, _q3 = (float(np.percentile(_sorted, 25)), float(np.percentile(_sorted, 75))) if len(_sorted) >= 2 else (_med, _med)
        entry = {'variant': v, 'protocol': tag, 'n_seeds': len(recs),
                 'ppl_mean': float(ppls.mean()),
                 'ppl_mean_arithmetic': float(ppls.mean()),
                 'ppl_std': float(ppls.std(ddof=1)) if len(ppls) > 1 else 0.0,
                 'ppls': [float(p) for p in ppls], 'seeds': [r.get('seed') for r in recs],
                 'ppl_primary_estimand': _primary_estimand,
                 'ppl_primary_missing': int(_n_primary_missing),
                 'params': _group_params(recs), 'tokens_seen': recs[0].get('tokens_seen'),
                 'ppl_median': _med, 'ppl_iqr': [_q1, _q3],
                 'ppl_ci95_seed_t': _seed_t_ci(ppls),
                 'nll_sum': _nll_total, 'n_tokens': _ntok_total,
                 'ppl_pooled': (_pooled if _pooled is not None else None),
                 'ppl_ci95_doc_bootstrap': _doc_bootstrap_ppl_ci(recs),
                 'ppl_ci_seed_doc_combined': _combined_seed_doc_ci(recs),
                 'ppl_aggregation': ('pooled_token_nll' if _pooled is not None else 'arithmetic_seed_mean_fallback (records lack nll_sum/n_tokens)'),
                 'ppl_primary': (float(_pooled) if _pooled is not None else float(ppls.mean()))}
        _pb = next((r.get('param_breakdown') for r in recs if isinstance(r.get('param_breakdown'), dict)), None)
        if _pb:
            entry['param_breakdown'] = _pb
            entry['params_total'] = _pb.get('total')
            entry['params_attention'] = _pb.get('attention')
            entry['params_mlp'] = _pb.get('mlp')
            entry['params_embedding'] = _pb.get('embedding')
            entry['active_params'] = _pb.get('active')
            entry['attention_param_share'] = _pb.get('attention_share')
        _kv = next((r.get('kv_cache_elements_per_token') for r in recs if isinstance(r.get('kv_cache_elements_per_token'), dict)), None)
        if _kv:
            entry['kv_cache_elements_per_token'] = _kv
        if _fp_idx is not None:
            entry['run_cfg_class'] = _fp_idx
            entry['run_cfg'] = recs[0].get('run_cfg')
        dyn_lens, all_lens, deltas = ([], [], [])
        bf1, bex = ([], [])
        # `bnd_rand` has two sampling definitions; their excesses are different
        # estimands and must not be averaged into one series.
        _bnd_rand_kinds = set()

        def _cell(layer, k):
            return _finite_scalar(layer.get(k))
        for r in recs:
            r_f1, r_ex, r_dl = ([], [], [])
            _stats = r.get('stats')
            if not isinstance(_stats, dict):
                _stats = {}
            for lk, lv in _stats.items():
                if not isinstance(lv, dict):
                    continue
                lm = _cell(lv, 'len_mean')
                if lm is None:
                    continue
                all_lens.append(lm)
                if '_dyn' in lk:
                    dyn_lens.append(lm)
                    if 'bnd_f1' in lv:
                        _f1 = _cell(lv, 'bnd_f1')
                        _ex = _cell(lv, 'bnd_excess') if lv.get('bnd_rand_exact') is not False else None
                        if _f1 is not None:
                            r_f1.append(_f1)
                        if _ex is not None or lv.get('bnd_rand') is not None:
                            _kind = lv.get('bnd_rand_kind')
                            _kind = (normalize_bnd_rand_kind(_kind)
                                     if _kind is not None else 'unspecified_legacy')
                            _bnd_rand_kinds.add(_kind)
                            if _ex is not None:
                                r_ex.append(_ex)
                dl = _cell(lv, 'delta')
                if dl is not None:
                    r_dl.append(dl)
            if r_f1:
                bf1.append(float(np.mean(r_f1)))
            if r_ex:
                bex.append(float(np.mean(r_ex)))
            if r_dl:
                # Average per record FIRST (as bf1/bex do), so records with more
                # dynamic layers do not get extra weight in the cross-seed mean.
                deltas.append(float(np.mean(r_dl)))
        if len(_bnd_rand_kinds) > 1:
            entry['boundary_rand_kind_conflict'] = sorted(_bnd_rand_kinds)
            print(f'[aggregate] WARNING: {key}: `bnd_rand` cells mix the '
                  f'{sorted(_bnd_rand_kinds)} definitions — their bnd_excess '
                  'values are different estimands and are NOT averaged; '
                  'report each kind separately')
        elif _bnd_rand_kinds:
            entry['boundary_rand_kind'] = next(iter(_bnd_rand_kinds))
        if dyn_lens:
            entry['avg_dyn_block_len'] = float(np.mean(dyn_lens))
        elif all_lens:
            entry['avg_block_len'] = float(np.mean(all_lens))
        if deltas:
            entry['delta_logit_mean'] = float(np.mean(deltas))
        if bf1:
            entry['boundary_f1_dyn'] = float(np.mean(bf1))
            entry['boundary_f1_dyn_std'] = float(np.std(bf1, ddof=1)) if len(bf1) > 1 else 0.0
        if bex and 'boundary_rand_kind_conflict' not in entry:
            entry['boundary_excess_dyn'] = float(np.mean(bex))
        hists = [r['ppl_history'] for r in recs
                 if isinstance(r.get('ppl_history'), (list, tuple)) and r.get('ppl_history')]
        if hists:
            per_step = {}
            for _h in hists:
                for _pt in _h:
                    try:
                        _s = int(_pt[0])
                        _v = float(_pt[1])
                    except (TypeError, ValueError, IndexError, KeyError):
                        continue
                    per_step.setdefault(_s, []).append(_v)
            def _grid(_hist):
                _out = []
                for _p in _hist:
                    try:
                        _out.append(int(_p[0]))
                    except (TypeError, ValueError, IndexError, KeyError):
                        continue
                return _out
            _ref_steps = _grid(hists[0])
            _off_grid = []
            for _i, _h in enumerate(hists[1:], start=1):
                _hs = _grid(_h)
                if _hs != _ref_steps:
                    _off_grid.append(_i)
            if _off_grid:
                print(f'[aggregate] {key}: seed(s) {_off_grid} of {len(hists)} evaluate at a DIFFERENT step grid than seed 0 — the seed-averaged curve is taken over the steps they SHARE (aligned on the step VALUE, not on list position), so a differently-sampled seed contributes only to the common steps.')
            steps_h = sorted(per_step)
            cols = {s: i for i, s in enumerate(steps_h)}
            mat = np.full((len(hists), len(steps_h)), float('nan'))
            for _i, _h in enumerate(hists):
                _own = {}
                for _pt in _h:
                    try:
                        _own[int(_pt[0])] = float(_pt[1])
                    except (TypeError, ValueError, IndexError, KeyError):
                        continue
                for _s, _v in _own.items():
                    mat[_i, cols[_s]] = _v
            # dtype=bool is essential: an all-malformed history yields a
            # zero-column matrix whose inferred dtype is float64, and ``~good``
            # then raises instead of reporting an empty curve.
            good = np.array([[ppl_is_usable(v) for v in row] for row in mat], dtype=bool)
            n_good = good.sum(axis=0)
            sums = np.where(good, mat, 0.0).sum(axis=0)
            mean_ppl = np.where(n_good > 0, sums / np.maximum(n_good, 1), np.nan)
            n_dropped = int((~good).sum())
            if n_dropped:
                print(f'[aggregate] {key}: {n_dropped} non-finite PPL curve point(s) across {len(hists)} seed(s) excluded from the seed-averaged curve ({int((n_good == 0).sum())} step(s) had no usable seed and are omitted)')
            _keep = n_good > 0
            entry['ppl_curve'] = [[int(s), float(m)] for s, m, k in zip(steps_h, mean_ppl, _keep) if k]
        agg[key] = entry
    for key, entry in agg.items():
        recs = _group_records.get((entry['variant'], entry['protocol'], entry.get('run_cfg_class')), [])
        entry['source'] = key
        if recs:
            entry['_group_records'] = recs
        rates = []
        for r in recs:
            _ts = _finite_scalar(r.get('tokens_seen'))
            _st = _finite_scalar(r.get('steps'))
            if _ts is not None and _st is not None and _st > 0.0:
                rates.append(_ts / _st)
        if rates:
            entry['tokens_per_step'] = float(np.mean(rates))
    _full_groups = {(tag, fp_idx): recs for (v, tag, fp_idx), recs in _split_groups if v == 'full'}

    def _cfg_fp_noparam(rec):
        # Baseline-matching fingerprint WITHOUT params: a `full` baseline
        # legitimately differs from the sparse arm in parameter count, so a
        # params-including fingerprint could never match it (dead branch).
        # run_cfg + steps/tokens + code semantics is exactly the gate
        # `pair_reason` applies (the code stamp must not be mixed either).
        return json.dumps([rec.get('run_cfg'),
                           [rec.get(k) for k in PAIR_STEP_KEYS],
                           measurement_semantics_key(rec)],
                          sort_keys=True, default=str)

    def _baseline_for(tag, fp_idx, base_groups, recs):
        # Pairing is only legal inside one (variant, protocol) group.  A
        # tagged arm must never borrow an untagged (or differently tagged)
        # baseline: that changes the warmup/eval protocol while pretending the
        # contrast is controlled.  Legacy panel readers may still report the
        # arm's own marginal aggregate; they simply get no dPPL.
        _want = _cfg_fp_noparam(recs[0]) if recs else None
        if _want is not None:
            _cands = sorted(base_groups.items(), key=lambda kv: (kv[0][0] != tag, kv[0][1] is None))
            for (_t_c, _i_c), _grp in _cands:
                if _t_c != tag:
                    continue
                if any((_cfg_fp_noparam(_r) == _want for _r in _grp)):
                    return (_grp, _t_c)
        for _cand in ((tag, fp_idx), (tag, None)):
            if _cand in base_groups:
                return (base_groups[_cand], _cand[0])
        _want_cfg = recs[0].get('run_cfg') if recs else None
        if _want_cfg is not None:
            _rc = [(_t_c, _grp) for (_t_c, _i_c), _grp in base_groups.items() if _t_c == tag and _grp and (_grp[0].get('run_cfg') == _want_cfg)]
            if len(_rc) == 1:
                return (_rc[0][1], _rc[0][0])
        return (None, None)
    _base_amb = []
    for (v, tag, fp_idx), recs in _split_groups:
        if v == 'full':
            continue
        key = _agg_key(v, tag, fp_idx)
        base_recs, base_tag = _baseline_for(tag, fp_idx, _full_groups, recs)
        if base_recs is None:
            print(f'[aggregate] {key}: NO `full` baseline in this panel — dPPL_vs_full not computed')
            continue
        if base_tag != tag:
            # _baseline_for is strict, so this is a programming error rather
            # than a fallback: refuse instead of silently changing protocol.
            _base_amb.append(f'{key}: baseline protocol {base_tag!r} != arm protocol {tag!r}')
            continue
        ds, skipped = _paired(recs, base_recs)
        if skipped:
            _why = sorted({reason for _s, reason in skipped})
            print(f'[aggregate] {key}: {len(skipped)} seed(s) NOT paired with `full` — {_why}; excluded from dPPL_vs_full')
        if ds:
            d = np.array(ds, dtype=float)
            agg[key]['dPPL_vs_full_mean'] = float(d.mean())
            agg[key]['dPPL_vs_full_std'] = float(d.std(ddof=1)) if len(d) > 1 else 0.0
            agg[key]['n_paired'] = len(d)
            agg[key]['n_paired_skipped'] = len(skipped)
            agg[key]['dPPL_vs_full_base'] = base_tag or '(untagged)'
    _sw_groups = {(tag, fp_idx): recs for (v, tag, fp_idx), recs in _split_groups if v == 'full_sw128_matched'}
    for (v, tag, fp_idx), recs in _split_groups:
        if v in ('full', 'full_sw128_matched'):
            continue
        key = _agg_key(v, tag, fp_idx)
        base_recs, base_tag = _baseline_for(tag, fp_idx, _sw_groups, recs)
        if base_recs is None:
            continue
        if base_tag != tag:
            _base_amb.append(f'{key}: `full_sw128_matched` baseline protocol {base_tag!r} != arm protocol {tag!r}')
            continue
        ds, skipped = _paired(recs, base_recs)
        if skipped:
            _why = sorted({reason for _s, reason in skipped})
            print(f'[aggregate] {key}: {len(skipped)} seed(s) NOT paired with `full_sw128_matched` — {_why}; excluded')
        if ds:
            d = np.array(ds, dtype=float)
            agg[key]['dPPL_vs_sw128m_mean'] = float(d.mean())
            agg[key]['dPPL_vs_sw128m_std'] = float(d.std(ddof=1)) if len(d) > 1 else 0.0
            agg[key]['n_paired_sw128m'] = len(d)
            agg[key]['n_paired_sw128m_skipped'] = len(skipped)
    if _base_amb:
        raise ValueError('aggregate: unsafe/cross-protocol baseline pairing for ' + '; '.join(sorted(_base_amb)) + '. Pair only a baseline in the SAME (variant, protocol) group; remove or re-tag the mismatched baseline before aggregating.')
    return agg


# Fingerprint fields that define the sample/measurement a PPL describes.
# Records in one aggregate group must agree on all of them; otherwise the group
# is split (not silently averaged) and the split is reported.  `_code` is the
# implementation-semantics stamp: it is not a data fingerprint, but a PPL
# produced by different code semantics is still not one measurement.
_AGG_FINGERPRINT_FIELDS = ('data_fp', 'val_fp', 'eval_fp', 'eval_subset_fp',
                           'holdout_row_fp', '_code')


def _aggregation_fp_class(rec):
    return tuple((k, str(rec.get(k))) for k in _AGG_FINGERPRINT_FIELDS
                 if rec.get(k) is not None and str(rec.get(k)) != '')


def aggregate_with_exclusions(summary):
    """Aggregate a panel while quarantining records that cannot be pooled.

    ``aggregate`` deliberately fails closed: a malformed record, an ambiguous
    same-seed duplicate, or two different evaluation slices in one group are
    data-identity faults, and silently averaging them would manufacture n.
    A finished training panel, however, must still produce the aggregate for
    its valid records and report exactly what was set aside.  This wrapper:

    * validates each record (object / measured PPL / integer seed / arm name),
      names every excluded key and the reason;
    * keeps the FIRST measured record for a duplicated (arm, protocol, seed)
      and excludes later ones as ambiguous duplicates;
    * splits a group whose records carry different corpus/evaluation
      fingerprints or different code-semantics stamps into separate output
      keys instead of averaging them;
    * retries a group that still trips the strict cross-protocol pairing gate
      per arm (so the valid marginal readings survive without a dPPL).

    Returns ``(agg, report, admitted_records)``.  ``report`` is JSON-safe and
    states the tolerance boundary: excluded records are never folded into a
    number, and no "missing" record is invented.
    """
    report = {
        'kind': 'aggregation_exclusions',
        'created_at': time.strftime('%Y-%m-%dT%H:%M:%S'),
        'code': code_stamp(),
        'n_input': 0, 'n_admitted': 0, 'n_excluded': 0,
        'reason_counts': {}, 'excluded': [], 'excluded_truncated': 0,
        'fingerprint_split_groups': [], 'pairing_split_groups': [],
        'n_aggregate_keys': 0,
        'tolerance': ('only malformed/unmeasured records and ambiguous '
                      'same-seed duplicates are dropped; groups that disagree '
                      'on a corpus/evaluation fingerprint or code-semantics '
                      'stamp are SPLIT, not averaged; every exclusion is named '
                      'and counted here'),
    }
    if not isinstance(summary, dict):
        report['n_input'] = 1
        report['reason_counts'] = {'summary is not an object': 1}
        report['n_excluded'] = 1
        return {}, report, {}
    report['n_input'] = len(summary)
    legacy_ok = legacy_warm_tags(summary)
    excluded = []
    reasons = collections.Counter()

    def _drop(key, why):
        excluded.append({'key': str(key), 'reason': str(why)})
        reasons[str(why)] += 1

    candidates = {}
    for key, rec in summary.items():
        if not isinstance(rec, dict):
            _drop(key, 'record is not a JSON object')
            continue
        if rec.get('synthesized'):
            _drop(key, 'synthesized reconstruction (not an independent run)')
            continue
        if not ppl_is_usable(rec.get('ppl')):
            _drop(key, 'missing/non-finite final PPL (failed or unmeasured run)')
            continue
        seed = _as_seed_int(rec.get('seed'))
        if seed is None:
            _drop(key, f'non-integer seed {rec.get("seed")!r}')
            continue
        v = rec.get('variant')
        if v is None:
            v = str(key).split('::', 1)[0]
        if not isinstance(v, str) or not v:
            _drop(key, f'non-string/empty variant {v!r}')
            continue
        # Canonicalise the fields aggregate/readers key on.  The original
        # record is kept untouched for the per-seed readers.
        canon = dict(rec, seed=seed, variant=v)
        tag = record_tag(canon, key, legacy_ok)
        ident = (v, tag, seed)
        if ident in candidates:
            _drop(key, f'duplicate (variant={v!r}, protocol={tag!r}, '
                       f'seed={seed}) — kept {candidates[ident][0]!r}')
            continue
        candidates[ident] = (str(key), canon)

    # Group by (protocol, sample/measurement class) ACROSS variants.  Splitting
    # inside each variant first (the previous shape) silently removed the
    # baseline from every subgroup, so `aggregate` could never form a paired
    # dPPL: the wrapper that every panel dump uses produced marginal means but
    # no paired contrast.  A class is the tuple of data/evaluation/code
    # fingerprints; all arms of one controlled comparison must share it, and
    # only the shared class is paired.
    groups = {}
    by_variant_tag = {}
    tag_classes = {}
    for (v, tag, _seed), (key, rec) in candidates.items():
        _cls = _aggregation_fp_class(rec)
        groups.setdefault((tag, _cls), {})[key] = rec
        by_variant_tag.setdefault((v, tag), []).append(rec)
        tag_classes.setdefault(tag, set()).add(_cls)
    for (v, tag), recs in sorted(by_variant_tag.items(),
                                 key=lambda kv: (kv[0][0], kv[0][1] or '')):
        _classes = {_aggregation_fp_class(r) for r in recs}
        if len(_classes) > 1:
            report['fingerprint_split_groups'].append({
                'variant': v, 'protocol': tag,
                'n_fingerprint_classes': len(_classes),
                'n_records': len(recs),
                'note': ('records from different corpora/evaluation slices or '
                         'code-semantics stamps were reported separately, never '
                         'pooled'),
            })
    agg = {}
    used = set()
    for (tag, _fp_class), sub in sorted(
            groups.items(), key=lambda kv: ((kv[0][0] or ''), repr(kv[0][1]))):
        suffix = ''
        if len(tag_classes.get(tag) or ()) > 1:
            _digest = hashlib.sha1(
                repr(_fp_class).encode('utf-8')).hexdigest()[:8]
            suffix = f'@fp{_digest}'
        try:
            sub_agg = aggregate(sub)
            used.update(sub.keys())
        except Exception as exc:
            # Most likely the strict cross-protocol baseline-pairing gate.
            # Re-run each arm separately so its marginal aggregate (and
            # its measured records) survive; no dPPL is then claimed.
            sub_agg = {}
            _pairing_split = False
            for vv in sorted({str(r.get('variant')) for r in sub.values()}):
                _sub_v = {k: r for k, r in sub.items()
                          if str(r.get('variant')) == vv}
                if not _sub_v:
                    continue
                try:
                    _one = aggregate(_sub_v)
                except Exception as exc2:
                    for k in _sub_v:
                        _drop(k, f'aggregate failed for arm {vv!r}: '
                                  f'{type(exc2).__name__}: {exc2}')
                    continue
                _pairing_split = True
                used.update(_sub_v.keys())
                for k, entry in _one.items():
                    _key = f'{k}@arm{vv}'
                    while _key in sub_agg:
                        _key += "'"
                    sub_agg[_key] = entry
            if _pairing_split:
                report['pairing_split_groups'].append({
                    'protocol': tag,
                    'variants': sorted({str(r.get('variant')) for r in sub.values()}),
                    'error': f'{type(exc).__name__}: {exc}',
                    'note': ('reported per arm; a cross-protocol dPPL is '
                             'not defined and was not produced'),
                })
            if not sub_agg:
                continue
        for key, entry in sub_agg.items():
            out_key = key + suffix
            while out_key in agg:
                out_key += "'"
            agg[out_key] = entry

    _unused = set(k for k, _r in candidates.values()) - used
    _excluded_keys = {e['key'] for e in excluded}
    for key in sorted(_unused):
        if str(key) not in _excluded_keys:
            _drop(key, 'no aggregate entry could be produced for this record')

    report['n_admitted'] = len(used)
    report['n_excluded'] = max(0, len(summary) - len(used))
    report['reason_counts'] = dict(sorted(reasons.items()))
    report['excluded'] = excluded[:200]
    report['excluded_truncated'] = max(0, len(excluded) - 200)
    report['n_aggregate_keys'] = len(agg)
    admitted_records = {key: r for (key, r) in candidates.values()
                        if key in used}
    if report['n_excluded']:
        print(f'[aggregate] {report["n_excluded"]}/{report["n_input"]} '
              f'record(s) quarantined: '
              + ', '.join(f'{k}={v}' for k, v in
                          report['reason_counts'].items()))
    for _g in report['fingerprint_split_groups']:
        print(f'[aggregate] {_g["variant"]}/{_g["protocol"] or "-"}: '
              f'{_g["n_fingerprint_classes"]} fingerprint classes reported '
              'separately (different data/evaluation slices were not pooled)')
    return agg, report, admitted_records


_TW = {'variant': 18, 'ppl': 16, 'd': 15, 'd2': 15, 'params': 10, 'seeds': 6, 'blklen': 7, 'bnd': 13}

def _fmt_cell(value, width, fmt, absent='—'):
    s = absent if value is None else f'{value:{fmt}}'
    return s if len(s) >= width else f'{s:>{width}s}'

def _fmt_pair(main, spread, width, main_fmt, spread_fmt, absent='—', main_cap=None, never_wider=None):
    if main is None:
        s = absent
    else:
        if never_wider is not None:
            fmt = never_wider
        elif main_cap is None:
            fmt = main_fmt
        else:
            fmt = main_cap if abs(main) >= 100000000.0 else main_fmt
        s = f'{main:{fmt}}±{spread:{spread_fmt}}'
    return s if len(s) >= width else f'{s:>{width}s}'

def _print_table(agg):
    print('\n============== validation perplexity (corpus per run cfg) ==============')
    print(f'{'variant':{_TW['variant']}s} {'PPL mean±std':>{_TW['ppl']}s} {'Δvs full':>{_TW['d']}s} {'Δvs sw128m':>{_TW['d2']}s} {'params(M)':>{_TW['params']}s} {'seeds':>{_TW['seeds']}s} {'blklen':>{_TW['blklen']}s} {'bndF1':>{_TW['bnd']}s}')
    order = ['full', 'full_matched', 'full_cos', 'full_sink', 'full_sw128', 'full_sw128_matched', 'csa_fixed', 'csa_dynamic', 'csa_dyn_fuse', 'csa_dyn_nocomp', 'csa_fix_randidx', 'csa_fix_zerocont', 'csa_fix_nosink', 'csa_fix_topk8', 'csa_fix_topk64', 'hybrid_fixed', 'hybrid_dynamic', 'hybrid_csa_dyn', 'hybrid_hca_dyn', 'hybrid_csa_dyn_fuse']
    rows = [v for v in order if v in agg] + [v for v in agg if v not in order]
    for v in rows:
        e = agg[v]
        _n = e['n_seeds']
        ppl = _fmt_pair(e.get('ppl_primary', e['ppl_mean']), e.get('ppl_std', 0.0), _TW['ppl'], '8.2f', '5.2f', main_cap='.2f') if _n > 1 else _fmt_cell(e.get('ppl_primary', e['ppl_mean']), _TW['ppl'], '.2f')
        d = e.get('dPPL_vs_full_mean')
        dd = _fmt_pair(d, e.get('dPPL_vs_full_std', 0.0), _TW['d'], '+8.2f', '5.2f', main_cap='+.2f')
        d2 = e.get('dPPL_vs_sw128m_mean')
        dd2 = _fmt_pair(d2, e.get('dPPL_vs_sw128m_std', 0.0), _TW['d2'], '+8.2f', '5.2f', main_cap='+.2f')
        bl = e.get('avg_dyn_block_len', e.get('avg_block_len'))
        bls = _fmt_cell(bl, _TW['blklen'], '.1f')
        _pm = e.get('params')
        pms = _fmt_cell(_pm / 1000000.0 if _pm is not None else None, _TW['params'], '.2f')
        bf = e.get('boundary_f1_dyn')
        bfs = _fmt_pair(bf, e.get('boundary_f1_dyn_std', 0.0), _TW['bnd'], '6.3f', '5.3f', never_wider='.3f')
        try:
            _ns = _fmt_cell(int(_n), _TW['seeds'], 'd')
        except (TypeError, ValueError, OverflowError):
            _ns = _fmt_cell(None, _TW['seeds'], 'd')
        _cells = [(v, _TW['variant']), (ppl, _TW['ppl']), (dd, _TW['d']), (dd2, _TW['d2']), (pms, _TW['params']), (_ns, _TW['seeds']), (bls, _TW['blklen']), (bfs, _TW['bnd'])]
        print(' '.join((f'{s:>{w}s}' for s, w in _cells)))
    print('Δ vs full   = paired per-seed difference vs dense (positive = worse).')
    print('Δ vs sw128m = paired difference vs the windowed param-matched dense')
    print('              baseline = what compression adds beyond pure locality.')
    print('blklen = mean learned block length (dynamic layers); bndF1 = boundary alignment F1 mean±std over seeds (v4: n_sample=64);')
    print('        see summary.json for bnd_rand / bnd_excess: excess > 0 means the')
    print('        learned boundaries are genuinely semantic).')
    print('================================================================')

def _print_pairs(summary):
    recs, _amb = _variant_seed_map(summary)
    _pair_amb = sorted(_amb)
    _pair_skip = []
    # Read the declared leave-one-out design instead of maintaining a second
    # hard-coded table that can silently omit a declared contrast.  The top-k
    # budget sweep is descriptive (not an innovation), so its pairs are added
    # explicitly after the declared ablations.
    _declared = declared_ablation_pairs() + [
        ('csa_fix_topk8', 'csa_fixed'), ('csa_fix_topk64', 'csa_fixed')]
    PAIRS, _seen_pairs = [], set()
    for _pair in _declared:
        if _pair not in _seen_pairs:
            _seen_pairs.add(_pair)
            PAIRS.append(_pair)
    print('\n========== paired per-seed deltas (a − b, positive = a worse) ==========')
    print('  (p = exact two-sided sign-flip over the paired per-seed deltas; a noise-level Δ is flagged even if p is small)')
    if _pair_amb:
        print('  [skip] a (variant, protocol, seed) triple holds more than one measured record, so its PPL is ambiguous — no delta printed for : ' + ', '.join(sorted((f'{v}/{t or '-'}/s{s}' for v, t, s in set(_pair_amb)))[:4]))
    for a, b in PAIRS:

        def _sel(v):
            return {(t, s): p for (vv, t, s), p in recs.items() if vv == v}
        ra, rb = (_sel(a), _sel(b))
        _a_t = {t for t, _s in ra}
        _b_t = {t for t, _s in rb}
        # Same (variant, protocol) group only.  Pairing a tagged arm with an
        # untagged baseline changes the protocol (warmup/eval condition) and
        # would otherwise manufacture a controlled-looking delta.
        common = []
        for tag in sorted(_a_t & _b_t):
            seeds = sorted({s for t, s in ra if t == tag} & {s for t, s in rb if t == tag})
            common += [(tag, tag, s) for s in seeds]
        _only_a = sorted(_a_t - _b_t)
        _only_b = sorted(_b_t - _a_t)
        if _only_a or _only_b:
            print(f'  [skip] {a} vs {b}: protocol group(s) only on one side '
                  f'(a-only={_only_a}, b-only={_only_b}) — no cross-protocol pairing')
        _by_cond = {}
        _est_by_cond = {}
        _sk = []
        for ts, bs, s in common:
            _reason = pair_reason(ra[ts, s], rb[bs, s])
            if _reason is not None:
                _sk.append((s, _reason))
                continue
            _delta = _paired_primary_delta(ra[ts, s], rb[bs, s])
            if _delta is None:
                _sk.append((s, 'primary estimand missing/mismatched (nested vs '
                               'full-validation rows, or no holdout accounting)'))
                continue
            _by_cond.setdefault((ts, bs), []).append(_delta)
            _est_by_cond.setdefault((ts, bs), set()).add(
                ra[ts, s].get('ppl_estimation_rows') == 'nested_validation_holdout')
        if _sk:
            _pair_skip.append((a, b, len(_sk), len(common), sorted({r for _s, r in _sk})))
        for (ts, bs), dl in sorted(_by_cond.items()):
            if len(_est_by_cond.get((ts, bs), ())) > 1:
                _pair_skip.append((a, b, len(dl), len(dl),
                                   ['mixed estimands across seeds (nested holdout '
                                    'vs full validation)']))
                continue
            st = paired_effect_stats(dl)
            _p = ('%.4f' % st['p_exact_signflip']) if math.isfinite(st['p_exact_signflip']) else 'n/a'
            _lab = '' if ts == bs == '' else f'   [{ts or '(untagged)'} vs {bs or '(untagged)'}]'
            print(f'  {a:22s} − {b:22s} = {st["mean"]:+7.2f} ± {st["std"]:5.2f}   (n={st["n"]}, p={_p}, {st["effect_vs_noise"]}){_lab}')
    if _pair_skip:
        print('  [skip] seed(s) rejected by the run_cfg/load gate (see `pair_reason`); the printed n counts only the pairs that cleared it —')
        for _a, _b, _nsk, _ncom, _why in _pair_skip:
            print(f'    {_a} − {_b}: {_nsk}/{_ncom} rejected — {_why}')
    print('=' * 78)

def _save_csv(agg, outdir):
    cols = ['variant', 'ppl_primary', 'ppl_mean', 'ppl_pooled', 'ppl_std', 'dPPL_vs_full_mean', 'dPPL_vs_full_std', 'dPPL_vs_sw128m_mean', 'dPPL_vs_sw128m_std', 'n_seeds', 'params', 'avg_dyn_block_len', 'boundary_f1_dyn', 'boundary_excess_dyn']
    rows = [{'variant': v, **{c: e.get(c, '') for c in cols[1:]}} for v, e in agg.items()]
    atomic_write_csv(os.path.join(outdir, 'aggregate.csv'), cols, rows)

def _plot(summary, agg, outdir):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    if not agg:
        return
    order = ['full', 'full_matched', 'full_cos', 'full_sink', 'full_sw128', 'full_sw128_matched', 'csa_fixed', 'csa_dynamic', 'csa_dyn_fuse', 'csa_dyn_nocomp', 'csa_fix_randidx', 'csa_fix_zerocont', 'csa_fix_nosink', 'csa_fix_topk8', 'csa_fix_topk64', 'hybrid_fixed', 'hybrid_dynamic', 'hybrid_csa_dyn', 'hybrid_hca_dyn', 'hybrid_csa_dyn_fuse']
    vs = [v for v in order if v in agg] + [v for v in agg if v not in order]
    fig, ax = plt.subplots(1, 5, figsize=(27, 4.5))
    ps = [agg[v].get('ppl_primary', agg[v]['ppl_mean']) for v in vs]
    es = [agg[v]['ppl_std'] for v in vs]
    ax[0].bar(range(len(vs)), ps, yerr=es, capsize=3, color='steelblue')
    ax[0].set_xticks(range(len(vs)))
    ax[0].set_xticklabels(vs, rotation=30, ha='right')
    ax[0].set_ylabel('validation perplexity (mean ± std)')
    ax[0].set_title('val PPL (corpus per run cfg)')
    ax[0].grid(alpha=0.3, axis='y')
    _unknown = [v for v in vs if agg[v].get('params') is None]
    if _unknown:
        print(f'[plot] {len(_unknown)} variant(s) report no `params` ({', '.join(_unknown)}) — their size bar is left at 0 and the size panel cannot be read for them')
    params_m = [(agg[v]['params'] or 0) / 1000000.0 for v in vs]
    ax[1].bar(range(len(vs)), params_m, color='orange')
    ax[1].set_xticks(range(len(vs)))
    ax[1].set_xticklabels(vs, rotation=30, ha='right')
    ax[1].set_ylabel('params (M)')
    ax[1].set_title('Model size')
    ax[1].grid(alpha=0.3, axis='y')
    for v in vs:
        _curves = []
        for _r in agg[v].get('_group_records', []):
            if not isinstance(_r, dict) or _r.get('synthesized'):
                continue
            _loss = _r.get('losses') if isinstance(_r.get('losses'), list) else _cell_curve_data(outdir, _r).get('losses')
            if isinstance(_loss, list) and _loss and all((isinstance(x, (int, float)) and math.isfinite(x) for x in _loss)):
                _curves.append(_loss)
        if not _curves:
            continue
        _lens = sorted({len(_c) for _c in _curves})
        if len(_lens) > 1:
            print(f'[_plot] {v}: seeds trained a DIFFERENT number of steps {_lens} — the training curve is drawn over the shared prefix of {_lens[0]} step(s) only.')
        n_pt = min((len(_c) for _c in _curves))
        curve = np.mean([np.array(_c[:n_pt], dtype=float) for _c in _curves], axis=0)
        k = max(1, n_pt // 50)
        _num = np.convolve(curve, np.ones(k), mode='same')
        _den = np.convolve(np.ones_like(curve), np.ones(k), mode='same')
        smooth = np.where(_den > 0, _num / _den, 0.0)
        ax[2].plot(smooth, label=v)
    ax[2].set_xlabel('step')
    ax[2].set_ylabel('train loss (seed-averaged)')
    ax[2].set_title('Training curves')
    ax[2].legend(fontsize=7)
    ax[2].grid(alpha=0.3)
    drew = False
    for v in vs:
        cur = agg[v].get('ppl_curve')
        if not cur:
            continue
        steps_h = np.array([p[0] for p in cur], dtype=float)
        ppls_h = np.array([p[1] for p in cur], dtype=float)
        tok_per_step = agg[v].get('tokens_per_step')
        if not tok_per_step:
            print(f'[_plot] {v}: no `tokens_per_step` in the aggregate — omitted from the tokens axis (plotting steps under a tokens label would be wrong by seq_len*batch_size). Re-run `aggregate` to stamp it.')
            continue
        ax[3].plot(steps_h * tok_per_step / 1000000.0, ppls_h, marker='.', ms=4, label=v)
        drew = True
    ax[3].set_xlabel('tokens seen (M)')
    ax[3].set_ylabel('val-subset PPL')
    ax[3].set_title('PPL vs training tokens (gap dynamics)')
    if drew:
        ax[3].legend(fontsize=7)
    ax[3].grid(alpha=0.3)
    _dense_keys = [k for k in agg if k.split('#')[0].split('@')[0] == 'full']
    _dense_key = next((k for k in _dense_keys if agg[k].get('ppl_curve') and agg[k].get('tokens_per_step')), None)
    if _dense_key is None:
        print(f'[_plot] no dense `full` group with both a `ppl_curve` and a `tokens_per_step` in this aggregate (candidates: {_dense_keys or 'none'}) — the sparse-vs-dense gap panel (finding #10) is NOT drawn.')
    else:
        if _dense_key != 'full':
            print(f'[_plot] the dense baseline is published as `{_dense_key}` (the `full` group was split by `run_cfg`); the sparse-vs-dense gap is taken against it' + (f', not {_dense_keys[1:]}' if len(_dense_keys) > 1 else '') + '.')
        ref = agg[_dense_key].get('ppl_curve')
        tps0 = agg[_dense_key].get('tokens_per_step')
    if _dense_key is not None and ref and tps0:
        gx = np.array([p[0] for p in ref], dtype=float) * tps0
        gy = np.array([p[1] for p in ref], dtype=float)
        drew2 = False
        for v in vs:
            if v == _dense_key:
                continue
            if v.startswith('full@cfg'):
                continue
            cur = agg[v].get('ppl_curve')
            if not cur:
                continue
            tps = agg[v].get('tokens_per_step')
            if not tps:
                continue
            xs = np.array([p[0] for p in cur], dtype=float) * tps
            ys = np.array([p[1] for p in cur], dtype=float)
            keep = (gx >= xs[0]) & (gx <= xs[-1])
            if not keep.any():
                continue
            ax[4].plot(gx[keep] / 1000000.0, np.interp(gx[keep], xs, ys) - gy[keep], marker='.', ms=4, label=f'{v}−full')
            drew2 = True
        ax[4].axhline(0, color='k', lw=0.8)
        ax[4].set_xlabel('tokens seen (M)')
        ax[4].set_ylabel('ΔPPL vs full')
        ax[4].set_title('sparse-vs-dense gap vs tokens (finding #10)')
        if drew2:
            ax[4].legend(fontsize=7)
        ax[4].grid(alpha=0.3)
    fig.tight_layout()
    fig.savefig(os.path.join(outdir, 'summary.png'), dpi=120)
    plt.close(fig)

def _read_summary_json(path):
    summary = {}
    if os.path.exists(path):
        try:
            with open(path, encoding='utf-8') as f:
                summary = json.load(f)
        except Exception as _e:
            print(f'[resume] FATAL: {path} exists but cannot be parsed ({type(_e).__name__}: {_e}).  Refusing to overwrite it with an empty summary — move it aside to start fresh.')
            raise
        if not isinstance(summary, dict):
            # Resume/update paths index the summary by cell key.  A parsed but
            # non-object file cannot carry any cell records, and overwriting it
            # would silently discard whatever the operator put there.
            raise ValueError(
                f'{path} parsed as a {type(summary).__name__}, not a cell -> '
                'record object; refusing to resume from/overwrite it')
    return summary


def _run_fp(cfg, d, n_layers, n_heads, d_head, vocab, train_ids, val_batch, device=None):
    """The resume fingerprint of a run() cell.  The parent planner and every
    par.py child compute the exact same string: the child re-serves the token
    ids from the same cache files, and `_ids_fp` is content-based.

    AMP / eager-twin modes are resolved from the run config (persisted in the
    manifest) or from an explicitly supplied ``device``; they are never read
    from this process's global CUDA state.  A zero-GPU planner can therefore
    recompute a GPU panel's fingerprint from the same config, and a child
    receives the parent's resolved modes through the job config."""
    _mg = cfg.get('matched')
    if _mg is None:
        _mkey = 'default'
    else:
        _mkey = ','.join(sorted((str(_x) for _x in _mg)))
    cfg.setdefault('warmup', 50)
    cfg.setdefault('comp_lambda', 0.05)
    _declared_impl = any(
        (k in cfg) and not (isinstance(cfg.get(k), str) and cfg.get(k).strip().lower() == 'auto')
        for k in ('amp_dtype', 'eager_batch'))
    _amp_mode, _eb = _resolve_impl_modes(cfg, device=device)
    if device is None and not _declared_impl:
        # No machine-dependent implementation descriptor enters the content
        # fingerprint.  Resolve to the canonical fp32/row-loop descriptor
        # explicitly (not via training_knobs()'s global DEVICE inference).
        try:
            _tk = training_knobs_fingerprint(amp_dtype=None, eager_batch=False)
        except TypeError:
            # Keep callers that replace training_knobs() with a zero-argument
            # test double working; their digest is the canonical one on CPU.
            _tk = training_knobs_fingerprint()
    else:
        _tk = training_knobs_fingerprint(amp_dtype=_amp_mode, eager_batch=_eb)
    _amp = _amp_mode or 'fp32'
    _ae = _adaptive_exact_limit()
    # The sampled long-context segmenter's grid depends on this ceiling too.
    # Keep the default token absent so existing default fingerprints stay
    # stable, but a non-default ceiling must invalidate resumed cells.
    _am = _adaptive_max_limit()
    _am_tok = '' if _am == (1 << 20) else f'_am{_am}'
    # The task/synthetic recipe (`data_extra`) is part of the data identity.
    # Keep the token absent when it is unset so legacy default fingerprints
    # stay stable, but a recipe change must invalidate resume.
    _es_pat = cfg.get('early_stop_patience')
    _es_tok = ''
    if _es_pat is not None:
        _es_tok = f'_esp{_es_pat}_esd{cfg.get("early_stop_min_delta", 0.0)}'
    _de = cfg.get('data_extra')
    _de_tok = ''
    if _de:
        try:
            _de_tok = '_de' + hashlib.sha256(
                json.dumps(_de, sort_keys=True, default=str).encode('utf-8')
            ).hexdigest()[:16]
        except (TypeError, ValueError):
            _de_tok = '_de' + str(_de)[:64]
    return f'steps{cfg['steps']}_sl{cfg['seq_len']}_bs{cfg['batch_size']}_nt{cfg['n_train_tokens']}_lr{cfg['lr']}_wd{cfg['weight_decay']}_d{d}_L{n_layers}_H{n_heads}_Dh{d_head}_v{vocab}_wu{cfg['warmup']}_cl{cfg['comp_lambda']}_dlm{cfg.get('delta_lr_mult', 10.0)}_mt{_mkey}_mr{cfg.get('mlp_match_ref', 'csa_dynamic')}_ee{cfg.get('eval_every', 0)}_es{cfg.get('eval_subset', 128)}_det{determinism_label()}_df{_ids_fp(train_ids)}-{_ids_fp(np.ascontiguousarray(val_batch).reshape(-1))}{_de_tok}{_es_tok}_tk{_tk}_amp{_amp}_eb{int(_eb)}_ae{_ae}{_am_tok}_cs{code_stamp()}'


# ---------------------------------------------------------------------------
# Run-order design: calendar time is a nuisance factor, not a treatment
# ---------------------------------------------------------------------------
# A panel that runs every seed of arm A and only then every seed of arm B has
# arm perfectly confounded with time: driver updates, thermal state, a noisy
# neighbour or a changed cluster image can all produce a between-arm gap that
# the paired seed test will read as an arm effect.  The design below makes the
# run order explicit: a deterministic randomized complete-block order with one
# block per seed (so both arms of every pair are trained close together), plus
# a position rotation that prevents one arm from always occupying the same
# slot inside a block.  It is a design choice, not a measurement change; the
# seed-level RNG and every recorded value are untouched.

RUN_ORDER_SCHEMA = 1
RUN_ORDER_DESIGNS = ('randomized_complete_block_balanced', 'inferred_no_plan')


def _run_order_u64(*parts):
    """Stable 64-bit draw: Python's hash() is randomized per process."""
    raw = '\x1f'.join(str(p) for p in parts).encode('utf-8')
    return int.from_bytes(hashlib.sha256(raw).digest()[:8], 'big')


def _run_order_default_label(cell, block_key):
    if isinstance(cell, (tuple, list)) and len(cell) >= 2:
        return f'{cell[0]}::seed{block_key(cell)}'
    return f'{cell}::seed{block_key(cell)}'


def blocked_run_order(cells, *, block_key, seed=0, balance_positions=True,
                      balance_key=None):
    """Return a deterministic randomized complete-block run order.

    ``block_key(cell)`` names the block (normally the seed).  Cells inside a
    block are run contiguously; the block order itself is sorted by key so a
    resumed or parallel pass sees the same plan.  ``balance_key(cell)`` names
    the within-block treatment (normally the arm), which is what position
    balance rotates.  It defaults to the first element of a ``(variant, seed)``
    tuple.

    When every block contains the same set of treatment keys,
    ``balance_positions`` uses a seeded base permutation plus a per-block
    rotation, so no arm always occupies the first slot (a fixed "first arm is
    always the baseline" order would leave a warm-up order effect confounded
    with arm).  Otherwise each block is shuffled independently with the same
    stable hash.

    The function is pure and deterministic: the same cells, block key and
    design seed always give the same order, independent of ``PYTHONHASHSEED``.
    It never changes a training value; each cell still seeds its own RNG.
    """
    if not callable(block_key):
        raise TypeError('block_key must be callable')
    if isinstance(seed, bool) or not isinstance(seed, numbers.Integral):
        raise TypeError(f'run-order seed must be an integer, got {seed!r}')
    seed = int(seed)
    try:
        raw = [tuple(c) if isinstance(c, list) else c for c in cells]
    except TypeError as e:
        raise TypeError(f'cells must be an iterable of hashable cells: {e}') from e
    if not raw:
        return []
    groups = collections.OrderedDict()
    seen = set()
    for cell in raw:
        try:
            hash(cell)
        except TypeError as e:
            raise TypeError(
                f'run-order cells must be hashable tuples (got '
                f'{type(cell).__name__}); a dict/list cell cannot be a resume '
                f'identity') from e
        if cell in seen:
            raise ValueError(f'duplicate run-order cell {cell!r}; training it '
                             'twice would corrupt the (arm, seed) identity')
        seen.add(cell)
        key = block_key(cell)
        try:
            hash(key)
        except TypeError as e:
            raise TypeError(f'block key for {cell!r} must be hashable') from e
        groups.setdefault(key, []).append(cell)
    keys = list(groups)
    try:
        keys.sort()
    except TypeError:
        keys.sort(key=repr)

    def _treatment(cell):
        if balance_key is not None:
            return balance_key(cell)
        if isinstance(cell, (tuple, list)) and cell:
            return cell[0]
        return cell

    ref = max(groups.values(), key=len)
    ref_treatments = [_treatment(c) for c in ref]
    try:
        hash(tuple(ref_treatments))
    except TypeError as e:
        raise TypeError('balance_key values must be hashable') from e
    if len(set(ref_treatments)) != len(ref_treatments):
        raise ValueError(
            'balance_key is not unique inside a block; the position-rotation '
            'design cannot identify the cell to place')
    treatment_set = set(ref_treatments)
    same_sets = all(
        len(g) == len(ref)
        and {_treatment(c) for c in g} == treatment_set
        for g in groups.values())
    base = list(ref_treatments)
    for i in range(len(base) - 1, 0, -1):
        j = _run_order_u64(seed, 'base', i) % (i + 1)
        base[i], base[j] = base[j], base[i]
    out = []
    for bi, key in enumerate(keys):
        group = list(groups[key])
        if balance_positions and same_sets and len(base) > 1:
            by_treatment = {_treatment(c): c for c in group}
            if len(by_treatment) != len(group):
                raise ValueError(f'block {key!r} has duplicate treatment keys')
            offset = (seed + bi) % len(base)
            rotated = base[offset:] + base[:offset]
            group = [by_treatment[t] for t in rotated]
        elif len(group) > 1:
            for i in range(len(group) - 1, 0, -1):
                j = _run_order_u64(seed, repr(key), i) % (i + 1)
                group[i], group[j] = group[j], group[i]
        out.extend(group)
    return out


def build_run_order_plan(cells, *, block_key, seed=0, block_name='seed',
                         variant_key=None, label=None,
                         balance_positions=True, balance_key=None,
                         design_name='randomized_complete_block_balanced',
                         created_at=None):
    """Build the JSON-safe plan written next to a panel's summary.

    Only the plan is new metadata; the caller still trains the same cells with
    the same seeds and hyperparameters.  ``blocks`` records the within-block
    order and ``planned_cells`` the flat order, so a later audit can check both
    the design and the actual event order without re-deriving them.
    """
    if design_name not in RUN_ORDER_DESIGNS:
        raise ValueError(f'unknown run-order design {design_name!r}')
    raw = [tuple(c) if isinstance(c, list) else c for c in cells]
    if not raw:
        raise ValueError('a run-order plan needs at least one cell')
    ordered = blocked_run_order(raw, block_key=block_key, seed=seed,
                                balance_positions=balance_positions,
                                balance_key=balance_key)

    def _variant(cell):
        if variant_key is not None:
            return str(variant_key(cell))
        if isinstance(cell, (tuple, list)) and cell:
            return str(cell[0])
        return str(cell)

    def _label(cell):
        return _run_order_default_label(cell, block_key) if label is None else str(label(cell))

    labels = [_label(c) for c in ordered]
    if len(set(labels)) != len(labels):
        raise ValueError('run-order labels are not unique; a label is the '
                         'cell identity used by the audit')
    variants = []
    blocks = collections.OrderedDict()
    cell_blocks = {}
    cell_variants = {}
    for cell in ordered:
        v = _variant(cell)
        b = str(block_key(cell))
        if v not in variants:
            variants.append(v)
        blocks.setdefault(b, []).append(v)
        cell_blocks[_label(cell)] = b
        cell_variants[_label(cell)] = v
    _same_blocks = all(
        len(vs) == len(variants) and set(vs) == set(variants)
        for vs in blocks.values())
    _pos_policy = ('cyclic_base_rotation'
                   if balance_positions and _same_blocks
                   else 'independent_block_shuffle')
    return {
        'kind': 'run_order',
        'schema': RUN_ORDER_SCHEMA,
        'created_at': created_at or time.strftime('%Y-%m-%dT%H:%M:%S'),
        'design': {
            'name': design_name,
            'block': block_name,
            'design_seed': int(seed),
            'randomized': design_name != 'inferred_no_plan',
            'position_balance': _pos_policy,
            'execution': 'cells_inside_a_block_are_contiguous',
        },
        'variants': variants,
        'seeds': list(blocks),
        'blocks': {b: list(vs) for b, vs in blocks.items()},
        'planned_cells': labels,
        'cell_blocks': cell_blocks,
        'cell_variants': cell_variants,
    }


def run_order_balance(plan, actual_order=None):
    """Audit a run-order plan and, optionally, the order actually observed.

    The plan-level contract is deliberately stronger than "the cells were
    shuffled": every block must contain every declared arm exactly once
    (complete blocks), and each arm's slot counts across blocks must differ by
    at most one (position balance).  An arm-major execution — every seed of
    one arm, then every seed of the next — is a FAIL, because arm and calendar
    time are then perfectly confounded and no seed-level p-value can repair it.

    ``actual_order`` is a list of cell labels in execution (start-time) order.
    Missing cells are allowed on a partial/resumed panel; a complete actual
    order that is arm-major is a failure, while a complete order that merely
    deviates from the planned permutation is a warning (parallel dispatch can
    legitimately reorder starts).  This audit is descriptive of the design and
    never changes a PPL, seed or decision rule.
    """
    out = {'kind': 'run_order_balance', 'status': 'ok', 'problems': [],
           'warnings': [], 'n_blocks': 0, 'n_cells': 0, 'n_variants': 0,
           'complete_blocks': 0, 'arm_major': False,
           'position_balanced': None, 'design_ok': False}
    if not isinstance(plan, dict):
        out['status'] = 'fail'
        out['problems'].append(f'run-order plan must be an object, got {type(plan).__name__}')
        return out
    design = plan.get('design') if isinstance(plan.get('design'), dict) else {}
    name = design.get('name')
    if name not in RUN_ORDER_DESIGNS:
        out['problems'].append(
            f'design.name={name!r} is not one of {list(RUN_ORDER_DESIGNS)}')
    elif name != 'inferred_no_plan':
        if design.get('randomized') is not True:
            out['problems'].append('a randomized run-order design must set randomized=true')
        _ds = design.get('design_seed')
        if isinstance(_ds, (bool, np.bool_)) or not isinstance(_ds, numbers.Integral):
            out['problems'].append(
                f'design.design_seed={_ds!r} must be an integer; a random '
                'sequence without a recorded seed cannot be reproduced')
    blocks = plan.get('blocks')
    variants = plan.get('variants')
    if not isinstance(blocks, dict) or not blocks:
        out['problems'].append('plan.blocks must be a non-empty object')
        blocks = {}
    if not isinstance(variants, list) or not variants:
        variants = list(dict.fromkeys(
            v for vs in blocks.values() if isinstance(vs, list) for v in vs))
        if variants:
            out['warnings'].append('plan.variants was missing; recovered it from blocks')
    variants = [str(v) for v in variants]
    if len(set(variants)) != len(variants):
        out['problems'].append('plan.variants contains duplicates')
    out['n_variants'] = len(variants)
    variant_set = set(variants)
    position_counts = {v: [0] * max(1, len(variants)) for v in variants}
    # When the design was inferred from events, an incomplete block is just a
    # partial observation, not proof of a bad plan; only arm-major is a hard
    # failure there.  A recorded plan is held to the full complete-block
    # contract.
    _issue = out['warnings'] if name == 'inferred_no_plan' else out['problems']
    complete = 0
    for b, vs in blocks.items():
        if not isinstance(vs, list) or not vs:
            _issue.append(f'block {b!r} must be a non-empty list')
            continue
        vs = [str(v) for v in vs]
        if len(vs) != len(set(vs)):
            _issue.append(f'block {b!r} contains a duplicate arm')
        if set(vs) == variant_set and len(vs) == len(variants):
            complete += 1
        else:
            _issue.append(
                f'block {b!r} is not a complete block: got {vs!r}, '
                f'expected each of {variants!r} exactly once')
        for i, v in enumerate(vs):
            if v in position_counts and i < len(position_counts[v]):
                position_counts[v][i] += 1
    out['n_blocks'] = len(blocks)
    out['complete_blocks'] = complete
    out['n_cells'] = sum(len(vs) for vs in blocks.values() if isinstance(vs, list))
    if not variants:
        out['problems'].append('plan declares no arms')
    if blocks and variants and complete != len(blocks):
        out['warnings'].append(
            f'{len(blocks) - complete} block(s) are incomplete; a partial '
            'panel can still be described, but it is not a complete-block design')
    balances = []
    for v, counts in position_counts.items():
        if counts:
            balances.append(max(counts) - min(counts))
    out['position_balanced'] = (max(balances) <= 1) if balances else None
    _pos_policy = design.get('position_balance')
    if out['position_balanced'] is False and _pos_policy != 'independent_block_shuffle':
        _issue.append(
            'arm positions are not balanced across blocks (an arm always '
            'occupies the same slot): within-block order is confounded with arm')
    out['arm_major'] = bool(
        len(variants) > 1 and len(blocks) > 1
        and all(isinstance(vs, list) and len(vs) == 1
                for vs in blocks.values()))
    if out['arm_major']:
        out['problems'].append(
            'every block contains only one arm: the panel is arm-major, so arm '
            'and calendar time are perfectly confounded')
    out['design_ok'] = bool(
        not out['problems'] and complete == len(blocks)
        and (out['position_balanced'] is not False
             or _pos_policy == 'independent_block_shuffle'))
    if name == 'inferred_no_plan':
        out['warnings'].append(
            'the run order was inferred from event timestamps because no '
            'run_order.json plan exists; the design itself cannot be verified')
        out['status'] = 'fail' if out['arm_major'] else 'not_verifiable_locally'
    elif out['problems']:
        out['status'] = 'fail'
    if actual_order is not None and not isinstance(actual_order, (list, tuple)):
        out['problems'].append('actual_order must be a list of cell labels')
    elif actual_order is not None:
        planned = plan.get('planned_cells')
        planned = [str(x) for x in planned] if isinstance(planned, list) else []
        label_block = plan.get('cell_blocks') if isinstance(plan.get('cell_blocks'), dict) else {}
        label_variant = plan.get('cell_variants') if isinstance(plan.get('cell_variants'), dict) else {}
        seen = set()
        actual_blocks = collections.OrderedDict()
        for lab in actual_order:
            lab = str(lab)
            if lab in seen:
                out['problems'].append(f'actual order repeats cell {lab!r}')
                continue
            seen.add(lab)
            b = label_block.get(lab)
            if b is None:
                out['problems'].append(
                    f'actual order names {lab!r}, which is not in the plan')
                continue
            actual_blocks.setdefault(str(b), []).append(lab)
        if planned:
            planned_set = set(planned)
            missing = [x for x in planned if x not in seen]
            extra = [x for x in seen if x not in planned_set]
            if extra:
                out['problems'].append(f'actual order contains unplanned cells: {extra[:5]}')
            out['actual'] = {
                'n_observed': len(seen),
                'n_planned': len(planned),
                'complete': not missing and not extra,
                'missing_cells': missing[:20],
            }
            if not missing and not extra:
                # `actual_blocks` groups by seed, so even an arm-major run has
                # every arm present in each seed group; it is the GLOBAL
                # sequence that reveals the confound.  Count maximal runs of
                # the same arm: a legacy arm-major run has one run per arm
                # (arm A seeds 0..n, then arm B seeds 0..n, ...), while a
                # seed-blocked run switches arm inside every block.
                seq_variants = []
                for lab in actual_order:
                    lab = str(lab)
                    v = label_variant.get(lab)
                    if v is None:
                        try:
                            v = lab.rsplit('::seed', 1)[0]
                        except ValueError:
                            v = lab
                    seq_variants.append(str(v))
                runs = 0
                for i, v in enumerate(seq_variants):
                    if i == 0 or v != seq_variants[i - 1]:
                        runs += 1
                variant_counts = collections.Counter(seq_variants)
                out['actual']['variant_runs'] = runs
                out['actual']['n_arms'] = len(variant_counts)
                actual_arm_major = bool(
                    len(actual_blocks) > 1
                    and len(variant_counts) > 1
                    and runs == len(variant_counts)
                    and all(n == len(actual_blocks)
                            for n in variant_counts.values()))
                if actual_arm_major:
                    out['arm_major'] = True
                    out['problems'].append(
                        'the completed run is arm-major even though the plan was '
                        'blocked; the driver did not honour the run-order plan')
        # Group the plan once instead of rescanning every planned cell for
        # every block: a future panel with many seeds would otherwise make the
        # audit quadratic in the number of cells.
        planned_by_block = collections.OrderedDict()
        for x in planned:
            planned_by_block.setdefault(str(label_block.get(x)), []).append(x)
        for b, seq in actual_blocks.items():
            plan_seq = planned_by_block.get(str(b), [])
            it = iter(plan_seq)
            if not all(any(x == y for y in it) for x in seq):
                out['warnings'].append(
                    f'block {b!r}: actual start order {seq!r} is not a '
                    f'subsequence of the planned order {plan_seq!r}')
    if out['problems'] and out['status'] != 'fail':
        out['status'] = 'fail'
    return out


def write_run_order(outdir, plan):
    """Persist the run-order plan beside the panel's other provenance."""
    if not isinstance(plan, dict) or plan.get('kind') != 'run_order':
        raise ValueError('write_run_order expects a plan from build_run_order_plan')
    path = os.path.join(outdir, 'run_order.json')
    atomic_write_json(path, plan)
    return path


def _plan_run(cfg, summary_path, fp):
    """Resume-check every (seed x variant) cell up front and return the cells
    that still need to run.

    Stale / synthesized / non-measurable records are dropped (under the lock)
    BEFORE any training starts, so a later failure can never leave a stale
    reading in place looking like this attempt's result.  With parallel
    dispatch this check runs once in the parent, before any child spawns."""
    summary = locked_json_read(summary_path)
    cells = []
    stale_dropped = []
    for seed in cfg['seeds']:
        for v in cfg['variants']:
            key = f'{v}::seed{seed}'
            _drop_msg = None
            _drop_is_stale = False
            if key in summary and 'ppl' in summary.get(key, {}):
                old = summary[key]
                if not ppl_is_usable(old.get('ppl')):
                    _drop_msg = f"[resume] {key} holds a NON-MEASURABLE ppl ({old.get('ppl')!r}) — every statistic in this repo refuses it (`ppl_is_usable`), so counting it as 'already completed' would drop the seed from the tables silently. DROPPING it and retraining"
                elif old.get('synthesized'):
                    _drop_msg = f'[resume] {key} is a SYNTHESIZED record (reconstructed from an old aggregate.json, no weights) — DROPPING it and retraining'
                elif old.get('run_cfg') is None:
                    _drop_msg = f"[resume] {key} has no config fingerprint (predates fingerprinting) — re-running and overwriting; the STALE record is dropped before retraining, so a failed or truncated attempt cannot leave it in place looking like this attempt's result"
                    _drop_is_stale = True
                elif old.get('run_cfg') == fp:
                    print(f'[skip] {key} already completed (resume)')
                    continue
                else:
                    _drop_msg = f"[resume] {key} was run under a DIFFERENT config ({old['run_cfg']} != {fp}) — re-running and overwriting; the STALE record is dropped before retraining, so a failed or truncated attempt cannot leave it in place looking like this attempt's result"
                    _drop_is_stale = True
            if _drop_msg is not None:
                print(_drop_msg)
                summary.pop(key, None)

                def _drop_cell(s, _key=key):
                    s.pop(_key, None)
                    return s
                locked_json_update(summary_path, _drop_cell)
                if _drop_is_stale:
                    stale_dropped.append(key)
            cells.append((v, seed))
    return cells, stale_dropped


def _run_cell(cfg, v, seed, *, guard=None, ratios=None, fp=None, train_ids=None, val_batch=None, vocab=None, val_bnd=None, prebook=False, prov=None):
    """Run exactly ONE (variant, seed) training cell and merge its record into
    outdir/summary.json under the lock.

    Used by the serial loop (in-process) and by par.py children (prebook=True:
    the projected time is reserved in the shared TimeGuard before training and
    refunded after recording the actual seconds, so concurrently launching
    children still respect the shared run-time cap)."""
    d = cfg.get('d', 256)
    n_layers = cfg.get('n_layers', 6)
    n_heads = cfg.get('n_heads', 8)
    d_head = cfg.get('d_head', 32)
    outdir = cfg['outdir']
    summary_path = os.path.join(outdir, 'summary.json')
    key = f'{v}::seed{seed}'
    ratios = {} if ratios is None else ratios
    if v not in ratios:
        ratios[v] = variant_mlp_ratio(v, vocab, d=d, n_layers=n_layers, n_heads=n_heads, d_head=d_head, seq_len=cfg['seq_len'], matched=cfg.get('matched'), ref_variant=cfg.get('mlp_match_ref', 'csa_dynamic'))
    out = {'status': 'ok', 'key': key, 'variant': v, 'seed': seed}
    _run_id = new_experiment_id('cell')
    _started_at = time.strftime('%Y-%m-%dT%H:%M:%S')
    _t_start = time.time()
    out['run_id'] = _run_id
    deadline_ts = None
    booked = 0.0
    _book_tok = f'run|{key}|pid{os.getpid()}'
    if guard is not None:
        est = guard.estimate_seconds(cfg['steps'], d=d, n_layers=n_layers, seq_len=cfg['seq_len'], batch_size=cfg['batch_size'], variant=v)
        if prebook and est:
            guard.book(est, token=_book_tok)
            booked = est
        if not guard.can_start(0 if booked else est):
            if booked:
                guard.book(-booked, token=_book_tok)
                booked = 0.0
            print(f'[cap] SKIP {key}: projected {est / 3600:.2f} h would pass the configured cap (headroom {max(guard.total_hours - guard.spent_hours(), 0.0):.2f} h)')
            out['status'] = 'skipped_cap'
            log_experiment_event(outdir, {'kind': 'cell', 'run_id': _run_id, 'status': 'skipped_cap', 'key': key, 'variant': v, 'seed': int(seed), 'run_cfg': fp, 'code': code_stamp(), 'started_at': _started_at, 'finished_at': time.strftime('%Y-%m-%dT%H:%M:%S'), 'reason': 'projected runtime would pass the configured cap'})
            return out
        deadline_ts = guard.deadline_ts()
        if booked:
            deadline_ts += booked
        print(f'[cap] {key}: projected {est / 60:.0f} min, booked so far {guard.state['booked_seconds'] / 3600:.2f} h')
    t_run = time.time()
    rec = None
    try:
        try:
            _save_mode = cfg.get('save_ckpt', os.environ.get('CSA_SAVE_CKPT', 'both'))
            _ckpt_dir = cfg.get('ckpt_dir') or os.path.join(outdir, 'checkpoints')
            rec = train_variant(v, train_ids, val_batch, vocab, seed=seed, d=d, n_layers=n_layers, n_heads=n_heads, d_head=d_head, seq_len=cfg['seq_len'], batch_size=cfg['batch_size'], steps=cfg['steps'], lr=cfg['lr'], weight_decay=cfg['weight_decay'], warmup=cfg['warmup'], comp_lambda=cfg['comp_lambda'], delta_lr_mult=cfg.get('delta_lr_mult', 10.0), eval_every=cfg.get('eval_every', 0), eval_subset=cfg.get('eval_subset', 128), val_bnd=val_bnd, mlp_ratio=ratios[v], deadline_ts=deadline_ts, save_ckpt=_save_mode, ckpt_dir=_ckpt_dir, diag_every=cfg.get('diag_every'), measure_eff=cfg.get('measure_efficiency', True), measure_eff_sweep=cfg.get('measure_efficiency_sweep', False), amp_dtype=cfg.get('amp_dtype', 'auto'), eager_batch=cfg.get('eager_batch', 'auto'), early_stop_patience=cfg.get('early_stop_patience'), early_stop_min_delta=cfg.get('early_stop_min_delta', 0.0))
            _prov = prov if prov is not None else experiment_provenance(cfg, train_ids=train_ids, val_batch=val_batch, vocab=vocab)
            _hp = run_hyperparameters(cfg, seed=seed, d=d, n_layers=n_layers, n_heads=n_heads, d_head=d_head, vocab=vocab, mlp_ratio=ratios[v], data_version=_prov.get('data', {}).get('data_version'), amp_dtype=rec.get('amp_dtype', 'auto'), eager_batch=rec.get('eager_batch', 'auto'))
            _curve_ref = None
            _curve_losses = []
            _curve_ph = []
            _curve_move_ph = False
            if not rec.get('cap_truncated'):
                _curve_ref, _curve_losses, _curve_ph, _curve_move_ph = _write_cell_curve(outdir, key, rec)
            _curve_sha = (_file_sha256(os.path.join(outdir, _curve_ref))
                          if _curve_ref else None)

            def _apply(summary):
                if rec.get('cap_truncated'):
                    _prev_ok = ppl_is_usable((summary.get(key) or {}).get('ppl'))
                    print(f'[cap] {key} was truncated after {rec.get('steps_done')} steps — its partial record is DISCARDED (it holds no `ppl`); ' + ('keeping the previous record instead.' if _prev_ok else 'the key is left ABSENT, not written as a stub.') + ' Raise RUN_CAP and re-run to retry this cell.')
                    if not _prev_ok:
                        summary.pop(key, None)
                        out['truncated'] = True
                else:
                    rec['run_cfg'] = fp
                    rec['_code'] = code_stamp()
                    assert fp.endswith(f'_cs{rec['_code']}'), (fp, rec['_code'])
                    rec['provenance'] = _prov
                    rec['hyperparams'] = _hp
                    rec['data_fp'] = _prov['data'].get('train_fp')
                    rec['val_fp'] = _prov['data'].get('val_fp')
                    rec['data_version'] = _prov['data'].get('data_version')
                    rec['corpus_fp'] = _prov['data'].get('corpus_fp')
                    rec['run_id'] = _run_id
                    rec['started_at'] = _started_at
                    rec['finished_at'] = time.strftime('%Y-%m-%dT%H:%M:%S')
                    if os.path.exists(os.path.join(outdir, 'overfit_sanity.json')):
                        rec['sanity_ref'] = 'overfit_sanity.json'
                    _rec_out = rec
                    _has_curve = bool(_curve_ref) or _curve_move_ph
                    if _has_curve:
                        _rec_out = dict(rec)
                        if _curve_ref:
                            _rec_out.pop('losses', None)
                            _rec_out.pop('delta_trace', None)
                        if _curve_move_ph:
                            _rec_out.pop('ppl_history', None)
                    if _curve_ref:
                        _cs = _finite_curve(_curve_losses)
                        _rec_out['curve_ref'] = _curve_ref
                        _rec_out['curve_sha256'] = _curve_sha
                        _rec_out['curve_n_points'] = _cs['n_points']
                        _rec_out['curve_first'] = _curve_losses[0] if _curve_losses else None
                        _rec_out['curve_last'] = _cs['last']
                        _rec_out['curve_best'] = _cs['min']
                        _rec_out['curve_n_nonfinite'] = _cs['n_nonfinite']
                        _rec_out['curve_first_nonfinite_index'] = _cs['first_nonfinite_index']
                    elif _curve_losses:
                        _rec_out['curve_n_points'] = len(_curve_losses)
                    if _curve_move_ph:
                        _rec_out['ppl_history_ref'] = _curve_ref
                        _rec_out['ppl_history_sha256'] = _curve_sha
                        _rec_out['ppl_history_n_points'] = len(_curve_ph)
                    elif _curve_ph:
                        _rec_out['ppl_history_n_points'] = len(_curve_ph)
                    summary[key] = _rec_out
                return summary
            locked_json_update(summary_path, _apply, indent=None)
            if out.get('truncated'):
                out['status'] = 'truncated'
                log_experiment_event(outdir, {'kind': 'cell', 'run_id': _run_id, 'status': 'truncated', 'key': key, 'variant': v, 'seed': int(seed), 'run_cfg': fp, 'code': code_stamp(), 'started_at': _started_at, 'finished_at': time.strftime('%Y-%m-%dT%H:%M:%S'), 'steps_done': rec.get('steps_done'), 'reason': 'hard runtime cap reached; partial record not written'})
            elif isinstance(rec, dict) and not rec.get('cap_truncated'):
                _losses = rec.get('losses') if isinstance(rec.get('losses'), list) else []
                _cs = _finite_curve(_losses)
                _ledger_losses, _losses_n, _losses_down = _ledger_curve(_losses)
                _ledger_ph, _ph_n, _ph_down = _ledger_curve_points(rec.get('ppl_history'))
                _ev = {'kind': 'cell', 'run_id': _run_id, 'status': 'ok', 'started_at': _started_at, 'finished_at': rec.get('finished_at'), 'elapsed_s': time.time() - _t_start, 'key': key, 'variant': v, 'seed': int(seed), 'run_cfg': fp, 'code': rec.get('_code') or code_stamp(), 'provenance': rec.get('provenance'), 'hyperparams': rec.get('hyperparams'), 'data_fp': rec.get('data_fp'), 'val_fp': rec.get('val_fp'), 'data_version': rec.get('data_version'), 'rng_fp': rec.get('rng_fp'), 'exec_fp': rec.get('exec_fp'), 'metrics': {'ppl': rec.get('ppl'), 'params': rec.get('params'), 'steps': rec.get('steps'), 'steps_completed': rec.get('steps_completed'), 'early_stop': rec.get('early_stop'), 'tokens_seen': rec.get('tokens_seen'), 'train_time_s': rec.get('train_time_s'), 'final_loss_smoothed': rec.get('final_loss_smoothed'), 'best_val_ppl': rec.get('best_val_ppl'), 'final_minus_best': rec.get('final_minus_best')}, 'curve_summary': {'n_points': _cs['n_points'], 'n_nonfinite': _cs['n_nonfinite'], 'first': _losses[0] if _losses else None, 'last': _cs['last'], 'best': _cs['min']}, 'curve_health': rec.get('curve_health'), 'instability_diagnosis': rec.get('instability_diagnosis'), 'opt_diag_summary': rec.get('opt_diag_summary'), 'checkpoints': rec.get('checkpoints'), 'efficiency': rec.get('efficiency'), 'losses': _ledger_losses, 'losses_n_points': _losses_n, 'losses_downsampled': _losses_down, 'ppl_history': _ledger_ph, 'ppl_history_n_points': _ph_n, 'ppl_history_downsampled': _ph_down, 'curve_ref': _curve_ref or rec.get('curve_ref'), 'sanity_ref': rec.get('sanity_ref')}
                log_experiment_event(outdir, _ev)
        except Exception as e:
            import traceback
            import sys as _sys
            _err = e
            _err_tb = traceback.format_exc()
            out['status'] = 'error'
            out['error'] = f'{_err}'

            def _apply_err(summary):
                if key in summary and ppl_is_usable((summary.get(key) or {}).get('ppl')):
                    print(f'[{key}] FAILED: {_err} — keeping the previous MEASURED record (the error record holds no `ppl` and must not replace it); the failed attempt is still booked to the guard below.')
                    print(_err_tb, file=_sys.stderr)
                else:
                    summary[key] = {'variant': v, 'seed': seed, 'error': _err_tb}
                    print(f'[{key}] FAILED: {_err}')
                return summary
            locked_json_update(summary_path, _apply_err, indent=None)
            log_experiment_event(outdir, {'kind': 'cell', 'run_id': _run_id, 'status': 'error', 'started_at': _started_at, 'finished_at': time.strftime('%Y-%m-%dT%H:%M:%S'), 'elapsed_s': time.time() - _t_start, 'key': key, 'variant': v, 'seed': int(seed), 'run_cfg': fp, 'code': code_stamp(), 'error': f'{_err}', 'traceback': _err_tb})
    finally:
        if guard is not None:
            steps_done = 0
            calib_s = None
            if isinstance(rec, dict) and rec.get('steps_done'):
                steps_done = int(rec['steps_done'])
            elif isinstance(rec, dict) and 'ppl' in rec:
                steps_done = int(rec.get('steps_completed') or cfg['steps'])
                calib_s = rec.get('train_time_s')
            guard.record_run(time.time() - t_run, steps_done, d, n_layers, cfg['seq_len'], cfg['batch_size'], calib_seconds=calib_s, variant=v)
            if booked:
                guard.book(-booked, token=_book_tok)
    gc.collect()
    return out


def run_cell_job(job):
    """Child-process entry for one `run`-kind cell (invoked by par.py).

    Re-serves the corpus from the same on-disk cache, recomputes the identical
    fingerprint, and runs the cell with pre-booked guard accounting.  The
    data-load seconds are NOT booked here: the parent already booked the
    phase's data load once, exactly like the serial path."""
    cfg = dict(job['cfg'])
    _matched = cfg.get('matched')
    if isinstance(_matched, (list, tuple)):
        cfg['matched'] = set(_matched)
    guard = TimeGuard(job['guard_cap']) if job.get('guard_cap') else None
    # Seed the child BEFORE the corpus is served, exactly like run() does in
    # the parent and like the v7/v10 child entries (run_warmup_cell_job /
    # run_probe_cell_job) already do: today's loaders consume no RNG, but a
    # future loader step that does (a sampled val slice, a DataLoader shuffle)
    # must not silently become the one unseeded construction path.
    set_seed(int(job['seed']))
    train_ids, val_batch, vocab, _, val_bnd = load_run_corpus(cfg)
    d = cfg.get('d', 256)
    n_layers = cfg.get('n_layers', 6)
    n_heads = cfg.get('n_heads', 8)
    d_head = cfg.get('d_head', 32)
    if torch.cuda.is_available():
        _pin_cuda_determinism()
    # The parent already computed the identical fingerprint/provenance over
    # this corpus; reuse them.  If an older job payload lacks the resolved
    # implementation modes, resolve them from THIS child's device and pin them
    # into the config so the fingerprint and the training record agree.
    if 'amp_dtype' not in cfg or 'eager_batch' not in cfg:
        _amp_mode, _eager_mode = _resolve_impl_modes(cfg, device=DEVICE)
        cfg['amp_dtype'] = 'fp32' if _amp_mode is None else _amp_mode
        cfg['eager_batch'] = bool(_eager_mode)
    fp = job.get('fp') or _run_fp(cfg, d, n_layers, n_heads, d_head, vocab, train_ids, val_batch, device=DEVICE)
    return _run_cell(cfg, job['v'], job['seed'], guard=guard, ratios={}, fp=fp, train_ids=train_ids, val_batch=val_batch, vocab=vocab, val_bnd=val_bnd, prebook=True, prov=job.get('prov'))


def preflight_fingerprint(cfg, *, stage, vocab=None, data_fp=None, probe_cfg=None):
    """Stable fingerprint for a standalone pre-flight artifact.

    Used when the check writes evidence before/independently of a panel
    ``run_cfg`` (m0/run_gapfill pre-flight dirs, and a synthetic probe that
    fails before the corpus is loaded).  It is deliberately not a resume key:
    it exists so the evidence can state which config/code/data/probe produced
    it."""
    blob = json.dumps({
        'config': _jsonable(cfg),
        'stage': str(stage),
        'vocab': None if vocab is None else int(vocab),
        'data_fp': data_fp,
        'probe_cfg': _jsonable(probe_cfg) if probe_cfg is not None else None,
        'train_knobs': training_knobs_fingerprint(),
        'code': code_stamp(),
    }, sort_keys=True, separators=(',', ':'), ensure_ascii=True)
    return 'preflight-' + hashlib.sha256(blob.encode('utf-8')).hexdigest()[:16]

def _is_confirmatory_cfg(cfg):
    """A confirmation / scale panel defaults to strict determinism + a
    mandatory real-architecture reproducibility check.

    An explicit ``require_repro``/``confirm`` flag always wins; otherwise the
    B-tier scale geometry (d>=512, multiple seeds) is treated as confirmatory.
    Small exploratory/test panels keep the advisory path."""
    for _k in ('confirm', 'confirmation', 'require_repro'):
        if cfg.get(_k) is not None:
            return bool(cfg.get(_k))
    try:
        _d = int(cfg.get('d', 256))
        _nseeds = len(cfg.get('seeds') or [])
    except (TypeError, ValueError, OverflowError):
        return False
    return bool(_d >= 512 and _nseeds >= 2)

def _record_failed_panel(outdir, cfg, run_cfg, prov, *, stage, error, planned_cells=None):
    """Persist a failed pre-flight as a first-class panel record.

    Evidence files (`overfit_sanity.json`, `seed_contract.json`, ...) and the
    JSONL ledger are already written before a hard stop, but without a
    manifest a failed attempt had no single file carrying the code version,
    config, seed plan and failure stage.

    An existing entry for the SAME run_cfg is never erased: a completed or
    already-incomplete panel keeps its cells, and the failure is appended to
    the ledger.  A panel that was left in ``running`` state (the process was
    killed, or a later pre-flight refused) is flipped to ``failed`` so a run
    that never finished cannot keep looking live forever.  This is the
    run-state reconciliation, not a retry: no cell measurement is changed.
    """
    try:
        mpath = os.path.join(outdir, 'run_manifest.json')
        _existing_entry = None
        if os.path.exists(mpath):
            try:
                with open(mpath, encoding='utf-8') as _mf:
                    _existing = json.load(_mf)
                if isinstance(_existing, dict):
                    _existing_entry = (_existing.get('panels') or {}).get(run_cfg)
            except Exception:
                _existing_entry = None
        _prev_status = str((_existing_entry or {}).get('status') or '').lower()
        if _prev_status == 'complete':
            # A completed panel is evidence; a later failed pre-flight with
            # the same config must not rewrite it into a failed run.
            log_experiment_event(outdir, {
                'kind': 'panel_finish', 'tracking_schema': 2,
                'status': 'failed', 'stage': str(stage), 'run_cfg': run_cfg,
                'code': code_stamp(), 'provenance': prov, 'error': f'{error}',
                'planned_cells': list(planned_cells or []),
                'note': 'existing COMPLETE run_manifest entry preserved; '
                        'this failed attempt is recorded only in the ledger',
            })
            return mpath
        # Re-read the measured cells (if any) so the failed entry still carries
        # everything that DID complete.  A corrupt summary is not a reason to
        # overwrite it; in that case the previous cells are preserved through
        # write_run_manifest's merge and the failure is still recorded.
        try:
            _summary = _read_summary_json(os.path.join(outdir, 'summary.json'))
        except Exception:
            _summary = {}
        write_run_manifest(outdir, cfg, run_cfg, prov, _summary, status='failed',
                           planned_cells=planned_cells,
                           started_at=((_existing_entry or {}).get('created_at')
                                       or time.strftime('%Y-%m-%dT%H:%M:%S')))
        log_experiment_event(outdir, {
            'kind': 'panel_finish', 'tracking_schema': 2,
            'status': 'failed', 'stage': str(stage), 'run_cfg': run_cfg,
            'code': code_stamp(), 'provenance': prov, 'error': f'{error}',
            'planned_cells': list(planned_cells or []),
            'previous_status': (_prev_status or None),
            'note': ('running/incomplete panel reconciled to failed; measured '
                     'cells were preserved' if _existing_entry else
                     'first failed attempt for this run_cfg'),
        })
        return mpath
    except Exception as _mfe:
        print(f'[track] WARNING: could not persist the failed-panel manifest ({type(_mfe).__name__}: {_mfe})')
        return None


def run(cfg=None, seeds=None, guard=None, label='', par=None):
    cfg = dict(RUN) if cfg is None else dict(cfg)
    # Freeze the scale protocol into the cfg before any probe/fingerprint so
    # every downstream consumer (loader, run_cfg, data_version, resume check)
    # reads the SAME declared sizes instead of falling back to current code
    # defaults independently.
    cfg = apply_data_protocol(cfg, allow_unknown=True)
    if seeds is not None:
        cfg['seeds'] = list(seeds)
    d = cfg.get('d', 256)
    n_layers = cfg.get('n_layers', 6)
    n_heads = cfg.get('n_heads', 8)
    d_head = cfg.get('d_head', 32)
    outdir = cfg['outdir']
    os.makedirs(outdir, exist_ok=True)
    # Normalise the panel axes BEFORE any probe, fingerprint or manifest is
    # written.  Without this a duplicate seed plans/trains the same cell twice
    # and a cfg without `seeds` trains the fallback seed while the manifest
    # records an empty plan.
    _seeds = normalize_seed_list(cfg.get('seeds'))
    _variants = normalize_variant_list(cfg.get('variants'))
    cfg['seeds'] = list(_seeds)
    cfg['variants'] = list(_variants)
    _planned_keys = [f'{v}::seed{seed}' for seed in _seeds for v in _variants]
    _first_seed, _last_seed = _seeds[0], _seeds[-1]
    _arch = {'d': int(d), 'n_layers': int(n_layers), 'n_heads': int(n_heads), 'd_head': int(d_head)}
    # Resolve the numerical implementation ONCE for this panel and persist the
    # concrete values in the config.  The resume fingerprint, the par.py job
    # payloads and the manifest then all describe the same run without any
    # later process having to infer modes from its own CUDA visibility.
    _amp_mode, _eager_mode = _resolve_impl_modes(cfg, device=DEVICE)
    cfg['amp_dtype'] = 'fp32' if _amp_mode is None else _amp_mode
    cfg['eager_batch'] = bool(_eager_mode)
    # A confirmation / scale panel runs with deterministic kernels by default
    # (an explicit CSA_DETERMINISTIC=0 still opts out) and treats the
    # same-machine reproducibility check as mandatory below.
    _confirm = _is_confirmatory_cfg(cfg)
    if _confirm:
        os.environ.setdefault('CSA_DETERMINISTIC', '1')
    # Seed the panel-level data-construction path (tokenizer fitting, cache
    # rebuilds, any future DataLoader setup) before the corpus is served.
    # Per-cell training re-seeds itself inside train_variant, so this cannot
    # change a recorded cell; it only closes an unseeded first-build path.
    set_seed(_first_seed)
    # The probe uses the panel's REAL architecture/MLP and a length that
    # exercises the block geometry rather than a fixed 64-token proxy.
    _probe_seq = probe_seq_len(cfg.get('seq_len', 64))
    _probe_steps = 200
    _probe_batch = 2

    def _panel_ratios(vocab_):
        _r = {}
        for _v in _variants:
            try:
                _r[_v] = variant_mlp_ratio(_v, int(vocab_), d=int(d), n_layers=int(n_layers), n_heads=int(n_heads), d_head=int(d_head), seq_len=int(cfg.get('seq_len', 512)), matched=cfg.get('matched'), ref_variant=cfg.get('mlp_match_ref', 'csa_dynamic'))
            except Exception:
                _r[_v] = None
        return _r

    # Synthetic pre-flight before the corpus load.  The actual-data probe below
    # is the authoritative one; this one still exercises the real model
    # geometry so a shape/gradient fault is caught even if the corpus is slow.
    _pre_vocab = int(cfg.get('vocab_size') or 1024)
    _pre_ratios = _panel_ratios(_pre_vocab)
    try:
        _sanity = list(overfit_guard(_variants, seed=_first_seed, steps=_probe_steps, seq_len=_probe_seq, batch_size=_probe_batch, vocab=_pre_vocab, arch=_arch, mlp_ratio=_pre_ratios))
    except RuntimeError as _fe:
        _prov0 = experiment_provenance(cfg)
        _reports0 = [dict(r) for _k, r in _OVERFIT_REPORTS.items() if _k[0] in set(_variants)]
        _cfg0 = _overfit_probe_config(seed=_first_seed, steps=_probe_steps, seq_len=_probe_seq, batch_size=_probe_batch, vocab=_pre_vocab, target_loss=0.05, target_acc=0.99, arch=_arch, source='synthetic', device=DEVICE)
        _doc0 = {
            'kind': 'small_batch_overfit_sanity_panel', 'stage': 'synthetic_preflight',
            'created_at': time.strftime('%Y-%m-%dT%H:%M:%S'),
            'run_cfg': preflight_fingerprint(cfg, stage='synthetic_overfit', vocab=_pre_vocab, probe_cfg=_cfg0),
            'label': label or outdir, 'passed': False, 'error': f'{_fe}',
            'provenance': _prov0, 'reports': _reports0,
        }
        atomic_write_json(os.path.join(outdir, 'overfit_sanity.json'), _doc0)
        log_experiment_event(outdir, {'kind': 'preflight', 'tracking_schema': 2, 'status': 'failed', 'stage': 'synthetic_overfit', 'run_cfg': _doc0['run_cfg'], 'code': code_stamp(), 'provenance': _prov0, 'error': f'{_fe}', 'sanity': {'passed': False, 'n_reports': len(_reports0)}})
        _record_failed_panel(outdir, cfg, _doc0['run_cfg'], _prov0, stage='synthetic_overfit', error=_fe, planned_cells=_planned_keys)
        raise
    _attb_bump_epoch()
    t_data = time.time()
    train_ids, val_batch, vocab, _, val_bnd = load_run_corpus(cfg)
    # Mandatory data gate: the loaders run it too, but a driver/monkeypatched
    # corpus cannot bypass it for a real dataset.  The report is persisted with
    # the panel before any model is fitted.
    if (cfg.get('dataset') or 'wikitext') in ('wikitext', 'fineweb'):
        _da = audit_corpus_split(train_ids, val_batch, vocab,
                                 dataset=cfg.get('dataset') or 'wikitext')
        try:
            atomic_write_json(os.path.join(outdir, 'data_audit.json'), {
                'kind': 'corpus_split_data_gate',
                'created_at': time.strftime('%Y-%m-%dT%H:%M:%S'),
                'dataset': cfg.get('dataset') or 'wikitext',
                'report': _da,
            })
        except Exception as _dae:
            print(f'[data] WARNING: could not persist data_audit.json ({type(_dae).__name__}: {_dae})')
    if guard is not None:
        guard.record_run(time.time() - t_data, 0, 0, 0, 0, 0)
    summary_path = os.path.join(outdir, 'summary.json')
    _read_summary_json(summary_path)
    if label:
        print(f'\n########## phase: {label} — {len(cfg['variants'])} variants x seeds {cfg['seeds']} x {cfg['steps']} steps ##########')
    # Prospective seed-plan note: a panel that contains an ablation arm is
    # checked BEFORE training so its seed count is not mistaken for a
    # confirmation after the fact.  This never blocks a run.
    try:
        _vs = set(cfg.get('variants') or [])
        _declared_pairs = [(_a, _b) for _contrasts in list(ABLATION_DESIGN.values()) + list(BASELINE_DESIGN.values()) for _a, _b, _n in _contrasts]
        if any(_a in _vs and _b in _vs for _a, _b in _declared_pairs):
            _sp = methodology_seed_plan(len(cfg['seeds']), variants=cfg.get('variants'))
            if _sp.get('min_seeds_for_family_significance') and not _sp.get('sufficient_for_family_rejection'):
                print('[seed-plan] this panel declares %d controlled contrasts; with n=%d seeds the family-corrected exact-test floor is above alpha, so results are DESCRIPTIVE ONLY. '
                      'A family-corrected rejection needs n>=%d (raise the seed list or narrow the pre-registered family before claiming significance).'
                      % (_sp['declared_contrasts'], _sp['n_seeds'], _sp['min_seeds_for_family_significance']))
            if _sp.get('ablation_complete') is False:
                _abl = _sp.get('ablation_completeness') or {}
                print('[seed-plan] ABLATION INCOMPLETE for this panel: missing %s. '
                      'A component with only a partial combination cannot support the claim that each module is useful; add the named full-minus-X arm (or run the full factorial).'
                      % '; '.join('%s=%s' % (_c, ','.join(_a))
                                  for _c, _a in sorted((_abl.get('missing_arms') or {}).items())))
    except Exception as _sp_err:
        print(f'[seed-plan] note unavailable ({type(_sp_err).__name__}: {_sp_err}) — continuing')
    if torch.cuda.is_available():
        _pin_cuda_determinism()
    fp = _run_fp(cfg, d, n_layers, n_heads, d_head, vocab, train_ids, val_batch, device=DEVICE)
    prov = experiment_provenance(cfg, train_ids=train_ids, val_batch=val_batch, vocab=vocab)
    ratios = _panel_ratios(vocab)
    _data_fp = _ids_fp(train_ids)

    # Explicit seed contract: same seed reproduces every RNG source the
    # pipeline can consume (Python/NumPy/Torch/CUDA/TF/DataLoader generator
    # and worker hook) and a different seed actually changes each one.  This
    # is cheaper than the 3-step training check and pinpoints WHICH stream is
    # unseeded when a reproduction fails.
    _dl_workers = int(cfg.get('dataloader_workers') or 0)
    _seed_contract = seed_contract_check(
        seed=_first_seed,
        check_dataloader_workers=_dl_workers > 0,
        dataloader_workers=max(1, _dl_workers))
    _seed_contract.update({'run_cfg': fp, 'label': label or outdir, 'provenance': prov})
    for _w in _seed_contract.get('warnings') or []:
        print(f'[determinism] WARNING: {_w}')
    atomic_write_json(os.path.join(outdir, 'seed_contract.json'), _seed_contract)
    log_experiment_event(outdir, {
        'kind': 'preflight', 'tracking_schema': 2,
        'status': ('ok' if _seed_contract.get('passed') else 'failed'),
        'stage': 'rng_seed_contract', 'run_cfg': fp,
        'code': code_stamp(), 'provenance': prov,
        'seed_contract': {k: _seed_contract.get(k) for k in ('passed', 'seed', 'checks', 'errors')},
    })
    if not _seed_contract.get('passed'):
        _record_failed_panel(outdir, cfg, fp, prov, stage='rng_seed_contract',
                             error=_seed_contract.get('diagnosis'), planned_cells=_planned_keys)
        raise RuntimeError(
            'RNG seed contract check FAILED '
            f"({_seed_contract.get('diagnosis')}) — do NOT start training; "
            'at least one RNG stream is unseeded or unstable on this machine. '
            'See seed_contract.json.')

    _data_contract = batch_contract_check(
        train_ids, cfg['seq_len'], cfg.get('batch_size', 12), DEVICE,
        seed=_first_seed, vocab=vocab)
    _data_contract.update({'run_cfg': fp, 'label': label or outdir, 'provenance': prov})
    atomic_write_json(os.path.join(outdir, 'data_contract.json'), _data_contract)
    log_experiment_event(outdir, {
        'kind': 'preflight', 'tracking_schema': 2,
        'status': ('ok' if _data_contract.get('passed') else 'failed'),
        'stage': 'batch_iterator_contract', 'run_cfg': fp,
        'code': code_stamp(), 'provenance': prov,
        'data_contract': {k: _data_contract.get(k) for k in
                          ('passed', 'diagnosis', 'seq_len', 'batch_size', 'seed', 'n_batches')},
    })
    if not _data_contract.get('passed'):
        _record_failed_panel(outdir, cfg, fp, prov, stage='batch_iterator_contract',
                             error=_data_contract.get('diagnosis'), planned_cells=_planned_keys)
        raise RuntimeError(
            'batch iterator contract check FAILED '
            f"({_data_contract.get('diagnosis')}) — do NOT start a full run; "
            'the actual training loader is not producing shifted, in-vocabulary, '
            'repeatable batches. See data_contract.json.')

    def _data_probe_cfg(v):
        return _overfit_probe_config(seed=_first_seed, steps=_probe_steps, seq_len=_probe_seq, batch_size=_probe_batch, vocab=vocab, target_loss=0.05, target_acc=0.99, arch=_arch, mlp_ratio=ratios.get(v), ignore_index=None, source='data', data_fp=_data_fp, device=DEVICE)

    # The real data-path check: the synthetic pass above cannot catch a broken
    # real token stream / vocabulary mapping.  It is a superset of the model
    # plumbing check, so a pass here is the stronger evidence; both reports
    # are persisted with the panel.
    _data_rep = []
    try:
        _data_rep = list(overfit_guard(_variants, seed=_first_seed, steps=_probe_steps, seq_len=_probe_seq, batch_size=_probe_batch, vocab=vocab, train_ids=train_ids, arch=_arch, mlp_ratio=ratios))
        _sanity += _data_rep
    except RuntimeError as _fe:
        _reports = [dict(r) for _k, r in _OVERFIT_REPORTS.items() if _k[0] in set(_variants)]
        _doc = {
            'kind': 'small_batch_overfit_sanity_panel', 'stage': 'data_preflight',
            'created_at': time.strftime('%Y-%m-%dT%H:%M:%S'),
            'run_cfg': fp, 'label': label or outdir, 'passed': False,
            'error': f'{_fe}', 'provenance': prov, 'reports': _reports,
        }
        atomic_write_json(os.path.join(outdir, 'overfit_sanity.json'), _doc)
        log_experiment_event(outdir, {'kind': 'preflight', 'tracking_schema': 2, 'status': 'failed', 'stage': 'data_overfit', 'run_cfg': fp, 'code': code_stamp(), 'provenance': prov, 'error': f'{_fe}', 'sanity': {'passed': False, 'n_reports': len(_reports)}})
        _record_failed_panel(outdir, cfg, fp, prov, stage='data_overfit', error=_fe, planned_cells=_planned_keys)
        raise
    if not _data_rep:
        # The guard is process-cached (correctly, so repeated phases do not
        # retrain the probe).  Recover THIS exact probe configuration's
        # evidence from the cache so a fresh outdir still gets a persisted
        # sanity record; a looser probe must never certify this panel.
        _sem_by_v = {v: _overfit_probe_semantics(_data_probe_cfg(v)) for v in _variants}
        _sanity = []
        for (_v, _src, *_rest), _r in _OVERFIT_REPORTS.items():
            if _v not in set(_variants):
                continue
            if _r.get('guard_probe_semantics') != _sem_by_v.get(_v):
                continue
            if _src in ('data', 'batch'):
                # Full data key: the evidence must name THIS corpus/panel.
                if len(_rest) < 2 or _rest[1] != _data_fp:
                    continue
            elif _src != 'synthetic':
                continue
            _sanity.append(dict(_r))
    _sanity_doc = None
    if _sanity:
        _sanity_doc = {
            'kind': 'small_batch_overfit_sanity_panel',
            'created_at': time.strftime('%Y-%m-%dT%H:%M:%S'),
            'run_cfg': fp,
            'label': label or outdir,
            'passed': all(bool(r.get('passed')) for r in _sanity),
            'provenance': prov,
            'reports': _sanity,
        }
        atomic_write_json(os.path.join(outdir, 'overfit_sanity.json'), _sanity_doc)
    # The hand-rolled probe above certifies model/loss/label plumbing.  Re-run
    # one fixed window through the ACTUAL `train_variant` loop so a broken
    # optimizer/scheduler/loss assembly cannot pass a separately written loop.
    _prod_doc = None
    if _variants and os.environ.get('CSA_SKIP_OVERFIT', '').strip().lower() not in ('1', 'true', 'yes', 'on'):
        try:
            # The production trainer is shared by every arm; a dense sentinel
            # tests optimizer/scheduler/loss-assembly wiring without coupling
            # the gate to a stochastic task or boundary-policy arm.
            _prod = production_loop_sanity_check(
                'full', seed=_first_seed, train_ids=train_ids,
                vocab=vocab, device=DEVICE)
            _prod_error = None
        except Exception as _fe:
            _prod = {'kind': 'production_loop_overfit_sanity', 'variant': 'full',
                     'passed': False, 'diagnosis': f'{type(_fe).__name__}: {_fe}'}
            _prod_error = f'{_fe}'
        _prod_doc = {
            'kind': 'production_loop_overfit_sanity_panel',
            'created_at': time.strftime('%Y-%m-%dT%H:%M:%S'),
            'run_cfg': fp, 'label': label or outdir,
            'passed': bool(_prod.get('passed')),
            'provenance': prov, 'reports': [dict(_prod)],
        }
        if _prod_error is not None:
            _prod_doc['error'] = _prod_error
        atomic_write_json(os.path.join(outdir, 'production_sanity.json'), _prod_doc)
        log_experiment_event(outdir, {
            'kind': 'preflight', 'tracking_schema': 2,
            'status': ('ok' if _prod_doc['passed'] else 'failed'),
            'stage': 'production_loop_overfit', 'run_cfg': fp,
            'code': code_stamp(), 'provenance': prov,
            'production_sanity': {'passed': _prod_doc['passed'],
                                  'ref': 'production_sanity.json',
                                  'variant': 'full'},
        })
        if _sanity_doc is not None:
            _sanity_doc['production_loop'] = _prod_doc
            if not _prod_doc['passed']:
                _sanity_doc['passed'] = False
            atomic_write_json(os.path.join(outdir, 'overfit_sanity.json'), _sanity_doc)
        if not _prod_doc['passed']:
            _record_failed_panel(outdir, cfg, fp, prov, stage='production_loop_overfit',
                                 error=_prod.get('diagnosis'), planned_cells=_planned_keys)
            raise RuntimeError(
                'production training-loop overfit check FAILED '
                f"({_prod.get('diagnosis')}) — do NOT start a full run; the "
                'actual train_variant loop is not applying updates to one fixed '
                'batch. See production_sanity.json.')
    # Same-machine seed check on the REAL architecture/data, first and last
    # panel seed.  Confirmation/scale panels require it to pass; exploratory
    # panels record the failure but stay advisory.
    _repro_seeds = list(dict.fromkeys([_first_seed, _last_seed]))
    _env_strict = os.environ.get('CSA_REQUIRE_REPRO')
    if _env_strict is None:
        _strict_repro = bool(_confirm)
    else:
        _strict_repro = _env_strict.strip().lower() in ('1', 'true', 'yes', 'on')
    try:
        _repro = list(reproducibility_guard(_variants, seed=_first_seed, steps=3, arch=_arch, train_ids=train_ids, vocab=vocab, mlp_ratio=ratios, seq_len=_probe_seq, batch_size=_probe_batch, seeds=_repro_seeds, strict=_strict_repro))
    except RuntimeError as _fe:
        _reports = [dict(r) for _k, r in _REPRO_REPORTS.items() if _k[0] in set(_variants)]
        _doc = {
            'kind': 'duplicate_run_reproducibility_panel', 'stage': 'reproducibility_preflight',
            'created_at': time.strftime('%Y-%m-%dT%H:%M:%S'),
            'run_cfg': fp, 'label': label or outdir, 'passed': False,
            'error': f'{_fe}', 'provenance': prov, 'reports': _reports,
        }
        atomic_write_json(os.path.join(outdir, 'reproducibility.json'), _doc)
        log_experiment_event(outdir, {'kind': 'preflight', 'tracking_schema': 2, 'status': 'failed', 'stage': 'reproducibility', 'run_cfg': fp, 'code': code_stamp(), 'provenance': prov, 'error': f'{_fe}', 'reproducibility': {'passed': False, 'n_reports': len(_reports)}})
        _record_failed_panel(outdir, cfg, fp, prov, stage='reproducibility', error=_fe, planned_cells=_planned_keys)
        raise
    if not _repro:
        _bases = set()
        for v in _variants:
            for sd in _repro_seeds:
                _bases.add(_repro_guard_base(seed=sd, steps=3, tol=1e-06, arch=_arch, vocab=vocab, mlp_ratio=ratios.get(v), seq_len=_probe_seq, batch_size=_probe_batch, train_ids=train_ids, data_fp=_data_fp))
        _repro = [dict(r) for k, r in _REPRO_REPORTS.items() if k[0] in set(_variants) and k[1] in _bases]
    _repro_doc = None
    if _repro:
        _repro_doc = {
            'kind': 'duplicate_run_reproducibility_panel',
            'created_at': time.strftime('%Y-%m-%dT%H:%M:%S'),
            'run_cfg': fp,
            'label': label or outdir,
            'passed': all(bool(r.get('passed')) for r in _repro),
            'provenance': prov,
            'reports': _repro,
        }
        atomic_write_json(os.path.join(outdir, 'reproducibility.json'), _repro_doc)
    cells, stale_dropped = _plan_run(cfg, summary_path, fp)
    # Plan the order over ALL declared cells, not only the pending ones, so a
    # resume cannot reshuffle a partially finished panel.  The same cells are
    # trained with the same seeds; only the calendar order changes.
    _all_order_cells = [(v, seed) for seed in cfg['seeds'] for v in cfg['variants']]
    _run_order_plan = build_run_order_plan(
        _all_order_cells, block_key=lambda c: int(c[1]), seed=_first_seed,
        block_name='seed')
    write_run_order(outdir, _run_order_plan)
    _run_rank = {lab: i for i, lab in enumerate(_run_order_plan['planned_cells'])}
    cells.sort(key=lambda c: _run_rank.get(f'{c[0]}::seed{c[1]}', len(_run_rank)))
    _panel_started = time.strftime('%Y-%m-%dT%H:%M:%S')
    # Crash-safe tracking: publish the panel's identity (code/data versions,
    # hyperparameters, planned cells) BEFORE the first cell can be
    # killed.  The final write below flips the status to complete and lists
    # every planned cell that produced no measurement.
    write_run_manifest(outdir, cfg, fp, prov, _read_summary_json(summary_path), sanity=_sanity_doc, reproducibility=_repro_doc, data_contract=_data_contract, seed_contract=_seed_contract, status='running', planned_cells=_planned_keys, started_at=_panel_started)
    log_experiment_event(outdir, {
        'kind': 'panel_start', 'tracking_schema': 2, 'label': label or outdir,
        'run_cfg': fp, 'code': code_stamp(), 'started_at': _panel_started,
        'config': _jsonable(cfg), 'seeds': list(cfg.get('seeds') or []),
        'variants': list(cfg.get('variants') or []),
        'n_cells_planned': len(_planned_keys), 'n_cells_to_run': len(cells),
        'n_cells_resumed': max(0, len(_planned_keys) - len(cells)),
        'provenance': prov,
        'data_contract': ({'passed': bool(_data_contract.get('passed')), 'diagnosis': _data_contract.get('diagnosis'), 'ref': 'data_contract.json'} if isinstance(_data_contract, dict) else None),
        'sanity': ({'passed': all(bool(r.get('passed')) for r in _sanity), 'n_reports': len(_sanity), 'ref': 'overfit_sanity.json'} if _sanity else None),
        'reproducibility': ({'passed': all(bool(r.get('passed')) for r in _repro), 'n_reports': len(_repro), 'ref': 'reproducibility.json'} if _repro else None),
        'seed_contract': ({'passed': bool(_seed_contract.get('passed')), 'ref': 'seed_contract.json'} if isinstance(_seed_contract, dict) else None),
    })
    dropped_truncations = []
    ratios = {}
    _ran_parallel = False
    if cells:
        import par as _par
        _par_ctx = par if isinstance(par, dict) else _par.resolve_ctx(par, label=label or outdir)
        if _par_ctx and _par.ctx_active(_par_ctx, len(cells)):
            _caller = sys._getframe(1).f_globals.get('__name__')
            # a '__main__' frame (e.g. run_gapfill.py driving L.run directly)
            # cannot be imported by that name in the child, and plain
            # exp_lib matches that caller's patch state exactly.
            module = _par_ctx.get('module') or (_caller if _caller and _caller != '__main__' else 'exp_lib')
            jobs = [dict(kind='run', module=module, label=label, cfg=cfg, v=v, seed=seed, guard_cap=(guard.cap_spec() if guard is not None else None), ckpt_flag=bool(_par_ctx.get('ckpt_flag')), ckpt_install=bool(_par_ctx.get('ckpt_install')), fp=fp, prov=prov) for v, seed in cells]
            # Children re-serve the corpus from the shared on-disk cache; the
            # parent can release its reference (and the loader memo entry) once
            # the jobs are dispatched.
            for _memo in (_WT103_MEMO, _FWEB_MEMO):
                for _mk, _mv in list(_memo.items()):
                    if isinstance(_mv, tuple) and _mv and _mv[0] is train_ids:
                        _memo.pop(_mk, None)
            del train_ids, val_batch, val_bnd
            gc.collect()
            results = _par.run_jobs(jobs, _par_ctx, phase_label=label or outdir)
            for r, (v, seed) in zip(results, cells):
                if not r:
                    continue
                if r.get('truncated'):
                    dropped_truncations.append(r.get('key') or f'{v}::seed{seed}')
            _ran_parallel = True
    if not _ran_parallel:
        for v, seed in cells:
            res = _run_cell(cfg, v, seed, guard=guard, ratios=ratios, fp=fp, train_ids=train_ids, val_batch=val_batch, vocab=vocab, val_bnd=val_bnd, prov=prov)
            if res.get('truncated'):
                dropped_truncations.append(res['key'])
    summary = _read_summary_json(summary_path)
    if dropped_truncations:
        print(f'\n[cap] {len(dropped_truncations)} cell(s) were retrained, hit the cap deadline, and produced NO measurement — they are ABSENT from {summary_path} and from every table above:')
        for _k in dropped_truncations:
            print(f'    {_k}')
        print('[cap] raise RUN_CAP and re-run to fill these cells in.')
    if stale_dropped:
        _still = [k for k in stale_dropped if k not in summary]
        print(f'\n[resume] {len(stale_dropped)} cell(s) held a record from a DIFFERENT config and were re-run; {len(_still)} of them produced NO measurement this pass and are now ABSENT from {summary_path} (the stale record was removed rather than kept, so no number measured by older code can be reported under the current config):')
        for _k in _still:
            print(f'    {_k}')
        if len(_still) != len(stale_dropped):
            print(f'    ({len(stale_dropped) - len(_still)} of them succeeded and carry a fresh record.)')
    _measured = {k for k in _planned_keys if isinstance(summary.get(k), dict) and ppl_is_usable((summary.get(k) or {}).get('ppl')) and not (summary.get(k) or {}).get('synthesized')}
    _missing = [k for k in _planned_keys if k not in _measured]
    _trace_bad = []
    for _k in _measured:
        _rec = summary.get(_k) or {}
        if _rec.get('run_cfg') not in (None, fp):
            _trace_bad.append(_k)
            continue
        for _ref_key in ('curve_ref', 'ppl_history_ref'):
            _ref = _rec.get(_ref_key)
            if _ref and '#' not in str(_ref) and not os.path.exists(os.path.join(outdir, str(_ref))):
                _trace_bad.append(_k)
                break
    if _trace_bad:
        print(f'\n[trace] {len(_trace_bad)} measured cell(s) reference a missing curve artifact or a foreign run_cfg: {_trace_bad[:10]} — the panel is marked incomplete.')
    # A finished process is not a finished panel.  Stamping a run with missing
    # measurements (or a broken trace reference) as `complete` is exactly how
    # a partially traced experiment gets quoted as if every planned cell
    # existed.
    _final_status = 'complete' if (not _missing and not _trace_bad) else 'incomplete'
    write_run_manifest(outdir, cfg, fp, prov, summary, sanity=_sanity_doc, reproducibility=_repro_doc, data_contract=_data_contract, seed_contract=_seed_contract, status=_final_status, planned_cells=_planned_keys, started_at=_panel_started)
    # Independent read-back of the trace that was just written.  A run whose
    # manifest/cells/curve digests do not agree is not "complete" even if the
    # process exited normally: that is how a partially traced panel would
    # otherwise be quoted as if every planned cell carried evidence.
    _tracking = verify_run_tracking(outdir, fp)
    atomic_write_json(os.path.join(outdir, 'tracking_verification.json'), _tracking)
    if not _tracking.get('passed'):
        print(f'[track] tracking verification FAILED: {_tracking.get("diagnosis")} — marking the panel incomplete')
        _final_status = 'incomplete'
    write_run_manifest(outdir, cfg, fp, prov, summary, sanity=_sanity_doc, reproducibility=_repro_doc, data_contract=_data_contract, seed_contract=_seed_contract, status=_final_status, planned_cells=_planned_keys, started_at=_panel_started, tracking_verification=_tracking)
    _agg = _finish_panel(outdir, summary)
    try:
        with open(os.path.join(outdir, 'aggregation_exclusions.json'),
                  encoding='utf-8') as _xf:
            _excl_doc = json.load(_xf)
    except Exception:
        _excl_doc = {}
    log_experiment_event(outdir, {
        'kind': 'panel_finish', 'tracking_schema': 2, 'label': label or outdir,
        'status': _final_status,
        'run_cfg': fp, 'code': code_stamp(), 'started_at': _panel_started,
        'finished_at': time.strftime('%Y-%m-%dT%H:%M:%S'),
        'provenance': prov, 'config': _jsonable(cfg),
        'seeds': list(cfg.get('seeds') or []),
        'variants': list(cfg.get('variants') or []),
        'data_version': prov.get('data', {}).get('data_version'),
        'n_cells_planned': len(_planned_keys), 'n_cells_to_run': len(cells),
        'n_cells_measured': len(_measured),
        'n_cells_missing': len(_missing), 'missing_cells': _missing[:20],
        'n_trace_bad': len(_trace_bad), 'trace_bad_cells': _trace_bad[:20],
        'n_truncated': len(dropped_truncations), 'n_stale_dropped': len(stale_dropped),
        'tracking_verification': {'passed': bool(_tracking.get('passed')), 'ref': 'tracking_verification.json', 'n_problems': len(_tracking.get('problems') or [])},
        'aggregate_ref': 'aggregate.json', 'summary_ref': 'summary.json',
        'aggregation_exclusions_ref': 'aggregation_exclusions.json',
        'n_records_quarantined': int(_excl_doc.get('n_excluded') or 0),
        'aggregation_exclusion_reasons': _excl_doc.get('reason_counts') or {},
        'aggregate': {str(v): {kk: e.get(kk) for kk in ('n', 'n_seeds', 'ppl_mean', 'ppl_std', 'params') if kk in e} for v, e in (_agg or {}).items() if isinstance(e, dict)},
    })
    return (summary, None)

def _dump_aggregate(outdir, summary):
    try:
        agg, _excl, records_for_readers = aggregate_with_exclusions(summary)
    except Exception as e:
        # The wrapper itself must not make a finished panel unreadable.  Keep
        # the failure visible (and counted) instead of crashing after training.
        print(f'[aggregate] aggregate({outdir}) failed: {type(e).__name__}: {e}')
        agg, records_for_readers = {}, {}
        _excl = {'kind': 'aggregation_exclusions', 'n_input': len(summary),
                 'n_admitted': 0, 'n_excluded': len(summary),
                 'reason_counts': {f'aggregate wrapper failed: {type(e).__name__}: {e}': len(summary)},
                 'excluded': [{'key': str(k), 'reason': f'aggregate wrapper failed: {type(e).__name__}: {e}'}
                              for k in summary][:200],
                 'excluded_truncated': max(0, len(summary) - 200),
                 'tolerance': 'aggregation failed catastrophically; no number was written as a silent zero'}
    atomic_write_json(os.path.join(outdir, 'aggregation_exclusions.json'), _excl)
    if _excl.get('n_excluded'):
        atomic_write_json(os.path.join(outdir, 'summary.aggregatable.json'),
                          records_for_readers)
        print(f'[aggregate] {_excl["n_excluded"]} record(s) were NOT aggregated '
              f'(of {_excl["n_input"]}); see aggregation_exclusions.json — '
              'the remaining records keep their exact values')
    _pub = {k: {kk: vv for kk, vv in e.items() if kk != '_group_records'} if isinstance(e, dict) and '_group_records' in e else e for k, e in agg.items()}
    atomic_write_json(os.path.join(outdir, 'aggregate.json'), _pub)
    _save_csv(_pub, outdir)
    _print_table(_pub)
    _print_pairs(records_for_readers)
    # Record this aggregation as a look BEFORE the audit reads the history, so
    # the audit's sequential correction sees the same seed set it is auditing.
    try:
        _looks = record_panel_look(outdir, records_for_readers)
        if int(_looks.get('n_looks') or 0) > 1:
            print(f'[look] this panel has {_looks["n_looks"]} analysis look(s) '
                  '(seed top-ups); significance is additionally checked against '
                  'the sequential sign-flip p in methodology_audit.json')
    except Exception as e:
        print(f'[look] could not record the look history ({type(e).__name__}: '
              f'{e}); the sequential correction will be unavailable')
    try:
        methodology_audit(records_for_readers, outdir=outdir, verbose=True)
    except Exception as e:
        print(f'[audit] methodology audit failed ({type(e).__name__}: {e}) — the panel is still aggregated; the audit is advisory and never blocks a run')
    _plot(records_for_readers, agg, outdir)
    return agg

def _finish_panel(outdir, summary):
    return _dump_aggregate(outdir, summary)


# ---- 统计机器的校准：先证明检验本身在零假设下不超发，再谈结果 -------------
# 本仓库的结论依赖一串统计程序：精确符号翻转、meet-in-the-middle、n>40 的
# Lugannani-Rice 鞍点尾、max-over-looks 序列 p、配对 TOST 与 Holm。它们被
# 单元测试覆盖，并不等于它们的**频率学错误率**已被校准。下面的模拟只用
# 局部 RNG、固定种子与合成数据，不触碰训练/评测 RNG、不读取任何结果目录，
# 也不改变任何测量语义；它验证的是「统计机器」，不是「实验假说」。

STATISTICAL_CALIBRATION_POLICY = {
    'version': 'statcal-1',
    'simulation_seed': 20261023,
    'n_sim': 2000,
    'alpha': 0.05,
    'power_floor': 0.60,
    'control_level': 0.001,
    'warning_level': 0.01,
    'exact_n': 12,
    'exact_power_delta': 1.0,
    'mitm_n': 21,
    'mitm_power_delta': 0.8,
    'saddlepoint_exact_n': 21,
    'saddlepoint_exact_draws': 300,
    'saddlepoint_max_abs_error': 0.03,
    'saddlepoint_mean_abs_error': 0.005,
    'saddlepoint_n': 48,
    'saddlepoint_power_delta': 0.5,
    'sequential_union_n': 12,
    'sequential_look_sizes': (6, 9, 12),
    'sequential_power_delta': 0.9,
    'tost_n': 12,
    'tost_margin': 1.0,
    'tost_null_mean': 1.0,
    'tost_alt_mean': 0.0,
    'tost_conf': 0.90,
    'holm_m': 6,
    'holm_alt_p': 1e-06,
    # Interval calibration: the reported seed-t, paired-bootstrap and
    # document/unit-bootstrap intervals are distinct estimators from the
    # hypothesis tests above, so their nominal coverage and non-vacuity are
    # checked separately.  The caps are design limits on the mean interval
    # width in the same units as the simulated data; they reject a trivially
    # wide interval that would pass a coverage-only check.
    'interval_conf': 0.95,
    'interval_n': 12,
    'interval_n_boot': 400,
    'interval_doc_units': 24,
    'interval_doc_between_sd': 1.0,
    'interval_seed_count': 6,
    'interval_seed_effect_sd': 0.2,
    'interval_doc_effect_sd': 0.5,
    'interval_within_sd': 0.1,
    'interval_doc_tokens': 8,
    'interval_combined_mu': 1.0,
    'interval_combined_n_boot': 300,
    'interval_max_width_t': 2.0,
    'interval_max_width_paired_boot': 2.0,
    'interval_max_width_doc_boot': 2.0,
    'interval_max_log_width_combined': 1.2,
    'note': ('deterministic synthetic calibration of the analysis machinery; '
             'it is not evidence about WikiText, the model, or any substantive '
             'hypothesis, and it cannot repair a confounded design'),
}


def _calibration_policy_fp(policy=None):
    payload = dict(STATISTICAL_CALIBRATION_POLICY if policy is None else policy)
    blob = json.dumps(payload, sort_keys=True, separators=(',', ':'),
                      ensure_ascii=True)
    return hashlib.sha256(blob.encode('utf-8')).hexdigest()


def _calibration_fraction(value, name):
    if isinstance(value, (bool, np.bool_)):
        raise ValueError(f'{name} must be a real number in (0,1), got {value!r}')
    try:
        v = float(value)
    except (TypeError, ValueError, OverflowError):
        raise ValueError(f'{name} must be a real number in (0,1), got {value!r}') from None
    if not (0.0 < v < 1.0):
        raise ValueError(f'{name} must be in (0,1), got {value!r}')
    return v


def _calibration_counts(n_reject, n_sim):
    k = _as_seed_int(n_reject)
    n = _as_seed_int(n_sim)
    if k is None or n is None or n < 1 or k < 0 or k > n:
        raise ValueError(
            'calibration counts require integers 0 <= n_reject <= n_sim and '
            f'n_sim >= 1, got n_reject={n_reject!r}, n_sim={n_sim!r}')
    return int(k), int(n)


def _binomial_sf(k, n, p):
    """P(Bin(n,p) >= k) for an arbitrary p, using the regularized beta."""
    k, n = _calibration_counts(k, n)
    p = _calibration_fraction(p, 'binomial p')
    if k <= 0:
        return 1.0
    if k > n:
        return 0.0
    v = _betai(float(k), float(n - k + 1), p)
    if not math.isfinite(v):
        raise ValueError('binomial upper tail is not finite')
    return float(min(1.0, max(0.0, v)))


def _binomial_cdf(k, n, p):
    """P(Bin(n,p) <= k) for an arbitrary p, using the regularized beta."""
    k, n = _calibration_counts(k, n)
    p = _calibration_fraction(p, 'binomial p')
    if k < 0:
        return 0.0
    if k >= n:
        return 1.0
    v = _betai(float(n - k), float(k + 1), 1.0 - p)
    if not math.isfinite(v):
        raise ValueError('binomial lower tail is not finite')
    return float(min(1.0, max(0.0, v)))


def calibration_type_i_gate(n_reject, n_sim, *, alpha=0.05,
                            control_level=0.001, warning_level=0.01):
    """One-sided calibration gate for a nominal type-I error rate.

    Under a correctly calibrated procedure the rejection count is Binomial
    (n_sim, alpha).  The gate fails only when the upper-tail probability
    ``P(X >= n_reject | alpha)`` is below ``control_level`` — i.e. when the
    observed false-positive rate is itself significantly above nominal.  A
    rate that is merely above alpha but compatible with Monte-Carlo noise is a
    warning, never a failure, and a conservative procedure (rate below alpha)
    passes.  ``control_level`` is fixed before the simulation; changing it
    after seeing the count would be the same optional-stopping problem the
    pipeline refuses elsewhere.
    """
    k, n = _calibration_counts(n_reject, n_sim)
    a = _validated_alpha(alpha, context='calibration_type_i_gate alpha')
    c = _calibration_fraction(control_level, 'control_level')
    w = _calibration_fraction(warning_level, 'warning_level')
    if w < c:
        raise ValueError('warning_level must be >= control_level')
    rate = k / n
    p_anti = _binomial_sf(k, n, a)
    if p_anti < c:
        status = 'fail'
    elif p_anti < w:
        status = 'warnings'
    else:
        status = 'ok'
    return {'n_sim': n, 'n_reject': k, 'rate': float(rate), 'alpha': a,
            'excess': float(rate - a), 'p_anti_conservative': float(p_anti),
            'control_level': c, 'warning_level': w, 'status': status}


def calibration_power_gate(n_reject, n_sim, *, power_floor=0.60,
                           control_level=0.001):
    """One-sided calibration gate for a sensitivity / positive-control rate.

    A test that never rejects would pass every type-I calibration, so a valid
    statistical assay also needs a positive control.  Under a procedure with
    power at least ``power_floor`` the count is Binomial(n_sim, floor).  The
    gate fails when the lower-tail probability is below ``control_level``
    (observed sensitivity significantly below the declared floor).  The floor
    is a design convention, not an estimate from the experiment.
    """
    k, n = _calibration_counts(n_reject, n_sim)
    f = _calibration_fraction(power_floor, 'power_floor')
    c = _calibration_fraction(control_level, 'control_level')
    rate = k / n
    p_below = _binomial_cdf(k, n, f)
    if p_below < c:
        status = 'fail'
    elif rate < f:
        status = 'warnings'
    else:
        status = 'ok'
    return {'n_sim': n, 'n_reject': k, 'rate': float(rate),
            'power_floor': f, 'p_below_floor': float(p_below),
            'control_level': c, 'status': status}


def calibration_interval_coverage_gate(n_covered, n_sim, *, nominal=0.95,
                                       control_level=0.001,
                                       warning_level=0.01):
    """One-sided calibration gate for a confidence interval's coverage.

    Under a correctly calibrated two-sided interval the number of simulations
    whose interval covers the true target is ``Binomial(n_sim, nominal)``.
    The gate fails only when the lower-tail probability
    ``P(X <= n_covered | nominal)`` is below ``control_level`` — i.e. when the
    observed coverage is significantly *below* nominal beyond Monte-Carlo
    noise.  Over-coverage is conservative and passes; a shortfall that is
    compatible with simulation noise is a warning, not a failure.  The
    thresholds are fixed before looking at the count, exactly as for the
    hypothesis-test calibration gates.
    """
    k, n = _calibration_counts(n_covered, n_sim)
    target = _calibration_fraction(nominal, 'nominal')
    c = _calibration_fraction(control_level, 'control_level')
    w = _calibration_fraction(warning_level, 'warning_level')
    if w < c:
        raise ValueError('warning_level must be >= control_level')
    rate = k / n
    p_under = _binomial_cdf(k, n, target)
    if p_under < c:
        status = 'fail'
    elif rate < target and p_under < w:
        status = 'warnings'
    else:
        status = 'ok'
    return {'n_sim': n, 'n_covered': k, 'rate': float(rate),
            'nominal': target, 'shortfall': float(rate - target),
            'p_under_coverage': float(p_under),
            'control_level': c, 'warning_level': w, 'status': status}


def calibration_interval_width_gate(mean_width, max_width):
    """Reject a vacuous interval (zero, non-finite, or wider than declared).

    Coverage alone cannot distinguish a calibrated interval from an
    arbitrarily wide one: [−inf, +inf] covers the truth with probability one
    and conveys nothing.  Each calibration path therefore declares a maximum
    acceptable mean width in the simulated data's units.  The cap is a design
    limit fixed before the simulation, not a post-hoc description of the
    observed interval.
    """
    try:
        w = float(mean_width)
        cap = float(max_width)
    except (TypeError, ValueError, OverflowError):
        return {'mean_width': None, 'max_width': None, 'status': 'fail',
                'problem': 'non-numeric interval width'}
    if isinstance(mean_width, (bool, np.bool_)) or isinstance(max_width, (bool, np.bool_)):
        return {'mean_width': None, 'max_width': None, 'status': 'fail',
                'problem': 'boolean interval width'}
    if not math.isfinite(w) or not math.isfinite(cap) or w <= 0 or cap <= 0:
        return {'mean_width': w if math.isfinite(w) else None,
                'max_width': cap if math.isfinite(cap) else None,
                'status': 'fail',
                'problem': 'interval width must be finite and > 0'}
    status = 'ok' if w <= cap else 'fail'
    return {'mean_width': w, 'max_width': cap, 'status': status,
            'problem': None if status == 'ok' else
            f'mean interval width {w:.6g} exceeds the declared cap {cap:.6g}'}


def _calibration_add_interval(out, name, coverage_control, width_control, **extra):
    rec = {'coverage_control': coverage_control,
           'width_control': width_control}
    rec.update(extra)
    out['tests'][name] = rec
    for part in ('coverage_control', 'width_control'):
        _st = rec[part].get('status')
        if _st == 'fail':
            out['status'] = 'fail'
            out['violations'].append(
                f'{name}.{part}: interval calibration failed '
                f'({rec[part].get("rate", rec[part].get("mean_width"))!r})')
        elif _st == 'warnings':
            if out['status'] == 'ok':
                out['status'] = 'warnings'
            out['warnings'].append(
                f'{name}.{part}: coverage shortfall compatible with '
                f'Monte-Carlo noise (rate={rec[part].get("rate")!r})')


def _calibration_path_gate(out, name, predicate, expected):
    rec = out['tests'][name]
    methods = rec.get('methods') or []
    ok = any(predicate(m) for m in methods)
    rec['path_ok'] = bool(ok)
    if not ok:
        out['status'] = 'fail'
        out['violations'].append(
            f'{name}: expected {expected} dispatch, observed methods={methods!r}')


def _calibration_add(out, name, null_control, positive_control, **extra):
    rec = {'null_control': null_control, 'positive_control': positive_control}
    rec.update(extra)
    out['tests'][name] = rec
    for part in ('null_control', 'positive_control'):
        _st = rec[part].get('status')
        if _st == 'fail':
            out['status'] = 'fail'
            out['violations'].append(
                f'{name}.{part}: calibration gate failed '
                f'(rate={rec[part].get("rate")!r}, '
                f'n={rec[part].get("n_reject")!r}/{rec[part].get("n_sim")!r})')
        elif _st == 'warnings':
            if out['status'] == 'ok':
                out['status'] = 'warnings'
            out['warnings'].append(
                f'{name}.{part}: rate outside the nominal target but compatible '
                f'with Monte-Carlo noise (rate={rec[part].get("rate")!r})')


def statistical_calibration_suite(*, seed=None, n_sim=None, alpha=None,
                                  power_floor=None, control_level=None,
                                  warning_level=None):
    """Deterministic synthetic calibration of every statistical procedure the
    evidence pipeline relies on.

    The suite exercises a **negative control** (data generated under the null:
    the false-positive rate must not exceed alpha beyond Monte-Carlo noise)
    and a **positive control** (data generated with a known effect: the same
    procedure must retain sensitivity above a declared floor) for the exact
    sign-flip enumeration, the 21-40 seed meet-in-the-middle path, the n>40
    saddlepoint tail (plus a direct saddlepoint-vs-exact agreement check at
    n=21), the max-over-looks sequential p, paired TOST at the margin, and the
    Holm step-down family.  A second group calibrates the interval estimators
    the reports quote (seed-level paired t, paired bootstrap-t, unit/document
    bootstrap-t and the combined seed x document interval) for both coverage
    of the true target and non-vacuity of the reported width.

    All randomness comes from local ``numpy.random.default_rng`` streams
    spawned from ``seed`` through a ``SeedSequence``; no global NumPy/Torch RNG
    is read or written, so the suite cannot perturb a training run or another
    panel's reproducibility.  The output is a pure function of the policy and
    inputs (the simulated p-values, not a clock).  A pass certifies that the
    analysis machinery has the advertised frequentist behaviour on idealized
    independent pairs; it does not certify the exchangeability, independence or
    unconfoundedness of any real panel, and it is not evidence for or against a
    substantive mechanism claim.  Passing is a screen for gross miscalibration,
    not an equivalence test proving the error rate equals alpha exactly.
    """
    policy = dict(STATISTICAL_CALIBRATION_POLICY)
    seed = policy['simulation_seed'] if seed is None else seed
    n_sim = policy['n_sim'] if n_sim is None else n_sim
    alpha = policy['alpha'] if alpha is None else alpha
    power_floor = policy['power_floor'] if power_floor is None else power_floor
    control_level = (policy['control_level'] if control_level is None
                     else control_level)
    warning_level = (policy['warning_level'] if warning_level is None
                     else warning_level)
    _seed = _as_seed_int(seed)
    if _seed is None or _seed < 0:
        raise ValueError(
            f'statistical_calibration_suite: seed must be a non-negative '
            f'integer, got {seed!r}')
    _n_sim = _as_seed_int(n_sim)
    if _n_sim is None or _n_sim < 20:
        raise ValueError(
            f'statistical_calibration_suite: n_sim must be an integer >= 20, '
            f'got {n_sim!r}')
    n_sim = int(_n_sim)
    alpha = _validated_alpha(alpha, context='statistical_calibration alpha')
    power_floor = _calibration_fraction(power_floor, 'power_floor')
    control_level = _calibration_fraction(control_level, 'control_level')
    warning_level = _calibration_fraction(warning_level, 'warning_level')
    if warning_level < control_level:
        raise ValueError('warning_level must be >= control_level')
    policy['simulation_seed'] = int(_seed)
    policy['n_sim'] = n_sim
    policy['alpha'] = alpha
    policy['power_floor'] = power_floor
    policy['control_level'] = control_level
    policy['warning_level'] = warning_level
    children = np.random.SeedSequence(int(_seed)).spawn(11)
    out = {'kind': 'statistical_calibration', 'status': 'ok',
           'seed': int(_seed), 'n_sim': n_sim, 'alpha': alpha,
           'power_floor': power_floor, 'control_level': control_level,
           'warning_level': warning_level, 'tests': {},
           'violations': [], 'warnings': [],
           'policy': policy, 'policy_fp': _calibration_policy_fp(policy),
           'deterministic': True,
           'note': policy['note'],
           'interpretation_boundary': (
               'a pass validates the statistical machinery on synthetic '
               'independent pairs; it does not validate the exchangeability, '
               'randomisation or measurement identity of a real panel, and it '
               'is not evidence for a substantive hypothesis')}

    rng = np.random.default_rng(children[0])
    n_exact = int(policy['exact_n'])
    delta_exact = float(policy['exact_power_delta'])
    k_null = k_alt = 0
    methods = set()
    for _ in range(n_sim):
        d = rng.normal(size=n_exact)
        r = exact_signflip_p(d.tolist())
        methods.add(r.get('method'))
        k_null += bool(r['p'] <= alpha)
    for _ in range(n_sim):
        d = rng.normal(loc=delta_exact, scale=1.0, size=n_exact)
        k_alt += bool(exact_signflip_p(d.tolist())['p'] <= alpha)
    _calibration_add(
        out, 'exact_signflip_enumeration',
        calibration_type_i_gate(k_null, n_sim, alpha=alpha,
                                control_level=control_level,
                                warning_level=warning_level),
        calibration_power_gate(k_alt, n_sim, power_floor=power_floor,
                               control_level=control_level),
        path='exact enumeration', n_seeds=n_exact,
        alternative_mean=delta_exact,
        methods=sorted(m for m in methods if m))
    _calibration_path_gate(out, 'exact_signflip_enumeration',
                           lambda m: m == 'exact', 'exact enumeration')

    rng = np.random.default_rng(children[1])
    n_mitm = int(policy['mitm_n'])
    delta_mitm = float(policy['mitm_power_delta'])
    k_null = k_alt = 0
    methods = set()
    for _ in range(n_sim):
        d = rng.normal(size=n_mitm)
        r = exact_signflip_p(d.tolist())
        methods.add(r.get('method'))
        k_null += bool(r['p'] <= alpha)
    for _ in range(n_sim):
        d = rng.normal(loc=delta_mitm, scale=1.0, size=n_mitm)
        k_alt += bool(exact_signflip_p(d.tolist())['p'] <= alpha)
    _calibration_add(
        out, 'exact_signflip_mitm',
        calibration_type_i_gate(k_null, n_sim, alpha=alpha,
                                control_level=control_level,
                                warning_level=warning_level),
        calibration_power_gate(k_alt, n_sim, power_floor=power_floor,
                               control_level=control_level),
        path='meet-in-the-middle', n_seeds=n_mitm,
        alternative_mean=delta_mitm, methods=sorted(m for m in methods if m))
    _calibration_path_gate(out, 'exact_signflip_mitm',
                           lambda m: m == 'exact-mitm', 'MITM')

    rng = np.random.default_rng(children[2])
    n_sp_exact = int(policy['saddlepoint_exact_n'])
    n_draws = min(int(policy['saddlepoint_exact_draws']), n_sim)
    errors = []
    n_disagree = 0
    for _ in range(n_draws):
        d = rng.normal(size=n_sp_exact)
        exact = exact_signflip_p(d.tolist())
        approx, _method = _signflip_saddlepoint_p(d.tolist())
        errors.append(abs(float(approx) - float(exact['p'])))
        n_disagree += bool((approx <= alpha) != (exact['p'] <= alpha))
    max_err = max(errors) if errors else float('nan')
    mean_err = float(np.mean(errors)) if errors else float('nan')
    tol_max = float(policy['saddlepoint_max_abs_error'])
    tol_mean = float(policy['saddlepoint_mean_abs_error'])
    acc_status = ('fail' if (not math.isfinite(max_err)
                             or max_err > tol_max
                             or not math.isfinite(mean_err)
                             or mean_err > tol_mean) else 'ok')
    out['tests']['saddlepoint_vs_exact'] = {
        'n_seeds': n_sp_exact, 'n_draws': n_draws,
        'max_abs_error': float(max_err), 'mean_abs_error': float(mean_err),
        'max_abs_tolerance': tol_max, 'mean_abs_tolerance': tol_mean,
        'rejection_disagreements': int(n_disagree), 'status': acc_status}
    if acc_status == 'fail':
        out['status'] = 'fail'
        out['violations'].append(
            'saddlepoint_vs_exact: approximation error '
            f'(max={max_err!r} > {tol_max!r} or mean={mean_err!r} > '
            f'{tol_mean!r})')

    rng = np.random.default_rng(children[3])
    n_sp = int(policy['saddlepoint_n'])
    delta_sp = float(policy['saddlepoint_power_delta'])
    k_null = k_alt = 0
    sp_methods = set()
    for _ in range(n_sim):
        d = rng.normal(size=n_sp)
        r = exact_signflip_p(d.tolist())
        sp_methods.add(r.get('method'))
        k_null += bool(r['p'] <= alpha)
    for _ in range(n_sim):
        d = rng.normal(loc=delta_sp, scale=1.0, size=n_sp)
        k_alt += bool(exact_signflip_p(d.tolist())['p'] <= alpha)
    _calibration_add(
        out, 'saddlepoint_tail',
        calibration_type_i_gate(k_null, n_sim, alpha=alpha,
                                control_level=control_level,
                                warning_level=warning_level),
        calibration_power_gate(k_alt, n_sim, power_floor=power_floor,
                               control_level=control_level),
        path='saddlepoint (n>40 dispatch)', n_seeds=n_sp,
        alternative_mean=delta_sp,
        methods=sorted(m for m in sp_methods if m))
    _calibration_path_gate(out, 'saddlepoint_tail',
                           lambda m: m == 'saddlepoint', 'saddlepoint')

    rng = np.random.default_rng(children[4])
    n_union = int(policy['sequential_union_n'])
    look_sizes = [int(x) for x in policy['sequential_look_sizes']]
    if (not look_sizes or look_sizes[-1] != n_union
            or any(x <= 0 or x > n_union for x in look_sizes)
            or any(b <= a for a, b in zip(look_sizes, look_sizes[1:]))):
        raise ValueError('sequential look sizes must be strictly increasing '
                         'and end at sequential_union_n')
    look_defs = [list(range(size)) for size in look_sizes]
    delta_seq = float(policy['sequential_power_delta'])
    k_null = k_alt = 0
    seq_methods = set()
    for _ in range(n_sim):
        d = rng.normal(size=n_union)
        looks = [(s, [float(d[i]) for i in s]) for s in look_defs]
        r = sequential_signflip_p(looks)
        seq_methods.add(r.get('method'))
        k_null += bool(r['p_sequential'] <= alpha)
    for _ in range(n_sim):
        d = rng.normal(loc=delta_seq, scale=1.0, size=n_union)
        looks = [(s, [float(d[i]) for i in s]) for s in look_defs]
        r = sequential_signflip_p(looks)
        k_alt += bool(r['p_sequential'] <= alpha)
    _calibration_add(
        out, 'sequential_looks',
        calibration_type_i_gate(k_null, n_sim, alpha=alpha,
                                control_level=control_level,
                                warning_level=warning_level),
        calibration_power_gate(k_alt, n_sim, power_floor=power_floor,
                               control_level=control_level),
        path='max-over-looks sign-flip', union_seeds=n_union,
        look_sizes=look_sizes, alternative_mean=delta_seq,
        methods=sorted(m for m in seq_methods if m))
    _calibration_path_gate(out, 'sequential_looks',
                           lambda m: 'max-over-looks' in str(m),
                           'max-over-looks sequential')

    rng = np.random.default_rng(children[5])
    n_tost = int(policy['tost_n'])
    margin = float(policy['tost_margin'])
    conf = float(policy['tost_conf'])
    null_mean = float(policy['tost_null_mean'])
    alt_mean = float(policy['tost_alt_mean'])
    k_null = k_alt = 0
    for _ in range(n_sim):
        d = rng.normal(loc=null_mean, scale=1.0, size=n_tost)
        k_null += bool(tost_paired(d.tolist(), margin, conf=conf)['equivalent'])
    for _ in range(n_sim):
        d = rng.normal(loc=alt_mean, scale=1.0, size=n_tost)
        k_alt += bool(tost_paired(d.tolist(), margin, conf=conf)['equivalent'])
    _calibration_add(
        out, 'tost_paired',
        calibration_type_i_gate(k_null, n_sim, alpha=alpha,
                                control_level=control_level,
                                warning_level=warning_level),
        calibration_power_gate(k_alt, n_sim, power_floor=power_floor,
                               control_level=control_level),
        n_seeds=n_tost, margin=margin, conf=conf,
        null_mean=null_mean, alternative_mean=alt_mean)

    rng = np.random.default_rng(children[6])
    m_holm = int(policy['holm_m'])
    alt_p = float(policy['holm_alt_p'])
    k_null = k_alt = 0
    for _ in range(n_sim):
        ps = rng.random(m_holm)
        h = holm_adjust([(f'c{i}', float(p)) for i, p in enumerate(ps)], alpha=alpha)
        k_null += bool(any(v.get('reject') for v in h.values()))
    for _ in range(n_sim):
        ps = np.concatenate(([alt_p], rng.random(m_holm - 1)))
        h = holm_adjust([(f'c{i}', float(p)) for i, p in enumerate(ps)], alpha=alpha)
        k_alt += bool(any(v.get('reject') for v in h.values()))
    _calibration_add(
        out, 'holm_family',
        calibration_type_i_gate(k_null, n_sim, alpha=alpha,
                                control_level=control_level,
                                warning_level=warning_level),
        calibration_power_gate(k_alt, n_sim, power_floor=power_floor,
                               control_level=control_level),
        family_m=m_holm, alternative_p=alt_p)

    # ---- interval calibration: coverage AND non-vacuity -------------------
    # A test that is correctly calibrated can still quote an interval that
    # under-covers or is so wide that it says nothing.  These paths exercise
    # the exact interval constructors the reports use.  The target is the
    # population mean (0 for the centred seed contrasts, 1.0 on the log-PPL
    # scale for the combined interval); the width caps are declared in the
    # policy before the draws.
    conf = float(policy['interval_conf'])
    n_int = int(policy['interval_n'])
    nb_int = int(policy['interval_n_boot'])

    # (1) seed-level paired t interval from paired_effect_stats.ci95_*
    rng = np.random.default_rng(children[7])
    k_cov = 0
    widths = []
    for _ in range(n_sim):
        d = rng.normal(size=n_int)
        st = paired_effect_stats(d.tolist(), min_n=3)
        lo, hi = st.get('ci95_low'), st.get('ci95_high')
        if (lo is not None and hi is not None
                and math.isfinite(float(lo)) and math.isfinite(float(hi))):
            k_cov += bool(float(lo) <= 0.0 <= float(hi))
            widths.append(float(hi) - float(lo))
    _calibration_add_interval(
        out, 'interval_seed_t',
        calibration_interval_coverage_gate(
            k_cov, n_sim, nominal=conf, control_level=control_level,
            warning_level=warning_level),
        calibration_interval_width_gate(
            float(np.mean(widths)) if widths else float('nan'),
            policy['interval_max_width_t']),
        path='paired t interval (paired_effect_stats.ci95)',
        n_units=n_int, target_mean=0.0, conf=conf)

    # (2) paired bootstrap-t interval used by paired_effect_stats
    rng = np.random.default_rng(children[8])
    k_cov = 0
    widths = []
    for _ in range(n_sim):
        d = rng.normal(size=n_int)
        bseed = int(rng.integers(0, 2**31 - 1))
        ci = paired_bootstrap_ci(d.tolist(), n_boot=nb_int, seed=bseed)
        if ci is not None and all(math.isfinite(float(x)) for x in ci):
            k_cov += bool(float(ci[0]) <= 0.0 <= float(ci[1]))
            widths.append(float(ci[1]) - float(ci[0]))
    _calibration_add_interval(
        out, 'interval_paired_bootstrap',
        calibration_interval_coverage_gate(
            k_cov, n_sim, nominal=conf, control_level=control_level,
            warning_level=warning_level),
        calibration_interval_width_gate(
            float(np.mean(widths)) if widths else float('nan'),
            policy['interval_max_width_paired_boot']),
        path='paired bootstrap-t (chunked, deterministic)',
        n_units=n_int, target_mean=0.0, conf=conf, n_boot=nb_int)

    # (3) unit/document bootstrap-t interval
    rng = np.random.default_rng(children[9])
    n_docs = int(policy['interval_doc_units'])
    between = float(policy['interval_doc_between_sd'])
    k_cov = 0
    widths = []
    for _ in range(n_sim):
        vals = rng.normal(0.0, between, size=n_docs)
        bseed = int(rng.integers(0, 2**31 - 1))
        ci = bootstrap_mean_ci(vals.tolist(), n_boot=nb_int,
                               seed=bseed, conf=conf)
        if ci is not None and all(math.isfinite(float(ci[k])) for k in ('ci_low', 'ci_high')):
            k_cov += bool(float(ci['ci_low']) <= 0.0 <= float(ci['ci_high']))
            widths.append(float(ci['ci_high']) - float(ci['ci_low']))
    _calibration_add_interval(
        out, 'interval_unit_bootstrap',
        calibration_interval_coverage_gate(
            k_cov, n_sim, nominal=conf, control_level=control_level,
            warning_level=warning_level),
        calibration_interval_width_gate(
            float(np.mean(widths)) if widths else float('nan'),
            policy['interval_max_width_doc_boot']),
        path='studentized unit/document bootstrap (chunked, deterministic)',
        n_units=n_docs, target_mean=0.0, conf=conf, n_boot=nb_int)

    # (4) combined seed x document interval used for the pooled PPL.  The
    #     synthetic panel has known seed, document and token noise; the
    #     population target is exp(mu), and the interval is checked on the
    #     log-PPL scale so the multiplicative geometry does not hide a
    #     vacuous interval.
    rng = np.random.default_rng(children[10])
    n_seeds_int = int(policy['interval_seed_count'])
    n_tok_int = int(policy['interval_doc_tokens'])
    seed_sd = float(policy['interval_seed_effect_sd'])
    doc_sd = float(policy['interval_doc_effect_sd'])
    within_sd = float(policy['interval_within_sd'])
    mu_int = float(policy['interval_combined_mu'])
    nb_comb = int(policy['interval_combined_n_boot'])
    target_ppl = math.exp(mu_int)
    k_cov = 0
    log_widths = []
    for _ in range(n_sim):
        se_eff = rng.normal(0.0, seed_sd, size=n_seeds_int)
        de_eff = rng.normal(0.0, doc_sd, size=n_docs)
        noise = rng.normal(0.0, within_sd, size=(n_seeds_int, n_docs))
        ce = mu_int + se_eff[:, None] + de_eff[None, :] + noise
        nll = (ce * n_tok_int).tolist()
        ntok = [n_tok_int] * n_docs
        recs = [{'nll_per_row': nll[s], 'n_tokens_per_row': ntok}
                for s in range(n_seeds_int)]
        bseed = int(rng.integers(0, 2**31 - 1))
        ci = _combined_seed_doc_ci(recs, n_boot=nb_comb, seed=bseed, conf=conf)
        if ci.get('status') == 'ok' and ci.get('ci95_ppl'):
            lo, hi = ci['ci95_ppl']
            try:
                k_cov += bool(float(lo) <= target_ppl <= float(hi))
                lw = math.log(float(hi)) - math.log(float(lo))
                if math.isfinite(lw):
                    log_widths.append(lw)
            except (TypeError, ValueError, OverflowError):
                pass
    _calibration_add_interval(
        out, 'interval_combined_seed_doc',
        calibration_interval_coverage_gate(
            k_cov, n_sim, nominal=conf, control_level=control_level,
            warning_level=warning_level),
        calibration_interval_width_gate(
            float(np.mean(log_widths)) if log_widths else float('nan'),
            policy['interval_max_log_width_combined']),
        path='combined seed x document interval (log-PPL scale)',
        n_seeds=n_seeds_int, n_units=n_docs, target_ppl=target_ppl,
        conf=conf, n_boot=nb_comb)

    return out
